#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// ADS1115 configuration values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0040 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Sensor sensitivity (example value, check datasheet)
#define SENSOR_SENSITIVITY 0.1 // V/A

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_address;
    int sda_gpio;
    int scl_gpio;
    float sensor_sensitivity;
} config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the ADS1115
int ads1115_init(int i2c_handle) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE |
                      ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_COMP_MODE_TRAD |
                      ADS1115_CONFIG_COMP_POL_LOW |
                      ADS1115_CONFIG_COMP_LAT_NON |
                      ADS1115_CONFIG_COMP_QUE_DISABLE;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register\n");
        return -1;
    }

    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t ads1115_read(int i2c_handle) {
    char buf[1];
    char read_buf[2];
    int16_t value;

    // Set the configuration register to start a single conversion
    uint16_t config = ADS1115_CONFIG_OS_SINGLE |
                      ADS1115_CONFIG_MUX_SINGLE_0 |
                      ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_COMP_MODE_TRAD |
                      ADS1115_CONFIG_COMP_POL_LOW |
                      ADS1115_CONFIG_COMP_LAT_NON |
                      ADS1115_CONFIG_COMP_QUE_DISABLE;

    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register\n");
        return -1;
    }

    // Wait for the conversion to complete (adjust delay as needed)
    gpioDelay(10); // 10 ms delay

    // Read the conversion result
    buf[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit value
    value = (read_buf[0] << 8) | read_buf[1];

    return value;
}

// Function to convert the ADC value to amperes
float convert_to_amperes(int16_t adc_value, float sensor_sensitivity) {
    float voltage = (adc_value * 4.096) / 32768.0; // Assuming +/-4.096V range
    float current = voltage / sensor_sensitivity;
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_init(i2c_handle) != 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t adc_value = ads1115_read(i2c_handle);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
        } else {
            float current = convert_to_amperes(adc_value, SENSOR_SENSITIVITY);
            printf("Current: %.3f A\n", current);
        }

        gpioDelay(500); // 500 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

