#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CE_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define temperature calibration parameters
#define VREF 3.3 // Reference voltage for MCP3008
#define ADC_RESOLUTION 1024.0 // 2^10

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    float voltage = (adc_value / ADC_RESOLUTION) * VREF;
    // Simple linear approximation: 10mV/°C
    float temperature = (voltage - 0.5) / 0.01; // Assuming 0.5V is 0°C
    return temperature;
}

// Function to log data to CSV file
void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CE_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("flame_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open flame_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,FlameDetected,Temperature\n");
    }
    rewind(fp);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read MCP3008 ADC
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read MCP3008 ADC\n");
            continue; // Skip to the next iteration
        }

        // Calculate temperature
        float temperature = calculate_temperature(adc_value);

        // Log data
        log_data(flame_detected, temperature);

        // Wait for one second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close SPI channel and file
    spiClose(spi_handle);
    fclose(fp);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

