#include <pigpio.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define VREF 4.096 // ADS1115 VREF in volts
#define MAX_TEMP 60.0 // Maximum temperature threshold
#define SAMPLE_RATE_MS 100
#define DEBOUNCE_MS 50

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int read_flame_sensor();
float read_temperature_sensor();
void activate_buzzer(int duration_ms);
void log_event(const char *message);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    static int last_state = 1; // Initialize to no flame detected (HIGH)
    static unsigned long last_change = 0;
    int current_state = gpioRead(FLAME_SENSOR_GPIO);
    unsigned long now = gpioTick();

    if (current_state != last_state) {
        if (now - last_change > DEBOUNCE_MS * 1000) { // Convert ms to microseconds
            last_state = current_state;
            last_change = now;
        }
    }
    return last_state; // Return the debounced state
}

// Function to read the temperature sensor from ADS1115
float read_temperature_sensor() {
    unsigned char config[3];
    short raw_value;
    float voltage, temperature;

    // Configure ADS1115 for single-ended AIN0, 4.096V, continuous conversion, 128 SPS
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0x43; // 0b01000011
    config[2] = 0x83; // 0b10000011

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        log_event("Error: Failed to write to ADS1115 configuration register.");
        return -1000.0; // Indicate error
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    char conversion_reg = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, &conversion_reg, 1) != 0) {
        log_event("Error: Failed to write to ADS1115 conversion register.");
        return -1000.0; // Indicate error
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        log_event("Error: Failed to read from ADS1115 conversion register.");
        return -1000.0; // Indicate error
    }

    // Combine the two bytes to get the raw value
    raw_value = (data[0] << 8) | data[1];

    // Convert raw value to voltage
    voltage = (float)raw_value * VREF / 32768.0;

    // Convert voltage to temperature (assuming 10mV/°C)
    temperature = voltage * 100.0;

    return temperature;
}

// Function to activate the buzzer for a specified duration
void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Setup function to initialize pigpio, I2C, and GPIO
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    // Turn off buzzer
    gpioWrite(BUZZER_GPIO, 0);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();
        float temperature = read_temperature_sensor();

        if (flame_detected == 0) {
            log_event("Flame detected!");
        }

        if (temperature > MAX_TEMP) {
            char message[50];
            snprintf(message, sizeof(message), "Temperature: %.2f\u00b0C", temperature);
            log_event(message);
        }

        if (flame_detected == 0 && temperature > MAX_TEMP) {
            log_event("Fire event!");
            activate_buzzer(2000); // Activate buzzer for 2 seconds
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

