// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8
#define SPI_SCLK_PIN 11
#define SPI_MOSI_PIN 10
#define SPI_MISO_PIN 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define CSV file name
#define CSV_FILE "flame_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_to_temperature(int adc_value);
void log_data(int flame_present, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS_PIN, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (read_mcp3008).\n");
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_to_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature
    // You'll need to calibrate this based on your specific sensor and setup
    float temperature = (adc_value / 1023.0) * 50.0; // Example: 0-50°C range
    return temperature;
}

// Function to log data to CSV file
void log_data(int flame_present, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_present, temperature);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);
    gpioSetMode(SPI_SCLK_PIN, PI_OUTPUT);
    gpioSetMode(SPI_MOSI_PIN, PI_OUTPUT);
    gpioSetMode(SPI_MISO_PIN, PI_INPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed.\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file for writing.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,FlamePresent,Temperature\n");
    }
    rewind(fp);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor and temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int flame_present = read_flame_sensor();
        int adc_value = read_mcp3008(0); // Read from channel 0

        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value. Skipping this entry.\n");
        } else {
            float temperature = convert_to_temperature(adc_value);
            log_data(flame_present, temperature);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up resources
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

