// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        data.ox = 0; // Set to default value in case of error
        data.red = 0;
        return data;
    }

    data.ox = (buf[0] << 8) | buf[1];
    data.red = (buf[2] << 8) | buf[3];

    return data;
}

// Function to convert OX value to CO concentration in ppm
float convert_ox_to_ppm(uint16_t ox_value) {
    // Calibration parameters (example values, adjust based on your sensor's datasheet)
    float slope = 0.1;  // Example slope
    float intercept = 0.0; // Example intercept

    return (float)ox_value * slope + intercept;
}

// Function to log CO ppm value to file
int log_co_ppm(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CO log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);

    fclose(fp);
    return 0;
}

// Function to log alert to file
int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO ppm exceeded threshold: %.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);

    fclose(fp);
    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Convert OX value to CO concentration
        float co_ppm = convert_ox_to_ppm(sensor_data.ox);

        // Log CO ppm value
        if (log_co_ppm(co_ppm) != 0) {
            fprintf(stderr, "Error logging CO ppm value.\n");
        }

        // Check for alert condition
        if (co_ppm > CO_PPM_THRESHOLD) {
            // Log alert
            if (log_alert(co_ppm) != 0) {
                fprintf(stderr, "Error logging alert.\n");
            }
        }

        // Wait for the next reading
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

