#include <pigpio.h>

// Define GPIO pins for I2C emulation
#define SDA_PIN 2
#define SCL_PIN 3

// Define I2C address of IMP23ABSU (example address, check datasheet)
#define IMP23ABSU_ADDR 0x48 // Example address, replace with actual address

// Define register addresses for reading data (example, check datasheet)
#define DATA_REG_LSB 0x00
#define DATA_REG_MSB 0x01

// Define sampling interval (100ms)
#define SAMPLE_INTERVAL_MS 100

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Structure to hold I2C state
typedef struct {
    int sda_pin;
    int scl_pin;
    int sda_level;
    int scl_level;
} i2c_state_t;

i2c_state_t i2c_state = {SDA_PIN, SCL_PIN, 0, 0};

// Function prototypes
int i2c_read_register(int handle, int reg);
float read_microphone(int handle);
float calculate_average(float mic1, float mic2);
void log_data(float avg_level);
void signal_handler(int signal);
int i2c_init();
void i2c_close(int handle);

// I2C read register function (bit-banged)
int i2c_read_register(int handle, int reg) {
    int data = 0;
    int i;

    // Send register address
    for (i = 7; i >= 0; i--) {
        int bit = (reg >> i) & 1;
        gpioWrite(i2c_state.sda_pin, bit);
        gpioDelay(1); // Small delay
        gpioWrite(i2c_state.scl_pin, 1);
        gpioDelay(1); // Small delay
        gpioWrite(i2c_state.scl_pin, 0);
        gpioDelay(1); // Small delay
    }

    // Read data (LSB first)
    for (i = 0; i < 8; i++) {
        gpioWrite(i2c_state.sda_pin, 1); // Release SDA
        gpioSetMode(i2c_state.sda_pin, PI_INPUT); // Set as input
        gpioDelay(1); // Small delay
        gpioWrite(i2c_state.scl_pin, 1);
        gpioDelay(1); // Small delay
        data |= (gpioRead(i2c_state.sda_pin) << i);
        gpioWrite(i2c_state.scl_pin, 0);
        gpioDelay(1); // Small delay
    }

    return data;
}

// Function to read microphone data
float read_microphone(int handle) {
    int lsb, msb;
    int raw_value;
    float voltage;
    float db_level;

    lsb = i2c_read_register(handle, DATA_REG_LSB);
    msb = i2c_read_register(handle, DATA_REG_MSB);

    if (lsb == -1 || msb == -1) {
        fprintf(stderr, "Error reading microphone data\n");
        return -999.0;
    }

    raw_value = (msb << 8) | lsb;

    // Convert raw value to voltage (example, adjust based on ADC resolution)
    voltage = (float)raw_value / 4095.0 * 3.3; // Assuming 12-bit ADC and 3.3V reference

    // Convert voltage to dB SPL (example, adjust based on microphone sensitivity)
    db_level = 20 * log10(voltage / 0.00002); // Assuming 20uV/Pa sensitivity

    return db_level;
}

// Function to calculate the average of two microphone readings
float calculate_average(float mic1, float mic2) {
    return (mic1 + mic2) / 2.0;
}

// Function to log data to a file
void log_data(float avg_level) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, avg_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// I2C initialization function
int i2c_init() {
    // Set GPIO pins as outputs
    gpioSetMode(i2c_state.sda_pin, PI_OUTPUT);
    gpioSetMode(i2c_state.scl_pin, PI_OUTPUT);

    // Initialize SDA and SCL to high
    gpioWrite(i2c_state.sda_pin, 1);
    gpioWrite(i2c_state.scl_pin, 1);

    return 0; // Return 0 for success, -1 for failure
}

// I2C close function
void i2c_close(int handle) {
    // No explicit I2C close function in pigpio, but we can reset the pins
    gpioWrite(i2c_state.sda_pin, 0);
    gpioWrite(i2c_state.scl_pin, 0);
    gpioSetMode(i2c_state.sda_pin, PI_INPUT);
    gpioSetMode(i2c_state.scl_pin, PI_INPUT);
}

int main() {
    int handle;
    float mic1_level, mic2_level, avg_level;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (i2c_init() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read microphone data
        mic1_level = read_microphone(0); // Handle is not used in bit-banged I2C
        mic2_level = read_microphone(0); // Handle is not used in bit-banged I2C

        // Calculate average
        avg_level = calculate_average(mic1_level, mic2_level);

        // Log data
        log_data(avg_level);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup
    i2c_close(0); // Handle is not used in bit-banged I2C
    fclose(log_file);
    gpioTerminate();

    return 0;
}

