#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define LED_PIN 27
#define CE0_PIN 8
#define CE1_PIN 9
#define MISO_PIN 9
#define MOSI_PIN 10
#define SCLK_PIN 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADC parameters
#define ADC_CHANNEL_0 0
#define ADC_CHANNEL_1 1

// Define RMS threshold
#define RMS_THRESHOLD 500

// Define LED on time
#define LED_ON_TIME 500 // milliseconds

// Define sampling window
#define SAMPLE_WINDOW 100 // milliseconds
#define SAMPLES_PER_CHANNEL (SAMPLE_WINDOW / 1) // 1 ms per sample

// Global variables
int spi_handle_0, spi_handle_1;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold audio data
typedef struct {
    int16_t mic1_data[SAMPLES_PER_CHANNEL];
    int16_t mic2_data[SAMPLES_PER_CHANNEL];
} audio_window_t;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_adc(int channel);
double calculate_rms(int16_t *data, int num_samples);
int log_data(double rms_mic1, double rms_mic2);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        return -1;
    }
    gpioWrite(LED_PIN, 0); // Turn LED off initially
    return 0;
}

// Function to initialize SPI communication
int initialize_spi() {
    spi_handle_0 = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle_0 < 0) {
        fprintf(stderr, "Error opening SPI channel 0: %d\n", spi_handle_0);
        return -1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle_1 < 0) {
        fprintf(stderr, "Error opening SPI channel 1: %d\n", spi_handle_1);
        spiClose(spi_handle_0);
        return -1;
    }

    return 0;
}

// Function to read data from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (channel == 0) {
        if (spiXfer(spi_handle_0, tx_buffer, rx_buffer, 3) != 0) {
            fprintf(stderr, "Error reading SPI channel 0\n");
            return -1;
        }
    } else {
        if (spiXfer(spi_handle_1, tx_buffer, rx_buffer, 3) != 0) {
            fprintf(stderr, "Error reading SPI channel 1\n");
            return -1;
        }
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS level
double calculate_rms(int16_t *data, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)data[i] * data[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to log data to file
int log_data(double rms_mic1, double rms_mic2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, rms_mic1, rms_mic2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    control_led(0); // Turn off LED
    if (spi_handle_0 >= 0) spiClose(spi_handle_0);
    if (spi_handle_1 >= 0) spiClose(spi_handle_1);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI communication
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    audio_window_t audio_window;
    int sample_count = 0;

    printf("Starting audio sampling...\n");

    while (program_running) {
        // Read ADC values
        int adc_value_0 = read_adc(ADC_CHANNEL_0);
        int adc_value_1 = read_adc(ADC_CHANNEL_1);

        if (adc_value_0 < 0 || adc_value_1 < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(10); // Small delay before retrying
            continue;
        }

        // Store ADC values in the audio window
        audio_window.mic1_data[sample_count] = (int16_t)adc_value_0;
        audio_window.mic2_data[sample_count] = (int16_t)adc_value_1;

        sample_count++;

        // Process audio data when the window is full
        if (sample_count == SAMPLES_PER_CHANNEL) {
            // Calculate RMS levels
            double rms_mic1 = calculate_rms(audio_window.mic1_data, SAMPLES_PER_CHANNEL);
            double rms_mic2 = calculate_rms(audio_window.mic2_data, SAMPLES_PER_CHANNEL);

            // Log data
            if (log_data(rms_mic1, rms_mic2) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Check for high-level threshold
            if (rms_mic1 > RMS_THRESHOLD || rms_mic2 > RMS_THRESHOLD) {
                control_led(1); // Turn on LED
                gpioDelay(LED_ON_TIME); // Keep LED on for specified time
                control_led(0); // Turn off LED
            }

            sample_count = 0; // Reset sample count
        }

        gpioDelay(1); // Sample every 1 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

