#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define SAMPLE_RATE 10 // Hz
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0 // Amperes
#define SENSOR_PRESENT_THRESHOLD 1000 // Raw ADC value
#define SENSOR_ABSENT_THRESHOLD 100 // Raw ADC value

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int *raw_value);
float convert_to_current(int raw_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    float current_threshold;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .ads1115_address = ADS1115_ADDR,
    .led_gpio = LED_GPIO,
    .current_threshold = CURRENT_THRESHOLD
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_value;
    float current;
    float average_current;
    int sensor_present = 0; // Flag to track sensor presence

    // Main loop
    while (!terminate) {
        // Read raw ADC value
        if (read_ads1115(&raw_value) != 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            cleanup();
            return 1;
        }

        // Check for sensor presence/absence
        if (raw_value > SENSOR_PRESENT_THRESHOLD) {
            sensor_present = 1;
        } else if (raw_value < SENSOR_ABSENT_THRESHOLD && sensor_present) {
            sensor_present = 0;
            // Optionally, you could reset the buffer here
        }

        // Convert raw value to current
        current = convert_to_current(raw_value);

        // Update circular buffer
        update_circular_buffer(current);

        // Calculate average current
        average_current = calculate_average_current();

        // Control LED based on average current
        if (sensor_present && average_current > config.current_threshold) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        // Delay to achieve desired sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V, 128 SPS, continuous conversion
    uint16_t config_value = 0x4003; // Single-ended A0, 4.096V, 128 SPS, Continuous conversion
    uint8_t write_buffer[3];
    write_buffer[0] = CONFIG_REG;
    write_buffer[1] = (config_value & 0xFF);
    write_buffer[2] = (config_value >> 8);

    int result = i2cWriteDevice(i2c_handle, (char *)write_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int *raw_value) {
    char read_buffer[2];
    int result = i2cReadDevice(i2c_handle, read_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from conversion register: %d\n", result);
        return 1;
    }

    *raw_value = (read_buffer[0] << 8) | read_buffer[1];
    return 0;
}

// Convert raw ADC value to current (Amperes)
float convert_to_current(int raw_value) {
    // Assuming a sensitivity of 0.1 mV/A and a gain of 1
    // The ADS1115 has a 16-bit resolution, so the full-scale range is 2^15
    float voltage = (raw_value * 4.096) / 32768.0; // Convert to voltage
    float current = voltage / 0.0001; // Convert voltage to current (A)
    return current;
}

// Update circular buffer with new current value
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current from circular buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED (on/off)
void control_led(int on) {
    gpioWrite(config.led_gpio, on);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

