#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID 0x92
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Expected sensor ID
#define TCS34725_ID_VALUE 0x44

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init(int i2c_handle);
int tcs34725_read_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, exiting gracefully...\n", signal);
}

// TCS34725 initialization function
int tcs34725_init(int i2c_handle) {
    int retries = 3;
    int status;

    // Enable the sensor
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03); // Power on and enable RGBC
        if (status == 0) break;
        fprintf(stderr, "Error enabling sensor (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (retries == 0) return -1;

    // Set integration time (ATIME)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5); // 101ms integration time
        if (status == 0) break;
        fprintf(stderr, "Error setting integration time (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (retries == 0) return -1;

    // Set gain (AGAIN)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01); // 4x gain
        if (status == 0) break;
        fprintf(stderr, "Error setting gain (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (retries == 0) return -1;

    // Verify sensor ID
    retries = 3;
    int sensor_id = -1;
    while (retries > 0) {
        sensor_id = i2cReadByteData(i2c_handle, TCS34725_ID);
        if (sensor_id >= 0) break;
        fprintf(stderr, "Error reading sensor ID (attempt %d): %d\n", 4 - retries, sensor_id);
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (retries == 0) return -1;

    if (sensor_id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", sensor_id, TCS34725_ID_VALUE);
        return -1;
    }

    return 0;
}

// TCS34725 data reading function
int tcs34725_read_data(int i2c_handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
        if (status >= 0) {
            *clear = (uint16_t)status;
            break;
        }
        fprintf(stderr, "Error reading clear data (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
        if (status >= 0) {
            *red = (uint16_t)status;
            break;
        }
        fprintf(stderr, "Error reading red data (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
        if (status >= 0) {
            *green = (uint16_t)status;
            break;
        }
        fprintf(stderr, "Error reading green data (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
        if (status >= 0) {
            *blue = (uint16_t)status;
            break;
        }
        fprintf(stderr, "Error reading blue data (attempt %d): %d\n", 4 - retries, status);
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (retries == 0) return -1;

    return 0;
}

// Data logging function
int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
