        int sensor1_value = read_mcp3008(SENSOR1_CHANNEL);
        int sensor2_value = read_mcp3008(SENSOR2_CHANNEL);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        } else {
            log_data(sensor1_value, sensor2_value);
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL, 0); // Sleep for 5 seconds
    }

