#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_amps(int adc_value);
void log_current(float current);
void overcurrent_protection(float current);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, retries = 0;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    while (retries < MAX_RETRIES) {
        count = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (count == 3) {
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d), retrying...\n", retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "SPI read failed after %d retries. Exiting.\n", MAX_RETRIES);
    terminate = 1; // Signal termination
    return -1; // Indicate failure
}

// Function to convert ADC value to amperes
float convert_to_amps(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and that the ADC range is 0-1023 (10-bit ADC)
    // and the current range is 0-20 Amperes
    return (float)adc_value * (20.0 / 1023.0);
}

// Function to log current to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle overcurrent protection
void overcurrent_protection(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        printf("Overcurrent detected: %.2f A\n", current);
        fprintf(log_file, "Overcurrent detected: %.2f A\n", current);
        fflush(log_file);
        gpioWrite(MOTOR_SHUTDOWN_PIN, 0); // Disable motor
        gpioDelay(1000000); // Wait 1 second
        gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Enable motor
        printf("Motor re-enabled\n");
    }
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set motor shutdown pin as output
    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Enable motor initially

    // Open log file
    log_file = fopen("current_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float current = convert_to_amps(adc_value);
            log_current(current);
            overcurrent_protection(current);
        } else {
            fprintf(stderr, "Failed to read ADC value. Exiting.\n");
            break; // Exit loop if ADC read fails
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Ensure motor is enabled on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

