        return -1;
    }
    return 0;
}

// Read from ADS1115 ADC
int read_ads1115(int channel) {
    int count = 0;
    int result;
    char config[3];

    // Configure ADS1115 for single-ended read
    config[0] = 0x01; // Configuration register
    config[1] = 0xC3 | (channel << 1); // Single-ended, 4.096V, 128 SPS, start single conversion
    config[2] = 0x83 | (channel << 1); // Single-ended, 4.096V, 128 SPS, start single conversion

    while (count < 3) {
        if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
            fprintf(stderr, "I2C write error (config), retry %d\n", count + 1);
            gpioDelay(10000); // 10ms delay
            count++;
            continue;
        }

        gpioDelay(10000); // Wait for conversion (at least 8ms for 128 SPS)

        result = i2cReadWordData(i2c_handle, 0x00); // Read conversion register
        if (result >= 0) {
            // Success, return the result
            return result;
        } else {
            fprintf(stderr, "I2C read error (data), retry %d\n", count + 1);
            gpioDelay(10000); // 10ms delay
