    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read pressure and temperature values
        int pressure_adc = read_ads1115(0); // Channel 0 for pressure
        int temperature_adc = read_ads1115(1); // Channel 1 for temperature

        if (pressure_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "Error reading ADC values, skipping this iteration\n");
            gpioDelay(1000000); // Wait 1 second
            continue;
        }

        // Decode SENT signals (Placeholder - needs actual MLX90834 SENT decoding logic)
        int decoded_pressure = decode_sent(pressure_adc);
        int decoded_temperature = decode_sent(temperature_adc);

        // Convert ADC values to pressure and temperature
        float pressure_kPa = convert_pressure(decoded_pressure);
        float temperature_C = convert_temperature(decoded_temperature);

        // Print the values
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure_kPa, temperature_C);

        // Control the LED
        control_led(pressure_kPa);

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

