#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_FILE "methane_log.txt"
#define ALARM_THRESHOLD 1000.0 // ppm
#define SLEEP_DURATION 1 // seconds

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(float ppm);
void check_alarm(float ppm);
void signal_handler(int signal);
int setup();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    const char *log_file;
    float alarm_threshold;
    int sleep_duration;
} Config;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to methane concentration (ppm)
float adc_to_ppm(int adc_value) {
    // Assuming a linear relationship between ADC value and methane concentration
    // You'll need to calibrate this based on your sensor's datasheet
    // Example: 0 ADC = 0 ppm, 1023 ADC = 2000 ppm
    float ppm = (float)adc_value * (2000.0 / 1023.0);
    return ppm;
}

// Function to log data to file
void log_data(float ppm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[30];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to check for alarm condition
void check_alarm(float ppm) {
    if (ppm > ALARM_THRESHOLD) {
        fprintf(stderr, "ALARM: Methane concentration exceeds %.2f ppm (%.2f ppm)\n", ALARM_THRESHOLD, ppm);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Setup function to initialize pigpio and SPI
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Continue to the next iteration, don't exit
            sleep(SLEEP_DURATION);
            continue;
        }

        // Convert ADC value to methane concentration
        float ppm = adc_to_ppm(adc_value);

        // Log data
        log_data(ppm);

        // Check for alarm
        check_alarm(ppm);

        // Sleep for a while
        sleep(SLEEP_DURATION);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

