#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define SAMPLE_RATE 1.0 // Hz
#define PRESSURE_MIN 0.0 // kPa
#define PRESSURE_MAX 100.0 // kPa
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    double sample_rate;
    double pressure_min;
    double pressure_max;
    char *log_file_name;
} Config;

// Function prototypes
int init_i2c(int bus, int addr);
int read_ads1115(int handle, int channel);
double convert_to_pressure(int adc_value);
int validate_pressure(double pressure);
char* get_iso8601_timestamp();
int log_pressure(double pressure, char *timestamp);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read from ADS1115
int read_ads1115(int handle, int channel) {
    // Configure ADS1115 for single-ended reading on the specified channel
    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x40 | (channel << 1); // Start single conversion, AINx, +/-4.096V
    config[2] = 0x83; // 128 SPS, disable comparator

    if (i2cWriteDevice(handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

