    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, ADS1115_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_ads1115(i2c_handle, 0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to pressure
        double pressure = convert_to_pressure(adc_value);

        // Validate pressure reading
        if (validate_pressure(pressure) == 0) {
            // Get timestamp
            char *timestamp = get_iso8601_timestamp();

            // Log pressure reading
            if (log_pressure(pressure, timestamp) != 0) {
                fprintf(stderr, "Error logging pressure reading\n");
            }

            free(timestamp); // Free the allocated memory
        }

        // Wait for the next sample
        gpioDelay((int)(1000000.0 / SAMPLE_RATE)); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

