#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with your email

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
SensorData process_sensor_data(int adc_value);
int log_data(SensorData data);
int send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3208 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct the SPI message to send to the MCP3208
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to process the raw ADC value and convert it to humidity and temperature
SensorData process_sensor_data(int adc_value) {
    SensorData data;

    // HIH-4602-A datasheet values (example, adjust based on your sensor)
    float VSUPPLY = 3.3; // Supply voltage
    float VOUT_HUMIDITY = 0.8 * VSUPPLY; // Voltage at 0% humidity
    float VOUT_TEMP = 0.3 * VSUPPLY; // Voltage at 25°C
    float R_HUMIDITY = 10000.0; // Humidity resistor value
    float R_TEMP = 10000.0; // Temperature resistor value
    float TEMP_OFFSET = 25.0; // Temperature offset

    // Convert ADC value to voltage (assuming 10-bit ADC)
    float voltage = (float)adc_value / 4095.0 * VSUPPLY;

    // Calculate humidity (example formula, adjust based on datasheet)
    data.humidity = (voltage - VOUT_HUMIDITY) / (VSUPPLY - VOUT_HUMIDITY) * 100.0;
    if (data.humidity < 0.0) data.humidity = 0.0;
    if (data.humidity > 100.0) data.humidity = 100.0;

    // Calculate temperature (example formula, adjust based on datasheet)
    data.temperature = TEMP_OFFSET + (voltage - VOUT_TEMP) / (VSUPPLY - VOUT_TEMP) * 50.0; // Assuming 50°C range

    return data;
}

// Function to log the data to a file
int log_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.humidity, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to send an email alert if the humidity exceeds the threshold
int send_email_alert(float humidity) {
    char command[256];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(command, sizeof(command), "echo \"Subject: Humidity Alert\n\nHumidity exceeded threshold at %s. Current humidity: %.2f%%\" | ssmtp %s", timestamp, humidity, EMAIL_RECIPIENT);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error sending email\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Process sensor data
        SensorData data = process_sensor_data(adc_value);

        // Log the data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Check humidity threshold and send email alert
        if (data.humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(data.humidity) != 0) {
                fprintf(stderr, "Error sending email alert\n");
            }
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

