#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CE_PIN 8 // GPIO8 (gpiochip4, BCM)
#define TEMP_LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// TMP36 Constants
#define TMP36_VREF 3.3
#define TMP36_OFFSET 0.5
#define TMP36_SCALE 0.01

// Global Variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int read_adc(int channel);
float adc_to_celsius(int adc_value);
int log_temperature(float temperature);
void signal_handler(int signal);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read ADC Value
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3208 Command: Start bit (1), Single-ended (1), Channel (3 bits), Don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended + channel
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (12 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC Value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (float)adc_value / 4095.0 * TMP36_VREF;
    float temperature = (voltage - TMP36_OFFSET) / TMP36_SCALE;
    return temperature;
}

// Log Temperature to File
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file exists and is empty
    FILE *fp = fopen(TEMP_LOG_FILE, "r");
    int is_new_file = 0;
    if (fp == NULL) {
        is_new_file = 1;
    } else {
        fseek(fp, 0, SEEK_END);
        long file_size = ftell(fp);
        if (file_size == 0) {
            is_new_file = 1;
        }
        fclose(fp);
    }

    log_file = fopen(TEMP_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    if (is_new_file) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fclose(log_file);
    return 0;
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CE pin as output
    gpioSetMode(CE_PIN, PI_OUTPUT);
    gpioWrite(CE_PIN, 1); // Deactivate CE initially

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Activate CE
        gpioWrite(CE_PIN, 0);

        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
        } else {
            // Convert to Celsius
            float temperature = adc_to_celsius(adc_value);

            // Validate temperature
            if (temperature >= -40.0 && temperature <= 125.0) {
                // Log temperature
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Error logging temperature\n");
                }
            } else {
                fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            }
        }

        // Deactivate CE
        gpioWrite(CE_PIN, 1);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    close(spi_fd);
    gpioWrite(CE_PIN, 1); // Ensure CE is deactivated
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

