// I2C address of the ICP-10125 sensor
#define I2C_ADDR 0x69

// I2C bus number (1 for Raspberry Pi Zero W)
#define I2C_BUS 1

// Measurement command (refer to ICP-10125 datasheet)
#define MEASURE_CMD 0x24 // Example command, adjust as needed

// File to log data to
#define LOG_FILE "environmental_data.csv"

// Global variables for graceful shutdown
int i2c_handle = -1;
FILE *log_file = NULL;

// Calibration parameters (replace with actual values from sensor EEPROM)
float T_cal[8]; // Temperature calibration coefficients
float P_cal[8]; // Pressure calibration coefficients

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
int write_sensor_command(uint8_t command);
int parse_sensor_data(uint8_t *data, float *temperature, float *pressure);
int log_data(float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int signal);
int read_calibration_data();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C communication
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data from the sensor
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        gpioTerminate();
        i2cClose(i2c_handle);
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t sensor_data[6];
        sensor_data_t readings;

        // Trigger measurement
        if (write_sensor_command(MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue; // Retry
        }

        // Wait for conversion (adjust delay as needed)
        gpioDelay(10); // 10 ms delay

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Retry
        }

        // Parse sensor data
        if (parse_sensor_data(sensor_data, &readings.temperature, &readings.pressure) != 0) {
            fprintf(stderr, "Failed to parse sensor data\n");
            continue; // Retry
        }

        // Log data to file
        if (log_data(readings.temperature, readings.pressure) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Display data on console
        display_data(readings.temperature, readings.pressure);

        // Wait for 5 seconds
        gpioDelay(5000); // 5000 ms delay
    }

    return 0;
}

