#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel assignments
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Define noise cancellation parameters
#define NOISE_CANCELLATION_FACTOR 0.5

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int mic1_sample;
    int mic2_sample;
    int cancelled_sample;
} AudioData;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
int apply_noise_cancellation(int mic1_sample, int mic2_sample);
void print_audio_data(AudioData data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Apply noise cancellation
int apply_noise_cancellation(int mic1_sample, int mic2_sample) {
    return (int)((mic1_sample - NOISE_CANCELLATION_FACTOR * mic2_sample) + 0.5); // Rounding
}

// Print audio data to CSV format
void print_audio_data(AudioData data) {
    printf("%d,%d,%d\n", data.mic1_sample, data.mic2_sample, data.cancelled_sample);
}

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read audio samples from microphones
        int mic1_sample = read_mcp3008(MIC1_CHANNEL);
        int mic2_sample = read_mcp3008(MIC2_CHANNEL);

        if (mic1_sample == -1 || mic2_sample == -1) {
            fprintf(stderr, "Error reading microphones, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Apply noise cancellation
        int cancelled_sample = apply_noise_cancellation(mic1_sample, mic2_sample);

        // Store audio data
        AudioData data = {mic1_sample, mic2_sample, cancelled_sample};

        // Print audio data
        print_audio_data(data);

        // Delay for a short period
        gpioDelay(10000); // 10ms delay
    }

    // Clean up resources before exiting
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

