        fprintf(stderr, "Error: Failed to open water_levels.json\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket to JSON file
    fprintf(json_file, "[\n");
    fflush(json_file);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        // Calculate water level percentage
        float percentage = calculate_water_level(adc_value);

        // Log water level to JSON file
        log_water_level(percentage);

