#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <stdint.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_calibration;
    int max_calibration;
    int moisture_threshold;
    int logging_interval;
    char email_address[256];
    char msmtp_config_path[256];
} Config;

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static Config config;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename, Config *config);
int spi_init(int channel);
int read_adc(int channel);
float calculate_moisture(int adc_value, int min_calibration, int max_calibration);
int log_data(float moisture_percent);
int send_email(float moisture_percent);
void signal_handler(int sig);
void cleanup();

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strcmp(key, "adc_channel") == 0) {
            config->adc_channel = atoi(value);
        } else if (strcmp(key, "min_calibration") == 0) {
            config->min_calibration = atoi(value);
        } else if (strcmp(key, "max_calibration") == 0) {
            config->max_calibration = atoi(value);
        } else if (strcmp(key, "moisture_threshold") == 0) {
            config->moisture_threshold = atoi(value);
        } else if (strcmp(key, "logging_interval") == 0) {
            config->logging_interval = atoi(value);
        } else if (strcmp(key, "email_address") == 0) {
            strncpy(config->email_address, value, sizeof(config->email_address) - 1);
            config->email_address[sizeof(config->email_address) - 1] = '\0';
        } else if (strcmp(key, "msmtp_config_path") == 0) {
            strncpy(config->msmtp_config_path, value, sizeof(config->msmtp_config_path) - 1);
            config->msmtp_config_path[sizeof(config->msmtp_config_path) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize SPI
int spi_init(int channel) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.%d", channel);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = 500000; // 500 kHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read ADC value
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 500000; // 500 kHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value, int min_calibration, int max_calibration) {
    float moisture_percent = 100.0 - ((float)(adc_value - min_calibration) / (float)(max_calibration - min_calibration) * 100.0);
    if (moisture_percent < 0.0) moisture_percent = 0.0;
    if (moisture_percent > 100.0) moisture_percent = 100.0;
    return moisture_percent;
}

// Function to log data to file
int log_data(float moisture_percent) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percent);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to send email alert
int send_email(float moisture_percent) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char command[512];
    snprintf(command, sizeof(command), "msmtp -C %s %s", config.msmtp_config_path, config.email_address);

    FILE *pipe = popen(command, "w");
    if (pipe == NULL) {
        perror("Error opening pipe to msmtp");
        return -1;
    }

    fprintf(pipe, "To: %s\n", config.email_address);
    fprintf(pipe, "Subject: Plant Moisture Alert\n\n");
    fprintf(pipe, "Plant moisture is below threshold at %s. Moisture: %.2f%%\n", timestamp, moisture_percent);

    int status = pclose(pipe);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", status);
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    // Set default values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_calibration = 300;
    config.max_calibration = 800;
    config.moisture_threshold = 30;
    config.logging_interval = 60;
    strcpy(config.email_address, "");
    strcpy(config.msmtp_config_path, "/etc/msmtprc");

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:x:t:i:e:f:")) != -1) {
        switch (opt) {
            case 'c':
                config.spi_channel = atoi(optarg);
                break;
            case 'a':
                config.adc_channel = atoi(optarg);
                break;
            case 'm':
                config.min_calibration = atoi(optarg);
                break;
            case 'x':
                config.max_calibration = atoi(optarg);
                break;
            case 't':
                config.moisture_threshold = atoi(optarg);
                break;
            case 'i':
                config.logging_interval = atoi(optarg);
                break;
            case 'e':
                strncpy(config.email_address, optarg, sizeof(config.email_address) - 1);
                config.email_address[sizeof(config.email_address) - 1] = '\0';
                break;
            case 'f':
                strncpy(config.msmtp_config_path, optarg, sizeof(config.msmtp_config_path) - 1);
                config.msmtp_config_path[sizeof(config.msmtp_config_path) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_calibration] [-x max_calibration] [-t moisture_threshold] [-i logging_interval] [-e email_address] [-f msmtp_config_path]\n", argv[0]);
                return 1;
        }
    }

    // Read configuration from file (optional)
    // if (read_config("plant_monitor.conf", &config) != 0) {
    //     fprintf(stderr, "Using default configuration.\n");
    // }

    // Initialize SPI
    if (spi_init(config.spi_channel) != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", config.logging_interval);
            sleep(config.logging_interval);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percent = calculate_moisture(adc_value, config.min_calibration, config.max_calibration);

        // Log data
        log_data(moisture_percent);

        // Check moisture threshold and send email alert
        if (moisture_percent < config.moisture_threshold) {
            if (send_email(moisture_percent) != 0) {
                fprintf(stderr, "Error sending email alert.\n");
            }
        }

        printf("Moisture: %.2f%%\n", moisture_percent);

        // Wait for the next logging interval
        sleep(config.logging_interval);
    }

    // Cleanup and exit
    cleanup();
    printf("Plant monitoring stopped.\n");
    return 0;
}

