        char *endptr;
        long interval = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || interval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default (1 second).\n");
        } else {
            sample_interval = (int)interval;
        }
    }

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Sampling every %d seconds.\n", sample_interval);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture = calculate_moisture(adc_value);
            log_data(adc_value, moisture);
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", sample_interval);
            log_data(-1, -1.0); // Log error
        }

        sleep(sample_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

