            fprintf(stderr, "Warning: Pressure out of range: %.2f kPa\n", pressure);
        }

        // Log pressure reading
        log_pressure(pressure);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    cleanup();
    printf("Pressure sensor monitoring stopped.\n");

    return 0;
}

