#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define PART_ID_REG 0x00
#define SPO2_REG 0x08
#define HEART_RATE_REG 0x09
#define SPO2_THRESHOLD 95.0
#define HEART_RATE_THRESHOLD 100.0
#define LOG_FILE "health_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *spo2, float *heart_rate);
void log_data(float spo2, float heart_rate);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Error logging function
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    fprintf(stderr, "ERROR: %s\n", message);
}

// Initialize the MAX30102 sensor
int initialize_sensor() {
    // Check Part ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        log_error("Failed to read Part ID register.");
        return -1;
    }
    if (part_id != 0x15) {
        log_error("Incorrect Part ID. Sensor not present.");
        return -1;
    }
    printf("MAX30102 Part ID: 0x%02X\n", part_id);

    // Configure sensor (example configuration - adjust as needed)
    // FIFO configuration
    if (i2cWriteByteData(i2c_handle, 0x08, 0x00) < 0) {
        log_error("Failed to write FIFO configuration.");
        return -1;
    }

    // Mode configuration
    if (i2cWriteByteData(i2c_handle, 0x09, 0x03) < 0) {
        log_error("Failed to write mode configuration.");
        return -1;
    }

    // SPO2 configuration
    if (i2cWriteByteData(i2c_handle, 0x0A, 0x27) < 0) {
        log_error("Failed to write SPO2 configuration.");
        return -1;
    }

    // LED pulse amplitude
    if (i2cWriteByteData(i2c_handle, 0x0C, 0x7F) < 0) {
        log_error("Failed to write LED pulse amplitude.");
        return -1;
    }

    // Sample rate
    if (i2cWriteByteData(i2c_handle, 0x0E, 0x40) < 0) {
        log_error("Failed to write sample rate.");
        return -1;
    }

    return 0;
}

// Read SpO2 and heart rate data from the sensor
int read_sensor_data(float *spo2, float *heart_rate) {
    int spo2_raw = i2cReadByteData(i2c_handle, SPO2_REG);
    int heart_rate_raw = i2cReadByteData(i2c_handle, HEART_RATE_REG);

    if (spo2_raw < 0 || heart_rate_raw < 0) {
        log_error("Failed to read sensor data.");
        return -1;
    }

    *spo2 = (float)spo2_raw; // Example conversion, adjust as needed
    *heart_rate = (float)heart_rate_raw; // Example conversion, adjust as needed

    return 0;
}

// Log data to file if thresholds are exceeded
void log_data(float spo2, float heart_rate) {
    if (spo2 < SPO2_THRESHOLD || heart_rate > HEART_RATE_THRESHOLD) {
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            perror("Error opening log file");
            return;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] SpO2: %.2f%%, Heart Rate: %.2f BPM\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, spo2, heart_rate);
        fclose(fp);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float spo2, heart_rate;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&spo2, &heart_rate) == 0) {
            printf("SpO2: %.2f%%, Heart Rate: %.2f BPM\n", spo2, heart_rate);
            log_data(spo2, heart_rate);
        } else {
            log_error("Failed to read sensor data in main loop.");
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

