#define LOG_FILE "/var/log/door_events.log"
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define SAMPLE_DELAY_MS 200
#define RELAY_PULSE_MS 3000
#define THRESHOLD 500 // Example threshold, adjust based on calibration

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
int ads1115_read(int fd);
int calibrate_sensor(int fd);
int check_distance(int adc_value, int threshold);
int control_relay(int gpio_pin, int state);
int read_reed_sensor(int gpio_pin);
int log_event(const char *message);
void signal_handler(int signal);

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// I2C write function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// ADS1115 read function
int ads1115_read(int fd) {
    int16_t raw_value;
    int retries = 3;

    while (retries > 0) {
        raw_value = i2c_read_word(fd, CONVERSION_REG);
        if (raw_value >= 0) {
            return raw_value;
        } else {
            fprintf(stderr, "ADS1115 read failed, retrying...\n");
            log_event("ADS1115 read failed, retrying...");
            usleep(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "ADS1115 read failed after multiple retries.\n");
    log_event("ADS1115 read failed after multiple retries.");
    return -1; // Indicate failure
}

// Sensor calibration function
int calibrate_sensor(int fd) {
    int sum = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int adc_value = ads1115_read(fd);
        if (adc_value < 0) {
            fprintf(stderr, "Calibration failed: ADS1115 read error.\n");
            log_event("Calibration failed: ADS1115 read error.");
            return -1;
        }
        sum += adc_value;
        usleep(CALIBRATION_DELAY_MS * 1000); // Delay in microseconds
    }
    return sum / CALIBRATION_SAMPLES;
}

// Distance check function
int check_distance(int adc_value, int threshold) {
    return adc_value < threshold;
}

// Relay control function
int control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Reed sensor read function
int read_reed_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Logging function
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

