    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V, continuous conversion, 128 SPS
    uint16_t config = 0x4003; // Single-ended A0, 4.096V, Continuous, 128 SPS
    if (i2c_write_word(i2c_fd, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Calibrate the sensor
    threshold = calibrate_sensor(i2c_fd);
    if (threshold < 0) {
        fprintf(stderr, "Sensor calibration failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    printf("Calibration complete. Threshold: %d\n", threshold);

    // Set GPIO modes
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetMode(GPIO_REED, PI_INPUT);
    gpioSetPullUpDown(GPIO_REED, PI_PUD_UP); // Enable pull-up resistor

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = ads1115_read(i2c_fd);
        if (adc_value >= 0) {
            if (check_distance(adc_value, threshold)) {
                printf("Distance below threshold. Activating relay.\n");
                log_event("Distance below threshold. Activating relay.");
                control_relay(GPIO_RELAY, 1); // Activate relay
                usleep(RELAY_PULSE_MS * 1000); // Pulse for 3 seconds
                control_relay(GPIO_RELAY, 0); // Deactivate relay

                // Read reed sensor
                int reed_state = read_reed_sensor(GPIO_REED);
                if (reed_state == 0) {
                    log_event("door opened");
                } else {
                    log_event("door not opened");
                }
            }
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
            log_event("Failed to read ADC value.");
        }
        usleep(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
    }

