#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for chip select
#define CS0 8
#define CS1 7
#define CS2 25

// SPI channel
#define SPI_CHANNEL 0

// SPI baud rate
#define SPI_BAUD 1000000

// SPI mode
#define SPI_MODE 0

// File name for logging
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int chip_select_pin, int channel);
void log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
int setup();
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud;
    int mode;
} spi_config_t;

// Function to read data from MCP3008 ADC
int read_mcp3008(int chip_select_pin, int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(chip_select_pin, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(chip_select_pin, 1); // Deselect the chip

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to log data to CSV file
void log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Setup function to initialize pigpio and SPI
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure chip select pins as outputs
    gpioSetMode(CS0, PI_OUTPUT);
    gpioSetMode(CS1, PI_OUTPUT);
    gpioSetMode(CS2, PI_OUTPUT);

    // Set chip select pins high (inactive)
    gpioWrite(CS0, 1);
    gpioWrite(CS1, 1);
    gpioWrite(CS2, 1);

    // Open SPI channel
    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD, SPI_MODE};
    spi_handle = spiOpen(spi_config.channel, spi_config.baud, spi_config.mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Check if the file is newly created (empty) and write header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int sensor1_value = read_mcp3008(CS0, 0);
        int sensor2_value = read_mcp3008(CS1, 0);
        int sensor3_value = read_mcp3008(CS2, 0);

        // Log data
        log_data(log_file, sensor1_value, sensor2_value, sensor3_value);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

