    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Dummy read
        int dummy_read = i2cReadByte(i2c_fd);
        if (dummy_read < 0) {
            fprintf(stderr, "Dummy read failed: %d\n", dummy_read);
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Read AIN0
        int read_result = i2cReadByteData(i2c_fd, AIN0);
        if (read_result < 0) {
            fprintf(stderr, "Failed to read AIN0: %d\n", read_result);
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Print the read value
