#define GPIO_MOTOR_SHUTDOWN 27
#define THRESHOLD_GAUSS 500.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float magnetic_field_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_adc(int16_t *raw_value);
float convert_to_voltage(int16_t raw_value);
float convert_to_gauss(float voltage);
void update_circular_buffer(float gauss);
float calculate_rolling_average();
void control_motor_shutdown(float rolling_average);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    syslog(LOG_INFO, "I2C device opened successfully.");
    return 0;
}

// Read ADC value
int read_adc(int16_t *raw_value) {
    char config[3];
    // Configure ADS1115 for single-ended AIN0, 4.096V range, single conversion, 128 SPS
    config[0] = 0x01; // Configuration register address
