#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define MAX_ADC_VALUE 1023

// Rainfall intensity levels
typedef enum {
    NO_RAIN,
    SLIGHT_RAIN,
    MODERATE_RAIN,
    HEAVY_RAIN,
    TORRENTIAL_RAIN
} RainfallIntensity;

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
RainfallIntensity map_adc_to_intensity(int adc_value);
void log_data(int adc_value, RainfallIntensity intensity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map ADC value to rainfall intensity
RainfallIntensity map_adc_to_intensity(int adc_value) {
    if (adc_value < 200) {
        return NO_RAIN;
    } else if (adc_value < 400) {
        return SLIGHT_RAIN;
    } else if (adc_value < 600) {
        return MODERATE_RAIN;
    } else if (adc_value < 800) {
        return HEAVY_RAIN;
    } else {
        return TORRENTIAL_RAIN;
    }
}

// Function to log data to stdout
void log_data(int adc_value, RainfallIntensity intensity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    const char *intensity_str;
    switch (intensity) {
        case NO_RAIN:
            intensity_str = "No Rain";
            break;
        case SLIGHT_RAIN:
            intensity_str = "Slight Rain";
            break;
        case MODERATE_RAIN:
            intensity_str = "Moderate Rain";
            break;
        case HEAVY_RAIN:
            intensity_str = "Heavy Rain";
            break;
        case TORRENTIAL_RAIN:
            intensity_str = "Torrestrial Rain";
            break;
        default:
            intensity_str = "Unknown";
            break;
    }

    printf("%s, ADC Value: %d, Rainfall Intensity: %s\n", timestamp, adc_value, intensity_str);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            RainfallIntensity intensity = map_adc_to_intensity(adc_value);
            log_data(adc_value, intensity);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying...\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 1, 0); // Sleep for 1 second
    }

    // Close SPI channel and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

