#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1.0
#define BLINK_PERIOD 0.05

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adc(int *raw_value);
double convert_to_gauss(int raw_value);
void blink_led(double duration);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    double default_threshold;
} app_config_t;

app_config_t config = {I2C_BUS, ADS1115_ADDR, LED_GPIO, DEFAULT_THRESHOLD};

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_value;
    double gauss_value;

    // Main loop
    while (!terminate) {
        if (read_adc(&raw_value) == 0) {
            gauss_value = convert_to_gauss(raw_value);
            printf("Magnetic Field: %.2f Gauss\n", gauss_value);

            if (gauss_value > threshold) {
                blink_led(BLINK_DURATION);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V gain, continuous conversion
    char config_data[3];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x43; // 0b01000011  Single-ended AIN0, 4.096V, Continuous
    config_data[2] = 0x83; // 0b10000011  Default comparator settings

    int result = i2cWriteDevice(i2c_handle, config_data, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read ADC value from ADS1115
int read_adc(int *raw_value) {
    char reg = CONVERSION_REG;
    char data[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device for conversion register\n");
        return 1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return 1;
    }

    *raw_value = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw ADC value to Gauss
double convert_to_gauss(int raw_value) {
    // Assuming 4.096V gain and 16-bit ADC
    double voltage = (raw_value * 4.096) / 32768.0;
    // Conversion factor from SS49E datasheet (example, adjust as needed)
    // This is a placeholder, replace with the actual conversion factor
    double gauss_per_volt = 1000.0; // Example: 1000 Gauss/Volt
    return voltage * gauss_per_volt;
}

// Blink LED for a specified duration
void blink_led(double duration) {
    double start_time = time_time();
    while (time_time() - start_time < duration && !terminate) {
        gpioWrite(config.led_pin, 1);
        gpioDelay(BLINK_PERIOD * 1000); // Convert seconds to milliseconds
        gpioWrite(config.led_pin, 0);
        gpioDelay(BLINK_PERIOD * 1000);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    gpioWrite(config.led_pin, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

