#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL "soil_moisture"
#define MQTT_TOPIC_PUMP "pump_control"
#define MQTT_CLIENT_ID "soil_monitor"

// Global variables
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int pump_state);
void publish_moisture(float moisture_percentage);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void signal_handler(int sig);
int mqtt_connect();
int mqtt_subscribe();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0;
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the pump
void control_pump(int pump_state) {
    if (gpioWrite(PUMP_GPIO, pump_state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d: %s", PUMP_GPIO, strerror(errno));
    } else {
        syslog(LOG_INFO, "Pump %s", pump_state ? "ON" : "OFF");
    }
}

// Function to publish moisture data to MQTT
void publish_moisture(float moisture_percentage) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture_percentage);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(ret));
    } else {
        syslog(LOG_INFO, "Published moisture: %.2f%% to topic %s", moisture_percentage, MQTT_TOPIC_SOIL);
    }
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(message->topic, MQTT_TOPIC_PUMP) == 0) {
            if (strcmp(payload, "pump_on") == 0) {
                control_pump(1);
            } else if (strcmp(payload, "pump_off") == 0) {
                control_pump(0);
