    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motors
    gpioSetMode(config.motor1_gpio, PI_OUTPUT);
    gpioSetMode(config.motor2_gpio, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(config.motor1_gpio, config.pwm_frequency);
    gpioSetPWMfrequency(config.motor2_gpio, config.pwm_frequency);

    // Set PWM range
    gpioSetPWMrange(config.motor1_gpio, PWM_RANGE);
    gpioSetPWMrange(config.motor2_gpio, PWM_RANGE);

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop motors
    set_motor_speed(config.motor1_gpio, 0);
    set_motor_speed(config.motor2_gpio, 0);

    // Close SPI device
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    log_event("System started");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            // Error already logged in read_mcp3008
            gpioDelay(10); // Small delay before next attempt
            continue;
        }

        // Control motors based on noise level
        if (adc_value > config.noise_threshold) {
            set_motor_speed(config.motor1_gpio, 50); // 50% speed
            set_motor_speed(config.motor2_gpio, 50);
            log_event("Vibration event detected");
        } else {
            set_motor_speed(config.motor1_gpio, 0);
            set_motor_speed(config.motor2_gpio, 0);
        }

        gpioDelay(10); // 10ms delay
    }

    // Cleanup and exit
    cleanup();
    log_event("System stopped");
    return 0;
}

