        // Control the pump
        control_pump(moisture_percentage);

        // Log the data
        log_data(moisture_percentage);

        // Wait for 60 seconds
        gpioDelay(60000000); // 60 seconds in microseconds
    }

    // Cleanup
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

