        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to estimated CO2 concentration
        float co2_ppm = voltage_to_co2(voltage);

        // Control the ventilation fan
        control_fan(co2_ppm);

        // Get fan state
        int fan_state = gpioRead(FAN_GPIO);

        // Log the data
        log_data(co2_ppm, fan_state);

