#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000000 // 1 MHz
#define VALVE_GPIO 17
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int sample1, int sample2, int sample3);
void set_valve_position(float average);
void log_data(int sample1, int sample2, int sample3, float average, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate the average of three samples
float calculate_average(int sample1, int sample2, int sample3) {
    float sum = 0.0;
    int count = 0;

    if (sample1 >= 0) {
        sum += sample1;
        count++;
    }
    if (sample2 >= 0) {
        sum += sample2;
        count++;
    }
    if (sample3 >= 0) {
        sum += sample3;
        count++;
    }

    if (count == 0) {
        return -1.0; // Indicate error
    }

    return sum / count;
}

// Function to set the valve position using PWM
void set_valve_position(float average) {
    int duty_cycle = (int)(average * 10000); // Scale average to 0-1000000
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(VALVE_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(int sample1, int sample2, int sample3, float average, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %d, %d, %.2f, %d\n", timestamp, sample1, sample2, sample3, average, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture irrigation system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read soil moisture samples
        int sample1 = read_mcp3008(0);
        int sample2 = read_mcp3008(0);
        int sample3 = read_mcp3008(0);

        // Calculate average
        float average = calculate_average(sample1, sample2, sample3);

        // Set valve position
        if (average >= 0) {
            set_valve_position(average);
            int valve_position = (int)(average * 100); // Scale average to 0-100
            if (valve_position < 0) valve_position = 0;
            if (valve_position > 100) valve_position = 100;

            // Log data
            log_data(sample1, sample2, sample3, average, valve_position);
        } else {
            fprintf(stderr, "Error: Failed to calculate average\n");
        }

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Shutdown sequence
    printf("Shutting down...\n");

    // Set valve to 0%
    gpioPWM(VALVE_GPIO, 0);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    printf("Shutdown complete.\n");

    return 0;
}

