#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;
    int retries = 0;
    int delay_ms = 1;

    // Construct SPI command
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00; // Don't care

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value
            adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d). Retrying in %d ms.\n", retries + 1, delay_ms);
            fprintf(log_file, "SPI read failed (attempt %d). Retrying in %d ms.\n", retries + 1, delay_ms);
            fflush(log_file);
            gpioDelay(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries++;
        }
    }

    fprintf(stderr, "SPI read failed after %d retries. Skipping sample.\n", MAX_RETRIES);
    fprintf(log_file, "SPI read failed after %d retries. Skipping sample.\n", MAX_RETRIES);
    fflush(log_file);
    return -1; // Indicate failure
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d. Shutting down gracefully.\n", signal);
    fprintf(log_file, "Received signal %d. Shutting down gracefully.\n", signal);
    fflush(log_file);
    terminate = 1;
}

int main() {
    int adc_value;
    float moisture_percentage;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    fprintf(log_file, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    fflush(log_file);

    // Main loop
    while (!terminate) {
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            moisture_percentage = convert_to_moisture_percentage(adc_value);
            log_data(moisture_percentage);
            printf("Moisture: %.2f%%\n", moisture_percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
            fprintf(log_file, "Failed to read ADC value.\n");
            fflush(log_file);
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Soil moisture monitoring stopped.\n");
    fprintf(log_file, "Soil moisture monitoring stopped.\n");
    fflush(log_file);

    return 0;
}

