    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    fprintf(log_file, "Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    fflush(log_file);

    // Main loop
    while (!terminate) {
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            moisture_percentage = convert_to_moisture_percentage(adc_value);
