#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CONFIG_FILE "theremin_config.txt"
#define LOG_FILE "theremin.log"

// Default calibration values
#define DEFAULT_MIN_DISTANCE 2.0
#define DEFAULT_MAX_DISTANCE 20.0
#define DEFAULT_MIN_VOLUME 0
#define DEFAULT_MAX_VOLUME 1023

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Calibration parameters
static float min_distance = DEFAULT_MIN_DISTANCE;
static float max_distance = DEFAULT_MAX_DISTANCE;
static int min_volume = DEFAULT_MIN_VOLUME;
static int max_volume = DEFAULT_MAX_VOLUME;

// Last valid sensor readings
static float last_valid_distance = 5.0; // Reasonable default
static int last_valid_volume = 512; // Reasonable default

// Function prototypes
float read_distance();
int read_ldr();
float map_distance_to_frequency(float distance);
int map_ldr_to_volume(int ldr_value);
void generate_tone(float frequency, int volume);
void load_configuration();
void save_configuration();
void signal_handler(int signal);
void log_message(const char *message);

// Function to read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout <= 0) {
        log_message("Timeout waiting for echo high");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout <= 0) {
        log_message("Timeout waiting for echo low");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 2.0 / 29.1; // Speed of sound: 29.1 us/cm

    return distance;
}

// Function to read LDR value from MCP3008 ADC
int read_ldr() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // MCP3008 command to read channel 0 (single-ended)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        log_message("SPI transfer failed");
        return -1; // Indicate error
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map distance to frequency (A4 = 440Hz)
float map_distance_to_frequency(float distance) {
    // Clamp distance to the defined range
    if (distance < min_distance) {
        distance = min_distance;
    } else if (distance > max_distance) {
        distance = max_distance;
    }

    // Map distance to a frequency range (e.g., A3 to A5)
    float frequency = 440.0 * pow(2.0, (distance - min_distance) / (max_distance - min_distance) * 2.0 - 2.0); // A3 to A5
    return frequency;
}

// Function to map LDR value to volume (PWM duty cycle)
int map_ldr_to_volume(int ldr_value) {
    // Clamp LDR value to the defined range
    if (ldr_value < min_volume) {
        ldr_value = min_volume;
    } else if (ldr_value > max_volume) {
        ldr_value = max_volume;
    }

    // Map LDR value to a volume range (0-100%)
    int volume = (int)(((float)(ldr_value - min_volume) / (max_volume - min_volume)) * 1000000.0); // 0-100% duty cycle
    return volume;
}

// Function to generate tone using PWM
void generate_tone(float frequency, int volume) {
    // Set PWM frequency (approximately)
    int period = (int)(1000000.0 / frequency); // Period in microseconds
    int duty_cycle = volume; // Duty cycle in microseconds

    gpioSetPWMfrequency(PWM_PIN, 1000000 / period); // Set PWM frequency
    gpioPWM(PWM_PIN, duty_cycle / 10000); // Set PWM duty cycle (0-1000)
}

// Function to load configuration from file
void load_configuration() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        log_message("Configuration file not found, using default values");
        return;
    }

    if (fscanf(fp, "%f %f %d %d", &min_distance, &max_distance, &min_volume, &max_volume) != 4) {
        log_message("Invalid configuration file format, using default values");
        fclose(fp);
        return;
    }

    fclose(fp);
    log_message("Configuration loaded from file");
}

// Function to save configuration to file
void save_configuration() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        log_message("Error opening configuration file for writing");
        return;
    }

    fprintf(fp, "%f %f %d %d", min_distance, max_distance, min_volume, max_volume);
    fclose(fp);
    log_message("Configuration saved to file");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    log_message("Starting Theremin program");

    // Load configuration
    load_configuration();

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Initialize PWM
    gpioSetPWMfrequency(PWM_PIN, 440); // Initial frequency
    gpioSetPWMrange(PWM_PIN, 1000); // Range for duty cycle

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        log_message("SPI open failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        float distance = read_distance();
        int ldr_value = read_ldr();

        // Handle sensor errors
        if (distance < 0) {
            log_message("Distance sensor error, using last valid value");
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        if (ldr_value < 0) {
            log_message("LDR sensor error, using last valid value");
            ldr_value = last_valid_volume;
        } else {
            last_valid_volume = ldr_value;
        }

        // Map sensor values to audio parameters
        float frequency = map_distance_to_frequency(distance);
        int volume = map_ldr_to_volume(ldr_value);

        // Generate tone
        generate_tone(frequency, volume);

        // Delay
        gpioDelay(50); // 50ms delay
    }

    // Clean up
    log_message("Stopping PWM");
    gpioPWM(PWM_PIN, 0); // Stop PWM

    log_message("Closing SPI");
    spiClose(spi_handle);

    log_message("Terminating pigpio");
    gpioTerminate();

    log_message("Closing log file");
    fclose(log_file);

    log_message("Exiting");
    return 0;
}

