    while (!terminate) {
        adc_value = read_mcp3008(MCP3008_CHANNEL);

        if (adc_value >= 0) {
            voltage = adc_to_voltage(adc_value);
            ppm = voltage_to_ppm(voltage);

            log_data(ppm);

            if (ppm > 50.0) {
                printf("Alcohol detected! Limit exceeded.\n");
            } else if (ppm < 20.0) {
                printf("Sobriety confirmed.\n");
            } else {
                printf("Alcohol level within acceptable range.\n");
            }

            // Sensor absent detection
            if (adc_value == 0 || adc_value == 1023) {
                sensor_absent_count++;
                if (sensor_absent_count >= SENSOR_ABSENT_THRESHOLD) {
                    fprintf(stderr, "Sensor absent condition detected!\n");
                    fprintf(log_file, "Sensor absent condition detected!\n");
                    fflush(log_file);
                    sensor_absent_count = 0; // Reset the counter after logging
                }
            } else {
                sensor_absent_count = 0; // Reset counter if sensor is present
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(1000000); // Sample every 1 second (1000000 microseconds)
    }

    cleanup();
    return 0;
}

