    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and irrigation system started.\n");

    // Main loop
    while (!terminate) {
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            fprintf(log_file, "Error: Failed to read moisture level\n");
        } else {
            int pump_state = (moisture_level < MOISTURE_THRESHOLD) ? 1 : 0;
            control_pump(pump_state);
            log_data(moisture_level, pump_state);
        }

        sleep(60); // Sample every 60 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

