#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CS   8
#define LED_PIN  17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz

// Define calibration duration
#define CALIBRATION_DURATION 5 // seconds

// Define sound level threshold
#define SOUND_THRESHOLD 100

// Global variables
int spi_handle;
double baseline = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calibrate_noise_level(int duration);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate noise level
double calibrate_noise_level(int duration) {
    double sum = 0.0;
    int num_samples = 0;
    time_t start_time = time(NULL);

    printf("Calibrating noise level for %d seconds...\n", duration);

    while (time(NULL) - start_time < duration) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value during calibration\n");
            return -1.0; // Indicate calibration failure
        }
        sum += adc_value;
        num_samples++;
        gpioDelay(10000); // 10 ms delay
    }

    if (num_samples == 0) {
        fprintf(stderr, "Error: No samples collected during calibration\n");
        return -1.0; // Indicate calibration failure
    }

    return sum / num_samples;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    baseline = calibrate_noise_level(CALIBRATION_DURATION);
    if (baseline < 0) {
        fprintf(stderr, "Error: Noise level calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Baseline noise level: %.2f\n", baseline);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Compare to baseline and control LED
        if (adc_value > baseline + SOUND_THRESHOLD) {
            gpioWrite(LED_PIN, 1); // Turn LED on
            gpioDelay(10000);      // 10 ms delay
            gpioWrite(LED_PIN, 0); // Turn LED off
            gpioDelay(10000);      // 10 ms delay
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

