            return -1.0; // Indicate calibration failure
        }
        sum += adc_value;
        num_samples++;
        gpioDelay(10000); // 10 ms delay
    }

    if (num_samples == 0) {
        fprintf(stderr, "Error: No samples collected during calibration\n");
        return -1.0; // Indicate calibration failure
    }

    return sum / num_samples;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    baseline = calibrate_noise_level(CALIBRATION_DURATION);
    if (baseline < 0) {
        fprintf(stderr, "Error: Noise level calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Baseline noise level: %.2f\n", baseline);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Compare to baseline and control LED
        if (adc_value > baseline + SOUND_THRESHOLD) {
            gpioWrite(LED_PIN, 1); // Turn LED on
            gpioDelay(10000);      // 10 ms delay
            gpioWrite(LED_PIN, 0); // Turn LED off
            gpioDelay(10000);      // 10 ms delay
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

