#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // AWM720P connected to channel 0
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for calibration data
typedef struct {
    float voltage;
    float airflow;
} CalibrationPoint;

// Calibration curve data (example)
CalibrationPoint calibration_curve[] = {
    {0.5, 0.0},   // 0.5V = 0 LPM
    {2.5, 10.0},  // 2.5V = 10 LPM
    {4.5, 20.0},  // 4.5V = 20 LPM
    {6.5, 30.0}   // 6.5V = 30 LPM
};
int calibration_curve_size = sizeof(calibration_curve) / sizeof(calibration_curve[0]);

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_airflow(float voltage);
void log_data(float airflow);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "ERROR: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert voltage to airflow using linear interpolation
float voltage_to_airflow(float voltage) {
    if (voltage <= calibration_curve[0].voltage) {
        return calibration_curve[0].airflow;
    }
    if (voltage >= calibration_curve[calibration_curve_size - 1].voltage) {
        return calibration_curve[calibration_curve_size - 1].airflow;
    }

    for (int i = 0; i < calibration_curve_size - 1; i++) {
        if (voltage >= calibration_curve[i].voltage && voltage <= calibration_curve[i + 1].voltage) {
            float v1 = calibration_curve[i].voltage;
            float a1 = calibration_curve[i].airflow;
            float v2 = calibration_curve[i + 1].voltage;
            float a2 = calibration_curve[i + 1].airflow;

            return a1 + (voltage - v1) * (a2 - a1) / (v2 - v1);
        }
    }

    return 0.0; // Should not reach here
}

// Function to log data to file
void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "ERROR: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s, ERROR: ADC read failed\n", timestamp);
            fflush(log_file);
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Convert ADC value to voltage (assuming 3.3V reference)
        float voltage = (float)adc_value * 3.3 / 1023.0;

        // Convert voltage to airflow
        float airflow = voltage_to_airflow(voltage);

        // Log data
        log_data(airflow);

        // Wait 100ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

