#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/spi/spi.h>
#include <sys/mman.h>
#include <stdarg.h>

// Define GPIO pin for chip select
#define GPIO_PIN 8

// Define GPIO memory map addresses (adjust for your Raspberry Pi version)
#define GPIO_BASE 0xFE200000  // For Raspberry Pi Zero W
#define GPIO_SIZE 4096

// Define GPIO register offsets
#define GPFSEL0 0  // GPIO Function Select 0
#define GPSET0 7   // GPIO Pin Output Set 0
#define GPCLR0 10  // GPIO Pin Output Clear 0
#define GPLEV0 13  // GPIO Pin Level 0

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
static volatile uint32_t *gpio_map = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_adc(int fd);
int log_data(FILE *fp, struct timespec ts, int adc_value);
void signal_handler(int sig);
int setup_gpio();
int cleanup_gpio();
int cleanup_resources();

// Helper function for error handling with logging
void error_exit(const char *format, ...) {
    va_list args;
    va_start(args, format);
    fprintf(stderr, "Error: ");
    vfprintf(stderr, format, args);
    va_end(args);
    cleanup_resources();
    exit(EXIT_FAILURE);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, bytes_written) != bytes_written) {
        fprintf(stderr, "Failed to write to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, bytes_written) != bytes_written) {
        fprintf(stderr, "Failed to write to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Failed to write to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the value of a GPIO pin (0 or 1)
int gpio_set_value(int pin, int value) {
    char path[64];
    int fd;
    char val_str[2];

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }

    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write(fd, val_str, 1) != 1) {
        fprintf(stderr, "Failed to write to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to initialize the SPI device
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd;
    int ret;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    ret = ioctl(fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set max speed
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        fprintf(stderr, "Failed to set max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to perform SPI transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 1) {
        fprintf(stderr, "Failed to perform SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the ADC value from MCP3008
int read_adc(int fd) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message to read from channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended mode, channel 0
    tx_buf[2] = 0x00; // Dummy byte

    // Perform the SPI transfer
    if (spi_transfer(fd, tx_buf, rx_buf, 3) == -1) {
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to log the data to a file
int log_data(FILE *fp, struct timespec ts, int adc_value) {
    fprintf(fp, "%ld.%09ld|%d\n", ts.tv_sec, ts.tv_nsec, adc_value);
    fflush(fp);
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to setup GPIO memory mapping
int setup_gpio() {
    int fd;

    // Open /dev/mem
    fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/mem: %s\n", strerror(errno));
        return -1;
    }

    // Map GPIO memory
    gpio_map = (uint32_t *)mmap(NULL, GPIO_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio_map == MAP_FAILED) {
        fprintf(stderr, "Failed to mmap GPIO memory: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to cleanup GPIO memory mapping
int cleanup_gpio() {
    if (gpio_map != NULL) {
        if (munmap((void *)gpio_map, GPIO_SIZE) == -1) {
            fprintf(stderr, "Failed to unmap GPIO memory: %s\n", strerror(errno));
            return -1;
        }
        gpio_map = NULL;
    }
    return 0;
}

// Function to cleanup resources before exiting
int cleanup_resources() {
    // Unexport GPIO pin
    gpio_unexport(GPIO_PIN);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Cleanup GPIO memory
    cleanup_gpio();

    return 0;
}

int main() {
    struct timespec ts;
    int adc_value;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 1000000; // 1 ms

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) == -1) {
        error_exit("Failed to export GPIO pin %d\n", GPIO_PIN);
    }

    // Set GPIO pin direction to output
    if (gpio_set_direction(GPIO_PIN, "out") == -1) {
        error_exit("Failed to set GPIO pin %d direction to output\n", GPIO_PIN);
    }

    // Initialize GPIO memory mapping
    if (setup_gpio() == -1) {
        error_exit("Failed to setup GPIO memory mapping\n");
    }

    // Initialize SPI device
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE_0, 8, 1000000);
    if (spi_fd == -1) {
        error_exit("Failed to initialize SPI device\n");
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup_resources();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_adc(spi_fd);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Log data
        if (log_data(log_file, ts, adc_value) == -1) {
            fprintf(stderr, "Failed to log data\n");
            break; // Exit loop on error
        }

        // Sleep for 1 ms
        if (nanosleep(&sleep_time, NULL) == -1) {
            if (errno == EINTR) {
                fprintf(stderr, "nanosleep interrupted by signal\n");
            } else {
                fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
            }
            break; // Exit loop on error
        }
    }

    // Cleanup resources before exiting
    cleanup_resources();

    return 0;
}

