#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for SPI communication
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define ADXL335 sensitivity (3.3V / 10-bit ADC)
#define SENSITIVITY (3.3 / 1024.0)

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    float x;
    float P;
} KalmanState;

KalmanState kalman_x = {0, 1};
KalmanState kalman_y = {0, 1};
KalmanState kalman_z = {0, 1};

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float convert_to_g(int adc_value);
float kalman_filter(KalmanState *state, float measurement);
void print_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Function to initialize the SPI bus
int initialize_spi() {
    // Configure GPIO pins for SPI
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }

    return 0;
}

// Function to read data from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select MCP3008
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008

    if (spi_result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", spi_result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to g-force
float convert_to_g(int adc_value) {
    return adc_value * SENSITIVITY;
}

// Function to apply Kalman filter
float kalman_filter(KalmanState *state, float measurement) {
    // Prediction step
    state->P = state->P + PROCESS_NOISE;

    // Update step
    float K = state->P / (state->P + MEASUREMENT_NOISE);
    state->x = state->x + K * (measurement - state->x);
    state->P = (1 - K) * state->P;

    return state->x;
}

// Function to print acceleration values
void print_acceleration(float x, float y, float z) {
    printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x, y, z);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_x = read_adc(0);
        int adc_y = read_adc(1);
        int adc_z = read_adc(2);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to g-force
        float g_x = convert_to_g(adc_x);
        float g_y = convert_to_g(adc_y);
        float g_z = convert_to_g(adc_z);

        // Apply Kalman filter
        float filtered_x = kalman_filter(&kalman_x, g_x);
        float filtered_y = kalman_filter(&kalman_y, g_y);
        float filtered_z = kalman_filter(&kalman_z, g_z);

        // Print acceleration values
        print_acceleration(filtered_x, filtered_y, filtered_z);

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

