// Define the magnetic field strength conversion factor (mT/V)
#define MAGNETIC_FIELD_CONVERSION_FACTOR 10.0

// Define the magnetic field strength range
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// File pointer for the log file
FILE *log_file = NULL;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the digital state of a Hall-Effect sensor
int read_sensor(int gpio_pin) {
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to convert the digital state to a magnetic field strength value
float convert_to_magnetic_field(int sensor_value) {
    return (float)sensor_value * MAGNETIC_FIELD_CONVERSION_FACTOR;
}

// Function to log the magnetic field strength values to a file
int log_magnetic_field(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    int write_result = fprintf(log_file, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    if (write_result < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

