    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Open the log file for writing
    log_file = fopen("magnetic_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the digital states of the Hall-Effect sensors
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values. Skipping logging.\n");
            gpioDelay(100); // Wait 100 milliseconds
            continue;
        }

        // Convert the digital states to magnetic field strength values
        float sensor1_mT = convert_to_magnetic_field(sensor1_value);
        float sensor2_mT = convert_to_magnetic_field(sensor2_value);
        float sensor3_mT = convert_to_magnetic_field(sensor3_value);

        // Check if the magnetic field strength values are within the valid range
        if (sensor1_mT < MIN_MAGNETIC_FIELD || sensor1_mT > MAX_MAGNETIC_FIELD ||
            sensor2_mT < MIN_MAGNETIC_FIELD || sensor2_mT > MAX_MAGNETIC_FIELD ||
            sensor3_mT < MIN_MAGNETIC_FIELD || sensor3_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Magnetic field strength out of range. Skipping logging.\n");
        } else {
            // Log the magnetic field strength values to the file
            if (log_magnetic_field(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
                fprintf(stderr, "Error logging magnetic field values.\n");
            }
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

