#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
static volatile bool running = true;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int pump_state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        log_event("SPI read failed");
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the pump
void control_pump(int pump_state) {
    digitalWrite(PUMP_GPIO, pump_state);
    const char *state_str = (pump_state == HIGH) ? "ON" : "OFF";
    char log_message[100];
    snprintf(log_message, sizeof(log_message), "Pump turned %s", state_str);
    log_event(log_message);
}

// Function to log events
void log_event(const char *message) {
    if (log_file == NULL) return; // Don't log if file couldn't be opened

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = false;
    log_event("Received signal, shutting down...");
    control_pump(LOW); // Turn off pump
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed\n");
        return 1;
    }

    // Set pump GPIO as output
    pinMode(PUMP_GPIO, OUTPUT);
    control_pump(LOW); // Ensure pump is off at startup

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    log_event("Program started");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value != -1) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Moisture: %.2f%%", moisture_percentage);
            log_event(log_message);

            if (moisture_percentage < MOISTURE_THRESHOLD) {
                control_pump(HIGH); // Turn pump on
            } else {
                control_pump(LOW);  // Turn pump off
            }
        } else {
            log_event("Failed to read ADC value");
        }

        delay(60000); // Wait 60 seconds
    }

    // Clean up (should not reach here if signal handler works)
    control_pump(LOW);
    fclose(log_file);

    return 0;
}

