#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void log_message(const char *message);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
int set_led_state(int led_state);
void signal_handler(int signum);
int mqtt_connect_with_backoff(struct mosquitto *mosq);

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

// MQTT connect with exponential backoff
int mqtt_connect_with_backoff(struct mosquitto *mosq) {
    int rc = 0;
    int retry_delay = 1;
    int max_delay = 60;

    while (running) {
        rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            return 0; // Connection successful
        }

        char error_message[256];
        snprintf(error_message, sizeof(error_message), "Connection failed: %s. Retrying in %d seconds.", mosquitto_strerror(rc), retry_delay);
        log_message(error_message);

        sleep(retry_delay);
        retry_delay *= 2;
        if (retry_delay > max_delay) {
            retry_delay = max_delay;
        }
    }
    return -1; // Connection failed after multiple retries
}

// MQTT connect callback
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message("MQTT connected successfully.");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "MQTT connection error: %s", mosquitto_strerror(result));
        log_message(error_message);
    }
}

// MQTT disconnect callback
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message("MQTT disconnected unexpectedly.");
    }
}

// MQTT message callback
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json_payload((const char *)message->payload, &led_state) == 0) {
            if (set_led_state(led_state) != 0) {
                log_message("Failed to set LED state.");
            }
        } else {
            log_message("Invalid JSON payload.");
        }
    } else {
        log_message("Empty message received.");
    }
}

// JSON parsing function
int parse_json_payload(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "JSON parse error: %s", error.text);
        log_message(error_message);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        log_message("Missing 'led_state' key in JSON.");
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(led_state_json)) {
        log_message("'led_state' is not a boolean.");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

// GPIO control function
int set_led_state(int led_state) {
    if (led_state) {
        gpioWrite(GPIO_PIN, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_PIN, 0); // Turn LED off
    }
    return 0;
}

// Signal handler
void signal_handler(int signum) {
    running = 0;
    log_message("Signal received, exiting...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure LED is off at startup

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message("Failed to create mosquitto instance.");
        gpioTerminate();
        return 1;
    }

    // Set MQTT callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to MQTT broker with backoff
    if (mqtt_connect_with_backoff(mosq) != 0) {
        log_message("Failed to connect to MQTT broker after multiple retries.");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start MQTT loop
    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

