#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sound sensor value
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        // Check for errors during read
        if (sound_level < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", SOUND_SENSOR_PIN);
            gpioTerminate();
            return 1;
        }

        // Print sound level
        printf("Sound level: %d\n", sound_level);

        // Trigger alarm if sound is detected
        if (sound_level == 0) {
            printf("Sound detected! Triggering alarm.\n");
            if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to write to GPIO%d\n", ALARM_LED_PIN);
                gpioTerminate();
                return 1;
            }
            gpioDelay(1000); // 1 second delay
            if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to write to GPIO%d\n", ALARM_LED_PIN);
                gpioTerminate();
                return 1;
            }
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("GPIO resources released. Exiting.\n");

    return 0;
}

