#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // LM35 connected to channel 0
#define VREF 3.3
#define LM35_SCALE 0.01 // 10mV per degree Celsius
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void update_circular_buffer(float temperature);
void print_temperature(float temperature);
void log_temperature_to_file(float temperature);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float temperature = voltage / LM35_SCALE;
    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the temperature to the console
void print_temperature(float temperature) {
    printf("Temperature: %.2f \u00b0C\n", temperature);
}

// Function to log the temperature to a file
void log_temperature_to_file(float temperature) {
    if (log_file != NULL) {
        fwrite(&temperature, sizeof(float), 1, log_file);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temp_log.dat", "wb+");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.  Continuing without logging.\n");
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Skipping this sample.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Update circular buffer
        update_circular_buffer(temperature);

        // Print temperature
        print_temperature(temperature);

        // Log temperature to file
        log_temperature_to_file(temperature);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    return 0;
}

