#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to log the event to a file
int log_event(int state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s,%d,%d\n", buf, FLAME_SENSOR_PIN, state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to print an alarm message
void print_alarm() {
    printf("ALARM: Flame detected!\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
