#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define I2C_BUS 1
#define MCP4725_ADDR 0x60
#define VREF 3.3
#define TMP36_SCALE 0.01
#define TMP36_OFFSET 0.5
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int write_mcp4725(float voltage);
int log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d). Retrying...\n", i + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float temperature = (voltage - TMP36_OFFSET) / TMP36_SCALE;
    return temperature;
}

// Function to write to MCP4725 DAC
int write_mcp4725(float voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Error: DAC voltage out of range: %.2f\n", voltage);
        return -1;
    }

    // Convert voltage to DAC value (12-bit)
    int dac_value = (int)(voltage / VREF * 4095.0);

    // Construct I2C message
    char tx_buffer[3];
    tx_buffer[0] = 0x40; // Write DAC value command
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    tx_buffer[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (i2cWriteDevice(i2c_handle, tx_buffer, 3) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C write failed (attempt %d). Retrying...\n", i + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Error: I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Function to log data to file
int log_data(int adc_value, float temperature, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Close SPI interface
    spiClose(spi_handle);

    // Close I2C interface
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Write to DAC
        if (write_mcp4725(temperature) != 0) {
            fprintf(stderr, "Error: Failed to write to DAC\n");
        }

        // Log data
        log_data(adc_value, temperature, temperature);

        // Wait 0.5 seconds
        gpioDelay(500000); // 500 ms
    }

    // Cleanup
    cleanup();

    return 0;
}

