// Define GPIO pins
#define CLAP_SENSOR_PIN 26
#define LED_PIN 16

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define LED_ON_TIME_MS 500
#define CLAP_THRESHOLD 1 // Adjust this value based on your setup

// Global variables
static volatile int running = 1;
static volatile unsigned long last_clap_time = 0;

// Function prototypes
int initialize_gpio();
int read_clap_sensor();
void control_led(int on);
void log_clap_event();
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int clap_pin;
    int led_pin;
    int clap_threshold;
} Config;

Config config = {CLAP_SENSOR_PIN, LED_PIN, CLAP_THRESHOLD};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.clap_pin, PI_INPUT);
    gpioSetMode(config.led_pin, PI_OUTPUT);

    return 0;
}

// Function to read the clap sensor
int read_clap_sensor() {
    return gpioRead(config.clap_pin);
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(config.led_pin, on);
}

// Function to log clap events with timestamp
void log_clap_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: Clap detected!\n", timestamp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    control_led(0); // Turn off LED
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Clap detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int clap_detected = read_clap_sensor();

        if (clap_detected) {
            unsigned long current_time = gpioTick();

            if (current_time - last_clap_time > DEBOUNCE_DELAY_MS * 1000) {
                log_clap_event();
                control_led(1); // Turn on LED
                gpioDelay(LED_ON_TIME_MS * 1000); // Wait for LED_ON_TIME_MS
                control_led(0); // Turn off LED
                last_clap_time = current_time;
            }
        }

        gpioDelay(1000); // Check every 1ms
    }

    return 0;
}

