        int distance = read_distance();
        log_distance(distance);
        print_feeder_status(distance);
        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input before exiting
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

