#define LED_GPIO 21
#define MAGNETIC_THRESHOLD 10.0 // mT
#define SENSITIVITY 0.002 // 2 mV/mT
#define OFFSET 2.5 // 2.5 V
#define VREF 3.3 // 3.3 V
#define ADC_RESOLUTION 1024.0 // 10-bit ADC

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_magnetic_field(int adc_value);
void log_magnetic_field(float magnetic_field);
void control_led(float magnetic_field);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to magnetic field strength
float adc_to_magnetic_field(int adc_value) {
    float voltage = (adc_value / ADC_RESOLUTION) * VREF;
    float magnetic_field = (voltage - OFFSET) / SENSITIVITY;
    return magnetic_field;
}

// Function to log magnetic field data to file
void log_magnetic_field(float magnetic_field) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.3f mT\n", timestamp, magnetic_field);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the LED based on magnetic field strength
void control_led(float magnetic_field) {
    if (magnetic_field > MAGNETIC_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed\n");
            break; // Exit loop on error
        }

        // Convert ADC value to magnetic field strength
        float magnetic_field = adc_to_magnetic_field(adc_value);

        // Log magnetic field data
        log_magnetic_field(magnetic_field);

        // Control LED
        control_led(magnetic_field);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

