#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 17
#define SENSOR_SENSITIVITY 0.1 // 100mV/A
#define VREF 5.0 // Reference voltage for MCP3008
#define ADC_RESOLUTION 1024.0 // 2^10
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int init_gpio();
int read_adc(int channel);
float convert_to_amps(int adc_value);
int log_current(float current);
void signal_handler(int signal);
void cleanup();

// Structure for SPI configuration
struct spi_config {
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed_hz;
};

// Initialize SPI
int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    struct spi_config config = {
        .mode = 0,
        .bits_per_word = 8,
        .speed_hz = 1000000 // 1 MHz
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed_hz) == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 1); // Enable sensor power
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
