#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Debounce samples
#define DEBOUNCE_SAMPLES 5

// Function prototypes
int read_sensor(int gpio);
int debounce_sensor(int gpio);
void log_sensor_state(int sensor1_state, int sensor2_state);
void check_simultaneous_detection(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor states with debouncing
        int sensor1_state = debounce_sensor(SENSOR1_GPIO);
        int sensor2_state = debounce_sensor(SENSOR2_GPIO);

        // Log sensor states
        log_sensor_state(sensor1_state, sensor2_state);

        // Check for simultaneous detection
        check_simultaneous_detection(sensor1_state, sensor2_state);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce a sensor
int debounce_sensor(int gpio) {
    int samples[DEBOUNCE_SAMPLES];
    int i;

    // Read multiple samples
    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        samples[i] = read_sensor(gpio);
        gpioDelay(2); // 2 milliseconds delay
    }

    // Determine the majority value
    int sum = 0;
    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        sum += samples[i];
    }

    // Return 0 if more than half of the samples are 0, otherwise return 1
    return (sum > (DEBOUNCE_SAMPLES / 2)) ? 1 : 0;
}

// Function to log the state of the sensors
void log_sensor_state(int sensor1_state, int sensor2_state) {
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);
}

// Function to check for simultaneous detection
void check_simultaneous_detection(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
}

