#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 200 // milliseconds
#define CAPTURE_DIR "/home/pi/security_cam/"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    program_running = 0;
}

int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];
    char command[256];
    int status;
    pid_t pid;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.jpg", timeinfo);
    snprintf(command, sizeof(command), "libcamera-still -o %s/%s", CAPTURE_DIR, filename);

    syslog(LOG_INFO, "Capturing image: %s", filename);

    pid = fork();

    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        // execl only returns on error
        syslog(LOG_ERR, "execl failed: %s", strerror(errno));
        exit(1); // Exit child process on error
    } else if (pid < 0) {
        // Fork failed
        syslog(LOG_ERR, "fork failed: %s", strerror(errno));
        return -1;
    } else {
        // Parent process
        int wait_status;
        waitpid(pid, &wait_status, 0);
        status = WEXITSTATUS(wait_status);

        if (status == 0) {
            syslog(LOG_INFO, "Image capture successful.");
        } else {
            syslog(LOG_ERR, "Image capture failed with status %d.", status);
        }
        return status;
    }
}

int main() {
    int pir_state = 0;
    int last_pir_state = 0;
    struct timespec ts;
    int dir_exists;

    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting security camera...");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Check if the capture directory exists
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        dir_exists = 1;
    } else {
        dir_exists = 0;
    }

    if (!dir_exists) {
        syslog(LOG_INFO, "Capture directory does not exist, creating...");
        if (mkdir(CAPTURE_DIR, 0777) == -1) {
            syslog(LOG_ERR, "Failed to create capture directory: %s", strerror(errno));
            gpioTerminate();
            closelog();
            return 1;
        }
        syslog(LOG_INFO, "Capture directory created.");
    }

    // Main loop
    while (program_running) {
        pir_state = gpioRead(GPIO_PIN);

        if (pir_state != last_pir_state) {
            syslog(LOG_INFO, "PIR state changed from %d to %d", last_pir_state, pir_state);
            last_pir_state = pir_state;

            if (pir_state == 1) {
                // Motion detected
                syslog(LOG_INFO, "Motion detected!");
                gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
                pir_state = gpioRead(GPIO_PIN); // Re-read the pin

                if (pir_state == 1) {
                    // Confirmed motion
                    syslog(LOG_INFO, "Motion confirmed!");
                    if (capture_image() != 0) {
                        syslog(LOG_ERR, "Image capture failed.");
                    }
                } else {
                    syslog(LOG_INFO, "Motion cancelled by debounce.");
                }
            }
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    gpioTerminate();
    closelog();

    return 0;
}

