    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    if (argc > 1) {
        device_name = argv[1];
    }

    // Initialize camera
    if (init_camera(device_name) < 0) {
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming() < 0) {
        unmap_buffers();
        close_device();
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    // Main loop
    while (!stop_flag) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            if (errno == EINTR) {
                fprintf(stderr, "Select interrupted by signal\n");
                break;
            }
            fprintf(stderr, "Error in select: %s\n", strerror(errno));
            break;
        } else if (r == 0) {
            fprintf(stderr, "Select timeout\n");
            continue;
        }

        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                fprintf(stderr, "EAGAIN, retrying...\n");
                continue;
            }
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        if (save_frame(buffers[buf.index].start, buf.bytesused) < 0) {
            fprintf(stderr, "Error saving frame\n");
            break;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            break;
        }
    }

    // Clean up
    stop_streaming();
    unmap_buffers();
    close_device();

    return EXIT_SUCCESS;
}

