#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define BUFFER_COUNT 4

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
static int                  fd                  = -1;
static buffer              *buffers             = NULL;
static unsigned int          n_buffers           = 0;
static FILE                 *log_file            = NULL;
static volatile sig_atomic_t keep_running        = 1;

// Function prototypes
int  xioctl(int fd, int request, void *arg);
int  init_device(const char *device_name);
int  init_mmap(int fd);
int  start_capturing(int fd);
int  stop_capturing(int fd);
void uninit_device(int fd);
void signal_handler(int signum);
int  write_frame_log(const char *timestamp);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        keep_running = 0;
    }
}

// Wrapper for ioctl with error handling
int xioctl(int fd, int request, void *arg) {
    int r;

    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);

    if (-1 == r) {
        fprintf(stderr, "Error %d, %s\n", errno, strerror(errno));
        return -1;
    }

    return r;
}

// Initialize the video device
int init_device(const char *device_name) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (-1 == fd) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n",
                device_name, errno, strerror(errno));
        return -1;
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "%s: VIDIOC_QUERYCAP\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n",
                device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n",
                device_name);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;  // Set desired width
    fmt.fmt.pix.height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "%s: VIDIOC_S_FMT\n", device_name);
        close(fd);
        return -1;
    }

    return 0;
}

// Initialize memory mapping
int init_mmap(int fd) {
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));

    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "VIDIOC_REQBUFS\n");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", DEVICE_NAME);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QUERYBUF\n");
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start =
            mmap(NULL /* start anywhere */,
                  buf.length,
                  PROT_READ | PROT_WRITE /* required */,
                  MAP_SHARED /* recommended */,
                  fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            fprintf(stderr, "mmap\n");
            return -1;
        }
    }

    return 0;
}

// Start capturing video
int start_capturing(int fd) {
    unsigned int i;
    enum v4l2_buf_type type;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF\n");
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON\n");
        return -1;
    }

    return 0;
}

// Stop capturing video
int stop_capturing(int fd) {
    enum v4l2_buf_type type;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        fprintf(stderr, "VIDIOC_STREAMOFF\n");
        return -1;
    }

    return 0;
}

// Uninitialize the video device
void uninit_device(int fd) {
    unsigned int i;

    if (-1 != fd) {
        if (-1 != stop_capturing(fd)) {
            for (i = 0; i < n_buffers; ++i) {
                if (-1 == munmap(buffers[i].start, buffers[i].length)) {
                    fprintf(stderr, "munmap error\n");
                }
            }
            free(buffers);
        }
        close(fd);
    }
}

// Write frame timestamp to log file
int write_frame_log(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }
}

int main() {
    fd_set          fds;
    struct timeval  tv;
    int             r;
    struct v4l2_buffer buf;
    struct timeval timestamp;
    char timestamp_str[30];

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize device
    if (-1 == init_device(DEVICE_NAME)) {
        fprintf(stderr, "Device initialization failed\n");
        return EXIT_FAILURE;
    }

    // Initialize memory mapping
    if (-1 == init_mmap(fd)) {
        fprintf(stderr, "Memory mapping failed\n");
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(FRAME_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Cannot open log file: %d, %s\n", errno, strerror(errno));
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (-1 == start_capturing(fd)) {
        fprintf(stderr, "Failed to start capturing\n");
        fclose(log_file);
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    printf("Capturing started. Press Ctrl+C to stop.\n");

    while (keep_running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        /* Timeout. */
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r) {
            if (EINTR == errno) {
                continue;
            }
            fprintf(stderr, "select\n");
            break;
        }

        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            continue;
        }

        if (FD_ISSET(fd, &fds)) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;

            if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
                fprintf(stderr, "VIDIOC_DQBUF\n");
                break;
            }

            // Get timestamp
            gettimeofday(&timestamp, NULL);
            snprintf(timestamp_str, sizeof(timestamp_str), "%ld.%06ld", timestamp.tv_sec, timestamp.tv_usec);

            // Write timestamp to log file
            if (-1 == write_frame_log(timestamp_str)) {
                fprintf(stderr, "Failed to write to log file\n");
                break;
            }

            if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
                fprintf(stderr, "VIDIOC_QBUF\n");
                break;
            }
        }
    }

    printf("Capturing stopped.\n");

    // Clean up
    fclose(log_file);
    uninit_device(fd);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

