        uninit_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (-1 == start_capturing(fd)) {
        fprintf(stderr, "Failed to start capturing\n");
        fclose(log_file);
        uninit_device(fd);
        return EXIT_FAILURE;
    }

    printf("Capturing started. Press Ctrl+C to stop.\n");

    while (keep_running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        /* Timeout. */
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r) {
            if (EINTR == errno) {
                continue;
            }
            fprintf(stderr, "select\n");
            break;
        }

        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            continue;
        }

        if (FD_ISSET(fd, &fds)) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;

            if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
                fprintf(stderr, "VIDIOC_DQBUF\n");
                break;
            }

            // Get timestamp
            gettimeofday(&timestamp, NULL);
            snprintf(timestamp_str, sizeof(timestamp_str), "%ld.%06ld", timestamp.tv_sec, timestamp.tv_usec);

            // Write timestamp to log file
            if (-1 == write_frame_log(timestamp_str)) {
                fprintf(stderr, "Failed to write to log file\n");
                break;
            }

            if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
                fprintf(stderr, "VIDIOC_QBUF\n");
                break;
            }
        }
    }

    printf("Capturing stopped.\n");

    // Clean up
    fclose(log_file);
    uninit_device(fd);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

