#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <arpa/inet.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <stdint.h>

#define MAX_FRAME_SIZE 65535
#define MAX_BUFFER_COUNT 4

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables
int                  fd                  = -1;
buffer_t             buffers[MAX_BUFFER_COUNT];
unsigned int         n_buffers           = 0;
unsigned int         frame_index         = 0;
unsigned int         target_port         = 0;
char                 *target_ip          = NULL;
int                  sockfd              = -1;
struct sockaddr_in   servaddr;
volatile sig_atomic_t running            = 1;

// Function prototypes
int  xioctl(int fd, int request, void *arg);
int  init_device(const char *device_name);
int  init_mmap();
int  start_capturing();
int  stop_capturing();
void uninit_device();
void send_udp_packet(unsigned char *data, size_t size, unsigned int frame_index, unsigned int fragment_index, unsigned int total_fragments, unsigned int payload_size);
void signal_handler(int signum);
void fragment_frame(unsigned char *frame_data, size_t frame_size, unsigned int frame_index);

// Helper function for error handling
void error_exit(const char *s)
{
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

// Wrapper for ioctl system call
int xioctl(int fd, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

// Initialize the video device
int init_device(const char *device_name)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        error_exit("Cannot open device");
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        error_exit("VIDIOC_QUERYCAP");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", device_name);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", device_name);
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Set desired width
    fmt.fmt.pix.height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        error_exit("VIDIOC_S_FMT");
    }

    return 0;
}

// Initialize memory mapping
int init_mmap()
{
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = MAX_BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s does not support memory mapping\n", "/dev/video0");
            exit(EXIT_FAILURE);
        } else {
            error_exit("VIDIOC_REQBUFS");
        }
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", "/dev/video0");
        exit(EXIT_FAILURE);
    }

    n_buffers = req.count;

    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            error_exit("VIDIOC_QUERYBUF");
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[i].start) {
            error_exit("mmap");
        }
    }

    return 0;
}

// Start capturing video
int start_capturing()
{
    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            error_exit("VIDIOC_QBUF");
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        error_exit("VIDIOC_STREAMON");
    }

    return 0;
}

// Stop capturing video
int stop_capturing()
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        error_exit("VIDIOC_STREAMOFF");
    }

    return 0;
}

// Uninitialize the video device
void uninit_device()
{
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            error_exit("munmap");
        }
    }

    if (-1 == close(fd)) {
        error_exit("close");
    }

    if (sockfd != -1) {
        close(sockfd);
    }
}

// Send UDP packet
void send_udp_packet(unsigned char *data, size_t size, unsigned int frame_index, unsigned int fragment_index, unsigned int total_fragments, unsigned int payload_size)
{
    size_t header_size = sizeof(unsigned int) * 4; // 4 unsigned ints
    size_t packet_size = header_size + payload_size;
    unsigned char *packet = (unsigned char *)malloc(packet_size);

    if (packet == NULL) {
        perror("malloc");
        return;
    }

    // Construct header
    unsigned int *header = (unsigned int *)packet;
    header[0] = htonl(frame_index);
    header[1] = htonl(fragment_index);
    header[2] = htonl(total_fragments);
    header[3] = htonl(payload_size);

    // Copy payload
    memcpy(packet + header_size, data, payload_size);

    // Send packet
    ssize_t sent_bytes = sendto(sockfd, packet, packet_size, 0, (struct sockaddr *)&servaddr, sizeof(servaddr));
    if (sent_bytes < 0) {
        perror("sendto");
    }

    free(packet);
}

// Fragment frame into UDP packets
void fragment_frame(unsigned char *frame_data, size_t frame_size, unsigned int frame_index)
{
    unsigned int fragment_index = 0;
    unsigned int total_fragments = (frame_size + MAX_FRAME_SIZE - 1) / MAX_FRAME_SIZE; // Ceiling division
    size_t offset = 0;

    while (offset < frame_size) {
        size_t payload_size = (frame_size - offset > MAX_FRAME_SIZE) ? MAX_FRAME_SIZE : frame_size - offset;
        send_udp_packet(frame_data + offset, payload_size, frame_index, fragment_index, total_fragments, payload_size);
        offset += payload_size;
        fragment_index++;
    }
}

// Signal handler
void signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, stopping...\n", signum);
        running = 0;
    }
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <target_ip> <target_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    target_ip = argv[1];
    target_port = atoi(argv[2]);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize device
    if (init_device("/dev/video0") < 0) {
        return EXIT_FAILURE;
    }

    // Initialize memory mapping
    if (init_mmap() < 0) {
        uninit_device();
        return EXIT_FAILURE;
    }

    // Create socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        uninit_device();
        return EXIT_FAILURE;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(target_port);
    if (inet_pton(AF_INET, target_ip, &servaddr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        uninit_device();
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing() < 0) {
        close(sockfd);
        uninit_device();
        return EXIT_FAILURE;
    }

    printf("Streaming started. Press Ctrl+C to stop.\n");

    while (running) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            perror("VIDIOC_DQBUF");
            break;
        }

        // Process the frame (fragment and send)
        fragment_frame(buffers[buf.index].start, buf.bytesused, frame_index);
        frame_index++;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    // Stop capturing
    if (stop_capturing() < 0) {
        fprintf(stderr, "Error stopping capture.\n");
    }

    // Uninitialize device
    uninit_device();

    printf("Streaming stopped.\n");

    return EXIT_SUCCESS;
}

