#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 192
#define IMAGE_HEIGHT 192
#define NUM_BUFFERS 4
#define IMAGE_FILE "image.jpg"

static int fd = -1;
static struct buffer {
    void   *start;
    size_t  length;
} *buffers;
static unsigned int n_buffers = 0;
static FILE *fp = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (fd != -1) {
        stop_capturing();
    }
    if (fp != NULL) {
        fclose(fp);
    }
    if (buffers != NULL) {
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers[i].start != NULL) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }
    if (fd != -1) {
        close(fd);
    }
    exit(0);
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    return 0;
}

// Function to set the pixel format
int set_pixel_format(int fd, unsigned int width, unsigned int height) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting pixel format");
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd, unsigned int num_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    return req.count;
}

// Function to map the buffers
int map_buffers(int fd, unsigned int num_buffers, struct buffer *buffers) {
    struct v4l2_buffer buf;

    for (unsigned int i = 0; i < num_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting streaming");
        return -1;
    }
    return 0;
}

// Function to stop streaming
int stop_capturing() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping streaming");
        return -1;
    }
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Function to enqueue a buffer
int enqueue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_QBUF, buf) == -1) {
        perror("Error enqueuing buffer");
        return -1;
    }
    return 0;
}

// Function to write the image to a file
int write_image_to_file(const char *filename, void *data, size_t size) {
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    if (fwrite(data, 1, size, fp) != size) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (query_capabilities(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Set pixel format
    if (set_pixel_format(fd, IMAGE_WIDTH, IMAGE_HEIGHT) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    n_buffers = request_buffers(fd, NUM_BUFFERS);
    if (n_buffers == 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the buffers
    buffers = calloc(n_buffers, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffers
    if (map_buffers(fd, n_buffers, buffers) == -1) {
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers[i].start != NULL) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_capturing(fd) == -1) {
        for (unsigned int i = 0; i < n_buffers; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue a buffer
    struct v4l2_buffer buf;
    if (dequeue_buffer(fd, &buf) == -1) {
        stop_capturing();
        for (unsigned int i = 0; i < n_buffers; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Verify bytesused
    if (buf.bytesused == 0) {
        fprintf(stderr, "Error: bytesused is zero\n");
        stop_capturing();
        for (unsigned int i = 0; i < n_buffers; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Write the image to a file
    if (write_image_to_file(IMAGE_FILE, buffers[buf.index].start, buf.bytesused) == -1) {
        stop_capturing();
        for (unsigned int i = 0; i < n_buffers; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Enqueue the buffer
    if (enqueue_buffer(fd, &buf) == -1) {
        stop_capturing();
        for (unsigned int i = 0; i < n_buffers; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (stop_capturing() == -1) {
        for (unsigned int i = 0; i < n_buffers; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap the buffers
    for (unsigned int i = 0; i < n_buffers; i++) {
        if (buffers[i].start != NULL) {
            if (munmap(buffers[i].start, buffers[i].length) == -1) {
                perror("Error unmapping buffer");
            }
        }
    }

    // Free the buffer array
    free(buffers);

    // Close the device file descriptor
    close(fd);

    printf("Image captured and saved to %s\n", IMAGE_FILE);

    return EXIT_SUCCESS;
}

