#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN 8
#define PAN_RIGHT_BUTTON_PIN 9

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define PWM range (microseconds)
#define PWM_RANGE 20000 // 20ms

// Define minimum and maximum pulse widths (microseconds)
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define button debounce time (milliseconds)
#define DEBOUNCE_TIME 50

// Global variables for servo positions
int pan_position = 75;
int tilt_position = 75;

// Function prototypes
int initialize_gpio();
void set_servo_pulse_width(int gpio, int pulse_width);
void update_servo_position(int *position, int increment);
int read_button(int gpio);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo pins as outputs
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pan servo pin as output\n");
        return 1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set tilt servo pin as output\n");
        return 1;
    }

    // Set button pins as inputs with pull-up resistors
    if (gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set tilt up button pin as input\n");
        return 1;
    }
    if (gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set tilt down button pin as input\n");
        return 1;
    }
    if (gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set pan left button pin as input\n");
        return 1;
    }
    if (gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set pan right button pin as input\n");
        return 1;
    }

    gpioSetPullUpDown(TILT_UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency and range
    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set pan servo PWM frequency\n");
        return 1;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set tilt servo PWM frequency\n");
        return 1;
    }
    if (gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set pan servo PWM range\n");
        return 1;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set tilt servo PWM range\n");
        return 1;
    }

    return 0;
}

// Set servo pulse width
void set_servo_pulse_width(int gpio, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    if (gpioPWM(gpio, pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width for GPIO %d\n", gpio);
    }
}

// Update servo position
void update_servo_position(int *position, int increment) {
    *position += increment;
    if (*position < 25) {
        *position = 25;
    } else if (*position > 125) {
        *position = 125;
    }
}

// Read button state with debouncing
int read_button(int gpio) {
    int button_state = gpioRead(gpio);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    return button_state;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set initial servo positions
    set_servo_pulse_width(PAN_SERVO_PIN, pan_position * 10);
    set_servo_pulse_width(TILT_SERVO_PIN, tilt_position * 10);

    printf("Pan-Tilt control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read button states
        int tilt_up_pressed = (read_button(TILT_UP_BUTTON_PIN) == 0);
        int tilt_down_pressed = (read_button(TILT_DOWN_BUTTON_PIN) == 0);
