#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>
#include <setjmp.h>
#include <jpeglib.h>
#include <math.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define JPEG_QUALITY 75

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
static int                  fd                  = -1;
static buffer              *buffers             = NULL;
static unsigned int          n_buffers           = 0;
static jmp_buf              jump_buffer;
static volatile sig_atomic_t keep_running        = 1;
static FILE                 *log_file            = NULL;

// Function prototypes
int  xioctl(int fd, int request, void *arg);
int  init_mmap(int fd, buffer *buffers, unsigned int *n_buffers);
int  start_capturing(int fd);
int  stop_capturing(int fd);
int  uninit_mmap(int fd, buffer *buffers, unsigned int n_buffers);
void signal_handler(int signum);
void log_message(const char *format, ...);
void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height);
void blur_filter(unsigned char *rgb, int width, int height);
int  encode_jpeg(const unsigned char *rgb, int width, int height, int quality, const char *filename);
void cleanup(int exit_code);

// Helper macro for error handling
#define CHECK_ERROR(err, msg) \
    if (err < 0) { \
        fprintf(stderr, "%s: %s\n", msg, strerror(errno)); \
        cleanup(EXIT_FAILURE); \
    }

// XIOCTL wrapper function
int xioctl(int fd, int request, void *arg) {
    int r;

    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

// Initialize memory mapping
int init_mmap(int fd, buffer *buffers, unsigned int *n_buffers) {
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count               = NUM_BUFFERS;
    req.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory              = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s: %s\n", "VIDIOC_REQBUFS", "Invalid argument");
            return -1;
        } else {
            perror("VIDIOC_REQBUFS");
            return -1;
        }
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "%s: %s\n", "VIDIOC_REQBUFS", "Insufficient buffer memory");
        return -1;
    }

    *n_buffers = req.count;

    for (unsigned int i = 0; i < *n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start  = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[i].start) {
            perror("mmap");
            return -1;
        }
    }

    return 0;
}

// Start capturing
int start_capturing(int fd) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

// Stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }

    return 0;
}

// Uninitialize memory mapping
int uninit_mmap(int fd, buffer *buffers, unsigned int n_buffers) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            perror("munmap");
            return -1;
        }
    }

    return 0;
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT) {
        log_message("Received SIGINT, exiting...");
        keep_running = 0;
        longjmp(jump_buffer, 1);
    }
}

// Logging function
void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] ", t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec);
    vfprintf(log_file, format, args);
    va_end(args);
    fflush(log_file);
}

// YUYV to RGB24 conversion
void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    int i, j;
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            int y1 = yuyv[0];
            int u = yuyv[1] - 128;
            int y2 = yuyv[2];
            int v = yuyv[3] - 128;

            int r1 = y1 + 1.164 * v;
            int g1 = y1 - 0.392 * u - 0.813 * v;
            int b1 = y1 + 2.017 * u;

            int r2 = y2 + 1.164 * v;
            int g2 = y2 - 0.392 * u - 0.813 * v;
            int b2 = y2 + 2.017 * u;

            r1 = (r1 < 0) ? 0 : ((r1 > 255) ? 255 : r1);
            g1 = (g1 < 0) ? 0 : ((g1 > 255) ? 255 : g1);
            b1 = (b1 < 0) ? 0 : ((b1 > 255) ? 255 : b1);

            r2 = (r2 < 0) ? 0 : ((r2 > 255) ? 255 : r2);
            g2 = (g2 < 0) ? 0 : ((g2 > 255) ? 255 : g2);
            b2 = (b2 < 0) ? 0 : ((b2 > 255) ? 255 : b2);

            rgb[(i * width + j) * 3 + 0] = r1;
            rgb[(i * width + j) * 3 + 1] = g1;
            rgb[(i * width + j) * 3 + 2] = b1;

            rgb[(i * width + j + 1) * 3 + 0] = r2;
            rgb[(i * width + j + 1) * 3 + 1] = g2;
            rgb[(i * width + j + 1) * 3 + 2] = b2;

            yuyv += 4;
        }
    }
}

// Blur filter (simple box blur)
void blur_filter(unsigned char *rgb, int width, int height) {
    unsigned char *temp_rgb = malloc(width * height * 3);
    if (temp_rgb == NULL) {
        perror("malloc");
        cleanup(EXIT_FAILURE);
    }

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int r = 0, g = 0, b = 0;
            int count = 0;

            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    int ni = i + di;
                    int nj = j + dj;

                    if (ni >= 0 && ni < height && nj >= 0 && nj < width) {
                        r += rgb[(ni * width + nj) * 3 + 0];
                        g += rgb[(ni * width + nj) * 3 + 1];
                        b += rgb[(ni * width + nj) * 3 + 2];
                        count++;
                    }
                }
            }

            temp_rgb[(i * width + j) * 3 + 0] = r / count;
            temp_rgb[(i * width + j) * 3 + 1] = g / count;
            temp_rgb[(i * width + j) * 3 + 2] = b / count;
        }
    }

    memcpy(rgb, temp_rgb, width * height * 3);
    free(temp_rgb);
}

// JPEG encoding
int encode_jpeg(const unsigned char *rgb, int width, int height, int quality, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        perror("fopen");
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    int row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Cleanup function
void cleanup(int exit_code) {
    log_message("Cleaning up...\n");

    if (fd != -1) {
        stop_capturing(fd);
        uninit_mmap(fd, buffers, n_buffers);
        close(fd);
    }

    if (buffers != NULL) {
        free(buffers);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(exit_code);
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_streamparm streamparm;
    struct timeval timeout;
    struct v4l2_buffer buf;
    unsigned char *yuyv_buffer = NULL;
    unsigned char *rgb_buffer = NULL;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];

    // Open log file
    log_file = fopen("camera_capture.log", "a");
    if (log_file == NULL) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    log_message("Starting camera capture...\n");

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize jump buffer
    if (setjmp(jump_buffer) != 0) {
        cleanup(EXIT_SUCCESS);
    }

    // Open device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("open");
        log_message("Failed to open device: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    }
    log_message("Device opened successfully.\n");

    // Query device capabilities
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        perror("VIDIOC_QUERYCAP");
        log_message("Failed to query device capabilities: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s: %s\n", "VIDIOC_QUERYCAP", "Video capture not supported");
        log_message("Video capture not supported.\n");
        cleanup(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s: %s\n", "VIDIOC_QUERYCAP", "Streaming not supported");
        log_message("Streaming not supported.\n");
        cleanup(EXIT_FAILURE);
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = IMAGE_WIDTH;
    fmt.fmt.pix.height      = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        log_message("Failed to set image format: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    }

    // Check if the format was set correctly
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "%s: %s\n", "VIDIOC_S_FMT", "Failed to set YUYV format");
        log_message("Failed to set YUYV format.\n");
        cleanup(EXIT_FAILURE);
    }

    // Get stream parameters
    memset(&streamparm, 0, sizeof(streamparm));
    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm.parm.capture.timeperframe.numerator   = 1;
    streamparm.parm.capture.timeperframe.denominator = 30; // 30 fps

    if (-1 == xioctl(fd, VIDIOC_S_PARM, &streamparm)) {
        perror("VIDIOC_S_PARM");
        log_message("Failed to set stream parameters: %s\n", strerror(errno));
        // Not critical, continue anyway
    }

    // Initialize memory mapping
    buffers = calloc(NUM_BUFFERS, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        log_message("Failed to allocate memory for buffers: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    }

    if (init_mmap(fd, buffers, &n_buffers) == -1) {
        log_message("Failed to initialize memory mapping.\n");
        cleanup(EXIT_FAILURE);
    }
    log_message("Memory mapping initialized.\n");

    // Allocate buffers
    yuyv_buffer = malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 2);
    if (!yuyv_buffer) {
        perror("malloc");
        log_message("Failed to allocate memory for YUYV buffer: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    }

    rgb_buffer = malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (!rgb_buffer) {
        perror("malloc");
        log_message("Failed to allocate memory for RGB buffer: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    }

    // Start capturing
    if (start_capturing(fd) == -1) {
        log_message("Failed to start capturing.\n");
        cleanup(EXIT_FAILURE);
    }
    log_message("Capturing started.\n");

    // Capture a frame
    timeout.tv_sec  = 2;
    timeout.tv_usec = 0;

    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    int r = select(fd + 1, &fds, NULL, NULL, &timeout);

    if (r == -1) {
        perror("select");
        log_message("Select error: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
    } else if (r == 0) {
        log_message("Select timeout.\n");
        cleanup(EXIT_FAILURE);
    } else {
        // Dequeue buffer
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            perror("VIDIOC_DQBUF");
            log_message("Failed to dequeue buffer: %s\n", strerror(errno));
            cleanup(EXIT_FAILURE);
        }

        // Copy YUYV data to buffer
        memcpy(yuyv_buffer, buffers[buf.index].start, IMAGE_WIDTH * IMAGE_HEIGHT * 2);

        // Requeue buffer
        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            log_message("Failed to requeue buffer: %s\n", strerror(errno));
            cleanup(EXIT_FAILURE);
        }

        // Convert YUYV to RGB24
        yuyv_to_rgb24(yuyv_buffer, rgb_buffer, IMAGE_WIDTH, IMAGE_HEIGHT);

        // Apply blur filter
        blur_filter(rgb_buffer, IMAGE_WIDTH, IMAGE_HEIGHT);

        // Generate filename
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

        // Encode JPEG
        if (encode_jpeg(rgb_buffer, IMAGE_WIDTH, IMAGE_HEIGHT, JPEG_QUALITY, filename) == -1) {
            log_message("Failed to encode JPEG.\n");
        } else {
            log_message("JPEG saved as %s\n", filename);
        }
    }

    // Stop capturing
    if (stop_capturing(fd) == -1) {
        log_message("Failed to stop capturing.\n");
    }

    // Uninitialize memory mapping
    if (uninit_mmap(fd, buffers, n_buffers) == -1) {
        log_message("Failed to uninitialize memory mapping.\n");
    }

    // Free buffers
    free(yuyv_buffer);
    free(rgb_buffer);
    free(buffers);

    // Close device
    close(fd);

    log_message("Exiting.\n");
    return 0;
}

