#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

// Function to check if the device node exists
int device_exists(const char *device_name) {
    struct stat buffer;
    return (stat(device_name, &buffer) == 0);
}

// Function to open the device node
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, struct v4l2_frmsizeenum *frmsize) {
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, frmsize) < 0) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(int fd, struct v4l2_frmivalenum *frmival) {
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, frmival) < 0) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to query control capabilities
int query_control(int fd, struct v4l2_queryctrl *ctrl) {
    if (ioctl(fd, VIDIOC_QUERYCTRL, ctrl) < 0) {
        fprintf(stderr, "Error querying control: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl ctrl;

    // Check if the device node exists
    if (!device_exists(DEVICE_NAME)) {
        fprintf(stderr, "Device %s does not exist.\n", DEVICE_NAME);
        return 1;
    }

    // Open the device node
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    // Query device capabilities
    if (query_capabilities(fd, &cap) < 0) {
        close(fd);
        return 1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: %08x\n", cap.capabilities);

    // Enumerate frame sizes
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Example format, adjust as needed

    printf("\nSupported frame sizes:\n");
    while (enumerate_frame_sizes(fd, &frmsize) == 0) {
        printf("  %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }

    // Enumerate frame intervals for the first supported size (example)
    frmival.index = 0;
    frmival.pixel_format = V4L2_PIX_FMT_YUYV; // Example format, adjust as needed
    frmival.width = 640; // Example width, adjust as needed
    frmival.height = 480; // Example height, adjust as needed

    printf("\nSupported frame intervals for %dx%d:\n", frmival.width, frmival.height);
    while (enumerate_frame_intervals(fd, &frmival) == 0) {
        printf("  %d/%d fps\n", frmival.discrete.numerator, frmival.discrete.denominator);
        frmival.index++;
    }

    // Query autofocus control
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (query_control(fd, &ctrl) < 0) {
        printf("\nAutofocus control not supported.\n");
    } else {
        printf("\nAutofocus control supported.\n");
        printf("  Name: %s\n", ctrl.name);
        printf("  Type: %d\n", ctrl.type);
        printf("  Minimum: %d\n", ctrl.minimum);
        printf("  Maximum: %d\n", ctrl.maximum);
        printf("  Step: %d\n", ctrl.step);
        printf("  Default: %d\n", ctrl.default_value);
    }

    close(fd);
    return 0;
}

