    } else {
        printf("\nAutofocus control supported.\n");
        printf("  Name: %s\n", ctrl.name);
        printf("  Type: %d\n", ctrl.type);
        printf("  Minimum: %d\n", ctrl.minimum);
        printf("  Maximum: %d\n", ctrl.maximum);
        printf("  Step: %d\n", ctrl.step);
        printf("  Default: %d\n", ctrl.default_value);
    }

    close(fd);
    return 0;
}

