#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

// Define pulse width increment/decrement
#define PULSE_WIDTH_INCREMENT 10

// Global variables for pulse widths
int pan_pulse_width = CENTER_PULSE_WIDTH;
int tilt_pulse_width = CENTER_PULSE_WIDTH;

// Function prototypes
void signal_handler(int signal);
void update_pan_pulse_width(int button_state);
void update_tilt_pulse_width(int button_state);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    gpioPWM(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit program
}

// Function to update pan pulse width based on button state
void update_pan_pulse_width(int button_state) {
    if (button_state == 0) { // Button is pressed (active low)
        pan_pulse_width += PULSE_WIDTH_INCREMENT;
        if (pan_pulse_width > MAX_PULSE_WIDTH) {
            pan_pulse_width = MAX_PULSE_WIDTH;
        }
        gpioPWM(PAN_SERVO_PIN, pan_pulse_width);
    }
}

// Function to update tilt pulse width based on button state
void update_tilt_pulse_width(int button_state) {
    if (button_state == 0) { // Button is pressed (active low)
        tilt_pulse_width += PULSE_WIDTH_INCREMENT;
        if (tilt_pulse_width > MAX_PULSE_WIDTH) {
            tilt_pulse_width = MAX_PULSE_WIDTH;
        }
        gpioPWM(TILT_SERVO_PIN, tilt_pulse_width);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors on buttons
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set initial PWM duty cycle (center position)
    gpioPWM(PAN_SERVO_PIN, CENTER_PULSE_WIDTH);
    gpioPWM(TILT_SERVO_PIN, CENTER_PULSE_WIDTH);

    // Print startup message
    printf("Pan-Tilt Control Program\n");
    printf("Pan Servo: GPIO%d (PWM), Tilt Servo: GPIO%d (PWM)\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Up: GPIO%d, Down: GPIO%d, Left: GPIO%d, Right: GPIO%d\n", UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center position: %d us\n", CENTER_PULSE_WIDTH);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read button states
        int up_button_state = gpioRead(UP_BUTTON_PIN);
        int down_button_state = gpioRead(DOWN_BUTTON_PIN);
        int left_button_state = gpioRead(LEFT_BUTTON_PIN);
        int right_button_state = gpioRead(RIGHT_BUTTON_PIN);

        // Update pulse widths based on button presses
        update_pan_pulse_width(right_button_state);
        update_pan_pulse_width(left_button_state);
        update_tilt_pulse_width(up_button_state);
        update_tilt_pulse_width(down_button_state);

        // Delay
        gpioDelay(50000); // 50 ms
    }

    return 0;
}

