#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <curl/curl.h>
#include <jansson.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_TIME_MS 2000
#define POLL_INTERVAL_MS 100
#define IMAGE_QUALITY 85
#define MOTION_CAPTURES_DIR "motion_captures"
#define DEFAULT_IP "127.0.0.1"
#define DEFAULT_PORT 8080

// Global variables
static volatile int running = 1;
static char *ip_address = DEFAULT_IP;
static int port = DEFAULT_PORT;

// Structure to hold image data for libcurl
struct MemoryStruct {
  char *memory;
  size_t size;
};

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int debounce_motion();
int capture_image(char *filename);
int create_json_payload(const char *filename, char *timestamp, int motion_status, int gpio_pin, char *json_payload);
int post_data(const char *url, const char *json_payload, const char *filename);
void signal_handler(int signal);
void cleanup();
void log_error(const char *message);

// Helper function to get current timestamp with microseconds
char* get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t nowtime = ts.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, ts.tv_nsec / 1000);
    return strdup(buf); // Remember to free the allocated memory
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(GPIO_PIN);
}

// Debounce motion detection
int debounce_motion() {
    int motion_detected = 0;
    for (int i = 0; i < DEBOUNCE_TIME_MS / POLL_INTERVAL_MS; ++i) {
        if (read_pir_sensor()) {
            motion_detected = 1;
        }
        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }
    return motion_detected;
}

// Capture image using raspistill
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -q %d -o %s/%s.jpg", IMAGE_QUALITY, MOTION_CAPTURES_DIR, filename);
    int status = system(command);
    if (status == -1) {
        log_error("Failed to execute raspistill command");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspistill command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Create JSON payload
int create_json_payload(const char *filename, char *timestamp, int motion_status, int gpio_pin, char *json_payload) {
    json_t *root = json_object();
    json_object_set_new(root, "filename", json_string(filename));
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "motion_status", json_integer(motion_status));
    json_object_set_new(root, "gpio_pin", json_integer(gpio_pin));

    json_payload = json_dumps(root, JSON_REAL_PRECISION(5));
    json_decref(root);
    return 0;
}

// Post data to server
int post_data(const char *url, const char *json_payload, const char *filename) {
    CURL *curl;
    CURLcode res;
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s/%s.jpg", MOTION_CAPTURES_DIR, filename);

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        struct curl_httppost *formpost = NULL;
        struct curl_httppost *lastptr = NULL;
        curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "json_payload", CURLFORM_COPYCONTENTS, json_payload, CURLFORM_END);
        curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "image", CURLFORM_FILE, filepath, CURLFORM_END);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_formfree(formpost);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated.\n");
}

// Log error messages
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        ip_address = argv[1];
    }
    if (argc > 2) {
        port = atoi(argv[2]);
    }

    // Create motion_captures directory if it doesn't exist
    if (mkdir(MOTION_CAPTURES_DIR, 0777) == -1 && errno != EEXIST) {
        log_error("Failed to create motion_captures directory");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_pir_sensor()) {
            if (debounce_motion()) {
                // Generate filename and timestamp
                char *timestamp = get_timestamp();
                char filename[64];
                snprintf(filename, sizeof(filename), "%s_motion", timestamp);

                // Capture image
                if (capture_image(filename) == 0) {
                    // Create JSON payload
                    char *json_payload = NULL;
                    create_json_payload(filename, timestamp, 1, GPIO_PIN, json_payload);

                    // Post data to server
                    char url[128];
                    snprintf(url, sizeof(url), "http://%s:%d/upload", ip_address, port);
                    if (post_data(url, json_payload, filename) != 0) {
                        log_error("Failed to post data to server");
                    }

                    free(json_payload);
                } else {
                    log_error("Failed to capture image");
                }
                free(timestamp);
            }
        }
        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

