        log_message("Error opening GPIO edge file.");
        close(gpio_value_fd);
        fclose(log_file);
        return 1;
    }
    if (write(edge_fd, "falling", 7) < 0) {
        log_message("Error writing to GPIO edge file.");
        close(edge_fd);
        close(gpio_value_fd);
        fclose(log_file);
        return 1;
    }
    close(edge_fd);

    char value[2];
    while (program_running) {
        if (read(gpio_value_fd, value, 1) > 0) {
            if (value[0] == '0') {
