                if (capture_image() != 0) {
                    log_message("Image capture failed.");
                }
                usleep(DEBOUNCE_DELAY_MS * 1000); // Debounce
            }
        } else {
            log_message("Error reading GPIO value.");
            break;
        }
        usleep(1000); // Check every 1ms
    }

    close(gpio_value_fd);
    fclose(log_file);
    log_message("Program exiting.");
    return 0;
}

