#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <sys/select.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define CROPPED_WIDTH 200
#define CROPPED_HEIGHT 150
#define OUTPUT_FILENAME "cropped.yuv"

static int fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;
static FILE *output_file = NULL;
static volatile sig_atomic_t stop_flag = 0;

// Signal handler for SIGINT and SIGTERM
static void signal_handler(int signum) {
    (void)signum; // Suppress unused parameter warning
    stop_flag = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to handle errors and exit
static void error_exit(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

// Function to initialize the V4L2 device
static int init_device(const char *device_name) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", device_name);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Request a single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    return 0;
}

// Function to start streaming
static int start_streaming() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to stop streaming
static int stop_streaming() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Function to unmap the buffer
static int unmap_buffer() {
    if (munmap(buffer, buffer_size) < 0) {
        perror("Error unmapping buffer");
        return -1;
    }
    return 0;
}

// Function to close the device
static int close_device() {
    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

// Function to capture a frame
static int capture_frame() {
    fd_set fds;
    struct timeval tv;
    struct v4l2_buffer buf;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Select interrupted by signal, retrying...\n");
            return -1; // Retry
        }
        perror("Error in select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1; // Timeout
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Function to crop the image
static int crop_image() {
    unsigned char *src = (unsigned char *)buffer;
    unsigned char *dst = NULL;
    size_t i, j, k;

    dst = (unsigned char *)malloc(CROPPED_WIDTH * CROPPED_HEIGHT * 2); // YUYV
    if (dst == NULL) {
        perror("Error allocating memory for cropped image");
        return -1;
    }

    for (i = 0; i < CROPPED_HEIGHT; i++) {
        for (j = 0; j < CROPPED_WIDTH; j++) {
            for (k = 0; k < 2; k++) {
                dst[i * CROPPED_WIDTH * 2 + j * 2 + k] = src[(i + 150) * IMAGE_WIDTH * 2 + (j + 200) * 2 + k];
            }
        }
    }

    return (int)dst; // Return pointer to cropped image
}

// Function to write the cropped image to a file
static int write_to_file(const unsigned char *cropped_image) {
    output_file = fopen(OUTPUT_FILENAME, "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_image, 1, CROPPED_WIDTH * CROPPED_HEIGHT * 2, output_file);
    if (bytes_written != CROPPED_WIDTH * CROPPED_HEIGHT * 2) {
        perror("Error writing to output file");
        fclose(output_file);
        return -1;
    }

    if (fclose(output_file) != 0) {
        perror("Error closing output file");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the device
    if (init_device(DEVICE_NAME) < 0) {
        error_exit("Device initialization failed");
    }

    // Start streaming
    if (start_streaming() < 0) {
        error_exit("Failed to start streaming");
    }

    // Capture a frame
    if (capture_frame() < 0) {
        fprintf(stderr, "Failed to capture frame, exiting...\n");
        goto cleanup;
    }

    // Crop the image
    unsigned char *cropped_image = (unsigned char *)crop_image();
    if (cropped_image == NULL) {
        fprintf(stderr, "Failed to crop image, exiting...\n");
        goto cleanup;
    }

    // Write the cropped image to a file
    if (write_to_file(cropped_image) < 0) {
        fprintf(stderr, "Failed to write image to file, exiting...\n");
        free(cropped_image);
        goto cleanup;
    }

    free(cropped_image);

cleanup:
    // Stop streaming
    stop_streaming();

    // Unmap the buffer
    unmap_buffer();

    // Close the device
    close_device();

    return 0;
}

