    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Select interrupted by signal, retrying...\n");
            return -1; // Retry
        }
        perror("Error in select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1; // Timeout
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Function to crop the image
static int crop_image() {
    unsigned char *src = (unsigned char *)buffer;
    unsigned char *dst = NULL;
    size_t i, j, k;

    dst = (unsigned char *)malloc(CROPPED_WIDTH * CROPPED_HEIGHT * 2); // YUYV
    if (dst == NULL) {
        perror("Error allocating memory for cropped image");
        return -1;
    }

    for (i = 0; i < CROPPED_HEIGHT; i++) {
        for (j = 0; j < CROPPED_WIDTH; j++) {
            for (k = 0; k < 2; k++) {
                dst[i * CROPPED_WIDTH * 2 + j * 2 + k] = src[(i + 150) * IMAGE_WIDTH * 2 + (j + 200) * 2 + k];
            }
        }
    }

    return (int)dst; // Return pointer to cropped image
}

// Function to write the cropped image to a file
static int write_to_file(const unsigned char *cropped_image) {
    output_file = fopen(OUTPUT_FILENAME, "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_image, 1, CROPPED_WIDTH * CROPPED_HEIGHT * 2, output_file);
    if (bytes_written != CROPPED_WIDTH * CROPPED_HEIGHT * 2) {
        perror("Error writing to output file");
        fclose(output_file);
        return -1;
    }

    if (fclose(output_file) != 0) {
        perror("Error closing output file");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the device
    if (init_device(DEVICE_NAME) < 0) {
        error_exit("Device initialization failed");
    }

    // Start streaming
    if (start_streaming() < 0) {
        error_exit("Failed to start streaming");
    }

    // Capture a frame
    if (capture_frame() < 0) {
        fprintf(stderr, "Failed to capture frame, exiting...\n");
        goto cleanup;
    }

    // Crop the image
    unsigned char *cropped_image = (unsigned char *)crop_image();
    if (cropped_image == NULL) {
        fprintf(stderr, "Failed to crop image, exiting...\n");
        goto cleanup;
    }

    // Write the cropped image to a file
    if (write_to_file(cropped_image) < 0) {
        fprintf(stderr, "Failed to write image to file, exiting...\n");
        free(cropped_image);
        goto cleanup;
    }

    free(cropped_image);

cleanup:
    // Stop streaming
    stop_streaming();

    // Unmap the buffer
    unmap_buffer();

    // Close the device
    close_device();

    return 0;
}

