#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define neutral position (90 degrees)
#define NEUTRAL_POSITION 90

// Define minimum and maximum angles
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define PWM range (0-1000000)
#define PWM_RANGE 1000000

// Global variables for pan and tilt angles
int pan_angle = NEUTRAL_POSITION;
int tilt_angle = NEUTRAL_POSITION;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int gpio, int angle);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO and PWM
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes to output
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    return 0;
}

// Set servo angle
int set_servo_angle(int gpio, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d)\n", angle);
        return 1;
    }

    // Calculate pulse width (500us - 2500us for 0-180 degrees)
    int pulse_width = (int)(((float)(angle) / 180.0) * 2000.0 + 500.0);

    // Set PWM duty cycle
    gpioPWM(gpio, pulse_width);

    return 0;
}

// Cleanup GPIO
void cleanup_gpio() {
    // Set servos to neutral position
    set_servo_angle(PAN_GPIO, NEUTRAL_POSITION);
    set_servo_angle(TILT_GPIO, NEUTRAL_POSITION);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set initial servo positions
    set_servo_angle(PAN_GPIO, pan_angle);
    set_servo_angle(TILT_GPIO, tilt_angle);

    printf("Use arrow keys to control servos. Press 'q' to quit.\n");

    // Main loop
    while (1) {
        int c = getchar();

        if (c == 'q') {
            break;
        }

        switch (c) {
            case 'w': // Up arrow
                tilt_angle += 5;
                if (tilt_angle > MAX_ANGLE) {
                    tilt_angle = MAX_ANGLE;
                }
                if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                    tilt_angle -= 5; // Revert angle if out of range
                }
                break;
            case 's': // Down arrow
                tilt_angle -= 5;
                if (tilt_angle < MIN_ANGLE) {
                    tilt_angle = MIN_ANGLE;
                }
                if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                    tilt_angle += 5; // Revert angle if out of range
                }
                break;
            case 'a': // Left arrow
                pan_angle -= 5;
                if (pan_angle < MIN_ANGLE) {
                    pan_angle = MIN_ANGLE;
                }
                if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                    pan_angle += 5; // Revert angle if out of range
                }
                break;
            case 'd': // Right arrow
                pan_angle += 5;
                if (pan_angle > MAX_ANGLE) {
                    pan_angle = MAX_ANGLE;
                }
                if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                    pan_angle -= 5; // Revert angle if out of range
                }
                break;
            default:
                // Ignore other characters
                break;
        }

        // Delay
        usleep(100000); // 100ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

