// Function to read CPU temperature from file
char *read_cpu_temp() {
    FILE *fp;
    char *temp_str = malloc(10 * sizeof(char)); // Allocate memory for the temperature string
    if (temp_str == NULL) {
        perror("Failed to allocate memory for temperature string");
        return NULL;
    }

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        free(temp_str);
        return NULL;
    }

    int temp_raw;
    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fprintf(stderr, "Failed to read temperature from file\n");
        fclose(fp);
        free(temp_str);
        return NULL;
    }

    fclose(fp);

    float temp_celsius = (float)temp_raw / 1000.0;
    snprintf(temp_str, 10, "%.1f C", temp_celsius);

    return temp_str;
}

// Function to read CPU usage from file
float read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0;
    static unsigned long long prev_idle_total = 0;
    float cpu_usage;

    fp = fopen(STAT_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open stat file");
        return -1.0;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Failed to read CPU stats from file\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;

    if (prev_total == 0) {
        prev_total = total;
        prev_idle_total = idle_total;
        return 0.0; // Initial value
    }

    unsigned long long total_diff = total - prev_total;
    unsigned long long idle_diff = idle_total - prev_idle_total;

    cpu_usage = (1.0 - (float)idle_diff / (float)total_diff) * 100.0;

    prev_total = total;
    prev_idle_total = idle_total;

    return cpu_usage;
}

// Function to initialize the OLED display
int oled_init() {
    // Initialization sequence (SSD1306)
    unsigned char init_sequence[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio/oscillator frequency
        0xA8, 0x3F, // Multiplex ratio
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode (horizontal)
        0xA1,       // Segment remap
        0xC8,       // COM scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF
        0xA6,       // Normal/Inverse display
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_sequence); i++) {
