// Function to clear the OLED display buffer
void oled_clear() {
    unsigned char buffer[OLED_WIDTH * OLED_HEIGHT / 8];
    memset(buffer, 0x00, sizeof(buffer));

    // Set column and page address
    i2cWriteByteData(i2c_handle, 0x00, 0x21); // Column start/end address
    i2cWriteByteData(i2c_handle, 0x00, 0x00); // Column start address
    i2cWriteByteData(i2c_handle, 0x00, OLED_WIDTH - 1); // Column end address
    i2cWriteByteData(i2c_handle, 0x00, 0x22); // Page start/end address
    i2cWriteByteData(i2c_handle, 0x00, 0x00); // Page start address
    i2cWriteByteData(i2c_handle, 0x00, (OLED_HEIGHT / 8) - 1); // Page end address

    // Send the buffer
    i2cWriteDevice(i2c_handle, buffer, sizeof(buffer));
}

// Function to draw a pixel on the OLED display
void oled_draw_pixel(int x, int y, int color) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) {
        return; // Out of bounds
    }

    int page = y / 8;
    int bit = y % 8;

    // Set column and page address
    i2cWriteByteData(i2c_handle, 0x00, 0x21); // Column start/end address
    i2cWriteByteData(i2c_handle, 0x00, x); // Column start address
    i2cWriteByteData(i2c_handle, 0x00, x); // Column end address
    i2cWriteByteData(i2c_handle, 0x00, 0x22); // Page start/end address
    i2cWriteByteData(i2c_handle, 0x00, page); // Page start address
    i2cWriteByteData(i2c_handle, 0x00, page); // Page end address

    // Read the current byte from the display
    char current_byte = i2cReadByteData(i2c_handle, 0x40 + x + page * OLED_WIDTH);

    if (color) {
        current_byte |= (1 << bit);
    } else {
        current_byte &= ~(1 << bit);
    }

    // Write the updated byte to the display
    i2cWriteByteData(i2c_handle, 0x40 + x + page * OLED_WIDTH, current_byte);
}

// Function to draw a character on the OLED display
void oled_draw_char(int x, int y, char c) {
    if (c < 32 || c > 126) {
        c = 0; // Use space for unknown characters
    }

    c -= 32; // Adjust index to font array

    for (int i = 0; i < 5; i++) {
        unsigned char pixel_data = font[c][i];
        for (int j = 0; j < 7; j++) {
            if ((pixel_data >> j) & 0x01) {
                oled_draw_pixel(x + i, y + j, 1);
            }
        }
    }
}

// Function to draw a string on the OLED display
void oled_draw_string(int x, int y, char *str) {
    int current_x = x;
    while (*str) {
        oled_draw_char(current_x, y, *str);
        current_x += 6; // Character width + 1 pixel spacing
        str++;
    }
}

