    oled_clear();

    oled_draw_string(0, 0, "Temp:");
    oled_draw_string(40, 0, temp_str);

    char cpu_str[20];
    snprintf(cpu_str, sizeof(cpu_str), "CPU: %.1f%%", cpu_usage);
    oled_draw_string(0, 16, cpu_str);
