#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <wiringPiSPI.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define WIND_VANE_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define DEBOUNCE_MS 5

// Calibration values (adjust these based on your setup)
#define ANEMOMETER_PULSES_PER_METER 2.0  // Example: 2 pulses per meter
#define WIND_VANE_DIRECTIONS 16          // Number of directions on the vane

// Global variables
volatile int pulse_count = 0;
int lcd_handle;
int spi_handle;
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void anemometer_interrupt(int gpio, int level, uint32_t tick, void *user);
float calculate_wind_speed(int pulses);
int read_wind_direction();
void update_lcd(float wind_speed, int wind_direction);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_print(int row, int col, const char *text);
int spi_read_adc(int channel);
int i2c_write_byte(int data);
int i2c_read_byte();

// Anemometer interrupt handler
void anemometer_interrupt(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_MS * 1000) // Debounce
    {
        pulse_count++;
        last_tick = current_tick;
    }
}

// Calculate wind speed from pulse count
float calculate_wind_speed(int pulses)
{
    return (float)pulses / ANEMOMETER_PULSES_PER_METER * (1000.0 / SAMPLE_WINDOW_MS) * 60.0; // m/s
}

// Read wind direction from MCP3008 ADC
int read_wind_direction()
{
    int adc_value = spi_read_adc(WIND_VANE_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading wind direction from ADC\n");
        return -1; // Indicate error
    }

    // Map ADC value to wind direction (0-15)
    return (int)(((float)adc_value / 1023.0) * WIND_VANE_DIRECTIONS);
}

// Update LCD with wind speed and direction
void update_lcd(float wind_speed, int wind_direction)
{
    char wind_speed_str[20];
    char wind_direction_str[20];

    snprintf(wind_speed_str, sizeof(wind_speed_str), "Speed: %.2f m/s", wind_speed);
    snprintf(wind_direction_str, sizeof(wind_direction_str), "Dir: %d", wind_direction);

    lcd_clear();
    lcd_print(0, 0, wind_speed_str);
    lcd_print(1, 0, wind_direction_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// LCD initialization function
int lcd_init()
{
    // Initialization sequence (adjust based on your LCD)
    i2c_write_byte(0x33); // Initialize
    i2c_write_byte(0x32); // Initialize
    i2c_write_byte(0x06); // Cursor move direction
    i2c_write_byte(0x0C); // Display on, cursor off, blink off
    i2c_write_byte(0x28); // 4-bit mode, 2 lines, 5x8 font
    i2c_write_byte(0x01); // Clear display
    delay(2);             // Wait for clear display to complete

    return 0;
}

// LCD clear function
void lcd_clear()
{
    i2c_write_byte(0x01); // Clear display command
    delay(2);             // Wait for clear display to complete
}

// LCD print function
void lcd_print(int row, int col, const char *text)
{
    int addr;
    if (row == 0) {
        addr = 0x80 + col; // First line
    } else {
        addr = 0xC0 + col; // Second line
    }
    i2c_write_byte(addr);

    for (int i = 0; text[i] != '\0'; i++) {
        i2c_write_byte(text[i]);
    }
}

// SPI read ADC function
int spi_read_adc(int channel)
{
    unsigned char buffer[3];
    buffer[0] = 0x01;                  // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;                  // Don't care

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// I2C write byte function
int i2c_write_byte(int data)
{
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        result = wiringPiI2CWrite(i2c_handle, data);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "I2C write failed, retrying...\n");
            delay(10); // Small delay before retry
            retries--;
        }
    }

    if (result != 0) {
        fprintf(stderr, "I2C write failed after multiple retries\n");
        return -1; // Indicate failure
    }

    return 0;
}

// I2C read byte function
int i2c_read_byte()
{
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        result = wiringPiI2CRead(i2c_handle);
        if (result >= 0) {
            break; // Success
        } else {
            fprintf(stderr, "I2C read failed, retrying...\n");
            delay(10); // Small delay before retry
            retries--;
        }
    }

    if (result < 0) {
        fprintf(stderr, "I2C read failed after multiple retries\n");
        return -1; // Indicate failure
    }

    return result;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1)
    {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize wiringPi SPI
    spi_handle = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle == -1)
    {
        fprintf(stderr, "wiringPi SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize wiringPi I2C
    i2c_handle = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (i2c_handle == -1)
    {
        fprintf(stderr, "wiringPi I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0)
    {
        fprintf(stderr, "LCD initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up anemometer interrupt
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_interrupt, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Reset pulse count
        pulse_count = 0;

        // Wait for sample window
        delay(SAMPLE_WINDOW_MS);

        // Calculate wind speed
        float wind_speed = calculate_wind_speed(pulse_count);

        // Read wind direction
        int wind_direction = read_wind_direction();
        if (wind_direction == -1) {
            wind_direction = -1; // Indicate error
        }

        // Update LCD
        update_lcd(wind_speed, wind_direction);

        // Print data to console
        printf("Wind Speed: %.2f m/s, Wind Direction: %d\n", wind_speed, wind_direction);
    }

    // Cleanup
    lcd_clear();
    gpioTerminate();
    close(spi_handle);
    close(i2c_handle);

    return 0;
}

