#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0

#define LCD_BACKLIGHT 0x08  // On
#define ENABLE 0b00000100 // Enable bit

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
int lcd_initialized = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
float calculate_flow_rate(int pulses);
void display_flow_rate(float flow_rate);
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void lcd_set_cursor(int col, int row);
void signal_handler(int signal);
void cleanup();

// Interrupt handler for pulse counting
void pulse_counter(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Function to calculate flow rate in LPM
float calculate_flow_rate(int pulses)
{
    return (float)pulses * 60.0 / 450.0; // 450 pulses per liter
}

// Function to display flow rate on LCD
void display_flow_rate(float flow_rate)
{
    char buffer[17];

    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_string("Flow Rate:");
    lcd_set_cursor(0, 1);
    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    lcd_string(buffer);
}

// LCD initialization function
void lcd_init()
{
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1)
    {
        fprintf(stderr, "Error: Failed to initialize I2C LCD.\n");
        return;
    }

    // Initialise display
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // Turn on display, cursor off, blink off
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    lcd_byte(0x02, LCD_CMD); // Return home
    lcd_initialized = 1;
}

// Function to send byte to LCD
void lcd_byte(int bits, int mode)
{
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    // High bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high | ENABLE);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high & ~ENABLE);
    delayMicroseconds(500);

    // Low bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low | ENABLE);
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low & ~ENABLE);
    delayMicroseconds(500);
}

// Function to send string to LCD
void lcd_string(const char *s)
{
    while (*s)
    {
        lcd_byte(*s++, LCD_CHR);
    }
}

// Function to clear LCD
void lcd_clear()
{
    lcd_byte(0x01, LCD_CMD);
    delayMicroseconds(500);
}

// Function to set cursor position
void lcd_set_cursor(int col, int row)
{
    int row_offsets[] = {0x00, 0x40};
    lcd_byte(0x80 | (col + row_offsets[row]), LCD_CMD);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup()
{
    if (lcd_initialized)
    {
        lcd_clear();
        lcd_byte(0x08, LCD_CMD); // Turn off display
    }
    gpioTerminate();
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO mode for flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Initialize LCD
    lcd_init();
    if (!lcd_initialized)
    {
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for pulse counting
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0)
    {
        fprintf(stderr, "Error: Failed to set up interrupt handler.\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1)
    {
        pulse_count = 0; // Reset pulse count
        gpioDelay(1000);  // Wait for 1 second

        float flow_rate = calculate_flow_rate(pulse_count);
        display_flow_rate(flow_rate);

        // Sensor absent condition check
        if (pulse_count == 0)
        {
            lcd_clear();
            lcd_set_cursor(0, 0);
            lcd_string("Sensor Absent");
            lcd_set_cursor(0, 1);
            lcd_string("Check Connection");
            delay(2000); // Display for 2 seconds
        }
    }

    return 0;
}

