#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows (anodes)
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
// Define GPIO pins for columns (cathodes)
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};

// Define the number of rows and columns
