};

// Function to set the state of a GPIO pin
int set_gpio(int pin, int value) {
    int result = gpioWrite(pin, value);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %d\n", pin, value, result);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to display a frame on the LED matrix
int display_frame(const int frame[num_rows][num_cols]) {
    for (int row = 0; row < num_rows; row++) {
        // Set row pin HIGH
        if (set_gpio(row_pins[row], 1) != 0) return 1;

        for (int col = 0; col < num_cols; col++) {
            // Set column pin LOW if the LED should be on
            if (frame[row][col] == 1) {
                if (set_gpio(col_pins[col], 0) != 0) return 1;
            } else {
                if (set_gpio(col_pins[col], 1) != 0) return 1;
            }
        }

        // Delay for the specified time
        gpioDelay(delay_us);

        // Set row pin LOW
        if (set_gpio(row_pins[row], 0) != 0) return 1;

        // Reset all column pins to HIGH
        for (int col = 0; col < num_cols; col++) {
            if (set_gpio(col_pins[col], 1) != 0) return 1;
        }
    }
    return 0;
}

// Function to shift the animation data left
void shift_left(int frame[num_rows][num_cols]) {
    int temp[num_rows][num_cols];
    for (int i = 0; i < num_rows; i++) {
        for (int j = 0; j < num_cols; j++) {
            temp[i][j] = frame[i][(j + 1) % num_cols];
        }
    }
    for (int i = 0; i < num_rows; i++) {
        for (int j = 0; j < num_cols; j++) {
            frame[i][j] = temp[i][j];
        }
    }
}

// Function to shift the animation data right
void shift_right(int frame[num_rows][num_cols]) {
    int temp[num_rows][num_cols];
    for (int i = 0; i < num_rows; i++) {
        for (int j = 0; j < num_cols; j++) {
            temp[i][j] = frame[i][(j + num_cols - 1) % num_cols];
        }
    }
    for (int i = 0; i < num_rows; i++) {
        for (int j = 0; j < num_cols; j++) {
            frame[i][j] = temp[i][j];
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Set all row pins to LOW
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 0);
    }

    // Set all column pins to HIGH
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the row pins as outputs
    for (int i = 0; i < num_rows; i++) {
        gpioSetMode(row_pins[i], PI_OUTPUT);
    }

    // Set the column pins as outputs
    for (int i = 0; i < num_cols; i++) {
        gpioSetMode(col_pins[i], PI_OUTPUT);
        gpioWrite(col_pins[i], 1); // Initialize all column pins to HIGH
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    int current_frame = 0;
    int left_to_right = 1; // 1 for left-to-right, 0 for right-to-left
    int frame[num_rows][num_cols];

    // Copy the initial animation data to the frame
    for (int i = 0; i < num_rows; i++) {
        for (int j = 0; j < num_cols; j++) {
            frame[i][j] = animation_data[0][i][j];
        }
    }

    while (1) {
        // Display the current frame
        if (display_frame(frame) != 0) {
            fprintf(stderr, "Error displaying frame\n");
            break;
        }

        // Shift the animation data
        if (left_to_right) {
            shift_left(frame);
        } else {
            shift_right(frame);
        }

        // Delay for the frame delay
        gpioDelay(frame_delay_ms * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    signal_handler(SIGINT);

    return 0;
}

