    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Set all row anodes LOW
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 0);
    }
    // Set all column cathodes HIGH
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as outputs and column pins as outputs
    for (int i = 0; i < num_rows; i++) {
        gpioSetMode(row_pins[i], PI_OUTPUT);
        gpioWrite(row_pins[i], 0); // Initialize row pins to LOW
    }
    for (int i = 0; i < num_cols; i++) {
        gpioSetMode(col_pins[i], PI_OUTPUT);
        gpioWrite(col_pins[i], 1); // Initialize column pins to HIGH
    }

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Iterate through columns
        for (int col = 0; col < num_cols; col++) {
            // Set the current column cathode LOW
            gpioWrite(col_pins[col], 0);

            // Light the LEDs sequentially by setting the corresponding row anodes HIGH
            for (int row = 0; row < num_rows; row++) {
                gpioWrite(row_pins[row], 1);
                gpioDelay(10000); // 10ms delay
                gpioWrite(row_pins[row], 0);
            }

            // Set the current column cathode HIGH again
            gpioWrite(col_pins[col], 1);

            // Delay for 150ms
            gpioDelay(150000);
        }
    }

    return 0;
}

