#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x4A
#define MEASURE_REG 0x00
#define DISTANCE_REG 0x01
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration (example)
typedef struct {
    int integration_time;
    int modulation_frequency;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_distance(int i2c_handle);
int log_data(FILE *fp, int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize the MLX75031 sensor
int initialize_sensor(int i2c_handle) {
    // Example initialization sequence (replace with actual sequence from datasheet)
    // This is a placeholder, actual initialization depends on the sensor's configuration
    char init_data[] = {0x01, 0x02, 0x03}; // Example initialization data
    int result;

    // Write initialization data to the sensor
    result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != sizeof(init_data)) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Add a small delay after initialization
    gpioDelay(10000); // 10ms

    return 0;
}

// Function to read distance data from the MLX75031 sensor
int read_distance(int i2c_handle) {
    char cmd = MEASURE_REG; // Command to trigger measurement
    char buffer[2]; // Buffer to store the distance data
    int result;

    // Write the command to trigger a measurement
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Delay to allow the sensor to perform the measurement
    gpioDelay(5000); // 5ms

    // Read the distance data from the sensor
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the distance value
    int distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Function to log data to a CSV file
int log_data(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write the timestamp and distance to the file
    fprintf(fp, "%s,%d\n", timestamp, distance);

    // Flush the buffer to ensure data is written to the file
    fflush(fp);

    return 0;
}

int main() {
    int distance;
    int file_exists = 0;

    // Check if the log file exists
    if (access(LOG_FILE, F_OK) == 0) {
        file_exists = 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the CSV header if the file is newly created
    if (!file_exists) {
        fprintf(log_file, "Timestamp,Distance\n");
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance data
        distance = read_distance(i2c_handle);

        if (distance < 0) {
            fprintf(stderr, "Error reading distance, logging -1\n");
            log_data(log_file, -1);
            // Attempt to re-open the I2C handle
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-opening fails
            }
            if (initialize_sensor(i2c_handle) != 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                terminate = 1;
            }
        } else {
            // Log the data
            log_data(log_file, distance);
        }

        // Delay for the specified interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Close the I2C bus
    i2cClose(i2c_handle);

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

