    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the CSV header if the file is newly created
    if (!file_exists) {
        fprintf(log_file, "Timestamp,Distance\n");
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance data
        distance = read_distance(i2c_handle);

        if (distance < 0) {
            fprintf(stderr, "Error reading distance, logging -1\n");
            log_data(log_file, -1);
            // Attempt to re-open the I2C handle
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-opening fails
            }
            if (initialize_sensor(i2c_handle) != 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                terminate = 1;
            }
        } else {
            // Log the data
