        }

        // Delay for the specified interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Close the I2C bus
    i2cClose(i2c_handle);

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

