#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "proximity.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
int log_detection();
int blink_led();
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int sensor_pin;
    int led_pin;
    char *log_file_name;
} gpio_config_t;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to log the detection event
int log_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (fprintf(log_file, "%s Object detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to blink the LED
int blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(100);        // Wait 100ms
    gpioWrite(LED_PIN, 0); // Turn LED off
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();       // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    int last_state = 1; // Assume initially no object detected (HIGH)

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0 && last_state == 1) {
            // Falling edge detected
            if (log_detection() != 0) {
                fprintf(stderr, "Error logging detection\n");
            }
            if (blink_led() != 0) {
                fprintf(stderr, "Error blinking LED\n");
            }
        }

        last_state = sensor_value;
        gpioDelay(100); // Poll every 100ms
    }

    cleanup();
    return 0;
}

