#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define PROX_DATA_REG 0x08
#define ALS_DATA_REG 0x0A
#define LOG_FILE "biometric_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_sensor_data(int *proximity, int *ambient_light);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the Si1145 sensor
int si1145_init() {
    int part_id;
    int result;

    // Read PART_ID register
    result = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", result);
        return -1;
    }
    part_id = result;

    // Verify PART_ID
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Si1145 sensor initialized successfully.\n");
    return 0;
}

// Function to read proximity and ambient light data from the sensor
int read_sensor_data(int *proximity, int *ambient_light) {
    int result;

    // Read proximity data
    result = i2cReadByteData(i2c_handle, PROX_DATA_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    *proximity = result;

    // Read ambient light data
    result = i2cReadByteData(i2c_handle, ALS_DATA_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading ambient light data: %d\n", result);
        return -1;
    }
    *ambient_light = result;

    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log data to a file
int log_data(const char *timestamp, int proximity, int ambient_light) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

int main() {
    int proximity, ambient_light;
    char *timestamp;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(timestamp, proximity, ambient_light) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

