#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TRIGGER_PULSE_DURATION 10 // us
#define ECHO_TIMEOUT 30000       // us
#define LOG_INTERVAL 60          // seconds
#define WATERING_THRESHOLD 15.0  // cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void trigger_sensor();
long long measure_pulse_width();
float calculate_distance(long long pulse_width);
void log_distance(float distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long long measure_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < ECHO_TIMEOUT) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= ECHO_TIMEOUT) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < ECHO_TIMEOUT) {
        gpioDelay(1);
        count++;
    }

    if (count >= ECHO_TIMEOUT) {
        return -2; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance
}

// Function to log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately

        if (distance < WATERING_THRESHOLD) {
            fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
            fflush(log_file);
        }
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_sensor();
        long long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[30];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
                fprintf(log_file, "%s, Error: Distance out of range (%.2f cm)\n", timestamp, distance);
                fflush(log_file);
            }
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            if (pulse_width == -1) {
                fprintf(log_file, "%s, Error: Echo timeout (rising edge)\n", timestamp);
            } else {
                fprintf(log_file, "%s, Error: Echo timeout (falling edge)\n", timestamp);
            }
            fflush(log_file);
        }

        gpioDelay(LOG_INTERVAL * 1000); // Delay for 60 seconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

