#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATAL 0x9C
#define APDS9960_PDATAH 0x9D

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int read_proximity();
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// APDS9960 initialization function
int apds9960_init() {
    // Enable proximity and RGB sensors
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time (ATIME)
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set proximity time (PTIME)
    if (i2cWriteByteData(i2c_handle, APDS9960_PTIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to PTIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set wait time (WTIME)
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to WTIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set proximity pulse count (PPULSE)
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register: %s\n", strerror(errno));
        return -1;
    }

    // Set control register (AGAIN = 4x, PGAIN = 4x)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
        return -1;
    }

    // Set config register 1 (default values)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG1, 0x60) < 0) {
        fprintf(stderr, "Error writing to CONFIG1 register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read proximity value
int read_proximity() {
    int proximity;

    proximity = i2cReadWordData(i2c_handle, APDS9960_PDATAL);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }

    return proximity;
}

// Function to read RGB color values
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    int ret;

    ret = i2cReadWordData(i2c_handle, APDS9960_RDATAL);
    if (ret < 0) {
        fprintf(stderr, "Error reading red data: %s\n", strerror(errno));
        return -1;
    }
    *red = (uint16_t)ret;

    ret = i2cReadWordData(i2c_handle, APDS9960_GDATAL);
    if (ret < 0) {
        fprintf(stderr, "Error reading green data: %s\n", strerror(errno));
        return -1;
    }
    *green = (uint16_t)ret;

    ret = i2cReadWordData(i2c_handle, APDS9960_BDATAL);
    if (ret < 0) {
        fprintf(stderr, "Error reading blue data: %s\n", strerror(errno));
        return -1;
    }
    *blue = (uint16_t)ret;

    return 0;
}

// Function to log data to CSV file
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (apds9960_init() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue, proximity;

    // Main loop
    while (!terminate) {
        // Read proximity value
        proximity = read_proximity();
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
                continue;
            }
            if (apds9960_init() < 0) {
                fprintf(stderr, "APDS9960 re-initialisation failed\n");
                terminate = 1;
                continue;
            }
            gpioDelay(100); // Small delay after re-initialization
            continue;
        }

        // Read RGB color values
        if (read_rgb(&red, &green, &blue) < 0) {
            fprintf(stderr, "Error reading RGB values, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
                continue;
            }
            if (apds9960_init() < 0) {
                fprintf(stderr, "APDS9960 re-initialisation failed\n");
                terminate = 1;
                continue;
            }
            gpioDelay(100); // Small delay after re-initialization
            continue;
        }

        // Check if proximity exceeds threshold
        if (proximity > PROXIMITY_THRESHOLD) {
            log_data(red, green, blue, proximity);
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

