int vl53l0x_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[2];
    buf[0] = reg & 0xFF;
    buf[1] = data;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to VL53L0X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
