    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L0X register 0x%02X\n", reg);
        return -1;
    }
    *data = buf[0];
    return 0;
}

// Function to write a word to a VL53L0X register
int vl53l0x_write_word(int handle, uint16_t reg, uint16_t data) {
    char buf[3];
    buf[0] = reg & 0xFF;
    buf[1] = (data >> 8) & 0xFF;
    buf[2] = data & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing word to VL53L0X register 0x%02X\n", reg);
