void signal_handler(int signal);

// Structure for VL53L0X configuration (example)
typedef struct {
    uint8_t signal_rate_limit;
    uint8_t inter_measurement_period;
} vl53l0x_config_t;

// Function to write a byte to a VL53L0X register
int vl53l0x_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[2];
    buf[0] = reg & 0xFF;
    buf[1] = data;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to VL53L0X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L0X register
int vl53l0x_read_byte(int handle, uint16_t reg, uint8_t *data) {
    char buf[1];
    buf[0] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L0X register 0x%02X\n", reg);
        return -1;
    }
    *data = buf[0];
    return 0;
}

// Function to write a word to a VL53L0X register
int vl53l0x_write_word(int handle, uint16_t reg, uint16_t data) {
    char buf[3];
    buf[0] = reg & 0xFF;
    buf[1] = (data >> 8) & 0xFF;
    buf[2] = data & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing word to VL53L0X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a word from a VL53L0X register
int vl53l0x_read_word(int handle, uint16_t reg, uint16_t *data) {
    char buf[2];
    char read_buf[2];
    buf[0] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading word from VL53L0X register 0x%02X\n", reg);
        return -1;
    }
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

