#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define CH101_ADDR 0x70
#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x01
#define TRIGGER_VALUE 0x01
#define TRIGGER_DELAY_MS 50
#define SAMPLE_DELAY_MS 200
#define LOG_FILE "distance_log.txt"
#define TIMESTAMP_BUFFER_SIZE 20

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_ch101();
int trigger_sensor();
int read_distance(unsigned char *data);
float convert_to_mm(unsigned char *data);
int log_distance(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the CH101 sensor
int init_ch101() {
    // No specific initialization needed for CH101 in this example
    // Assuming the sensor is already configured for continuous measurement mode
    return 0;
}

// Trigger the sensor to start a measurement
int trigger_sensor() {
    int result = i2cWriteByteData(i2c_handle, TRIGGER_REG, TRIGGER_VALUE);
    if (result != 0) {
        fprintf(stderr, "Error triggering sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance data from the sensor
int read_distance(unsigned char *data) {
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to millimeters
float convert_to_mm(unsigned char *data) {
    unsigned int raw_distance = (data[0] << 8) | data[1];
    return (float)raw_distance / 10.0; // Example conversion, adjust as needed
}

// Log the distance to a file
int log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[TIMESTAMP_BUFFER_SIZE];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    printf("%s, %.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_ch101() != 0) {
        fprintf(stderr, "Error initializing CH101 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned char distance_data[2];
    float distance_mm;

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        if (trigger_sensor() == 0) {
            // Wait for the trigger delay
            gpioDelay(TRIGGER_DELAY_MS * 1000); // Convert ms to us

            // Read the distance data
            if (read_distance(distance_data) == 0) {
                // Convert the data to millimeters
                distance_mm = convert_to_mm(distance_data);

                // Log the distance
                log_distance(distance_mm);
            } else {
                fprintf(stderr, "Error reading distance, skipping sample.\n");
            }
        } else {
            fprintf(stderr, "Error triggering sensor, skipping sample.\n");
        }

        // Wait for the sample delay
        gpioDelay(SAMPLE_DELAY_MS * 1000); // Convert ms to us
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

