// Structure for I2C configuration
typedef struct {
    int bus;
    int address;
    int flags;
} i2c_config_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_config_t config = {I2C_BUS, I2C_ADDRESS, 0};
    i2c_handle = i2cOpen(config.bus, config.address, config.flags);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send the measurement command
int send_measurement_command() {
    uint8_t command[] = {0x00, 0x01, 0x00, 0x00};
    int result = i2cWriteDevice(i2c_handle, (char *)command, MEASUREMENT_COMMAND_LENGTH);
    if (result != MEASUREMENT_COMMAND_LENGTH) {
        fprintf(stderr, "Error sending measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the measurement response
int read_measurement_response(uint8_t *response) {
    int result = i2cReadDevice(i2c_handle, (char *)response, MEASUREMENT_RESPONSE_LENGTH);
    if (result != MEASUREMENT_RESPONSE_LENGTH) {
        fprintf(stderr, "Error reading measurement response: %d\n", result);
        return -1;
    }
    return 0;
}

