#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L0X_REG_INTERRUPT_CLEAR 0x0086
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x008F

// Expected model ID
#define VL53L0X_MODEL_ID 0xEA

// I2C handle
int i2c_handle;

// Signal handler flag
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read a byte from an I2C register
int read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a byte to an I2C register
int write_byte(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from an I2C register
int read_word(int handle, uint8_t reg, uint16_t *value)
{
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading word from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)result;
    return 0;
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x(int handle)
{
    uint8_t model_id;

    // Read the model ID
    if (read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    // Verify the model ID
    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L0X_MODEL_ID);
        return -1;
    }

    // Clear interrupt
    if (write_byte(handle, VL53L0X_REG_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance(int handle, uint16_t *distance)
{
    uint8_t range_status;
    uint16_t raw_distance;

    // Read range status
    if (read_byte(handle, VL53L0X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read raw distance
    if (read_word(handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &raw_distance) != 0) {
        fprintf(stderr, "Error reading raw distance\n");
        return -1;
    }

    *distance = raw_distance;
    return 0;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t distance;
        char timestamp[20];

        // Read distance
        if (read_distance(i2c_handle, &distance) == 0) {
            // Get timestamp
            get_timestamp(timestamp);

            // Print distance
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance, continuing...\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

