#include <pigpio.h>

// Si1182 I2C address
#define SI1182_ADDR 0x60

// Si1182 register addresses
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_ALS_VIS_DATA0 0x22

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    printf("Ctrl+C pressed. Cleaning up...\n");
    terminate = 1;
}

// Function to read a 16-bit value from the Si1182
int read_si1182_data(int i2c_handle, uint16_t *data)
{
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, SI1182_REG_ALS_VIS_DATA0, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading data from Si1182: %d\n", result);
        return -1;
    }

    *data = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    uint16_t proximity_data;

    // Main loop
    while (!terminate) {
        if (read_si1182_data(i2c_handle, &proximity_data) == 0) {
            printf("Proximity: %u\n", proximity_data);
        } else {
            fprintf(stderr, "Failed to read proximity data. Retrying...\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

