#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4A
#define DISTANCE_REG 0x00

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        keep_running = 0;
        printf("Exiting gracefully...\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500 ms

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT) failed");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM) failed");
        return 1;
    }

    // Open I2C bus
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence by reading a register
    unsigned char buf[1];
    if (read(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error: MLX75030 not found at address 0x%02X\n", MLX75030_ADDR);
        close(i2c_fd);
        return 1;
    }

    printf("MLX75030 sensor found at address 0x%02X\n", MLX75030_ADDR);

    // Main loop
    while (keep_running) {
        // Read distance measurement
        unsigned char distance_data[2];
        if (read(i2c_fd, distance_data, 2) != 2) {
            fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        } else {
            // Combine the two bytes into a 16-bit value
            int distance = (distance_data[0] << 8) | distance_data[1];
            printf("Distance: %d mm\n", distance);
        }

        // Sleep for 500 ms
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

