#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define OPT3101 I2C address
#define OPT3101_ADDR 0x64

// Define OPT3101 register addresses (Example - adjust based on datasheet)
#define OPT3101_REG_DISTANCE 0x00
#define OPT3101_REG_AMBIENT 0x02
#define OPT3101_REG_ERROR_FLAGS 0x04
#define OPT3101_REG_CONFIG 0x06

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
    int ambient_light;
    int error_flags;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the OPT3101 sensor
int init_opt3101() {
    // Example configuration (adjust based on datasheet)
    // This is a placeholder, refer to the OPT3101 datasheet for proper configuration
    char config_data[2] = {0x01, 0x02}; // Example configuration values
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to OPT3101 configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the OPT3101 sensor
int read_opt3101(sensor_data_t *data) {
    char buffer[6]; // Buffer to hold distance, ambient light, and error flags
    int result;

    // Read distance (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, OPT3101_REG_DISTANCE, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from OPT3101: %d\n", result);
        return -1;
    }

    // Parse the data (adjust based on the OPT3101 datasheet)
    data->distance = (buffer[0] << 8) | buffer[1];
    data->ambient_light = (buffer[2] << 8) | buffer[3];
    data->error_flags = (buffer[4] << 8) | buffer[5];

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0); // Bus 1, address 0x64, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the OPT3101 sensor
    if (init_opt3101() != 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read data from the sensor
        if (read_opt3101(&sensor_data) == 0) {
            // Print the data to the console
            printf("Distance: %d, Ambient Light: %d, Error Flags: 0x%X\n",
                   sensor_data.distance, sensor_data.ambient_light, sensor_data.error_flags);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

