#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // 200 ms timeout in microseconds
#define MIN_PULSE_DURATION_US 10 // Minimum pulse duration in microseconds
#define MAX_PULSE_DURATION_US 38000 // Maximum pulse duration in microseconds (38 ms)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(MIN_PULSE_DURATION_US); // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Function to measure the echo pulse duration
long measure_pulse_duration() {
    long start_tick, end_tick, pulse_duration;

    // Wait for the echo pin to go HIGH (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go LOW (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;
    if (pulse_duration < 0) {
        // Handle tick rollover
        pulse_duration += 0xFFFFFFFF + 1; // Add the maximum tick value and 1
    }

    return pulse_duration;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_duration) {
    if (pulse_duration <= 0 || pulse_duration > MAX_PULSE_DURATION_US) {
        fprintf(stderr, "Invalid pulse duration: %ld us\n", pulse_duration);
        return -1.0; // Indicate an error
    }

    float time_taken = (float)pulse_duration / 1000000.0; // Convert to seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Calculate distance in cm
    return distance;
}

// Function to log the distance with a timestamp
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_duration = measure_pulse_duration();

        if (pulse_duration > 0) {
            float distance = calculate_distance(pulse_duration);
            if (distance > 0) {
                log_distance(distance);
            }
        }

        gpioDelay(1000000); // Wait for 1 second
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

