#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD_LENGTH 8
#define RANGE_PROFILE_LENGTH 128
#define NUM_BINS 64
#define BIN_SIZE 2 // 16-bit
#define TARGET_THRESHOLD 1.0 // meters
#define GPIO_LED 17
#define LED_ON_TIME 2 // seconds
#define INTRUSION_LOG_FILE "intrusion_log.csv"

// Global variables
int uart_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    char uart_device[50];
    int baud_rate;
    int gpio_led;
    char log_file[50];
} Config;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_range_profile(int uart_handle, unsigned char *data, int data_length);
int decode_range_profile(const unsigned char *data, int data_length, unsigned short *range_profile);
int detect_target(const unsigned short *range_profile, int num_bins, float threshold);
int log_intrusion(const char *timestamp, float distance);
int control_led(int gpio_pin, int on_time);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    uart_handle = serOpen(device, baud_rate, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", device);
        return -1;
    }
    return uart_handle;
}

// Read range profile from UART
int read_range_profile(int uart_handle, unsigned char *data, int data_length) {
    int bytes_read = serRead(uart_handle, data, data_length);
    if (bytes_read != data_length) {
        fprintf(stderr, "Error reading from UART: %d bytes read (expected %d)\n", bytes_read, data_length);
        return -1;
    }
    return 0;
}

// Decode range profile data
int decode_range_profile(const unsigned char *data, int data_length, unsigned short *range_profile) {
    if (data_length != RANGE_PROFILE_LENGTH) {
        fprintf(stderr, "Error: Invalid data length for range profile: %d (expected %d)\n", data_length, RANGE_PROFILE_LENGTH);
        return -1;
    }

    for (int i = 0; i < NUM_BINS; i++) {
        range_profile[i] = (data[i * BIN_SIZE + 1] << 8) | data[i * BIN_SIZE];
    }
    return 0;
}

// Detect target within threshold
int detect_target(const unsigned short *range_profile, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        float distance = (float)range_profile[i] / 100.0; // Assuming range is in cm
        if (distance <= threshold) {
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

// Log intrusion event
int log_intrusion(const char *timestamp, float distance) {
    log_file = fopen(INTRUSION_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", INTRUSION_LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

// Control LED
int control_led(int gpio_pin, int on_time) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(on_time * 1000000); // Delay for on_time seconds
    gpioWrite(gpio_pin, 0); // Turn LED off
    return 0;
}

// Get ISO 8601 timestamp
