#include <string.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor();
void control_buzzer(int state);
void log_event(int sensor_state);
void signal_handler(int signal);

// Function to read the sensor state
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to control the buzzer
void control_buzzer(int state) {
    int result = gpioWrite(BUZZER_PIN, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to buzzer: %d\n", result);
    }
}

// Function to log events to a file
void log_event(int sensor_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor state: %d\n", timestamp, sensor_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Release GPIO resources
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioSetMode(SENSOR_PIN, PI_INPUT); // Set sensor pin to input
    gpioSetMode(BUZZER_PIN, PI_INPUT); // Set buzzer pin to input

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("obstacle_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_sensor_state = -1; // Initialize to an invalid state

    // Main loop
    while (program_running) {
        int sensor_state = read_sensor();
        if (sensor_state == -1) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break; // Exit the loop if there's an error reading the sensor
        }

        // Control the buzzer based on sensor state
        if (sensor_state == 0) { // Obstacle detected (active-low)
            control_buzzer(1); // Turn on buzzer
        } else {
            control_buzzer(0); // Turn off buzzer
        }

        // Log the event if the sensor state has changed
        if (sensor_state != previous_sensor_state) {
            log_event(sensor_state);
            previous_sensor_state = sensor_state;
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup (in case the loop exits without a signal)
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioSetMode(SENSOR_PIN, PI_INPUT); // Set sensor pin to input
    gpioSetMode(BUZZER_PIN, PI_INPUT); // Set buzzer pin to input

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate(); // Terminate pigpio

    return 0;
}

