    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result;

    // Read two bytes from register 0x00 (example)
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    // Convert the two bytes to a distance value (example)
    *distance = (float)((buf[0] << 8) | buf[1]) / 10.0; // Example conversion

    return 0;
}

// Log data to file
int log_data(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Set GPIO alert
void set_gpio_alert(int level) {
    gpioWrite(GPIO_ALERT, level);
}

