#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define LED_GPIO 18
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(uint16_t *distance);
float calculate_distance(uint16_t raw_distance);
int calculate_led_frequency(float distance);
int set_led_state(int state);
void log_data(float distance, int frequency);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    uint8_t integration_time;
    uint8_t measurement_mode;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor with retries
int read_distance(uint16_t *distance) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error, retry %d\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to calculate distance in centimeters (example formula)
float calculate_distance(uint16_t raw_distance) {
    // Replace with the actual formula from the datasheet
    return (float)raw_distance * 0.1; // Example: 0.1 cm per unit
}

// Function to calculate LED blink frequency based on distance
int calculate_led_frequency(float distance) {
    // Replace with the actual mapping from distance to frequency
    if (distance < 10.0) {
        return 10; // 10 Hz
    } else if (distance < 50.0) {
        return 5;  // 5 Hz
    } else {
        return 1;  // 1 Hz
    }
}

// Function to set the LED state
int set_led_state(int state) {
    gpioWrite(LED_GPIO, state);
    return 0;
}

// Function to log data with timestamp
void log_data(float distance, int frequency) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Distance: %.2f cm, Frequency: %d Hz\n", timestamp, distance, frequency);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_distance;
    float distance;
    int frequency;
    int led_state = 0; // 0 = off, 1 = on
    int half_cycle_delay_us;

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&raw_distance) == 0) {
            // Calculate distance
            distance = calculate_distance(raw_distance);

            // Calculate LED frequency
            frequency = calculate_led_frequency(distance);

            // Calculate half-cycle delay in microseconds
            half_cycle_delay_us = 500000 / frequency; // 0.5 seconds / frequency

            // Blink the LED
            set_led_state(led_state);
            gpioDelay(half_cycle_delay_us);
            led_state = !led_state; // Toggle LED state

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance, attempting to re-initialize I2C\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting\n");
                break;
            }
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    set_led_state(0); // Turn off LED
    gpioTerminate();

    return 0;
}

