#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A
#define MEASURE_CMD 0x00
#define MEASURE_DELAY_US 100000 // 100ms
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000 // 10ms
#define LOG_FILE "distance_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx75030_address;
    char *log_filename;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_distance(int handle, unsigned short *distance);
int log_data(FILE *fp, unsigned short distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read distance from MLX75030
int read_distance(int handle, unsigned short *distance) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(handle, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_US);
            retries++;
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        result = i2cReadDevice(handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_US);
            retries++;
            continue;
        }

        *distance = (buf[0] << 8) | buf[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Log data to file
int log_data(FILE *fp, unsigned short distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .mlx75030_address = MLX75030_ADDR,
        .log_filename = LOG_FILE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(config.i2c_bus, config.mlx75030_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned short distance;

    // Main loop
    while (!terminate) {
        if (read_distance(i2c_handle, &distance) == 0) {
            if (log_data(log_file, distance) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

