FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio);
int debounce(int gpio, int state);
int log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value
int read_sensor(int gpio) {
    int value = -1; // Initialize to an invalid value
    for (int i = 0; i < 3; ++i) {
        value = gpioRead(gpio);
        if (value >= 0) {
            return value;
        } else {
            fprintf(stderr, "Error reading GPIO %d, attempt %d\n", gpio, i + 1);
            gpioDelay(1); // Small delay before retrying
        }
    }
    fprintf(stderr, "Failed to read GPIO %d after multiple attempts\n", gpio);
    return -1; // Return -1 to indicate failure
}

// Function to debounce sensor
int debounce(int gpio, int state) {
    gpioDelay(DEBOUNCE_MS * 1000); // Convert ms to microseconds
    int new_state = read_sensor(gpio);
    if (new_state == state) {
        return state;
    } else {
        return -1; // Indicate debounce failure
    }
}

// Function to log events
int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    int result = fprintf(log_file, "%s,%d,%s\n", timestamp, sensor_id, event_type);
    if (result < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

