                    log_event(1, "CLEARED");
                }
                sensor1_state = debounced_state;
            }
        }

        if (new_sensor2_state != sensor2_state) {
            int debounced_state = debounce(SENSOR_2_GPIO, new_sensor2_state);
            if (debounced_state != -1) {
                if (debounced_state == 0 && sensor2_state == 1) {
                    log_event(2, "DETECTED");
                } else if (debounced_state == 1 && sensor2_state == 0) {
                    log_event(2, "CLEARED");
                }
                sensor2_state = debounced_state;
            }
        }

        gpioDelay(10000); // Delay 10ms
    }

    // Clean up
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

