#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_MM_REG 0x01
#define TIMEOUT_MS 50
#define SAMPLE_DELAY_MS 500
#define CSV_FILENAME "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_register(int fd, uint8_t reg, uint8_t data);
int read_distance(int fd);
void log_data(FILE *fp, int distance_mm);
void signal_handler(int signal);

// I2C read function with timeout
int i2c_read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int fd) {
    uint8_t status;
    uint8_t distance_data[2];
    int distance_mm;
    struct timespec start, current;
    long elapsed_ms;

    // Poll MEAS_STATUS register until it indicates a successful measurement
    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        if (i2c_read_register(fd, MEAS_STATUS_REG, &status, 1) != 0) {
            fprintf(stderr, "Error reading MEAS_STATUS: %s\n", strerror(errno));
            return -1;
        }
        if ((status & 0x01) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &current);
            elapsed_ms = (current.tv_sec - start.tv_sec) * 1000 + (current.tv_nsec - start.tv_nsec) / 1000000;
            if (elapsed_ms >= TIMEOUT_MS) {
                fprintf(stderr, "Timeout waiting for measurement\n");
                return -1;
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        } else {
            break; // Measurement ready
        }
    } while (1);

    // Read distance data
    if (i2c_read_register(fd, DISTANCE_MM_REG, distance_data, 2) != 0) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    distance_mm = (distance_data[0] << 8) | distance_data[1];

    return distance_mm;
}

// Log data to CSV file
void log_data(FILE *fp, int distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d\n", timestamp, distance_mm);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int distance_mm;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        distance_mm = read_distance(i2c_fd);
        if (distance_mm >= 0) {
            log_data(csv_file, distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(SAMPLE_DELAY_MS);
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

