    char cmd[1] = {0x00}; // Dummy command to trigger a reading
    char data[2];
    int distance;

    // Trigger a single measurement (refer to VL53L1X datasheet for correct command)
    if (i2cWriteI2CBlockData(i2c_handle, 0x00, cmd, 1) != 1) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for data to be ready (polling - can be improved with interrupts)
    int ready = 0;
    int timeout = 100; // Timeout after 100ms
    while (!ready && timeout > 0) {
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, data, 1) != 1) {
            fprintf(stderr, "Error reading data ready status\n");
            return -1;
        }
        ready = (data[0] & 0x01);
        gpioDelay(1000); // Wait 1ms
        timeout--;
    }

    if (!ready) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read the distance (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
