#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // Timeout in microseconds (0.5 seconds)
#define MIN_DISTANCE 2.0       // Minimum valid distance in cm
#define MAX_DISTANCE 400.0     // Maximum valid distance in cm
#define BUZZER_THRESHOLD 30.0  // Distance threshold for buzzer activation in cm
#define BUZZER_FREQUENCY 1000  // Buzzer frequency in Hz
#define SAMPLE_INTERVAL_MS 100 // Sample interval in milliseconds

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t start, uint32_t end);
void control_buzzer(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us delay
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
        timeout_flag = 0; // Reset timeout flag
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 0; // Reset echo received flag
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start, uint32_t end) {
    uint32_t diff = end - start;
    double time_taken = (double)diff / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm
    return distance;
}

// Function to control the buzzer based on distance
void control_buzzer(double distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioPWM(BUZZER_PIN, 128); // Activate buzzer (50% duty cycle)
    } else {
        gpioPWM(BUZZER_PIN, 0);    // Deactivate buzzer
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();        // Release pigpio resources
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM frequency for buzzer
    gpioSetPWMfrequency(BUZZER_PIN, BUZZER_FREQUENCY);

    // Register interrupt callback function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor system started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the ultrasonic sensor
        trigger_pulse();

        // Wait for echo or timeout
        echo_received = 0;
        timeout_flag = 0;
        start_tick = 0;
        end_tick = 0;

        gpioDelay(100); // Small delay before checking for echo

        if (!echo_received) {
            timeout_flag = 1;
        }

        // Calculate distance
        double distance = 0.0;
        if (!timeout_flag) {
            distance = calculate_distance(start_tick, end_tick);
        }

        // Validate distance
        if (timeout_flag) {
            printf("Sensor absent (timeout)\n");
        } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading (out-of-range): %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    return 0;
}

