#define OPEN_ANGLE 1800
#define CLOSE_ANGLE 1000
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define ZMQ_ENDPOINT "tcp://*:5555"

// Global variables
int i2c_handle;
FILE *log_file;
void *context = NULL;
void *subscriber = NULL;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
int servo_set_angle(int angle);
void log_event(const char *message);
