// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0015
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L1X_REG_VHV_CONFIG_PAD_SCL_SDA_EXTSUP_HV 0x0089

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_event("I2C write error");
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, char *data) {
    char reg_buf[1];
    reg_buf[0] = reg;
    int result = i2cWriteDevice(i2c_handle, reg_buf, 1);
    if (result != 0) {
        log_event("I2C write (address select) error");
        return -1;
    }
    result = i2cReadDevice(i2c_handle, data, 1);
    if (result != 0) {
        log_event("I2C read error");
        return -1;
    }
    return 0;
}

