#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define MIN_PULSE_DURATION 100 // Minimum valid pulse duration in microseconds
#define MAX_PULSE_DURATION 30000 // Maximum valid pulse duration in microseconds
#define TIMEOUT_DURATION 60000 // Timeout duration in microseconds
#define SAMPLE_INTERVAL 200 // Sampling interval in milliseconds

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_duration);
void log_distance(double distance);
void timeout_handler();
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_received = 1;
    } else if (level == 0) {
        falling_tick = tick;
    }
}

// Function to calculate distance from pulse duration
double calculate_distance(uint32_t pulse_duration) {
    return (double)pulse_duration * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file and stdout
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file);
    printf("%s, %.2f\n", timestamp, distance);
}

// Function to handle timeout
void timeout_handler() {
    fprintf(stderr, "Warning: Timeout occurred. No echo received within %d ms.\n", TIMEOUT_DURATION / 1000);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        echo_received = 0;
        rising_tick = 0;
        falling_tick = 0;

        trigger_pulse();

        gpioDelay(SAMPLE_INTERVAL);

        if (echo_received) {
            uint32_t pulse_duration = falling_tick - rising_tick;

            if (pulse_duration < MIN_PULSE_DURATION) {
                fprintf(stderr, "Warning: Pulse duration too short: %d us\n", pulse_duration);
            } else if (pulse_duration > MAX_PULSE_DURATION) {
                fprintf(stderr, "Warning: Pulse duration too long: %d us\n", pulse_duration);
            } else {
                double distance = calculate_distance(pulse_duration);
                log_distance(distance);
            }
        } else {
            timeout_handler();
        }
    }

    return 0;
}

