#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD 17
#define MOTOR_BACKWARD 18
#define TRIGGER_PIN 24
#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300
#define MAX_RETRIES 5
#define BASE_DELAY_MS 1

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void trigger_callback(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to write a byte to a VL53L1X register with retry and exponential backoff
int vl53l1x_write_byte(int reg, uint8_t data) {
    int retries = 0;
    int delay_ms = BASE_DELAY_MS;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, reg, data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (reg 0x%02X, data 0x%02X), retrying in %d ms (attempt %d/%d)\n", reg, data, delay_ms, retries + 1, MAX_RETRIES);
            gpioDelay(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, data 0x%02X)\n", MAX_RETRIES, reg, data);
    return -1; // Failure
}

// Function to read a byte from a VL53L1X register with retry and exponential backoff
int vl53l1x_read_byte(int reg, uint8_t *data) {
    int retries = 0;
    int delay_ms = BASE_DELAY_MS;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, reg);
        if (result >= 0) {
            *data = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X), retrying in %d ms (attempt %d/%d)\n", reg, delay_ms, retries + 1, MAX_RETRIES);
            gpioDelay(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", MAX_RETRIES, reg);
    return -1; // Failure
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    uint8_t model_id;

    // Check sensor ID
    if (vl53l1x_read_byte(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", model_id);
        return -1;
    }

    // Soft reset
    if (vl53l1x_write_byte(0x0000, 0x00) != 0) {
        fprintf(stderr, "Failed to soft reset sensor\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Start measurement
    if (vl53l1x_write_byte(VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Failed to start measurement\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(uint16_t *distance) {
    uint8_t range_status;
    uint8_t data[2];
    int retries = 0;
    int delay_ms = BASE_DELAY_MS;
    int result;

    // Poll status register until data ready
    do {
        result = vl53l1x_read_byte(VL53L1X_REG_RESULT_RANGE_STATUS, &range_status);
        if (result != 0) {
            fprintf(stderr, "Failed to read range status\n");
            return -1;
        }

        if ((range_status & 0x01) == 0) {
            gpioDelay(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Timeout waiting for data ready\n");
                return -1;
            }
        } else {
            break; // Data ready
        }
    } while (1);

    // Read distance
    if (vl53l1x_read_byte(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &data[0]) != 0) {
        fprintf(stderr, "Failed to read distance (LSB)\n");
        return -1;
    }
    if (vl53l1x_read_byte(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &data[1]) != 0) {
        fprintf(stderr, "Failed to read distance (MSB)\n");
        return -1;
    }

    *distance = (data[1] << 8) | data[0];

    return 0;
}

// Function to control the motor forward
void motor_forward() {
    gpioWrite(MOTOR_FORWARD, 1);
    gpioWrite(MOTOR_BACKWARD, 0);
    printf("Motor: FORWARD\n");
}

// Function to control the motor backward
void motor_backward() {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 1);
    printf("Motor: BACKWARD\n");
}

// Function to stop the motor
void motor_stop() {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
    printf("Motor: STOP\n");
}

// Interrupt service routine for the trigger pin
void trigger_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        uint16_t distance;
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD_LOW) {
                motor_forward();
            } else if (distance > DISTANCE_THRESHOLD_HIGH) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            fprintf(stderr, "Failed to read distance in ISR\n");
            motor_stop(); // Stop motor on error
        }
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_DOWN); // Pull-down resistor

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L1X sensor and motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100000); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    motor_stop();
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

