#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ELE0_FIL_CFG 0x5E
#define MPR121_ELE1_FIL_CFG 0x5F
#define MPR121_ELE2_FIL_CFG 0x60
#define MPR121_ELE3_FIL_CFG 0x61
#define MPR121_ELE4_FIL_CFG 0x62
#define MPR121_ELE5_FIL_CFG 0x63
#define MPR121_ELE6_FIL_CFG 0x64
#define MPR121_ELE7_FIL_CFG 0x65
#define MPR121_ELE8_FIL_CFG 0x66
#define MPR121_ELE9_FIL_CFG 0x67
#define MPR121_ELE10_FIL_CFG 0x68
#define MPR121_ELE11_FIL_CFG 0x69
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// GPIO pin for LED
#define LED_PIN 27

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_register(int reg);
int mpr121_write_register(int reg, int value);
int mpr121_read_touch_status();
void led_on();
void led_off();
void log_proximity_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init() {
    // Reset MPR121
    if (mpr121_write_register(0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Stop mode
    if (mpr121_write_register(MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set ECR to stop mode\n");
        return -1;
    }

    // Configure electrode sensitivity and baseline filtering
    if (mpr121_write_register(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_register(MPR121_FDLR, 0x00) < 0) return -1;

    if (mpr121_write_register(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NCLF, 0x0E) < 0) return -1;
    if (mpr121_write_register(MPR121_FDLF, 0x00) < 0) return -1;

    // Set filter configuration
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_register(MPR121_ELE0_FIL_CFG + i, 0x10) < 0) return -1; // Example value
    }

    // Configure AFE and baseline filtering
    if (mpr121_write_register(MPR121_CONFIG1, 0x20) < 0) return -1; // Example value
    if (mpr121_write_register(MPR121_CONFIG2, 0x01) < 0) return -1; // Example value

    // Enter run mode
    if (mpr121_write_register(MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to set ECR to run mode\n");
        return -1;
    }

    return 0;
}

// Function to read a register from the MPR121
int mpr121_read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a register to the MPR121
int mpr121_write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to write register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status() {
    int low_byte = mpr121_read_register(MPR121_TOUCHSTATUS_L);
    int high_byte = mpr121_read_register(MPR121_TOUCHSTATUS_H);

    if (low_byte < 0 || high_byte < 0) {
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

// Function to turn the LED on
void led_on() {
    gpioWrite(LED_PIN, 1);
}

// Function to turn the LED off
void led_off() {
    gpioWrite(LED_PIN, 0);
}

// Function to log a proximity event to a file
void log_proximity_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Proximity event detected\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
