#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TRIGGER_PULSE_DURATION 10 // us
#define TIMEOUT_DURATION 30000   // us (30 ms)

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void triggerSensor();
long measurePulseWidth();
float calculateDistance(long pulseWidth);
void logDistance(float distance);
void signalHandler(int signal);
int initializeGPIO();
void cleanupGPIO();

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long measurePulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_DURATION) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_DURATION) {
        fprintf(stderr, "Error: Echo signal never went high (timeout).\n");
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_DURATION) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_DURATION) {
        fprintf(stderr, "Error: Echo signal never went low (timeout).\n");
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance
}

// Function to log the distance to a file
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signalHandler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100); // Wait 100 us

    return 0; // Indicate success
}

// Function to cleanup GPIO resources
void cleanupGPIO() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signalHandler);

    // Initialize GPIO
    if (initializeGPIO() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        cleanupGPIO();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        triggerSensor();
        long pulseWidth = measurePulseWidth();

        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                logDistance(distance);
            } else {
                fprintf(stderr, "Error: Distance out of range (%.2f cm).\n", distance);
            }
        } else {
            fprintf(stderr, "Error: Pulse width measurement failed.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    cleanupGPIO();

    return 0;
}

