// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo (adjust as needed)
    gpioSetPWMrange(SERVO_PIN, 20000); // 20ms period (50Hz)
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50Hz

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;

    if (level == 1) {
        // Rising edge
        start_tick = tick;
    } else if (level == 0) {
        // Falling edge
        end_tick = tick;

        // Calculate pulse width
        uint32_t pulse_width = end_tick - start_tick;

        // Handle tick counter wrap-around
        if (end_tick < start_tick) {
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
        }

        // Set pulse width and flag
        pulse_data.pulse_width = pulse_width;
        pulse_data.new_pulse = 1;
    }
}

// Calculate distance in centimeters
float calculate_distance(uint32_t pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Moving average filter
float moving_average(float new_value, float *buffer, int buffer_size, int *index) {
    buffer[*index] = new_value;
    *index = (*index + 1) % buffer_size;

    float sum = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer[i];
    }
    return sum / buffer_size;
}

// Set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return 1;
    }

    // Map angle (0-180) to pulsewidth (1000-2000)
    int pulsewidth = (int)(SERVO_MIN_PULSEWIDTH + (float)angle / 180.0 * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH));

    gpioPWM(SERVO_PIN, pulsewidth); // Set PWM duty cycle
    return 0;
}

// Log data to CSV file
int log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance(cm),Angle(degrees)\n");
    }

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize moving average filter
    float distance_buffer[MOVING_AVERAGE_SIZE] = {0.0};
    int distance_index = 0;

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for a short period
        gpioDelay(100); // 100ms

        // Read pulse width and calculate distance
        float distance = -1.0;
        int angle = 90;

        if (pulse_data.new_pulse) {
            distance = calculate_distance(pulse_data.pulse_width);

            // Validate distance
            if (distance < 2.0 || distance > 400.0) {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
                distance = -1.0;
            }

            // Apply moving average filter
            distance = moving_average(distance, distance_buffer, MOVING_AVERAGE_SIZE, &distance_index);

            // Set servo angle based on distance (example)
            if (distance > 0) {
                angle = (int)(90.0 - (distance - 2.0) / 398.0 * 90.0); // Map distance to angle (0-180)
                if (angle < 0) angle = 0;
                if (angle > 180) angle = 180;
            }

            pulse_data.new_pulse = 0; // Reset flag
        }

        // Set servo angle
        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error setting servo angle!\n");
        }

        // Log data
        log_data(distance, angle);
    }

    // Clean up
    set_servo_angle(0); // Stop servo
    fclose(log_file);
    gpioTerminate();

    return 0;
}

