        fprintf(stderr, "Error reading MSB of distance\n");
        return -1;
    }
    if (vl53l1x_read_byte(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &lsb) != 0) {
        fprintf(stderr, "Error reading LSB of distance\n");
        return -1;
    }

    *distance = (msb << 8) | lsb;

    return 0;
}

