#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile int proximity_value = 0;
static volatile int interrupt_flag = 0;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor(int handle);
int read_proximity(int handle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void log_data(int proximity, const char *status);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C interface
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Function to configure the Si1102 sensor
int configure_sensor(int handle) {
    // Example configuration (adjust based on Si1102 datasheet)
    char config_data[] = {0x01, 0x00}; // Example register and value
    int result = i2cWriteDevice(handle, config_data, sizeof(config_data));
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the proximity value from the sensor
int read_proximity(int handle) {
    char command = 0x02; // Example command to trigger a read
    char buffer[2];
    int result;

    result = i2cWriteDevice(handle, &command, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing command to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Small delay for the sensor to prepare the data

    result = i2cReadDevice(handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    return (buffer[0] << 8) | buffer[1]; // Combine the two bytes into a 16-bit value
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    interrupt_flag = 1; // Set the flag to indicate an interrupt occurred
}

// Function to log data to a file
void log_data(int proximity, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Convert string to integer (hex/decimal)
                break;
            case 't':
                threshold = atoi(optarg); // Convert string to integer
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
