#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0    // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT_US 200000      // Timeout in microseconds (200ms)

// Global variables
static volatile int running = 1;
static double previous_frequency = 0.0;

// Function prototypes
double measure_distance();
double distance_to_frequency(double distance);
void set_pwm_frequency(double frequency);
void signal_handler(int signal);

// Function to measure distance using HC-SR04
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    if (diff_tick < 0) {
        diff_tick += 0xFFFFFFFF; // Handle tick rollover
    }

    double time_taken = (double)diff_tick / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

// Function to map distance to frequency on a logarithmic scale
double distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    }

    // Logarithmic mapping
    double log_distance = log10(distance / MIN_DISTANCE) / log10(MAX_DISTANCE / MIN_DISTANCE);
    double frequency = MIN_FREQUENCY * pow(MAX_FREQUENCY / MIN_FREQUENCY, log_distance);

    return frequency;
}

// Function to set PWM frequency
void set_pwm_frequency(double frequency) {
    int range = 1000; // PWM range
    int duty_cycle = 500; // 50% duty cycle

    gpioSetPWMrange(PWM_PIN, range);
    gpioSetPWMfrequency(PWM_PIN, (int)frequency);
    gpioPWM(PWM_PIN, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency to 0 initially
    gpioPWM(PWM_PIN, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance > 0) {
            double frequency = distance_to_frequency(distance);
            set_pwm_frequency(frequency);
            previous_frequency = frequency;
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            fprintf(stderr, "Error: Distance measurement failed. Using previous frequency.\n");
            set_pwm_frequency(previous_frequency);
        }

        gpioDelay(50); // Delay for 50ms
    }

    return 0;
}

