// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 5.0      // Minimum distance in cm
#define MAX_DISTANCE 50.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT 100000         // Timeout in microseconds (100ms)

// Global variable for echo start time
static volatile uint32_t echo_start_time = 0;

// Function prototypes
void triggerSensor();
float measureDistance();
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(float frequency);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();        // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(2);              // Wait 2 us
    gpioWrite(TRIGGER_PIN, 1); // Send trigger pulse
    gpioDelay(10);             // Wait 10 us
    gpioWrite(TRIGGER_PIN, 0); // End trigger pulse
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_time = tick;
    } else if (level == 0) {
        uint32_t echo_end_time = tick;
        uint32_t pulse_width = echo_end_time - echo_start_time;

        if (pulse_width > TIMEOUT) {
            fprintf(stderr, "Error: Echo timeout exceeded.\n");
        }
    }
}

// Function to measure the distance using the ultrasonic sensor
float measureDistance() {
    echo_start_time = 0; // Reset echo start time
    triggerSensor();

    // Wait for echo pulse to start (with timeout)
    int timeout_counter = 0;
    while (echo_start_time == 0 && timeout_counter < TIMEOUT) {
        gpioDelay(1); // Wait 1 us
        timeout_counter++;
    }

    if (echo_start_time == 0) {
        fprintf(stderr, "Error: No echo received.\n");
        return -1.0; // Indicate error
    }

    // Wait for echo pulse to end (with timeout)
    uint32_t echo_end_time = 0;
    timeout_counter = 0;
    while (echo_end_time == 0 && timeout_counter < TIMEOUT) {
        gpioDelay(1); // Wait 1 us
        if (gpioRead(ECHO_PIN) == 0) {
            echo_end_time = gpioTick();
        }
        timeout_counter++;
    }

    if (echo_end_time == 0) {
        fprintf(stderr, "Error: Echo pulse did not end.\n");
        return -1.0; // Indicate error
    }

    uint32_t pulse_width = echo_end_time - echo_start_time;

    if (pulse_width > TIMEOUT) {
        fprintf(stderr, "Error: Echo timeout exceeded.\n");
        return -1.0; // Indicate error
    }

    // Calculate distance in centimeters
    float distance = (pulse_width / 2.0) * (SPEED_OF_SOUND / 1000000.0);
    return distance;
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency
void setBuzzerFrequency(float frequency) {
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
    gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM frequency (initial value)
    gpioSetPWMfrequency(BUZZER_PIN, 1000); // Initial frequency

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    float last_valid_distance = 25.0; // Initial valid distance

    // Main loop
    while (1) {
        float distance = measureDistance();

        if (distance > 0) {
            last_valid_distance = distance;
            float frequency = mapDistanceToFrequency(distance);
            setBuzzerFrequency(frequency);
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            fprintf(stderr, "Error: Distance measurement failed. Using last valid distance.\n");
            float frequency = mapDistanceToFrequency(last_valid_distance);
            setBuzzerFrequency(frequency);
            printf("Using last valid distance: %.2f cm, Frequency: %.2f Hz\n", last_valid_distance, frequency);
        }

        gpioDelay(10000); // Wait 10 ms
    }

    return 0;
}

