#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MIN_DISTANCE 2.0       // Minimum valid distance in cm
#define MAX_DISTANCE 400.0     // Maximum valid distance in cm
#define TOO_CLOSE_DISTANCE 10.0 // Distance threshold for "Too close!" message

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Function to measure the echo pulse duration
long getPulseDuration()
{
    long startTime = 0, endTime = 0;

    // Wait for echo pin to go high (start of pulse)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        if (startTime == 0) startTime = gpioTick();
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US)
    {
        return -1; // Timeout
    }

    // Wait for echo pin to go low (end of pulse)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US)
    {
        return -1; // Timeout
    }

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration)
{
    if (pulseDuration < 0)
    {
        return -1.0; // Indicate error
    }
    return (float)pulseDuration * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to validate the distance
int validateDistance(float distance)
{
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Function to print the distance
void printDistance(float distance)
{
    if (distance < 0)
    {
        printf("Invalid reading\n");
    }
    else
    {
        printf("Distance: %.2f cm", distance);
        if (distance < TOO_CLOSE_DISTANCE)
        {
            printf(" Too close!\n");
        }
        else
        {
            printf("\n");
        }
    }
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse duration
        long pulseDuration = getPulseDuration();

        // Calculate the distance
        float distance = calculateDistance(pulseDuration);

        // Validate the distance
        if (validateDistance(distance))
        {
            // Print the distance
            printDistance(distance);
        }
        else
        {
            printf("Invalid reading\n");
        }

        // Wait 500 milliseconds
        gpioDelay(500);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

