    int distance;
    int status;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_distance();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the sensor
int initialize_sensor() {
    // Placeholder for sensor initialization code
    // Replace with actual initialization sequence from the ICU-20201 datasheet
    // This example assumes a simple write to a configuration register
    char init_data[] = {0x01, 0x02}; // Example initialization data
    int result = spiWrite(spi_handle, init_data, sizeof(init_data));
    if (result != sizeof(init_data)) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
sensor_data_t read_distance() {
    sensor_data_t data;
    char tx_buffer[2] = {0x00, 0x00}; // Example transmit buffer
    char rx_buffer[2];
    int result;

    gpioWrite(CS_PIN, 0); // Select the sensor
    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    gpioWrite(CS_PIN, 1); // Deselect the sensor

    if (result != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        data.distance = -1; // Indicate error
        data.status = -1;
        return data;
    }

    // Convert raw data to distance (mm) - replace with actual conversion formula
    data.distance = (rx_buffer[0] << 8) | rx_buffer[1]; // Example conversion
    data.status = 0; // Indicate success

    return data;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data.distance != -1) {
        fprintf(log_file, "%s,%d\n", timestamp, data.distance);
    } else {
        fprintf(log_file, "%s,ERROR\n", timestamp);
    }
    fflush(log_file); // Ensure data is written to disk immediately
}

