#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1175_ADDR 0x60
#define ALS_VISIBLE_REG 0x22
#define LOG_FILE "proximity_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_als_visible(uint16_t *als_visible);
int write_log(uint16_t als_visible);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si1175_address;
    char *log_filename;
} config_t;

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ALS Visible register
int read_als_visible(uint16_t *als_visible) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_VISIBLE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS Visible: %d\n", result);
        return -1;
    }
    *als_visible = (buf[1] << 8) | buf[0];
    return 0;
}

// Write to log file
int write_log(uint16_t als_visible) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s,%u\n", buf, als_visible);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    // Main loop
    uint16_t als_visible;
    while (!terminate) {
        if (read_als_visible(&als_visible) == 0) {
            write_log(als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in 5 seconds.\n");
        }
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

