#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define ALS_VIS_DATA0 0x22
#define PS1_DATA0 0x18
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_sensor_data(float *lux, int *proximity);
int log_data(float lux, int proximity);
void signal_handler(int signal);
char* get_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Get timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS.mmm\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Initialize the sensor
int init_sensor() {
    int part_id;

    // Read Part ID
    if (i2cReadByteData(i2c_handle, PART_ID_REG) < 0) {
        fprintf(stderr, "Error reading Part ID register.\n");
        return -1;
    }
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID register.\n");
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure Measurement Rate
    if (i2cWriteByteData(i2c_handle, MEAS_RATE_REG, 0x07) < 0) {
        fprintf(stderr, "Error writing to Measurement Rate register.\n");
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(float *lux, int *proximity) {
    int als_vis_data0, als_vis_data1, ps1_data0, ps1_data1;

    als_vis_data0 = i2cReadByteData(i2c_handle, ALS_VIS_DATA0);
    if (als_vis_data0 < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0 register.\n");
        return -1;
    }

    als_vis_data1 = i2cReadByteData(i2c_handle, ALS_VIS_DATA0 + 1);
    if (als_vis_data1 < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA1 register.\n");
        return -1;
    }

    ps1_data0 = i2cReadByteData(i2c_handle, PS1_DATA0);
    if (ps1_data0 < 0) {
        fprintf(stderr, "Error reading PS1_DATA0 register.\n");
        return -1;
    }

    ps1_data1 = i2cReadByteData(i2c_handle, PS1_DATA0 + 1);
    if (ps1_data1 < 0) {
        fprintf(stderr, "Error reading PS1_DATA1 register.\n");
        return -1;
    }

    *lux = (float)((als_vis_data1 << 8) | als_vis_data0) / 100.0; // Example conversion
    *proximity = (ps1_data1 << 8) | ps1_data0;

    return 0;
}

// Log data to file
int log_data(float lux, int proximity) {
    char *timestamp = get_timestamp();
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s,%.2f,%d\n", timestamp, lux, proximity);
    return 0;
}

