#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define DISTANCE_THRESHOLD 20.0  // Distance threshold in centimeters
#define TIMEOUT_US 500000         // Timeout in microseconds (0.5 seconds)

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int pigpio_initialized = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void control_buzzer(double distance);
void print_distance(double distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 2; // Indicate falling edge received
    }
}

// Function to calculate distance from pulse width
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to control the buzzer based on distance
void control_buzzer(double distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
    }
}

// Function to print the distance to stdout
void print_distance(double distance) {
    printf("Distance: %.2f cm\n", distance);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (pigpio_initialized) {
        gpioTerminate();
    }
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Set up interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Trigger the sensor
        trigger_sensor();

        // Wait for echo
        echo_received = 0; // Reset flag
        start_tick = 0;
        end_tick = 0;
        uint32_t start_time = gpioTick();

        while (echo_received != 2 && (gpioTick() - start_time) < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // Calculate pulse width
        uint32_t pulse_width = 0;
        if (echo_received == 2) {
            pulse_width = end_tick - start_tick;
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Control buzzer
        control_buzzer(distance);

        // Print distance
        print_distance(distance);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    return 0;
}

