// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants for distance calculation
#define SOUND_SPEED 0.0343 // cm/us
#define TIMEOUT_US 50000   // 50ms timeout

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to measure distance using HC-SR04 sensor
float get_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0;
