#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MODEL_ID_REG 0x00c0
#define EXPECTED_MODEL_ID 0xEEAA
#define TIMING_BUDGET_REG 0x001E
#define TIMING_BUDGET_VALUE 50000 // 50ms
#define DISTANCE_REG 0x0089
#define SERVO_PIN 18
#define OPEN_PULSE_WIDTH 1000
#define CLOSE_PULSE_WIDTH 2000
#define OPEN_THRESHOLD 250
#define CLOSE_THRESHOLD 200
#define PWM_FREQUENCY 50
#define PWM_RANGE 20000 // 20ms period (50Hz)
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void set_servo_pulse_width(int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Check model ID
    int model_id = i2cReadWordData(i2c_handle, MODEL_ID_REG);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: 0x%04X (expected 0x%04X)\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    // Set timing budget
    if (i2cWriteWordData(i2c_handle, TIMING_BUDGET_REG, TIMING_BUDGET_VALUE) < 0) {
        fprintf(stderr, "Error writing timing budget\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }
    return distance;
}

// Set servo pulse width
void set_servo_pulse_width(int pulse_width) {
    // Ensure pulse width is within valid range
    if (pulse_width < 500) pulse_width = 500;
    if (pulse_width > 2500) pulse_width = 2500;

    // Convert pulse width to duty cycle (0-20000 for 20ms period)
    int duty_cycle = (int)(((float)pulse_width / 20000.0) * PWM_RANGE);

    gpioPWM(SERVO_PIN, duty_cycle);
}

// Log event to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, PWM_RANGE);

    // Register signal handler
    signal(SIGINT, signal_handler);

    int current_pulse_width = 1500; // Initial pulse width
    int target_pulse_width = 1500;  // Initial target pulse width
    int distance;

    // Main loop
    while (!terminate) {
        distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Determine target pulse width based on distance
        if (distance > OPEN_THRESHOLD) {
            target_pulse_width = OPEN_PULSE_WIDTH;
        } else if (distance < CLOSE_THRESHOLD) {
            target_pulse_width = CLOSE_PULSE_WIDTH;
        } else {
            target_pulse_width = 1500; // Maintain current position
        }

        // Smooth transition to target pulse width
        if (current_pulse_width < target_pulse_width) {
            current_pulse_width += 10; // Increment pulse width
            if (current_pulse_width > target_pulse_width) current_pulse_width = target_pulse_width;
        } else if (current_pulse_width > target_pulse_width) {
            current_pulse_width -= 10; // Decrement pulse width
            if (current_pulse_width < target_pulse_width) current_pulse_width = target_pulse_width;
        }

        set_servo_pulse_width(current_pulse_width);

        // Log events
        if (current_pulse_width == OPEN_PULSE_WIDTH && target_pulse_width == OPEN_PULSE_WIDTH) {
            log_event("Gate opened");
        } else if (current_pulse_width == CLOSE_PULSE_WIDTH && target_pulse_width == CLOSE_PULSE_WIDTH) {
            log_event("Gate closed");
        }

        gpioDelay(50); // Delay 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(SERVO_PIN, 0); // Stop PWM
    gpioTerminate();
    fclose(log_file);

    return 0;
}

