#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0       // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0     // Maximum measurable distance in cm
#define MIN_ANGLE 0.0          // Minimum servo angle in degrees
#define MAX_ANGLE 180.0        // Maximum servo angle in degrees
#define MIN_PULSE_WIDTH 500    // Minimum pulse width in microseconds
#define MAX_PULSE_WIDTH 2500   // Maximum pulse width in microseconds
#define TIMEOUT 50000          // Timeout in microseconds (50ms)

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
float measure_distance();
float distance_to_angle(float distance);
void set_servo_angle(float angle);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_servo_angle(90.0); // Set servo to a safe position (90 degrees)
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Flag that rising edge was received
    } else if (level == 0 && echo_received == 1) {
        echo_end_tick = tick;
        echo_received = 0; // Reset the flag
    }
}

// Function to measure distance using HC-SR04
float measure_distance() {
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_received = 0;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    int start_time = gpioTick();
    while (echo_start_tick == 0 && (gpioTick() - start_time) < TIMEOUT) {
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (echo_start_tick == 0) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1.0; // Timeout
    }

    start_time = gpioTick();
    while (echo_end_tick == 0 && (gpioTick() - start_time) < TIMEOUT) {
        gpioDelay(1);
    }

    if (echo_end_tick == 0) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1.0; // Timeout
    }

    int pulse_width = echo_end_tick - echo_start_tick;
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Distance in cm

    return distance;
}

// Function to map distance to servo angle
float distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    }
}

// Function to set servo angle
void set_servo_angle(float angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Invalid angle: %f. Angle must be between %f and %f\n", angle, MIN_ANGLE, MAX_ANGLE);
        return;
    }

    int pulse_width = (int)((angle / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float distance = measure_distance();
        if (distance > 0) {
            float angle = distance_to_angle(distance);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

