    gpioDelay(10000); // 10 ms delay

    result = i2cReadWordData(i2c_handle, HUMID_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    raw_humidity = (uint16_t)result;

    // Convert raw data to temperature and humidity (datasheet formulas)
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

