#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define WHO_AM_I 0x75
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define TEMP_OUT_H 0x41

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig)
{
    printf("Caught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read a 16-bit value from the MPU-6050
int16_t read_mpu6050_data(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return 0; // Return 0 on error
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU-6050 not found. WHO_AM_I returned 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("MPU-6050 found!\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        int16_t accel_x = read_mpu6050_data(i2c_handle, ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6050_data(i2c_handle, ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6050_data(i2c_handle, ACCEL_XOUT_H + 4);

        // Read temperature data
        int16_t temperature = read_mpu6050_data(i2c_handle, TEMP_OUT_H);

        // Read gyroscope data
        int16_t gyro_x = read_mpu6050_data(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = read_mpu6050_data(i2c_handle, GYRO_XOUT_H + 2);
        int16_t gyro_z = read_mpu6050_data(i2c_handle, GYRO_XOUT_H + 4);

        // Print the data
        printf("Accel: %6d %6d %6d  Temp: %6d  Gyro: %6d %6d %6d\n",
               accel_x, accel_y, accel_z, temperature, gyro_x, gyro_y, gyro_z);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

