#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait 10 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t calculated_crc = calculate_crc(data, len - 1);
    if (calculated_crc != data[len - 1]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Temperature
    uint16_t temp_raw = (data[0] << 8) | data[1];
    sensor_data.temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;

    // Humidity
    uint16_t humidity_raw = (data[3] << 8) | data[4];
    sensor_data.humidity = -6.0 + 125.0 * (float)humidity_raw / 65535.0;
    if (sensor_data.humidity < 0.0) sensor_data.humidity = 0.0;
    if (sensor_data.humidity > 100.0) sensor_data.humidity = 100.0;

    return sensor_data;
}

// Log sensor data with timestamp
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[6];
    sensor_data_t converted_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC for temperature
            if (validate_crc(sensor_data, 3) == 0) {
                // Validate CRC for humidity
                if (validate_crc(sensor_data + 3, 3) == 0) {
                    // Convert data
                    converted_data = convert_data(sensor_data);

                    // Log data
                    log_data(converted_data);
                } else {
                    fprintf(stderr, "Humidity CRC validation failed. Re-initializing I2C.\n");
                    i2cClose(i2c_handle);
                    if (init_i2c() != 0) {
                        fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                        break;
                    }
                }
            } else {
                fprintf(stderr, "Temperature CRC validation failed. Re-initializing I2C.\n");
                i2cClose(i2c_handle);
                if (init_i2c() != 0) {
                    fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                    break;
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

