    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to read temperature data: %d", result);
        log_error(error_message);
        return 1;
    }

