#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
SensorData convert_data(char *buffer, float pressure_scale, float temperature_scale);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc = (crc << 1);
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t calculated_crc = calculate_crc(data, nbrOfBytes);
    return (calculated_crc == checksum);
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
SensorData convert_data(char *buffer, float pressure_scale, float temperature_scale) {
    SensorData data;
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data.pressure = (float)raw_pressure / pressure_scale;
    data.temperature = (float)raw_temperature / temperature_scale;

    return data;
}

// Function to log data to a file
int log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,pressure,temperature\n");
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
