    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[6];
    sensor_data_t converted_data;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC for temperature data
            if (validate_crc(sensor_data, 3)) {
                // Validate CRC for humidity data
                if (validate_crc(sensor_data + 3, 3)) {
                    // Convert data
                    converted_data = convert_data(sensor_data);

                    // Log data
                    log_data(converted_data);
                } else {
                    fprintf(stderr, "Humidity CRC validation failed\n");
                }
            } else {
                fprintf(stderr, "Temperature CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        sleep(5); // Wait 5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

