        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[6];
        sensor_data_t converted_data;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue; // Retry
        }

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Retry
        }

        // Convert data
        converted_data = convert_data(sensor_data);

        // Log data
        if (log_data(converted_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

