#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5
#define LOG_FILE "sensor_data.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

