    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the Si7015 sensor
int init_sensor() {
    // No specific initialization needed for Si7015 in this mode
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    unsigned char buf[2];
    int result;
    int retries = 0;

    // Measure temperature
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD);
        if (result == 0) break;
        fprintf(stderr, "Temp write failed (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write temperature command after %d retries\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(20000); // Wait 20ms for measurement

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Temp read failed (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(RETRY_DELAY_MS * 1000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read temperature data after %d retries\n", MAX_RETRIES);
        return -1;
    }

    unsigned int temp_raw = (buf[0] << 8) | buf[1];
    data->temperature = (175.72 * temp_raw / 65536.0) - 46.85;

    // Measure humidity
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, HUMID_MEASURE_CMD);
        if (result == 0) break;
        fprintf(stderr, "Humidity write failed (attempt %d): %s\n", retries + 1, strerror(errno));
