        fprintf(stderr, "Failed to write humidity command after %d retries\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(20000); // Wait 20ms for measurement

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Humidity read failed (attempt %d): %s\n", retries + 1, strerror(errno));
        gpioDelay(RETRY_DELAY_MS * 1000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read humidity data after %d retries\n", MAX_RETRIES);
        return -1;
    }

    unsigned int humidity_raw = (buf[0] << 8) | buf[1];
    data->humidity = (125.0 * humidity_raw / 65536.0) - 6.0;

    return 0;
}

// Log sensor data to file
int log_sensor_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

