#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// CRC-8-ATM checksum parameters
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(unsigned char *data);
float convert_temperature(unsigned char *data);
unsigned char calculate_crc(unsigned char data[], int len);
int validate_crc(unsigned char data[], int len);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sts30_address;
    const char *log_file;
    const char *error_log_file;
    int sample_interval;
} config_t;

config_t config = {
    I2C_BUS,
    STS30_ADDR,
    LOG_FILE,
    ERROR_LOG_FILE,
    SAMPLE_INTERVAL_SEC
};

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialisation failed");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char sensor_data[3];
        float temperature;

        // Send measurement command
        if (send_measurement_command() != 0) {
            log_error("Failed to send measurement command");
            continue; // Retry
        }

        // Wait for conversion (at least 15ms)
        gpioDelay(15000); // 15ms

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            log_error("Failed to read sensor data");
            continue; // Retry
        }

        // Validate CRC
        if (!validate_crc(sensor_data, 3)) {
            log_error("CRC validation failed");
            continue; // Retry
        }

        // Convert temperature
        temperature = convert_temperature(sensor_data);

        // Log temperature
        if (log_temperature(temperature) != 0) {
            log_error("Failed to log temperature");
        }

        // Wait for the next sample
        gpioDelay(config.sample_interval * 1000000); // Convert seconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.sts30_address, 0);
    if (i2c_handle < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to open I2C device: %d", i2c_handle);
        log_error(error_message);
        return 1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    unsigned char cmd[2];
    cmd[0] = (MEASURE_CMD >> 8) & 0xFF;
    cmd[1] = MEASURE_CMD & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to write measurement command: %d", result);
        log_error(error_message);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to read sensor data: %d", result);
        log_error(error_message);
        return 1;
    }
    return 0;
}

// Convert temperature
float convert_temperature(unsigned char *data) {
    unsigned int raw_temperature = (data[0] << 8) | data[1];
    return -45.0 + (175.0 * raw_temperature / 65535.0);
}

// Calculate CRC-8-ATM checksum
unsigned char calculate_crc(unsigned char data[], int len) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Log temperature
int log_temperature(float temperature) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        log_error("Failed to open log file");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Log error
int log_error(const char *message) {
    FILE *fp = fopen(config.error_log_file, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

