    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", FILENAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[6];
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC for pressure
            if (validate_crc(data, 2, data[2]) == 0) {
                // Validate CRC for temperature
                if (validate_crc(data + 3, 2, data[5]) == 0) {
                    // Convert data
                    convert_data(data, &pressure, &temperature);

                    // Write to file
                    write_to_file(pressure, temperature);
                }
            }
        }

        // Sleep for 100ms
        gpioDelay(SLEEP_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up resources
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

