#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Data Structures
typedef struct {
    time_t timestamp;
    float temperature;
} Reading;

// Global Variables
int i2c_handle;
Reading buffer[BUFFER_SIZE];
int buffer_index = 0;
int fan_state = 0; // 0 = off, 1 = on

// Function Prototypes
int read_temperature(float *temperature);
void buffer_add(float temperature);
void buffer_print();
void control_fan(float temperature);
void signal_handler(int signal);
void cleanup();

// Function Implementations
int read_temperature(float *temperature) {
    char cmd = 0xE3; // Command to measure temperature, hold master
    char buf[2];
    int result, i;

    for (i = 0; i < RETRY_COUNT; i++) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(10000); // Wait for measurement (10ms)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 0) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert raw data to temperature (Celsius)
        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

void buffer_add(float temperature) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void buffer_print() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[i].timestamp));
        printf("%s: %.2f\n", timestamp_str, buffer[i].temperature);
    }
}

void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH && fan_state == 0) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_state = 1;
        printf("Fan turned ON\n");
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_state == 1) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_state = 0;
        printf("Fan turned OFF\n");
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
