#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define CMD_READ_MEASUREMENT 0xec05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c(int bus, int addr);
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t data[], int len);
int start_periodic_measurement(int handle);
int stop_periodic_measurement(int handle);
int read_measurement(int handle, uint16_t *co2, float *temperature, float *humidity);
int log_data(FILE *fp, uint16_t co2, float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c(1, SCD40_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Failed to start periodic measurement. Exiting.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Wait for 1 second
        gpioDelay(1000);

        // Read measurement
        if (read_measurement(i2c_handle, &sensor_data.co2, &sensor_data.temperature, &sensor_data.humidity) == 0) {
            // Log data
            if (log_data(log_file, sensor_data.co2, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read measurement.\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement.\n");
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    fclose(log_file);

    printf("Program terminated cleanly.\n");
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write command to SCD40
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC-8
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC check failed. Expected 0x%02X, got 0x%02X\n", data[len - 1], crc);
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement(int handle) {
    return write_command(handle, CMD_START_PERIODIC_MEASUREMENT);
}

// Stop periodic measurement
int stop_periodic_measurement(int handle) {
    return write_command(handle, CMD_STOP_PERIODIC_MEASUREMENT);
}

// Read measurement
int read_measurement(int handle, uint16_t *co2, float *temperature, float *humidity) {
    uint8_t data[9];
    uint16_t raw_co2, raw_temperature, raw_humidity;

    // Send read measurement command
    if (write_command(handle, CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }

    // Wait for data to be ready (100ms)
    gpioDelay(100);

    // Read 9 bytes of data
    if (read_data(handle, data, 9) != 0) {
        return -1;
    }

    // Verify CRC for CO2
    if (verify_crc(data, 2) != 0) {
        return -1;
    }

    // Verify CRC for Temperature
    if (verify_crc(data + 2, 2) != 0) {
        return -1;
    }

    // Verify CRC for Humidity
    if (verify_crc(data + 4, 2) != 0) {
        return -1;
    }

    // Extract raw values
    raw_co2 = (data[0] << 8) | data[1];
    raw_temperature = (data[3] << 8) | data[4];
    raw_humidity = (data[6] << 8) | data[7];

    // Convert to physical units
    *co2 = raw_co2;
    *temperature = -45 + 175 * (raw_temperature / 65535.0);
    *humidity = 100 * (raw_humidity / 65535.0);

    return 0;
}

// Log data to file
int log_data(FILE *fp, uint16_t co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Terminating...\n");
    terminate = 1;
}

