#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define GPIO_LED 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define CMD_READ_MEASUREMENT 0xec05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86

// Structure for sensor readings
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_scd40();
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
void print_buffer(circular_buffer_t *buffer);
void control_led(int co2_level);
void signal_handler(int signal);

// CRC-8 checksum calculation
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc = (crc << 1);
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize SCD40 sensor
int init_scd40() {
    char buf[2];
    int result;

    // Start periodic measurement
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for the command to be processed

    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    char buf[2];
    char read_buf[9];
    int result;

    // Read measurement command
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Small delay after writing the command

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, read_buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Validate CRC for CO2
    uint8_t data[2] = {read_buf[0], read_buf[1]};
    uint8_t crc = calculate_crc(data, 2);
    if (crc != read_buf[2]) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }

    // Validate CRC for Temperature
    data[0] = read_buf[3];
    data[1] = read_buf[4];
    crc = calculate_crc(data, 2);
    if (crc != read_buf[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

