float read_temperature() {
    uint32_t start_tick, end_tick, high_tick, low_tick;
    int seconds, micros;

    gpioSetMode(GPIO_PIN, PI_INPUT); // Ensure GPIO is in input mode

    // Wait for the rising edge
    gpioTime(PI_TIME_RELATIVE, &seconds, &micros);
    start_tick = seconds * 1000000 + micros;
    while (gpioRead(GPIO_PIN) == 0 && program_running) {
        gpioTime(PI_TIME_RELATIVE, &seconds, &micros);
        end_tick = seconds * 1000000 + micros;
        if (end_tick - start_tick > TIMEOUT_US) {
            log_message("Timeout waiting for rising edge.");
            return -1000.0; // Indicate timeout error
        }
    }

    // Measure high pulse width
    gpioTime(PI_TIME_RELATIVE, &seconds, &micros);
    high_tick = seconds * 1000000 + micros;
    while (gpioRead(GPIO_PIN) == 1 && program_running) {
        gpioTime(PI_TIME_RELATIVE, &seconds, &micros);
        end_tick = seconds * 1000000 + micros;
        if (end_tick - high_tick > TIMEOUT_US) {
            log_message("Timeout waiting for falling edge (high pulse).");
            return -1000.0; // Indicate timeout error
        }
    }
    low_tick = end_tick;

    // Measure low pulse width
    while (gpioRead(GPIO_PIN) == 0 && program_running) {
        gpioTime(PI_TIME_RELATIVE, &seconds, &micros);
        end_tick = seconds * 1000000 + micros;
        if (end_tick - low_tick > TIMEOUT_US) {
            log_message("Timeout waiting for rising edge (low pulse).");
            return -1000.0; // Indicate timeout error
        }
    }

    // Calculate pulse widths in microseconds
    uint32_t high_pulse_width = high_tick - start_tick;
    uint32_t low_pulse_width = end_tick - low_tick;
    uint32_t total_cycle_width = end_tick - start_tick;

    // Calculate temperature (example formula, adjust as needed)
