                log_message(error_message);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Delay for 5 seconds
    }

    // Clean up
    log_message("Program exiting.");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

