    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Failed to read sensor data\n");
        return 1;
    }
    return 0;
}

// Calculate CRC
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= (data[i]);
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t calculated_crc = calculate_crc(data, nbrOfBytes);
    return (calculated_crc == checksum) ? 0 : 1;
