    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
