#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_CMD 0xF3
#define HUMID_MEASURE_CMD 0xF5
#define CRC_POLYNOMIAL 0x131 // x^8 + x^5 + x^4 + 1
#define CRC_INIT 0x00
#define LOG_FILE "environment.log"
#define ERROR_LOG_FILE "error.log"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int command, unsigned char *data);
float convert_temperature(unsigned char msb, unsigned char lsb);
float convert_humidity(unsigned char msb, unsigned char lsb);
unsigned char calculate_crc(unsigned char data[], int len);
int verify_crc(unsigned char data[], int len, unsigned char crc);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void log_error(const char *message);

// CRC-8 calculation function
unsigned char calculate_crc(unsigned char data[], int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC verification function
int verify_crc(unsigned char data[], int len, unsigned char crc) {
    unsigned char calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int command, unsigned char *data) {
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, command);
        if (result != 0) {
            log_error("Failed to write command to sensor");
            gpioDelay(10); // Small delay before retry
            retries--;
            continue;
        }

        gpioDelay(50); // Wait for measurement (datasheet specifies 37ms for temp/humidity)

        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result == 3) {
            return 0; // Success
        } else {
            log_error("Failed to read sensor data");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }

    return -1; // Failure after multiple retries
}

// Convert temperature to Celsius
float convert_temperature(unsigned char msb, unsigned char lsb) {
    unsigned short raw_temp = (msb << 8) | lsb;
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert humidity to percentage
float convert_humidity(unsigned char msb, unsigned char lsb) {
    unsigned short raw_humidity = (msb << 8) | lsb;
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Log data to CSV file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            log_error("Failed to open log file");
            return -1;
        }
        fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Log errors to error log file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (error_log_file == NULL) {
        error_log_file = fopen(ERROR_LOG_FILE, "a");
        if (error_log_file == NULL) {
            perror("Failed to open error log file");
            return;
        }
    }

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    unsigned char temp_data[3];
    unsigned char humidity_data[3];
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_sensor_data(TEMP_MEASURE_CMD, temp_data) == 0) {
            if (verify_crc(temp_data, 2, temp_data[2])) {
                temperature = convert_temperature(temp_data[0], temp_data[1]);
            } else {
                log_error("Temperature CRC check failed");
                temperature = -999.0; // Indicate error
            }
        } else {
            log_error("Failed to read temperature");
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(HUMID_MEASURE_CMD, humidity_data) == 0) {
            if (verify_crc(humidity_data, 2, humidity_data[2])) {
                humidity = convert_humidity(humidity_data[0], humidity_data[1]);
            } else {
                log_error("Humidity CRC check failed");
                humidity = -999.0; // Indicate error
            }
        } else {
            log_error("Failed to read humidity");
            humidity = -999.0; // Indicate error
        }

        // Log data
        if (log_data(temperature, humidity) != 0) {
            log_error("Failed to log data");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for the next sample
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }

    return 0;
}

