#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define CONVERSION_TIME_MS 50
#define FILENAME "airflow.dat"

// Global variables for signal handling
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device() {
    int handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Function to write the measurement command to the sensor
int write_measurement_command(int handle) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write measurement command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(int handle, char *buffer, int len) {
    int result = i2cReadDevice(handle, buffer, len);
    if (result != len) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to validate the CRC checksum
int validate_crc(const char *data, int len) {
    uint8_t crc = crc8((const uint8_t *)data, len - 1);
    if (crc != (uint8_t)data[len - 1]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
void convert_data(const char *data, float *pressure, float *temperature) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    *pressure = (float)raw_pressure / 240.0; // Pa
    *temperature = (float)raw_temperature / 200.0; // °C
}

// Function to log data to a file
int log_data(FILE *fp, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write pressure to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Write measurement command
        if (write_measurement_command(i2c_handle) != 0) {
            break;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_MS * 1000); // Convert ms to microseconds

        // Read sensor data
        char data[9];
        if (read_sensor_data(i2c_handle, data, 9) != 0) {
            break;
        }

        // Validate CRC for pressure
        if (validate_crc(data, 3) != 0) {
            break;
        }

        // Validate CRC for temperature
        if (validate_crc(data + 3, 3) != 0) {
            break;
        }

        // Convert data to pressure and temperature
        float pressure, temperature;
        convert_data(data, &pressure, &temperature);

        // Log data to file
        if (log_data(fp, pressure, temperature) != 0) {
            break;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

