void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Extract data and CRC
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t temperature_data[2] = {buffer[3], buffer[4]};
    uint8_t status_data[2] = {buffer[6], buffer[7]};
    uint8_t crc = buffer[8];

    // Validate CRC for each data word
    if (!validate_crc(pressure_data, 2, crc)) {
        fprintf(stderr, "CRC validation failed for pressure data\n");
        return -1;
    }
    if (!validate_crc(temperature_data, 2, crc)) {
        fprintf(stderr, "CRC validation failed for temperature data\n");
        return -1;
    }
    if (!validate_crc(status_data, 2, crc)) {
        fprintf(stderr, "CRC validation failed for status data\n");
        return -1;
    }

    // Convert data
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->status = (uint16_t)((buffer[6] << 8) | buffer[7]);

    return 0;
}

// Log pressure data to file
void log_pressure_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %d Pa, Temperature: %d, Status: %d\n",
            timestamp, data.pressure, data.temperature, data.status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_MS * 1000); // Convert ms to us

        // Read sensor data
        if (read_sensor_data(&sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Log pressure data
        log_pressure_data(sensor_data);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

