    if (result != 2) {
        fprintf(stderr, "Error reading pressure: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit integer
    int16_t pressure = (buf[0] << 8) | buf[1];
    return pressure;
}

