float calculate_flow_rate(int pressure) {
    // HAFBLF0100A2AX5: 0.01 Pa/0.01 mbar, 0-100 mbar range
    // Flow rate (SLPM) = Pressure (Pa) * 100
    return (float)pressure * 100.0;
