void set_fan_speed(int gpio, float flow_rate) {
    // Map flow rate (0-100 SLPM) to PWM duty cycle (0-1000000)
    int duty_cycle = (int)(flow_rate * 10000.0); // Scale flow rate to 0-1000000
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

