    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(GPIO_FAN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_FAN, PWM_FREQ);
    gpioSetPWMrange(GPIO_FAN, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

