    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read pressure
        int pressure = read_pressure(i2c_handle);
        if (pressure < 0) {
            fprintf(stderr, "Error reading pressure, retrying in %d ms\n", SAMPLE_INTERVAL_MS);
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
            continue; // Skip to the next iteration
        }

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pressure);

        // Set fan speed
        set_fan_speed(GPIO_FAN, flow_rate);

        // Log data
        log_data(log_file, flow_rate);

        // Delay
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    fprintf(stderr, "Cleaning up resources...\n");
    gpioPWM(GPIO_FAN, 0); // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

