// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful termination
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the LPS33HW sensor
int init_lps33hw() {
    // Enable continuous data acquisition (ODR = 1 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x10) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Function to read pressure and temperature data from the LPS33HW sensor
int read_lps33hw(float *pressure, float *temperature) {
    char buffer[5];
    int result;

    // Read pressure data (3 bytes)
    result = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    // Read temperature data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer + 3, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    // Convert pressure data
    int32_t pressure_raw = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);
    *pressure = (float)pressure_raw / 4096.0; // hPa

    // Convert temperature data
    int16_t temperature_raw = (int16_t)buffer[3] | ((int16_t)buffer[4] << 8);
    *temperature = (float)temperature_raw / 100.0; // °C

    return 0;
}

// Function to log data to a file
int log_data(float pressure, float temperature) {
    time_t now;
    struct tm timeinfo;
    char timestamp[20];

    time(&now);
    localtime_r(&now, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);

    return 0;
}

// Function to log errors to a file and stderr
int log_error(const char *message) {
    time_t now;
    struct tm timeinfo;
    char timestamp[20];

    time(&now);
    localtime_r(&now, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() < 0) {
        fprintf(stderr, "Error initializing LPS33HW sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful termination
    signal(SIGINT, signal_handler);

    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read pressure and temperature data
        if (read_lps33hw(&pressure, &temperature) == 0) {
            // Log the data
            log_data(pressure, temperature);
        } else {
            // Log the error
            log_error("Failed to read sensor data");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

