#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SCD30_ADDR 0x61
#define MEASUREMENT_INTERVAL 5 // seconds
#define LOG_FILE "air_quality.log"

// SCD30 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define CMD_GET_DATA_READY 0x0202
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int start_periodic_measurement();
int read_measurement(float *co2, float *temperature, float *humidity);
int stop_periodic_measurement();
int log_data(float co2, float temperature, float humidity);
int control_ventilation(float co2);
void signal_handler(int signal);
unsigned char crc8(const unsigned char *data, int len);
char* get_iso8601_timestamp();

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read measurement data
int read_measurement(float *co2, float *temperature, float *humidity) {
    char buf[2];
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %s\n", strerror(errno));
        return -1;
    }

    char data[18];
    result = i2cReadDevice(i2c_handle, data, 18);
    if (result != 18) {
        fprintf(stderr, "Failed to read measurement data: %s\n", strerror(errno));
        return -1;
    }

    // CRC Check
    if (crc8(data, 2) != data[2] ||
        crc8(data + 3, 2) != data[5] ||
        crc8(data + 6, 2) != data[8] ||
        crc8(data + 9, 2) != data[11] ||
        crc8(data + 12, 2) != data[14] ||
        crc8(data + 15, 2) != data[17]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data
    *co2 = (float)((((uint32_t)data[0]) << 8) | data[1]);
    *temperature = (float)((((uint32_t)data[3]) << 8) | data[4]);
    *humidity = (float)((((uint32_t)data[6]) << 8) | data[7]);

    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(float co2, float temperature, float humidity) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately
    free(timestamp);
    return 0;
}

// Function to control ventilation
int control_ventilation(float co2) {
    if (co2 < 800.0) {
        printf("Ventilation OFF\n");
    } else if (co2 >= 800.0 && co2 < 1200.0) {
        printf("Ventilation LOW\n");
    } else {
        printf("Ventilation HIGH\n");
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// CRC8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to start periodic measurement. Exiting.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float co2, temperature, humidity;
    int data_ready;
    char buf[2];
    int result;

    // Main loop
    while (!terminate) {
        // Check data ready status
        buf[0] = (CMD_GET_DATA_READY >> 8) & 0xFF;
        buf[1] = CMD_GET_DATA_READY & 0xFF;
        result = i2cWriteDevice(i2c_handle, buf, 2);
        if (result != 0) {
            fprintf(stderr, "Failed to send get data ready command: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }

        char data_ready_buf[3];
        result = i2cReadDevice(i2c_handle, data_ready_buf, 3);
        if (result != 3) {
            fprintf(stderr, "Failed to read data ready status: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }

        data_ready = data_ready_buf[0];

        if (data_ready) {
            // Read measurement data
            if (read_measurement(&co2, &temperature, &humidity) == 0) {
                // Log data
                if (log_data(co2, temperature, humidity) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }

                // Control ventilation
                control_ventilation(co2);
            } else {
                fprintf(stderr, "Failed to read measurement data\n");
            }
        } else {
            //printf("Data not ready yet\n");
        }

        sleep(MEASUREMENT_INTERVAL);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

