#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONVERSION_DELAY_MS 20
#define READ_DELAY_SEC 5

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(int bus) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to set the HDC1000 configuration register
int set_config(int fd, uint16_t config) {
    uint8_t buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = config & 0xFF;
    buf[2] = (config >> 8) & 0xFF;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data
int read_data(int fd, float *temperature, float *humidity) {
    uint8_t buf[4];
