#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Temperature reading function
float read_temperature() {
    int raw_temp;
    float temperature;

    // Send temperature measurement command
    if (i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1000.0; // Indicate error
    }

    // Wait for measurement (datasheet recommends at least 20ms)
    gpioDelay(25000); // 25ms

    // Read temperature data
    raw_temp = i2cReadWordData(i2c_handle, 0);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_temp);
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius
    temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    return temperature;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds.\n", SLEEP_DURATION);
        }

        sleep(SLEEP_DURATION);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

