#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C address of the ICP-10101 sensor
#define ICP10101_ADDR 0x69

// Define the command to trigger a measurement
#define MEASURE_CMD 0x30

// Define the default values for temperature and pressure
#define DEFAULT_TEMP 0x0000
#define DEFAULT_PRESS 0x0000

// Define the scaling factors for temperature and pressure
#define TEMP_SCALE 0.01
#define PRESS_SCALE 0.1

// Global variable for the I2C handle
int i2c_handle;

// Function prototypes
int trigger_measurement(int i2c_handle);
int read_raw_data(int i2c_handle, uint16_t *temperature, uint16_t *pressure);
float convert_temperature(uint16_t raw_temperature);
float convert_pressure(uint16_t raw_pressure);
void print_data(float temperature, float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to trigger a measurement
int trigger_measurement(int i2c_handle) {
    int result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read raw temperature and pressure data
int read_raw_data(int i2c_handle, uint16_t *temperature, uint16_t *pressure) {
    char buffer[4];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature * TEMP_SCALE;
}

// Function to convert raw pressure to Pascals
float convert_pressure(uint16_t raw_pressure) {
    return (float)raw_pressure * PRESS_SCALE;
}

// Function to print the temperature and pressure data with an ISO 8601 timestamp
void print_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f \u00b0C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t raw_temperature, raw_pressure;
        float temperature, pressure;

        // Trigger a measurement
        if (trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Wait for 7 milliseconds
        gpioDelay(7000);

        // Read the raw data
        if (read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read data, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Check for sensor absent condition
        if (raw_temperature == DEFAULT_TEMP && raw_pressure == DEFAULT_PRESS) {
            fprintf(stderr, "Sensor absent, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Convert the raw data to temperature and pressure
        temperature = convert_temperature(raw_temperature);
        pressure = convert_pressure(raw_pressure);

        // Print the data
        print_data(temperature, pressure);

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

