#include <pigpio.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define MLX90821_ADDR 0x60
#define LOG_FILE "pressure_log.csv"
#define PRESSURE_MIN 200.0
#define PRESSURE_MAX 250.0

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
float read_pressure();
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx90821_address;
    char *log_filename;
    float pressure_min;
    float pressure_max;
} config_t;

config_t config = {
    I2C_BUS,
    MLX90821_ADDR,
    LOG_FILE,
    PRESSURE_MIN,
    PRESSURE_MAX
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_filename, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Check if the file is newly created (empty)
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float pressure = read_pressure();
        if (pressure >= 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 1, 0); // Sleep for 1 second
    }

    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.mlx90821_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

float read_pressure() {
    char buf[2];
    int bytes_read;
    int retries = 0;

    while (retries < 2) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read == 2) {
            // Convert raw data to pressure (kPa) - Example conversion
            int raw_pressure = (buf[0] << 8) | buf[1];
            float pressure = (float)raw_pressure * 0.1; // Example scaling

            // Check for pressure range
            if (pressure < config.pressure_min || pressure > config.pressure_max) {
                fprintf(stderr, "Warning: Pressure out of range: %.2f kPa\n", pressure);
            }

            return pressure;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C\n");
                return -1;
            }
            retries++;
            gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Small delay before retry
        }
    }

    return -1; // Indicate failure after retries
}

int log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

