#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1MB
#define MEASUREMENT_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_hih6130(int i2c_handle, float *temperature, float *humidity);
int log_data(const char *timestamp, float temperature, float humidity);
void roll_log_file();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read temperature and humidity from HIH6130
int read_hih6130(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for 40ms
    gpioDelay(40000); // 40ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Check status bits
    int status = (buf[0] >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Error: Sensor status indicates an error (status = %d)\n", status);
        return -1;
    }

    // Calculate humidity
    unsigned int humidity_raw = ((buf[0] & 0x3F) << 8) | buf[1];
    *humidity = ((float)humidity_raw / 16383) * 100;

    // Calculate temperature
    unsigned int temperature_raw = (buf[2] << 6) | (buf[3] >> 2);
    *temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return 0;
}

// Function to log data to file
int log_data(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Function to roll the log file
void roll_log_file() {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file for reading!\n");
        return;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    fclose(fp);

    if (file_size > LOG_FILE_SIZE_LIMIT) {
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file for writing!\n");
            return;
        }
        fclose(fp);
        printf("Log file rolled.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log data
            if (log_data(timestamp, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            printf("Timestamp: %s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Roll log file
        roll_log_file();

        // Wait for the next measurement
        sleep(MEASUREMENT_INTERVAL);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

