#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define TIMEOUT_US 100000 // 100ms timeout
#define MIN_PULSE_WIDTH 12
#define MAX_PULSE_WIDTH 271
#define SYNC_PULSE_WIDTH 56
#define LOG_FILE "pressure_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to convert pulse width to nibble value
int pulse_width_to_nibble(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        return -1; // Indicate invalid pulse width
    }
    return (pulse_width - MIN_PULSE_WIDTH) / 21;
}

// Function to calculate checksum
int calculate_checksum(int status_nibble, int data_nibbles[3]) {
    int checksum = status_nibble;
    for (int i = 0; i < 3; i++) {
        checksum += data_nibbles[i];
    }
    return checksum & 0x0F; // Keep only the lower 4 bits
}

// Function to decode SENT data
int decode_sent_data(int pulse_widths[], int num_pulses, int *status_nibble, int data_nibbles[], int *checksum_nibble) {
    if (num_pulses < 5) {
        fprintf(stderr, "Error: Not enough pulses received (%d)\n", num_pulses);
        return -1;
    }

    // Check for synchronization pulse
    if (pulse_widths[0] != SYNC_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid synchronization pulse width (%d)\n", pulse_widths[0]);
        return -1;
    }

    *status_nibble = pulse_width_to_nibble(pulse_widths[1]);
    if (*status_nibble == -1) {
        fprintf(stderr, "Error: Invalid status nibble pulse width (%d)\n", pulse_widths[1]);
        return -1;
    }

    for (int i = 0; i < 3; i++) {
        data_nibbles[i] = pulse_width_to_nibble(pulse_widths[2 + i]);
        if (data_nibbles[i] == -1) {
            fprintf(stderr, "Error: Invalid data nibble %d pulse width (%d)\n", i, pulse_widths[2 + i]);
            return -1;
        }
    }

    *checksum_nibble = pulse_width_to_nibble(pulse_widths[5]);
    if (*checksum_nibble == -1) {
        fprintf(stderr, "Error: Invalid checksum nibble pulse width (%d)\n", pulse_widths[5]);
        return -1;
    }

    return 0;
}

// Function to convert nibbles to pressure (example conversion)
float nibbles_to_pressure(int status_nibble, int data_nibbles[]) {
    // This is a placeholder.  Replace with the actual conversion formula
    // from the MLX90824 datasheet.
    // Example:
    int raw_pressure = (data_nibbles[0] << 12) | (data_nibbles[1] << 8) | (data_nibbles[2] << 4);
    return (float)raw_pressure * 0.1; // Example scaling
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    int pulse_widths[6]; // Array to store pulse widths
    int num_pulses = 0;
    uint32_t start_tick, end_tick, diff;
    int status_nibble, data_nibbles[3], checksum_nibble;
    float pressure;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    while (program_running) {
        num_pulses = 0;
        // Wait for the start of a frame (falling edge)
        while (gpioRead(GPIO_PIN) == 1 && program_running) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (!program_running) break;

        start_tick = gpioTick();

        // Read pulse widths
        for (int i = 0; i < 6 && program_running; i++) {
            while (gpioRead(GPIO_PIN) == 0 && program_running) {
                gpioDelay(1);
            }
            if (!program_running) break;

            end_tick = gpioTick();
            diff = end_tick - start_tick;
            if (end_tick < start_tick) {
                diff = (0xFFFFFFFF - start_tick) + end_tick; // Handle tick rollover
            }
            pulse_widths[i] = diff;
            start_tick = end_tick;
            num_pulses++;
        }

        if (!program_running) break;

        // Decode SENT data
        if (decode_sent_data(pulse_widths, num_pulses, &status_nibble, data_nibbles, &checksum_nibble) == 0) {
            // Calculate checksum
            int calculated_checksum = calculate_checksum(status_nibble, data_nibbles);

            // Verify checksum
            if (calculated_checksum == checksum_nibble) {
                // Convert nibbles to pressure
                pressure = nibbles_to_pressure(status_nibble, data_nibbles);

                // Get current timestamp
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log pressure reading
                fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
                fflush(log_file); // Ensure data is written to file immediately
                printf("%s, Pressure: %.2f Pa\n", timestamp, pressure);
            } else {
                fprintf(stderr, "Error: Checksum mismatch (calculated: %d, received: %d)\n", calculated_checksum, checksum_nibble);
            }
        } else {
            fprintf(stderr, "Error: SENT data decoding failed\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

