            }
        } else {
            fprintf(log_file, "%s", "Error: Failed to read sensor data in main loop.\n");
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

