    if (result != 4) {
        fprintf(stderr, "Error reading speed data: %d\n", result);
        return -1;
    }

    *speed = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

