        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Speed (RPM),Temperature (C)\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&raw_speed, &raw_temperature) == 0) {
            speed = convert_speed(raw_speed);
            temperature = convert_temperature(raw_temperature);
            log_data(speed, temperature);
        } else {
            fprintf(log_file, "%s,NaN,NaN\n", ctime(&time(NULL)));
            fflush(log_file);
        }

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

