int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    // Extract flow and temperature values from the data
    uint16_t flow_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t temp_raw = ((uint16_t)data[2] << 8) | data[3];

    // Apply scaling factors (from datasheet)
    sensor_data.flow_slpm = (float)(flow_raw & 0x3FFF) / 16383.0 * 25.0; // Flow: 0-25 SLPM
    sensor_data.temperature_c = (float)(temp_raw & 0x0FFF) / 4095.0 * 165.0 - 40.0; // Temp: -40 to 125 C

    return sensor_data;
}

