    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[4];
        sensor_data_t processed_data;
        int reinit_attempts = 0;

        // I2C initialization with retry
        while (i2c_handle < 0 && reinit_attempts < MAX_REINIT_ATTEMPTS) {
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C initialization failed, retrying... (%d/%d)\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
                reinit_attempts++;
                sleep(1); // Wait before retrying
            } else {
                break; // I2C initialized successfully
            }
        }

        if (i2c_handle < 0) {
            fprintf(stderr, "I2C initialization failed after multiple attempts. Exiting.\n");
            break; // Exit loop if I2C initialization fails repeatedly
        }

        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log data
            if (log_data(processed_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            stale_read_count = 0; // Reset stale read count on successful read
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1; // Reset handle to trigger re-initialization
            stale_read_count++;
        }

        // Handle stale reads
        if (stale_read_count >= STALE_READ_THRESHOLD) {
            fprintf(stderr, "Warning: Stale read detected. Skipping data logging.\n");
            stale_read_count = 0; // Reset count to avoid repeated warnings
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

