#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define DHT11_GPIO 4
#define TIMEOUT_US 100000 // 100ms timeout

// Structure to hold DHT11 data
typedef struct {
    int humidity_integer;
    int humidity_decimal;
    int temperature_integer;
    int temperature_decimal;
    int checksum;
} DHT11Data;

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Function prototypes
int start_signal(int gpio);
int read_response(int gpio);
int read_data_bit(int gpio);
DHT11Data decode_data(unsigned int data);
int verify_checksum(DHT11Data data);
int write_to_file(DHT11Data data);
void log_error(const char *message, int status_code);
void signal_handler(int signal);
void cleanup();

// Function to generate the start signal
int start_signal(int gpio) {
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(gpio, 1);
    gpioDelay(20); // Short delay after releasing the line
    return 0;
}

// Function to read the DHT11 response signal
int read_response(int gpio) {
    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDown(gpio, PI_PUD_UP);

    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait for the line to go low
        timeout++;
        if (timeout > TIMEOUT_US) {
            log_error("DHT11 response timeout", 1);
            return -1; // Timeout
        }
    }

    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1); // Wait for the line to go high
        timeout++;
        if (timeout > TIMEOUT_US) {
            log_error("DHT11 response timeout (high)", 2);
            return -1; // Timeout
        }
    }

    return 0;
}

// Function to read a single data bit
int read_data_bit(int gpio) {
    int timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1); // Wait for the line to go high
        timeout++;
        if (timeout > TIMEOUT_US) {
            log_error("DHT11 data bit timeout (low)", 3);
            return -1; // Timeout
        }
    }

    long start = gpioTick();
    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait for the line to go low
        timeout++;
        if (timeout > TIMEOUT_US) {
            log_error("DHT11 data bit timeout (high)", 4);
            return -1; // Timeout
        }
    }
    long end = gpioTick();

    if ((end - start) > 50) {
        return 1; // '1'
    } else {
        return 0; // '0'
    }
}

// Function to decode the 40 bits into DHT11Data structure
DHT11Data decode_data(unsigned int data) {
    DHT11Data result;
    result.humidity_integer = (data >> 24) & 0xFF;
    result.humidity_decimal = (data >> 16) & 0xFF;
    result.temperature_integer = (data >> 8) & 0xFF;
    result.temperature_decimal = data & 0xFF;
    result.checksum = (data >> 24) & 0xFF; // Checksum is the first byte
    return result;
}

// Function to verify the checksum
int verify_checksum(DHT11Data data) {
    unsigned char checksum = (data.humidity_integer + data.humidity_decimal + data.temperature_integer + data.temperature_decimal) & 0xFF;
    if (checksum != data.checksum) {
        log_error("Checksum failure", 5);
        return 0; // Checksum failure
    }
    return 1; // Checksum success
}

// Function to write the data to a file
int write_to_file(DHT11Data data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, data.humidity_integer, data.humidity_decimal, data.temperature_integer, data.temperature_decimal, data.checksum);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to log errors to a file
void log_error(const char *message, int status_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,ERROR,%d,%s\n", timestamp, status_code, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("DHT11 sensor reading started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        unsigned int data = 0;

        // Start the DHT11 reading
        if (start_signal(DHT11_GPIO) != 0) {
            log_error("Failed to send start signal", 6);
            gpioDelay(2000000); // Wait 2 seconds before retrying
            continue;
        }

        // Read the response signal
        if (read_response(DHT11_GPIO) != 0) {
            gpioDelay(2000000); // Wait 2 seconds before retrying
            continue;
        }

        // Read the 40 data bits
        for (int i = 0; i < 40; i++) {
            int bit = read_data_bit(DHT11_GPIO);
            if (bit == -1) {
                gpioDelay(2000000); // Wait 2 seconds before retrying
                data = 0; // Reset data
                break; // Exit the loop, retry the entire reading
            }
            data = (data << 1) | bit;
        }

        // Decode the data
        DHT11Data dht11_data = decode_data(data);

        // Verify the checksum
        if (verify_checksum(dht11_data)) {
            // Write the data to the file
            write_to_file(dht11_data);
            printf("Humidity: %d.%d%%, Temperature: %d.%d°C\n", dht11_data.humidity_integer, dht11_data.humidity_decimal, dht11_data.temperature_integer, dht11_data.temperature_decimal);
        }

        gpioDelay(2000000); // Wait 2 seconds before the next reading
    }

    cleanup();
    return 0;
}

