    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("DHT11 sensor reading started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        unsigned int data = 0;

        // Start the DHT11 reading
        if (start_signal(DHT11_GPIO) != 0) {
            log_error("Failed to send start signal", 6);
            gpioDelay(2000000); // Wait 2 seconds before retrying
            continue;
        }

        // Read the response signal
        if (read_response(DHT11_GPIO) != 0) {
            gpioDelay(2000000); // Wait 2 seconds before retrying
            continue;
        }

        // Read the 40 data bits
        for (int i = 0; i < 40; i++) {
            int bit = read_data_bit(DHT11_GPIO);
            if (bit == -1) {
                gpioDelay(2000000); // Wait 2 seconds before retrying
                data = 0; // Reset data
                break; // Exit the loop, retry the entire reading
            }
            data = (data << 1) | bit;
        }

        // Decode the data
        DHT11Data dht11_data = decode_data(data);

        // Verify the checksum
        if (verify_checksum(dht11_data)) {
            // Write the data to the file
            write_to_file(dht11_data);
            printf("Humidity: %d.%d%%, Temperature: %d.%d°C\n", dht11_data.humidity_integer, dht11_data.humidity_decimal, dht11_data.temperature_integer, dht11_data.temperature_decimal);
        }

        gpioDelay(2000000); // Wait 2 seconds before the next reading
    }

    cleanup();
    return 0;
}

