#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06 // High repeatability, clock stretching disabled
#define LOG_FILE "sht31d_data.log"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t calculated_crc = calculate_crc(data, len - 1);
    return (calculated_crc == data[len - 1]);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            gpioDelay(20); // Wait for measurement (at least 15ms)
            result = i2cReadDevice(i2c_handle, (char *)data, 6);
            if (result == 6) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            }
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(10); // Small delay before retrying
    }

    return -1; // Failure after multiple retries
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + (175.0 * (float)raw_temp / 65535.0);
}

// Convert raw humidity to relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

