int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t data[6];
    float temperature, humidity;
    time_t last_log_time = 0;

    while (!terminate) {
        if (read_sensor_data(data) == 0) {
            // Validate CRC for temperature
            if (validate_crc(data, 3)) {
                uint16_t raw_temp = (data[0] << 8) | data[1];
                temperature = convert_temperature(raw_temp);

                // Validate CRC for humidity
                if (validate_crc(data + 3, 3)) {
                    uint16_t raw_humidity = (data[3] << 8) | data[4];
                    humidity = convert_humidity(raw_humidity);

                    // Log data
                    log_data(temperature, humidity);
                    last_log_time = time(NULL);
                } else {
                    fprintf(stderr, "Humidity CRC validation failed\n");
                }
            } else {
                fprintf(stderr, "Temperature CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 5 seconds
        time_t now = time(NULL);
        if (now - last_log_time < 5) {
            sleep(5 - (now - last_log_time));
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

