#define ADPD105_REG_ID 0x00
#define ADPD105_REG_DATA_LOW 0x01
#define ADPD105_REG_DATA_HIGH 0x02
#define ADPD105_REG_CONFIG 0x03

// Define I2C bus
#define I2C_BUS 1

