int initialize_sensor(int i2c_handle) {
    // Example: Write a configuration register (replace with actual register and value)
    char config_data[2] = {ADPD105_REG_CONFIG, 0x01}; // Example config value
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char reg = ADPD105_REG_DATA_LOW; // Start reading from the low byte
    char buffer[6]; // Buffer to hold red, green, and blue data (2 bytes each)
    int result;

    // Read red data
    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor for red data: %s\n", strerror(errno));
        return -1;
    }
    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
        return -1;
    }

    *red = (buffer[1] << 8) | buffer[0];
    *green = (buffer[3] << 8) | buffer[2];
    *blue = (buffer[5] << 8) | buffer[4];

    return 0;
}

// Function to calculate CCT (replace with actual calculation from datasheet)
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    // This is a placeholder.  Replace with the actual CCT calculation.
    // The formula will depend on the specific ADPD105 configuration and datasheet.
    // This is a very basic approximation.
    float cct = (float)(red + green + blue) / 3.0; // Example calculation
    return cct;
}

// Function to log CCT to file
void log_cct(float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the file exists and is empty. If so, write the header.
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        // File doesn't exist, create it and write the header
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file for writing: %s\n", strerror(errno));
            return;
        }
        fprintf(log_file, "Timestamp,Average_CCT\n");
    } else {
        // File exists, check if it's empty
        fseek(fp, 0, SEEK_END);
        long file_size = ftell(fp);
        fclose(fp);

        if (file_size == 0) {
            // File is empty, write the header
            log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file for writing: %s\n", strerror(errno));
                return;
            }
            fprintf(log_file, "Timestamp,Average_CCT\n");
        } else {
            // File is not empty, open for appending
            log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file for writing: %s\n", strerror(errno));
                return;
            }
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, cct);
    fclose(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles
    i2c_handle_1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %s\n", strerror(errno));
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensor(i2c_handle_1) != 0) {
        fprintf(stderr, "Error initializing sensor 1\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle_2) != 0) {
        fprintf(stderr, "Error initializing sensor 2\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1;
        uint16_t red2, green2, blue2;
        float cct1, cct2, average_cct;

        // Read sensor data
        if (read_sensor_data(i2c_handle_1, &red1, &green1, &blue1) != 0) {
            fprintf(stderr, "Error reading sensor 1 data\n");
        } else {
            // Calculate CCT
            cct1 = calculate_cct(red1, green1, blue1);
        }

        if (read_sensor_data(i2c_handle_2, &red2, &green2, &blue2) != 0) {
            fprintf(stderr, "Error reading sensor 2 data\n");
        } else {
            // Calculate CCT
            cct2 = calculate_cct(red2, green2, blue2);
        }

        // Calculate average CCT
        if (i2c_handle_1 >= 0 && i2c_handle_2 >= 0) {
            average_cct = (cct1 + cct2) / 2.0;
            log_cct(average_cct);
        } else {
            fprintf(stderr, "Skipping average CCT calculation due to sensor error.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    return 0;
}

