#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
float read_temperature();
void update_buffer(float temperature);
float calculate_average();
void control_fan(float average_temperature);
void signal_handler(int signal);

// Function to read temperature from LM75B sensor
float read_temperature() {
    int i, result;
    float temperature = -100.0; // Initialize to an invalid value
    uint8_t data[2];

    for (i = 0; i < RETRY_COUNT; i++) {
        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result == 2) {
            // Success
            int16_t raw_temp = (data[0] << 8) | data[1];
            raw_temp = raw_temp >> 5; // Shift right by 5 bits
            temperature = (float)raw_temp * 0.125;
            return temperature;
        } else {
            fprintf(stderr, "Error reading temperature (attempt %d): %d\n", i + 1, result);
            time_sleep(0.1); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return temperature; // Return invalid value on failure
}

// Function to update the circular buffer
void update_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to calculate the running average
float calculate_average() {
    if (buffer_count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += temperature_buffer[i];
    }
    return sum / buffer_count;
}

// Function to control the cooling fan with hysteresis
void control_fan(float average_temperature) {
    static int fan_on = 0; // Track fan state

    if (average_temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON (Average Temperature: %.2f\u00b0C)\n", average_temperature);
    } else if (average_temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF (Average Temperature: %.2f\u00b0C)\n", average_temperature);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring and fan control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -99.0) { // Check for valid temperature reading
            update_buffer(temperature);
            float average_temperature = calculate_average();
            control_fan(average_temperature);
            printf("Temperature: %.2f\u00b0C, Average Temperature: %.2f\u00b0C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping fan control.\n");
        }

        time_sleep(1.0); // Wait for 1 second
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

