#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define MAX_I2C_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
float read_temperature();
void control_led(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int led_pin;
    float high_threshold;
    float low_threshold;
} config_t;

config_t config = {LED_GPIO, TEMP_THRESHOLD_HIGH, TEMP_THRESHOLD_LOW};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature != -1000.0) { // Indicate error with -1000.0
            printf("Temperature: %.2f °C\n", temperature);
            control_led(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(config.led_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", config.led_pin);
        return 1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Read temperature from STTS2004
float read_temperature() {
    char buf[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_I2C_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read == 2) {
            // Convert raw data to temperature (see STTS2004 datasheet)
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            raw_temp = raw_temp >> 4; // Shift right by 4 bits
            float temperature = (float)raw_temp * 0.0625; // Resolution is 0.0625 °C
            return temperature;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            sleep(1); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_I2C_RETRIES);
    return -1000.0; // Indicate error
}

// Control LED with hysteresis
void control_led(float temperature) {
    static int led_state = 0; // 0 = off, 1 = on

    if (temperature > config.high_threshold && led_state == 0) {
        if (gpioWrite(config.led_pin, 1) != 0) {
            fprintf(stderr, "Failed to set GPIO%d high\n", config.led_pin);
        } else {
            led_state = 1;
        }
    } else if (temperature < config.low_threshold && led_state == 1) {
        if (gpioWrite(config.led_pin, 0) != 0) {
            fprintf(stderr, "Failed to set GPIO%d low\n", config.led_pin);
        } else {
            led_state = 0;
        }
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(config.led_pin, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

