#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_hdc1080();
sensor_data_t read_hdc1080();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize HDC1080 sensor
int init_hdc1080() {
    // Configure for temperature and humidity measurement, 14-bit resolution
    if (i2cWriteByteData(i2c_handle, CONFIGURATION_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to configuration register\n");
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HDC1080
sensor_data_t read_hdc1080() {
    sensor_data_t data;
    unsigned short raw_temperature, raw_humidity;

    // Trigger temperature and humidity measurement
    if (i2cWriteByte(i2c_handle, 0x00) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Wait for conversion (at least 15ms)
    gpioDelay(20000); // 20ms

    // Read temperature data
    raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_REG);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Read humidity data
    raw_humidity = i2cReadWordData(i2c_handle, HUMIDITY_REG);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Convert raw data to temperature (Celsius) and humidity (%RH)
    data.temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data.humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return data;
}

// Log data to file
void log_data(sensor_data_t data) {
