#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86
#define CMD_READ_MEASUREMENT 0xec05

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Circular buffer size
#define BUFFER_SIZE 100

// Logging interval (seconds)
#define LOGGING_INTERVAL 60

// I2C bus
#define I2C_BUS 1

// Global variables
static int i2c_handle;
static volatile sig_atomic_t running = 1;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t buffer_not_empty = PTHREAD_COND_INITIALIZER;
static pthread_cond_t buffer_not_full = PTHREAD_COND_INITIALIZER;

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_tail = 0;
static int buffer_count = 0;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int stop_periodic_measurement();
int read_measurement(uint16_t *co2, float *temperature, float *humidity);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
