    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
