    result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }

    // Validate CRC for CO2
    uint8_t co2_data[2] = {data[0], data[1]};
    if (!validate_crc(co2_data, 2, data[2])) {
        log_error("CO2 CRC validation failed");
        return -1;
    }

    // Validate CRC for Temperature
    uint8_t temperature_data[2] = {data[3], data[4]};
    if (!validate_crc(temperature_data, 2, data[5])) {
        log_error("Temperature CRC validation failed");
        return -1;
    }

    // Validate CRC for Humidity
    uint8_t humidity_data[2] = {data[6], data[7]};
    if (!validate_crc(humidity_data, 2, data[8])) {
        log_error("Humidity CRC validation failed");
        return -1;
