        // Generate timestamped filename
        time(&now);
        tstruct = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", tstruct);
        snprintf(filename, sizeof(filename), "/var/log/scd40_data/scd40_data_%s.csv", timestamp);

        // Open CSV file for appending
        fp = fopen(filename, "a");
        if (fp == NULL) {
            log_error("Failed to open CSV file for writing");
            continue; // Skip to the next iteration
        }

        // Write header row if the file is newly created
        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        if (fsize == 0) {
            fprintf(fp, "Timestamp,CO2,Temperature,Humidity\n");
        }

        // Write data from buffer to CSV file
        while (buffer_count > 0) {
            if (remove_from_buffer(&data) == 0) {
