            } else {
                break; // Exit loop if buffer is empty
            }
        }

        // Close CSV file
        fclose(fp);
    }

    pthread_exit(NULL);
}

// Log error message to file
void log_error(const char *message) {
    FILE *fp;
    time_t now;
    struct tm *tstruct;
    char timestamp[80];

    // Create log directory if it doesn't exist
    create_log_directory();

    // Open error log file for appending
    fp = fopen("/var/log/scd40_error.log", "a");
