        } else {
            break; // Exit loop if buffer is empty
        }
    }

    // Close CSV file
    fclose(fp);
}

int main() {
    pthread_t logging_thread_id;
    uint16_t co2;
    float temperature, humidity;
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create logging thread
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Wait for one second before the first read
        sleep(1);

        // Read sensor data
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            // Get current timestamp
            time(&sensor_data.timestamp);

            // Add data to circular buffer
            sensor_data.co2 = co2;
            sensor_data.temperature = temperature;
            sensor_data.humidity = humidity;
            add_to_buffer(sensor_data);

            printf("CO2: %u ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", co2, temperature, humidity);
        } else {
            log_error("Failed to read sensor data");
        }

        // Wait for five seconds
        sleep(5);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        log_error("Failed to stop periodic measurement");
    }

    // Wait for logging thread to finish
    pthread_join(logging_thread_id, NULL);

    // Persist remaining data to CSV file
    persist_data_to_csv();

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

