#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define TRIGGER_MEASUREMENT 0x362F
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "sdp810_log.txt"

// CRC-8 parameters
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    uint8_t crc_received = data[len - 1];
    return (crc_calculated == crc_received);
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger measurement
int trigger_measurement() {
    char buf[2];
    buf[0] = (TRIGGER_MEASUREMENT >> 8) & 0xFF;
    buf[1] = TRIGGER_MEASUREMENT & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(45000); // Wait 45 ms
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    sensor_data.pressure = (float)raw_pressure / (float)raw_scale_factor;
    sensor_data.temperature = (float)raw_temperature / (float)raw_scale_factor;

    return sensor_data;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[9];

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(sensor_data, 3)) {
            fprintf(stderr, "CRC validation failed for pressure\n");
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(sensor_data + 3, 3)) {
            fprintf(stderr, "CRC validation failed for temperature\n");
            continue;
        }

        // Validate CRC for scale factor
        if (!validate_crc(sensor_data + 6, 3)) {
            fprintf(stderr, "CRC validation failed for scale factor\n");
            continue;
        }

        // Convert data
        sensor_data_t converted_data = convert_data(sensor_data);

        // Log data
        log_data(converted_data);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

