#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature(int reg);
void log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from the sensor
float read_temperature(int reg) {
    int retries = 0;
    int raw_temp;
    float temp_celsius;

    while (retries < MAX_RETRIES) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            // Convert raw temperature to Celsius
            temp_celsius = (float)raw_temp * 0.02 - 273.15;
            return temp_celsius;
        } else {
            fprintf(stderr, "Error reading temperature from register 0x%02X: %d. Retry %d\n", reg, raw_temp, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature from register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1000.0; // Indicate an error
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Ambient: %.2f °C, Object: %.2f °C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON (Object Temp: %.2f °C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF (Object Temp: %.2f °C)\n", object_temp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperatures
        float ambient_temp = read_temperature(AMBIENT_TEMP_REG);
        float object_temp = read_temperature(OBJECT_TEMP_REG);

        // Log temperature data
        if (ambient_temp > -999.0 && object_temp > -999.0) {
            log_temperature(ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping logging.\n");
        }

        // Control the fan
        control_fan(object_temp);

        // Wait for 2 seconds
        gpioDelay(2000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

