#include <errno.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(unsigned char *data);
sensor_data_t process_sensor_data(const unsigned char *data);
int create_http_response(const sensor_data_t *data, char *response, size_t response_size);
void handle_client(int client_socket);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data with retries
int read_sensor_data(unsigned char *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_HIGH_PRECISION);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        gpioDelay(10000); // Wait 10ms for measurement

        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Process raw sensor data to temperature and humidity
sensor_data_t process_sensor_data(const unsigned char *data) {
