#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define CSV_FILE "temperature_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
int log_temperature(FILE *log_file, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from TMP102
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    *temperature = raw_temp * 0.0625;

    return 0;
}

// Function to log temperature to CSV file
int log_temperature(FILE *log_file, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    float temperature;

    // Main loop
    while (1) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(log_file, temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping logging.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

