#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x0F
#define TEMPERATURE_MSB 0x00
#define TEMPERATURE_LSB 0x01
#define HUMIDITY_MSB 0x02
#define HUMIDITY_LSB 0x03

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a register from the HDC2010
int read_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write a register to the HDC2010
int write_register(int handle, uint8_t reg, uint8_t data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data
int read_temperature_humidity(int handle, float *temperature, float *humidity) {
    uint8_t data[4];
    int retries = 3;
    int result;

    // Trigger measurement
    while (retries > 0) {
        result = write_register(handle, MEASUREMENT_CONFIG, 0x01);
        if (result == 0) break;
        retries--;
        gpioDelay(10); // Small delay before retry
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to trigger measurement after multiple retries.\n");
        return -1;
    }

    // Wait for measurement to complete (polling with timeout)
    int timeout_ms = 500;
    while (timeout_ms > 0) {
        uint8_t config;
        retries = 3;
        while (retries > 0) {
            result = read_register(handle, MEASUREMENT_CONFIG, &config, 1);
            if (result == 0) break;
            retries--;
            gpioDelay(10);
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to read measurement config after multiple retries.\n");
            return -1;
        }

        if (!(config & 0x01)) {
            break; // Measurement complete
        }
        gpioDelay(10); // Wait 10ms
        timeout_ms -= 10;
    }

    if (timeout_ms <= 0) {
        fprintf(stderr, "Timeout waiting for measurement to complete.\n");
        return -1;
    }

    // Read temperature and humidity data
    retries = 3;
    while (retries > 0) {
        result = read_register(handle, TEMPERATURE_MSB, data, 4);
        if (result == 0) break;
        retries--;
        gpioDelay(10);
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature/humidity data after multiple retries.\n");
        return -1;
    }

    // Convert data to temperature and humidity
    int temperature_raw = (data[0] << 8) | data[1];
    int humidity_raw = (data[2] << 8) | data[3];

    *temperature = ((float)temperature_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humidity_raw / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    time_t last_output_time = time(NULL);

    // Main loop
    while (!terminate) {
        if (read_temperature_humidity(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity.\n");
        }

        time_t current_time = time(NULL);
        if (difftime(current_time, last_output_time) >= 5.0) {
            last_output_time = current_time;
        }

        gpioDelay(100); // Delay 100ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

