#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_SIZE 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID parameters
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// Target temperature profile
float target_profile[MAX_PROFILE_SIZE][2]; // [time, temperature]
int profile_size = 0;

// Function prototypes
int read_thermocouple();
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void set_relay_duty_cycle(float duty_cycle);
void log_data(float temperature, float pid_output);
int load_target_profile();
void signal_handler(int signal);

// Function to read temperature from MAX6675
int read_thermocouple() {
    char buffer[4];
    int raw_value;
    float temperature;

    if (spiRead(spi_handle, buffer, 4) != 4) {
        fprintf(stderr, "Error reading SPI data\n");
        return -1; // Indicate error
    }

    raw_value = (buffer[0] << 8) | buffer[1];
    raw_value = raw_value >> 3; // Remove fault bit

    if (raw_value & 0x04) {
        fprintf(stderr, "Thermocouple open or shorted\n");
        return -1; // Indicate error
    }

    temperature = (float)raw_value * 0.25;
    return (int)(temperature * 100); // Return temperature * 100 to avoid floating point in main loop
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set relay duty cycle using PWM
void set_relay_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;
    int pwm_value = (int)(duty_cycle * PWM_RANGE);
    gpioPWM(RELAY_GPIO, pwm_value);
}

// Function to log data to file
void log_data(float temperature, float pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load target temperature profile from file
int load_target_profile() {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening profile file\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL && profile_size < MAX_PROFILE_SIZE) {
        if (sscanf(line, "%f,%f", &target_profile[profile_size][0], &target_profile[profile_size][1]) == 2) {
            profile_size++;
        } else {
            fprintf(stderr, "Error parsing profile file line: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(RELAY_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(RELAY_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load target temperature profile
    if (load_target_profile() != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float integral = 0.0;
    float previous_error = 0.0;
    int profile_index = 0;
    time_t start_time = time(NULL);

    // Main loop
    while (!terminate) {
        // Get current time
        time_t current_time = time(NULL);
        float elapsed_time = difftime(current_time, start_time);

        // Update target temperature based on profile
        float target_temperature = 0.0;
        if (profile_index < profile_size) {
            if (elapsed_time >= target_profile[profile_index][0]) {
                target_temperature = target_profile[profile_index][1];
                profile_index++;
            } else {
                target_temperature = target_profile[profile_index][1];
            }
        } else {
            target_temperature = target_profile[profile_size - 1][1]; // Hold last temperature
        }

        // Read temperature from thermocouple
        int raw_temperature = read_thermocouple();
        if (raw_temperature == -1) {
            fprintf(stderr, "Error reading thermocouple, exiting\n");
            break;
        }
        float actual_temperature = (float)raw_temperature / 100.0;

        // Calculate PID output
        float pid_output = calculate_pid(target_temperature, actual_temperature, &integral, &previous_error);

        // Set relay duty cycle
        set_relay_duty_cycle(pid_output);

        // Log data
        log_data(actual_temperature, pid_output);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate();

    return 0;
}

