int read_temperature(float *temperature) {
    DIR *dir;
    struct dirent *ent;
    char sensor_path[256];
    char w1_slave_file[256];
    int fd;
    char buffer[256];
    ssize_t bytes_read;
    float temp_sum = 0.0;
    int sensor_count = 0;

    dir = opendir(W1_DEVICES_PATH);
    if (dir == NULL) {
        perror("opendir");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            // Found a DS18B20 sensor
            snprintf(sensor_path, sizeof(sensor_path), "%s%s", W1_DEVICES_PATH, ent->d_name);
            snprintf(w1_slave_file, sizeof(w1_slave_file), "%s/w1_slave", sensor_path);

            fd = open(w1_slave_file, O_RDONLY);
            if (fd == -1) {
                perror("open w1_slave");
                continue; // Try the next sensor
            }

            bytes_read = read(fd, buffer, sizeof(buffer) - 1);
            close(fd);

            if (bytes_read > 0) {
                buffer[bytes_read] = '\0';

                // Validate CRC
                if (validate_crc(buffer) != 0) {
                    fprintf(stderr, "CRC validation failed for sensor %s\n", ent->d_name);
                    continue; // Skip this sensor
                }

                // Extract temperature
                char *temp_str = strstr(buffer, "t=");
                if (temp_str != NULL) {
                    long temp_raw = strtol(temp_str + 2, NULL, 10);
                    float temp_celsius = (float)temp_raw / 1000.0;
                    temp_sum += temp_celsius;
                    sensor_count++;
                } else {
                    fprintf(stderr, "Temperature data not found in w1_slave for sensor %s\n", ent->d_name);
                }
            } else {
                perror("read w1_slave");
            }
        }
    }

    closedir(dir);

    if (sensor_count > 0) {
        *temperature = temp_sum / sensor_count;
        return 0; // Success
    } else {
        fprintf(stderr, "No valid temperature readings found.\n");
        return -1; // Failure
    }
}

