void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to validate CRC checksum
int validate_crc(const char *data) {
    unsigned char crc = 0;
    unsigned char shift_register = 0;
    int i, j;

    for (i = 0; i < 160; i++) {
        shift_register = (crc ^ data[i]) & 1;
        if (shift_register) {
            crc = crc ^ 7;
            crc = (crc << 1) | 1;
        } else {
            crc = (crc << 1);
        }
    }

    unsigned char received_crc[2];
    sscanf(data + 158, "%2hhx", &received_crc[0]);

    return (crc != received_crc[0]);
