    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetMode(GPIO_PWM, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_PWM, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PWM, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read temperature
        if (read_temperature(&current_temperature) == 0) {
            // Calculate PID output
            pid_output = calculate_pid(current_temperature);

            // Set PWM duty cycle
            set_pwm_duty_cycle(pid_output);
            pwm_duty_cycle = (int)(pid_output * PWM_RANGE / 100.0);

            // Set relay state (example: turn on if PID output > 50)
            set_relay_state(pid_output > 50 ? 1 : 0);

            // Log data
            log_data(current_temperature, pid_output, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature. Check sensor connections.\n");
        }

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    set_relay_state(0); // Turn off relay
    gpioPWM(GPIO_PWM, 0); // Set PWM to zero
    fclose(log_file);
    gpioTerminate();

    return 0;
}

