#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init(int i2c_handle);
int aht20_trigger_measurement(int i2c_handle);
int aht20_read_data(int i2c_handle, uint8_t *data);
float aht20_convert_humidity(uint32_t raw_humidity);
void control_dehumidifier(float humidity);
void log_humidity(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// AHT20 initialization function
int aht20_init(int i2c_handle) {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    int result, retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, init_cmd, sizeof(init_cmd));
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "AHT20 init failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "AHT20 init failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// AHT20 trigger measurement function
int aht20_trigger_measurement(int i2c_handle) {
    uint8_t measure_cmd[] = {0xAC, 0x33, 0x00};
    int result, retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, measure_cmd, sizeof(measure_cmd));
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "AHT20 trigger measurement failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "AHT20 trigger measurement failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// AHT20 read data function
int aht20_read_data(int i2c_handle, uint8_t *data) {
    int result, retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "AHT20 read data failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "AHT20 read data failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// AHT20 convert humidity function
float aht20_convert_humidity(uint32_t raw_humidity) {
    return ((float)raw_humidity / 0x100000) * 100;
}

// Control dehumidifier function
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Activate dehumidifier
        printf("Dehumidifier activated (humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Deactivate dehumidifier
        printf("Dehumidifier deactivated (humidity: %.2f%%)\n", humidity);
    }
}

// Log humidity function
void log_humidity(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init(i2c_handle) != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set dehumidifier GPIO as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        uint32_t raw_humidity;
        float humidity;

        // Trigger measurement
        if (aht20_trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
        } else {
            gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

            // Read data
            if (aht20_read_data(i2c_handle, data) == 0) {
                // Check status byte (bit 7 of data[0])
                if (!(data[0] & 0x80)) {
                    // Extract raw humidity data
                    raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);

                    // Convert humidity
                    humidity = aht20_convert_humidity(raw_humidity);

                    // Log humidity
                    log_humidity(humidity);

                    // Control dehumidifier
                    control_dehumidifier(humidity);
                } else {
                    fprintf(stderr, "AHT20 busy or calibration error\n");
                }
            } else {
                fprintf(stderr, "Failed to read data\n");
            }
        }

        gpioDelay(5000000); // Delay 5 seconds (5000000 microseconds)
    }

    // Cleanup
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

