    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init(i2c_handle) != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set dehumidifier GPIO as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        uint32_t raw_humidity;
        float humidity;

        // Trigger measurement
        if (aht20_trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
        } else {
            gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

            // Read data
            if (aht20_read_data(i2c_handle, data) == 0) {
                // Check status byte (bit 7 of data[0])
                if (!(data[0] & 0x80)) {
                    // Extract raw humidity data
                    raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);

                    // Convert humidity
                    humidity = aht20_convert_humidity(raw_humidity);

                    // Log humidity
                    log_humidity(humidity);

                    // Control dehumidifier
                    control_dehumidifier(humidity);
                } else {
                    fprintf(stderr, "AHT20 busy or calibration error\n");
                }
            } else {
                fprintf(stderr, "Failed to read data\n");
            }
        }

        gpioDelay(5000000); // Delay 5 seconds (5000000 microseconds)
    }

    // Cleanup
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Ensure dehumidifier is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

