#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5
#define API_ENDPOINT "api.example.com"
#define API_PORT 80
#define POLL_INTERVAL 60 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_humidity(float *humidity);
int post_humidity(float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "I2C device opened successfully.");
    return 0;
}

// Read humidity from HTU21D sensor
int read_humidity(float *humidity) {
    unsigned char buf[3];
    int result;

    // Trigger humidity measurement
    result = i2cWriteByte(i2c_handle, TRIGGER_HUMID_MEASURE);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement: %s", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (datasheet recommends at least 50ms)
    gpioDelay(50000); // 50ms

    // Read 3 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %s", strerror(errno));
        return -1;
    }

    // Convert data to humidity
    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

    // Validate humidity
    if (*humidity < 0.0 || *humidity > 100.0) {
        syslog(LOG_ERR, "Humidity value out of range: %.2f", *humidity);
        return -1;
    }

    syslog(LOG_INFO, "Humidity reading: %.2f%%", *humidity);
    return 0;
}

// Post humidity data to API endpoint
int post_humidity(float humidity) {
    int sockfd;
    struct sockaddr_in serv_addr;
    char json_data[100];
    char buffer[1024] = {0};
    int result;

    // Create JSON payload
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation error: %s", strerror(errno));
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(API_PORT);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, API_ENDPOINT, &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", API_ENDPOINT);
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Construct HTTP POST request
    char request[512];
    snprintf(request, sizeof(request), 
             "POST /humidity HTTP/1.1\r\n" 
             "Host: %s\r\n" 
             "Content-Type: application/json\r\n" 
             "Content-Length: %zu\r\n" 
             "Connection: close\r\n" 
             "\r\n" 
             "%s", API_ENDPOINT, strlen(json_data), json_data);

    // Send HTTP POST request
    result = send(sockfd, request, strlen(request), 0);
    if (result < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Receive response (optional, but good practice)
    result = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (result < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
    } else {
        buffer[result] = '\0';
        syslog(LOG_INFO, "Received response: %s", buffer);
    }

    close(sockfd);
    syslog(LOG_INFO, "Humidity data posted successfully.");
    return 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        syslog(LOG_INFO, "I2C device closed.");
    }
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated.");
    closelog();
}

int main() {
    float humidity;
    int result;

    // Initialize syslog
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting humidity monitor...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        return 1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully.");

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read humidity
        if (read_humidity(&humidity) == 0) {
            // Post humidity data
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity.");
        }

        // Wait for the next poll interval
        sleep(POLL_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

