#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_ID 0xD0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Expected chip ID
#define BMP280_CHIP_ID 0x58

// Pressure thresholds
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_bmp280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
void log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280 sensor
    if (init_bmp280() != 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        cleanup();
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw data\n");
            continue; // Try again
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);

        // Log pressure if it exceeds thresholds
        if (pressure > PRESSURE_HIGH_THRESHOLD || pressure < PRESSURE_LOW_THRESHOLD) {
            log_pressure(pressure);
        }

        // Wait 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize BMP280 sensor
int init_bmp280() {
    int retries = 3;
    int status = -1;

    while (retries > 0) {
        // Open I2C bus
        i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Verify chip ID
        uint8_t chip_id;
        if (read_register(i2c_handle, BMP280_REG_ID, &chip_id) != 0) {
            fprintf(stderr, "Error reading chip ID\n");
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        if (chip_id != BMP280_CHIP_ID) {
            fprintf(stderr, "Incorrect chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        // Read calibration data
        if (read_calibration_data() != 0) {
            fprintf(stderr, "Error reading calibration data\n");
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        // Set sensor mode to forced mode
        if (write_register(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) { // Oversampling x1, Normal mode
            fprintf(stderr, "Error writing control register\n");
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        status = 0; // Success
        break;
    }

    if (status != 0) {
        fprintf(stderr, "BMP280 initialisation failed after multiple retries\n");
        return -1;
    }

    return 0;
}

// Read calibration data from the sensor
int read_calibration_data() {
    uint8_t data[26];
    int result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 26);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data block: %d\n", result);
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    int result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading raw data block: %d\n", result);
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double T_fine;

    var1 = (((double)raw_temperature / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    T_fine = (var1 + var2);
    T = (T_fine / 5120.0);
    return T;
}

// Compensate pressure
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
