        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize BMP280 sensor
int init_bmp280() {
    int retries = 3;
    int status = -1;

    while (retries > 0) {
        // Open I2C bus
        i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Verify chip ID
        uint8_t chip_id;
        if (read_register(i2c_handle, BMP280_REG_ID, &chip_id) != 0) {
            fprintf(stderr, "Error reading chip ID\n");
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        if (chip_id != BMP280_CHIP_ID) {
            fprintf(stderr, "Incorrect chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
