#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle_tmp117 = -1;
int i2c_handle_aht20 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
float read_tmp117(int handle);
int read_aht20(int handle, float *humidity);
int read_pir(int gpio);
void log_data(FILE *fp, float temperature, float humidity, int motion);
void signal_handler(int signal);
void close_resources();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read temperature from TMP117
float read_tmp117(int handle) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            return raw_temp * 0.0078125;
        } else {
            fprintf(stderr, "Error reading TMP117 (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    fprintf(stderr, "Failed to read TMP117 after %d retries.\n", MAX_RETRIES);
    return NAN; // Not a Number
}

// Function to read humidity from AHT20
int read_aht20(int handle, float *humidity) {
    char init_cmd[] = {0xBE, 0x08, 0x00};
    char measure_cmd[] = {0xAC, 0x33, 0x00};
    char buf[6];
    int retries = 0;
    int result;

    // Initialization
    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, init_cmd, 3);
        if (result == 3) break;
        fprintf(stderr, "Error initializing AHT20 (attempt %d): %d\n", retries + 1, result);
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize AHT20 after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    gpioDelay(20000); // Wait 20ms

    // Measurement
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, measure_cmd, 3);
        if (result == 3) break;
        fprintf(stderr, "Error measuring AHT20 (attempt %d): %d\n", retries + 1, result);
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to measure AHT20 after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    gpioDelay(80000); // Wait 80ms

    // Read data
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 6);
        if (result == 6) break;
        fprintf(stderr, "Error reading AHT20 data (attempt %d): %d\n", retries + 1, result);
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read AHT20 data after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Check status bit
    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy.\n");
        return -1;
    }

    // Calculate humidity
    uint32_t humidity_raw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
    *humidity = ((float)humidity_raw / 0x100000) * 100;
    return 0;
}

// Function to read motion detection from PIR sensor
int read_pir(int gpio) {
    return gpioRead(gpio);
}

// Function to log data to CSV file
void log_data(FILE *fp, float temperature, float humidity, int motion) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to close resources
void close_resources() {
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle_tmp117 = init_i2c(I2C_BUS, TMP117_ADDR);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Failed to initialize TMP117. Continuing without it.\n");
    }

    i2c_handle_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Failed to initialize AHT20. Continuing without it.\n");
    }

    // Configure PIR sensor GPIO
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Open log file (create new file each day)
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char filename[30];
        strftime(filename, sizeof(filename), "sensor_log_%Y-%m-%d.csv", &tm);

        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", filename);
            close_resources();
            return 1;
        }

        // Write header if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        }

        // Read sensor data
        float temperature = NAN;
        float humidity = NAN;
        int motion = 0;

        if (i2c_handle_tmp117 >= 0) {
            temperature = read_tmp117(i2c_handle_tmp117);
        }
        if (i2c_handle_aht20 >= 0) {
            if (read_aht20(i2c_handle_aht20, &humidity) != 0) {
                humidity = NAN; // Set to NAN if read fails
            }
        }
        motion = read_pir(PIR_GPIO);

        // Log data
        log_data(log_file, temperature, humidity, motion);

        // Close log file
        fclose(log_file);
        log_file = NULL;

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Close resources before exiting
    close_resources();

    return 0;
}

