    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to close resources
void close_resources() {
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle_tmp117 = init_i2c(I2C_BUS, TMP117_ADDR);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Failed to initialize TMP117. Continuing without it.\n");
    }

    i2c_handle_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Failed to initialize AHT20. Continuing without it.\n");
    }

    // Configure PIR sensor GPIO
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Open log file (create new file each day)
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char filename[30];
        strftime(filename, sizeof(filename), "sensor_log_%Y-%m-%d.csv", &tm);

        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", filename);
            close_resources();
            return 1;
        }

        // Write header if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        }

        // Read sensor data
        float temperature = NAN;
        float humidity = NAN;
        int motion = 0;

        if (i2c_handle_tmp117 >= 0) {
            temperature = read_tmp117(i2c_handle_tmp117);
        }
        if (i2c_handle_aht20 >= 0) {
            if (read_aht20(i2c_handle_aht20, &humidity) != 0) {
                humidity = NAN; // Set to NAN if read fails
            }
        }
        motion = read_pir(PIR_GPIO);

        // Log data
        log_data(log_file, temperature, humidity, motion);

        // Close log file
        fclose(log_file);
        log_file = NULL;

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Close resources before exiting
    close_resources();

    return 0;
}

