// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control constants
#define MOTOR_FORWARD 1
#define MOTOR_STOP 0

// Define motor duration
#define MOTOR_DURATION 5 // seconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int direction);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received signal, stopping motor and cleaning up...");
    control_motor(MOTOR_STOP); // Stop the motor
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set initial motor state to stop
    control_motor(MOTOR_STOP);

    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Control the motor
int control_motor(int direction) {
    if (direction == MOTOR_FORWARD) {
        // Move motor forward
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioWrite(MOTOR_ENA_PIN, 1); // Enable motor
        log_message("Motor started");
        gpioDelay(MOTOR_DURATION * 1000000); // Delay for motor duration (microseconds)
        gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        log_message("Motor stopped");
    } else if (direction == MOTOR_STOP) {
        // Stop the motor
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
    } else {
        fprintf(stderr, "Invalid motor direction\n");
        return -1;
    }
    return 0;
}

// Log messages with timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    log_message("Program started");

    // Main loop
    while (program_running) {
        int rain_detected = (read_rain_sensor() == 0); // YL-83 is active low

        if (rain_detected) {
            log_message("Rain detected!");
            control_motor(MOTOR_FORWARD);
        }

        gpioDelay(2000000); // Delay for 2 seconds (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motor(MOTOR_STOP);
    gpioTerminate();
    log_message("Program terminated");

    return 0;
}

