#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Structure to hold CPU usage data
typedef struct {
    unsigned long long user;
    unsigned long long nice;
    unsigned long long system;
    unsigned long long idle;
    unsigned long long iowait;
    unsigned long long irq;
    unsigned long long softirq;
} cpu_stats_t;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_cpu_stats(cpu_stats_t *stats);
float calculate_cpu_load(cpu_stats_t *prev, cpu_stats_t *curr);
void map_load_to_color(float load, int *red, int *green, int *blue);
int set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(cpu_stats_t *stats) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu",
               &stats->user, &stats->nice, &stats->system, &stats->idle,
               &stats->iowait, &stats->irq, &stats->softirq) != 7) {
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load percentage
float calculate_cpu_load(cpu_stats_t *prev, cpu_stats_t *curr) {
    unsigned long long prev_idle = prev->idle + prev->iowait;
    unsigned long long curr_idle = curr->idle + curr->iowait;

    unsigned long long prev_non_idle = prev->user + prev->nice + prev->system + prev->irq + prev->softirq;
    unsigned long long curr_non_idle = curr->user + curr->nice + curr->system + curr->irq + curr->softirq;

    unsigned long long prev_total = prev_idle + prev_non_idle;
    unsigned long long curr_total = curr_idle + curr_non_idle;

    unsigned long long totald = curr_total - prev_total;
    unsigned long long idled = curr_idle - prev_idle;

    float cpu_usage = (float)(totald - idled) / totald;
    return cpu_usage * 100.0;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float load, int *red, int *green, int *blue) {
    if (load <= 50.0) {
        // Green to Yellow
        *red = 0;
        *green = (int)(load / 50.0 * 255.0);
        *blue = 255 - (int)(load / 50.0 * 255.0);
    } else {
        // Yellow to Red
        *red = (int)((load - 50.0) / 50.0 * 255.0);
        *green = 255 - (int)((load - 50.0) / 50.0 * 255.0);
        *blue = 0;
    }
}

// Function to set the RGB LED color using pigpio
int set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Common anode, so invert the value
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, so invert the value
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, so invert the value
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    cpu_stats_t prev_stats, curr_stats;

    // Read initial CPU stats
    if (read_cpu_stats(&prev_stats) != 0) {
        fprintf(stderr, "Failed to read initial CPU stats\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read current CPU stats
        if (read_cpu_stats(&curr_stats) != 0) {
            fprintf(stderr, "Failed to read CPU stats\n");
            break;
        }

        // Calculate CPU load
        float cpu_load = calculate_cpu_load(&prev_stats, &curr_stats);

        // Map CPU load to RGB color
        int red, green, blue;
        map_load_to_color(cpu_load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Update previous stats
        prev_stats = curr_stats;

        // Wait for 500ms
        usleep(500000); // 500ms = 500000 microseconds
    }

    // Turn off the LED
    set_led_color(255, 255, 255);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

