#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000
#define BUFFER_SIZE 20

// Data structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} BufferEntry;

// Circular buffer
BufferEntry buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
int calculate_duty_cycle(float temperature);
void update_fan_speed(int duty_cycle);
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1000.0;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (ignoring fault bits)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    float temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature < 40.0) {
        duty_cycle = (int)((temperature - 25.0) / (40.0 - 25.0) * 127.5);
    } else if (temperature < 60.0) {
        duty_cycle = (int)((temperature - 40.0) / (60.0 - 40.0) * 127.5 + 127.5);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to update fan speed using PWM
void update_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("Timestamp: %s, Temperature: %.2f, Duty Cycle: %d\n", time_str, buffer[index].temperature, buffer[index].duty_cycle);
    }
    printf("--- End of Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(FAN_GPIO, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            // Calculate duty cycle
            int duty_cycle = calculate_duty_cycle(temperature);

            // Update fan speed
            update_fan_speed(duty_cycle);

            // Get current timestamp
            time_t now = time(NULL);

            // Add data to circular buffer
            add_to_buffer(now, temperature, duty_cycle);

            printf("Temperature: %.2f, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping fan update.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Stop PWM
    update_fan_speed(0);

    // Close SPI interface
    spiClose(spi_handle);

    // Print buffer contents
    print_buffer();

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");

    return 0;
}

