        duty_cycle = (int)((temperature - 40.0) / (60.0 - 40.0) * 127.5 + 127.5);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to update fan speed using PWM
void update_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("Timestamp: %s, Temperature: %.2f, Duty Cycle: %d\n", time_str, buffer[index].temperature, buffer[index].duty_cycle);
    }
    printf("--- End of Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(FAN_GPIO, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            // Calculate duty cycle
            int duty_cycle = calculate_duty_cycle(temperature);

            // Update fan speed
            update_fan_speed(duty_cycle);

            // Get current timestamp
            time_t now = time(NULL);

            // Add data to circular buffer
            add_to_buffer(now, temperature, duty_cycle);

            printf("Temperature: %.2f, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping fan update.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Stop PWM
    update_fan_speed(0);

    // Close SPI interface
    spiClose(spi_handle);

    // Print buffer contents
    print_buffer();

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");

    return 0;
}

