}

// Function to read a register from the MAX31865
int read_register(uint8_t reg, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set read bit
    tx_buf[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// Function to write a register in the MAX31865
int write_register(uint8_t reg, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear read bit
    tx_buf[1] = data;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error writing register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// Function to read the RTD value from the MAX31865
int read_rtd_data(uint16_t *rtd_value) {
    uint8_t msb, lsb;

    if (read_register(MAX31865_RTD_MSB_REG, &msb) != 0) {
        fprintf(stderr, "Error reading RTD MSB\n");
        return -1;
    }

    if (read_register(MAX31865_RTD_LSB_REG, &lsb) != 0) {
        fprintf(stderr, "Error reading RTD LSB\n");
        return -1;
    }

    *rtd_value = ((uint16_t)msb << 8) | lsb;
    *rtd_value = *rtd_value >> 1; // Remove fault bit

    return 0;
}

// Function to check the fault status register
int check_fault_status() {
    uint8_t fault_status;

    if (read_register(MAX31865_FAULT_REG, &fault_status) != 0) {
        fprintf(stderr, "Error reading fault status\n");
        return -1;
    }

    if (fault_status != 0) {
        fprintf(stderr, "Fault detected: 0x%02X\n", fault_status);
        if (fault_status & FAULT_HIGH_THRESHOLD) {
            fprintf(stderr, "  High threshold fault\n");
        }
        if (fault_status & FAULT_LOW_THRESHOLD) {
            fprintf(stderr, "  Low threshold fault\n");
        }
        if (fault_status & FAULT_REFIN_LOW) {
            fprintf(stderr, "  REFIN- low fault\n");
        }
        if (fault_status & FAULT_REFIN_HIGH) {
            fprintf(stderr, "  REFIN+ high fault\n");
        }
        if (fault_status & FAULT_RTDIN_LOW) {
            fprintf(stderr, "  RTDIN- low fault\n");
        }
        if (fault_status & FAULT_RTDIN_HIGH) {
            fprintf(stderr, "  RTDIN+ high fault\n");
        }
        if (fault_status & FAULT_OVERUNDER_VOLTAGE) {
            fprintf(stderr, "  Over/under-voltage fault\n");
        }
        if (fault_status & FAULT_OPEN_CIRCUIT) {
            fprintf(stderr, "  RTD open circuit fault\n");
        }
        return -1; // Indicate fault
    }

    return 0; // No fault
}

// Function to calculate the temperature using the Callendar-Van Dusen equation
double calculate_temperature(uint16_t rtd_value) {
    // These values are example values.  Refer to the MAX31865 datasheet
    // for the correct values for your specific RTD and reference resistor.
    double rtd_resistance = (double)rtd_value * 430.0 / 32768.0; // Example: 430 ohms RTD
    double a = 3.9083e-3;
    double b = -5.775e-7;
    double c = -4.183e-12;
    double r0 = 100.0; // Example: 100 ohms reference resistor

    double rtd_ratio = rtd_resistance / r0;

    double temperature = -242.0 + 2.25 * rtd_ratio;
    temperature += 2.58 * pow(rtd_ratio, 2.0);
    temperature -= 4.826 * pow(rtd_ratio, 3.0);
    temperature -= 2.818 * pow(rtd_ratio, 4.0);
    temperature += 1.524 * pow(rtd_ratio, 5.0);

    return temperature;
}

// Function to log the temperature to a file
int log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close SPI and log file
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Configure MAX31865 for 3-wire RTD mode with bias
    if (write_register(MAX31865_CONFIG_REG, 0xC2) != 0) {
        fprintf(stderr, "Error configuring MAX31865\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t rtd_value;
        double temperature;

        if (read_rtd_data(&rtd_value) == 0) {
            if (check_fault_status() == 0) {
                temperature = calculate_temperature(rtd_value);
