            } else {
                fprintf(stderr, "Fault detected, skipping temperature logging\n");
            }
        } else {
            fprintf(stderr, "Error reading RTD data, skipping temperature logging\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
