#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_ID 0xD0
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_PRESS_LSB 0xF8
#define BME280_REG_PRESS_XLSB 0xF9
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_TEMP_LSB 0xFB
#define BME280_REG_TEMP_XLSB 0xFC
#define BME280_REG_HUM_MSB 0xFD
#define BME280_REG_HUM_LSB 0xFE

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Expected chip ID
#define BME280_CHIP_ID 0x60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int init_bme280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
double compensate_humidity(int32_t raw_humidity, double t_fine);
int log_data(double temperature, double humidity, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize BME280 sensor
int init_bme280() {
    int status;
    uint8_t chip_id;

    // Check if pigpio is initialized
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BME280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Read chip ID
    status = i2cReadI2CBlockData(i2c_handle, BME280_REG_ID, (char *)&chip_id, 1);
    if (status < 0) {
        fprintf(stderr, "Failed to read chip ID: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Verify chip ID
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BME280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set sensor control registers (example values)
    uint8_t ctrl_meas = (0b011 << 5) | (0b011 << 2) | 0b011; // Temperature oversampling x1, Pressure oversampling x1, Normal mode
    status = i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, ctrl_meas);
    if (status < 0) {
        fprintf(stderr, "Failed to write CTRL_MEAS register: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    uint8_t ctrl_hum = 0b011; // Humidity oversampling x1
    status = i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUM, ctrl_hum);
    if (status < 0) {
        fprintf(stderr, "Failed to write CTRL_HUM register: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    uint8_t config = (0b000 << 5) | (0b000 << 2); // Standby time 0.5ms, Filter off
    status = i2cWriteByteData(i2c_handle, BME280_REG_CONFIG, config);
    if (status < 0) {
        fprintf(stderr, "Failed to write CONFIG register: %d\n", status);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read calibration data from sensor
int read_calibration_data() {
    int status;
    uint8_t data[26];

    status = i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)data, 26);
    if (status < 0) {
        fprintf(stderr, "Failed to read calibration data (0x88-0xA1): %d\n", status);
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib.dig_H1 = data[25];

    uint8_t data_h[7];
    status = i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_26, (char *)data_h, 7);
    if (status < 0) {
        fprintf(stderr, "Failed to read calibration data (0xE1-0xE7): %d\n", status);
        return -1;
    }

    calib.dig_H2 = (int16_t)data_h[0] | ((int16_t)data_h[1] << 8);
    calib.dig_H3 = data_h[2];
    calib.dig_H4 = (int16_t)((data_h[3] << 4) | (data_h[4] & 0x0F));
    calib.dig_H5 = (int16_t)((data_h[5] << 4) | (data_h[4] >> 4));
    calib.dig_H6 = (int8_t)data_h[6];

    return 0;
}

// Read raw temperature, pressure, and humidity data
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    int status;
    uint8_t data[8];

    status = i2cReadI2CBlockData(i2c_handle, BME280_REG_PRESS_MSB, (char *)data, 8);
    if (status < 0) {
        fprintf(stderr, "Failed to read raw data: %d\n", status);
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    *humidity = ((int32_t)data[6] << 8) | (int32_t)data[7];

    return 0;
}

// Compensate temperature
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double adc_T = (double)raw_temperature;

    var1 = (adc_T / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    var2 = ((adc_T / 131072.0 - (double)calib.dig_T1 / 8192.0) * (adc_T / 131072.0 - (double)calib.dig_T1 / 8192.0)) * (double)calib.dig_T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    double adc_P = (double)raw_pressure;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
