#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 3

// GPIO pin for alert
#define ALERT_PIN 24

// Circular buffer size (60 seconds * 20 samples/second)
#define BUFFER_SIZE 1200

// Structure to hold pressure reading and timestamp
typedef struct {
    long long timestamp;
    float pressure;
} PressureReading;

// Circular buffer
PressureReading pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// I2C file descriptor
int i2c_fd;

// Function prototypes
int init_bmp180();
float read_pressure();
void add_reading(float pressure);
float calculate_average();
void check_deviation(float current_pressure, float average_pressure);
void signal_handler(int signal);
void timer_interrupt();

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO pin for alert
    pinMode(ALERT_PIN, OUTPUT);
    digitalWrite(ALERT_PIN, LOW);

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize BMP180 sensor
    if (init_bmp180() != 0) {
        fprintf(stderr, "Error initializing BMP180 sensor.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer interrupt (every 50ms)
    if (wiringPiISR(0, INT_EDGE_RISING, timer_interrupt) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until Ctrl+C is pressed)
    while (program_running) {
        delay(100); // Sleep to reduce CPU usage
    }

    return 0;
}

// Initialize BMP180 sensor
int init_bmp180() {
    // Read calibration data
    ac1 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC1);
    ac2 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC2);
    ac3 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC3);
    ac4 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC4);
    ac5 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC5);
    ac6 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_AC6);
    b1 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B1);
    b2 = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_B2);
    mb = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MB);
    mc = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MC);
    md = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CAL_MD);

    // Check for errors during calibration data read
    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data from BMP180.\n");
        return -1;
    }

    return 0;
}

// Read pressure from BMP180 sensor
float read_pressure() {
    int ut, up;
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    // Request temperature reading
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x2E);
    delay(5); // Wait 4.5ms

    // Read uncompensated temperature (UT)
    ut = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_MSB);
    if (ut == -1) {
        fprintf(stderr, "Error reading uncompensated temperature.\n");
        return -1.0;
    }

    // Request pressure reading
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6));
    delay(2 + (3 << BMP180_OSS)); // Wait for conversion

    // Read uncompensated pressure (UP)
    up = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_MSB);
    if (up == -1) {
        fprintf(stderr, "Error reading uncompensated pressure.\n");
        return -1.0;
    }

    // Calculate pressure (see BMP180 datasheet)
    x1 = ((long)ut - (long)ac6) * ((long)ac5) / pow(2, 15);
    x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    b5 = x1 + x2;
    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    x2 = ac2 * b6 / pow(2, 11);
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) / 4;
    x1 = ac3 * b6 / pow(2, 13);
    x2 = (b1 * (b6 * b6 / pow(2, 12))) / pow(2, 16);
    x3 = ((x1 + x2) + 2) / pow(2, 2);
    b4 = ac4 * (unsigned long)(x3 + 32768) / pow(2, 15);
    b7 = ((unsigned long)up - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    p = p + (x1 + x2 + 3791) / pow(2, 4);

    return (float)p / 100.0; // Return pressure in hPa
}

// Add pressure reading to circular buffer
void add_reading(float pressure) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    pressure_buffer[buffer_index].timestamp = timestamp;
    pressure_buffer[buffer_index].pressure = pressure;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate rolling average of pressure readings
float calculate_average() {
    float sum = 0.0;
    int count = 0;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (pressure_buffer[i].pressure != 0.0) {
            sum += pressure_buffer[i].pressure;
            count++;
        }
    }

    if (count > 0) {
        return sum / count;
    } else {
        return 0.0;
    }
}

// Check for pressure deviation and trigger alert
void check_deviation(float current_pressure, float average_pressure) {
    float deviation = fabs(current_pressure - average_pressure);

    if (deviation > 5.0) {
        digitalWrite(ALERT_PIN, HIGH);
        fprintf(stderr, "ALERT: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa, Deviation: %.2f hPa\n", current_pressure, average_pressure, deviation);
    } else {
        digitalWrite(ALERT_PIN, LOW);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    program_running = 0;
}

