    // Request pressure reading
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6));
    delay(2 + (3 << BMP180_OSS)); // Wait for conversion

    // Read uncompensated pressure (UP)
    up = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_MSB);
    if (up == -1) {
        fprintf(stderr, "Error reading uncompensated pressure.\n");
        return -1.0;
