// Add pressure reading to circular buffer
void add_reading(float pressure) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    pressure_buffer[buffer_index].timestamp = timestamp;
    pressure_buffer[buffer_index].pressure = pressure;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
