    float sum = 0.0;
    int count = 0;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (pressure_buffer[i].pressure != 0.0) {
            sum += pressure_buffer[i].pressure;
            count++;
        }
    }

    if (count > 0) {
        return sum / count;
    } else {
