int read_raw_temperature(int32_t *raw_temp) {
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    int result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
