#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int read_temperature() {
    FILE *fp;
    int temperature = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temperature) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temperature;
}

int map_temperature_to_duty_cycle(int temperature) {
    int duty_cycle;

    if (temperature <= 40000) {
        duty_cycle = 0;
    } else if (temperature >= 70000) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)(((float)(temperature - 40000) / 30000.0) * 255.0);
    }

    return duty_cycle;
}

int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

int log_data(int temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            (float)temperature / 1000.0, duty_cycle);

    fclose(fp);
    return 0;
}

int main() {
    int temperature, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature
        temperature = read_temperature();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider exiting or using a default temperature here
            sleep(5);
            continue; // Or break if exiting is desired
        }

        // Map temperature to duty cycle
        duty_cycle = map_temperature_to_duty_cycle(temperature);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM, using previous value or exiting.\n");
            // Consider exiting or using a previous duty cycle here
            sleep(5);
            continue; // Or break if exiting is desired
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Stop the fan
    gpioPWM(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Fan control program stopped.\n");

    return 0;
}

