    calib->dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib->dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib->dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib->dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib->dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib->dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib->dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib->dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib->dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib->dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);

    // Set oversampling and power mode
    uint8_t config = (0x02 << 5) | (0x02 << 2) | 0x03; // t_sb = 0.5ms, filter = x4, spi3w_en = disabled
    result = i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, config);
    if (result < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }

    uint8_t ctrl_meas = (0x03 << 5) | (0x03 << 2) | 0x03; // osrs_t = x16, osrs_p = x16, normal mode
    result = i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, ctrl_meas);
    if (result < 0) {
        fprintf(stderr, "Error writing ctrl_meas register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read temperature and pressure data from BMP280
int read_bmp280_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    uint8_t buffer[6];
    int result;

    // Read pressure and temperature data
    result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    *pressure = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    *temperature = ((int32_t)buffer[3] << 12) | ((int32_t)buffer[4] << 4) | ((int32_t)buffer[5] >> 4);

    return 0;
}

// Compensate temperature
double compensate_temperature(int32_t adc_T, struct bmp280_calib_data calib) {
    double var1, var2, T;
    double T1 = (double)calib.dig_T1;
    double T2 = (double)calib.dig_T2;
    double T3 = (double)calib.dig_T3;

    var1 = (((double)adc_T) / 16384.0 - T1 / 1024.0) * T2;
    var2 = ((((double)adc_T) / 131072.0 - T1 / 8192.0) * (((double)adc_T) / 131072.0 - T1 / 8192.0)) * T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double compensate_pressure(int32_t adc_P, struct bmp280_calib_data calib, double t_fine) {
    double var1, var2, p;
    double P1 = (double)calib.dig_P1;
    double P2 = (double)calib.dig_P2;
    double P3 = (double)calib.dig_P3;
    double P4 = (double)calib.dig_P4;
    double P5 = (double)calib.dig_P5;
    double P6 = (double)calib.dig_P6;
    double P7 = (double)calib.dig_P7;
    double P8 = (double)calib.dig_P8;
    double P9 = (double)calib.dig_P9;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * P6 / 32768.0;
    var2 = var2 + var1 * P5 * 2.0;
    var2 = (var2 / 4.0) + (P4 * 65536.0);
    var1 = (P3 * var1 * var1 / 524288.0 + P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = P9 * p * p / 2147483648.0;
    var2 = p * P8 / 32768.0;
    p = p + (var1 + var2 + P7) / 16.0;

    return p / 100.0; // in hPa
}

// Write data to file
int write_data_to_file(FILE *fp, double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        i2c_handle = i2cOpen(1, BMP280_I2C_ADDR_ALT, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C bus with alternative address: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }
    }

    // Initialize BMP280 sensor
    if (init_bmp280(i2c_handle, &calib) != 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen("weather_data.txt", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_bmp280_data(i2c_handle, &raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature, calib);
            pressure = compensate_pressure(raw_pressure, calib, temperature);

            // Write data to file
            if (write_data_to_file(data_file, temperature, pressure) != 0) {
                fprintf(stderr, "Error writing data to file\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(data_file);
    gpioTerminate();

    return 0;
}

