#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define ALERT_GPIO 18
#define TEMP_THRESHOLD 28.0
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
pthread_mutex_t buffer_mutex;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
double read_temperature();
void update_buffer(double temperature);
double calculate_average();
void *alert_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from LM75 sensor
double read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -100.0; // Indicate error
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits

    double temperature = raw_temp * 0.125;
    return temperature;
}

// Function to update the circular buffer
void update_buffer(double temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the running average
double calculate_average() {
    double sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

// Alert thread function
void *alert_thread(void *arg) {
    while (program_running) {
        double average_temp = calculate_average();
        if (average_temp > TEMP_THRESHOLD) {
            gpioWrite(ALERT_GPIO, 1); // Turn LED on
        } else {
            gpioWrite(ALERT_GPIO, 0); // Turn LED off
        }
        sleep(1); // Check every second
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    pthread_mutex_destroy(&buffer_mutex);
    gpioWrite(ALERT_GPIO, 0); // Turn off LED
    gpioSetMode(ALERT_GPIO, PI_INPUT); // Set back to input
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize temperature buffer with 0.0
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Create alert thread
    pthread_t alert_thread_id;
    if (pthread_create(&alert_thread_id, NULL, alert_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create alert thread\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        double temperature = read_temperature();
        if (temperature > -99.0) { // Check for valid temperature reading
            update_buffer(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                program_running = 0; // Exit loop if re-initialization fails
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Wait for alert thread to finish
    pthread_join(alert_thread_id, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

