#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define RTD_NOMINAL_RESISTANCE 100.0
#define RTD_REFERENCE_RESISTANCE 430.0
#define MAX_TEMPERATURE 80.0
#define CONFIG_FILE "config.json"
#define LOG_FILE "error.log"

// Global variables
int spi_handle;
double target_temperature = 25.0;
double Kp = 1.0;
double Ki = 0.1;
double Kd = 0.01;
double integral = 0.0;
double previous_error = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename);
int initialize_spi();
double read_rtd_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_pwm_duty_cycle(double duty_cycle);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from JSON file
int read_config(const char *filename) {
    json_t *root, *target, *kp, *ki, *kd;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    target = json_object_get(root, "target_temperature");
    kp = json_object_get(root, "Kp");
    ki = json_object_get(root, "Ki");
    kd = json_object_get(root, "Kd");

    if (target && json_is_real(target)) {
        target_temperature = json_real_value(target);
    } else {
        fprintf(stderr, "Warning: target_temperature not found or invalid, using default: %.2f\n", target_temperature);
    }

    if (kp && json_is_real(kp)) {
        Kp = json_real_value(kp);
    } else {
        fprintf(stderr, "Warning: Kp not found or invalid, using default: %.2f\n", Kp);
    }

    if (ki && json_is_real(ki)) {
        Ki = json_real_value(ki);
    } else {
        fprintf(stderr, "Warning: Ki not found or invalid, using default: %.2f\n", Ki);
    }

    if (kd && json_is_real(kd)) {
        Kd = json_real_value(kd);
    } else {
        fprintf(stderr, "Warning: Kd not found or invalid, using default: %.2f\n", Kd);
    }

    json_decref(root);
    return 0;
}

// Function to initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read RTD temperature from MAX31865
double read_rtd_temperature() {
    unsigned char buffer[5];
    int i;

    // Read 5 bytes from SPI
    if (spiRead(spi_handle, buffer, 5) != 5) {
        log_error("SPI read failed");
        return -1000.0; // Indicate error
    }

    // Check for fault
    if (buffer[3] & 0x01) {
        log_error("MAX31865 fault detected");
        return -1000.0; // Indicate error
    }

    // Extract RTD value (bytes 1 and 2)
    int rtd_raw = ((buffer[1] << 8) | buffer[2]) >> 1;

    // Convert RTD value to temperature (PT100)
    double rtd_resistance = ((double)rtd_raw / 32768.0) * RTD_REFERENCE_RESISTANCE;
    double temperature = (rtd_resistance - RTD_NOMINAL_RESISTANCE) / 0.385;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp output to 0-100%
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * PWM_RANGE / 100.0);
    gpioPWM(PWM_GPIO, pwm_value);
}

// Function to log errors to file
void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] Error: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        fprintf(stderr, "Error: Could not open log file for writing\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    set_pwm_duty_cycle(0.0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM GPIO as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Read configuration from file
    if (read_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Error: Could not read configuration file, using defaults\n");
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature from RTD
        double temperature = read_rtd_temperature();
        if (temperature < -999.0) {
            log_error("Failed to read temperature, exiting");
            break;
        }

        // Calculate PID output
        double pid_output = calculate_pid(target_temperature, temperature);

        // Set PWM duty cycle
        set_pwm_duty_cycle(pid_output);

        // Check for failsafe conditions
        if (temperature > MAX_TEMPERATURE) {
            log_error("Temperature exceeds maximum limit, shutting down heater");
            set_pwm_duty_cycle(0.0);
            break;
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

