int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    ac1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    b2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    mb = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    mc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    md = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == PI_BAD_I2C_ADDR || ac2 == PI_BAD_I2C_ADDR || ac3 == PI_BAD_I2C_ADDR ||
