    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    retries = 0;
    while (init_i2c() != 0 && retries < 3) {
        fprintf(stderr, "I2C initialization failed, retrying... (%d/3)\n", retries + 1);
        retries++;
        gpioDelay(1000000); // Wait 1 second before retrying
    }
    if (retries == 3) {
        fprintf(stderr, "I2C initialization failed after multiple retries\n");
        cleanup();
        return 1;
    }

    // Read calibration data
    retries = 0;
    while (read_calibration_data() != 0 && retries < 3) {
        fprintf(stderr, "Calibration data read failed, retrying... (%d/3)\n", retries + 1);
        retries++;
        gpioDelay(1000000); // Wait 1 second before retrying
    }
    if (retries == 3) {
        fprintf(stderr, "Calibration data read failed after multiple retries\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw temperature and pressure
        retries = 0;
        while (read_raw_temperature(&raw_temp) != 0 && retries < 3) {
            fprintf(stderr, "Raw temperature read failed, retrying... (%d/3)\n", retries + 1);
            retries++;
            gpioDelay(1000000); // Wait 1 second before retrying
        }
        if (retries == 3) {
            fprintf(stderr, "Raw temperature read failed after multiple retries\n");
            break;
        }

        retries = 0;
        while (read_raw_pressure(&raw_pressure) != 0 && retries < 3) {
            fprintf(stderr, "Raw pressure read failed, retrying... (%d/3)\n", retries + 1);
            retries++;
            gpioDelay(1000000); // Wait 1 second before retrying
        }
        if (retries == 3) {
            fprintf(stderr, "Raw pressure read failed after multiple retries\n");
            break;
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);

        // Check for breaches
        if (temperature > 30.0 || pressure < 950.0) {
            log_breach(temperature, pressure);
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

