    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Keep the program running
    while (1) {
        sleep(1);
    }

    return 0;
}

int read_calibration_data() {
    ac1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B1);
    b2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B2);
    mb = read_i2c_word(i2c_handle, BMP180_REG_CAL_MB);
    mc = read_i2c_word(i2c_handle, BMP180_REG_CAL_MC);
    md = read_i2c_word(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        return -1;
    }

    return 0;
}

int read_raw_temperature(int *raw_temperature) {
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms

    *raw_temperature = read_i2c_word(i2c_handle, BMP180_REG_MSB);
    if (*raw_temperature == -1) {
        return -1;
    }

    return 0;
}

int read_raw_pressure(int *raw_pressure) {
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait for conversion

    char data[3];
    if (i2cWriteDevice(i2c_handle, (char[]){BMP180_REG_MSB}, 1) != 0) {
        fprintf(stderr, "Error writing register address for pressure read.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading pressure data.\n");
        return -1;
    }

    *raw_pressure = ((unsigned long)data[0] << 16 | (unsigned long)data[1] << 8 | (unsigned long)data[2]) >> (8 - BMP180_OSS);

    return 0;
}

float calculate_temperature(int raw_temperature) {
    long x1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    float temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

float calculate_pressure(int raw_pressure, int raw_temperature) {
    long x1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)ac2 * b6) / pow(2, 11);
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) / 4;

    unsigned long x1_pressure = ((long)ac3 * b6) / pow(2, 13);
    unsigned long x2_pressure = ((long)b1 * (b6 * b6) / pow(2, 12)) / pow(2, 16);
    unsigned long b4 = x1_pressure + x2_pressure + 32768;

    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (x1 + x2 + 3791) / pow(2, 4);

    return pressure;
}

void timer_callback() {
    int raw_temperature, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0) {
        temperature = calculate_temperature(raw_temperature);
    } else {
        fprintf(stderr, "Error reading raw temperature in timer callback\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) == 0) {
        pressure = calculate_pressure(raw_pressure, raw_temperature);
    } else {
        fprintf(stderr, "Error reading raw pressure in timer callback\n");
        return;
    }

    time_t now = time(NULL);
    sensor_data_t data = {now, temperature, pressure};
    add_to_buffer(data);

    printf("Timestamp: %ld, Temperature: %.2f °C, Pressure: %.2f Pa\n", now, temperature, pressure);

    // Control fan based on temperature
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

void add_to_buffer(sensor_data_t data) {
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

sensor_data_t get_latest_reading() {
    int index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return circular_buffer[index];
}

