#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define HEATER_GPIO 17
#define PWM_FREQUENCY 1000 // 1 kHz
#define MAX_DUTY_CYCLE 80.0
#define DEFAULT_TARGET_TEMP 25.0
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
double target_temperature = DEFAULT_TARGET_TEMP;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_max31855(double *thermocouple_temp, double *internal_temp);
double calculate_pi_control(double current_temperature, double target_temperature, double last_error, double *integral);
void set_heater_duty_cycle(double duty_cycle);
void log_data(double thermocouple_temp, double internal_temp, double duty_cycle);
void signal_handler(int signal);
void cleanup();

// PI controller parameters
double Kp = 1.0;
double Ki = 0.1;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
        printf("Target temperature set to: %.2f °C\n", target_temperature);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for heater control
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Thermocouple Temperature (C),Internal Temperature (C),Duty Cycle (%)\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    double thermocouple_temp, internal_temp;
    double last_error = 0.0;
    double integral = 0.0;
    double duty_cycle;

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(&thermocouple_temp, &internal_temp) != 0) {
            fprintf(stderr, "Error reading temperature, setting duty cycle to 0\n");
            duty_cycle = 0.0;
        } else {
            // Calculate PI control
            duty_cycle = calculate_pi_control(thermocouple_temp, target_temperature, last_error, &integral);

            // Limit duty cycle to maximum
            if (duty_cycle > MAX_DUTY_CYCLE) {
                duty_cycle = MAX_DUTY_CYCLE;
            }
            if (duty_cycle < 0.0) {
                duty_cycle = 0.0;
            }
        }

        // Set heater duty cycle
        set_heater_duty_cycle(duty_cycle);

        // Log data
        log_data(thermocouple_temp, internal_temp, duty_cycle);

        // Update last error
        last_error = thermocouple_temp - target_temperature;

        // Wait for a short period
        gpioDelay(100); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to read temperature from MAX31855
int read_max31855(double *thermocouple_temp, double *internal_temp) {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1;
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 fault: Open circuit\n");
        return -1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 fault: Short to GND\n");
        return -1;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        return -1;
    }

    // Extract thermocouple temperature
    int16_t thermocouple_raw = ((data[0] << 8) | data[1]) >> 2;
    *thermocouple_temp = thermocouple_raw * 0.25;

    // Extract internal temperature
    int16_t internal_raw = ((data[2] << 8) | data[3]) >> 4;
    *internal_temp = internal_raw * 0.0625;

    return 0;
}

// Function to calculate PI control
double calculate_pi_control(double current_temperature, double target_temperature, double last_error, double *integral) {
    double error = target_temperature - current_temperature;
    *integral += error;

    // Anti-windup
    if (*integral > MAX_DUTY_CYCLE) {
        *integral = MAX_DUTY_CYCLE;
    } else if (*integral < 0.0) {
        *integral = 0.0;
    }

    double output = Kp * error + Ki * (*integral);
    return output;
}

// Function to set heater duty cycle
void set_heater_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 255.0);
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log data
void log_data(double thermocouple_temp, double internal_temp, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, thermocouple_temp, internal_temp, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_duty_cycle(0.0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

