#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds
#define TEMP_BLUE  40000
#define TEMP_GREEN 60000

// Define temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global volatile flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file %s\n", TEMP_FILE);
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: Error occurred while reading temperature file %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to set RGB LED color using pigpio
int set_led_color(int red, int green, int blue)
{
    int result;

    result = gpioPWM(RED_PIN, 255 - red);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set red PWM value: %d\n", result);
        return -1;
    }

    result = gpioPWM(GREEN_PIN, 255 - green);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set green PWM value: %d\n", result);
        return -1;
    }

    result = gpioPWM(BLUE_PIN, 255 - blue);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set blue PWM value: %d\n", result);
        return -1;
    }

    return 0;
}

int main()
{
    int temp;
    int red, green, blue;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error: Failed to read CPU temperature, skipping update\n");
            sleep(0.5);
            continue;
        }

        // Determine LED color based on temperature
        if (temp < TEMP_BLUE) {
            red   = 0;
            green = 0;
            blue  = 255;
        } else if (temp < TEMP_GREEN) {
            red   = 0;
            green = 255;
            blue  = 0;
        } else {
            red   = 255;
            green = 0;
            blue  = 0;
        }

        // Set LED color
        result = set_led_color(red, green, blue);
        if (result != 0) {
            fprintf(stderr, "Error: Failed to set LED color, skipping update\n");
        }

        // Print temperature and LED color values
        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temp, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup
    result = set_led_color(255, 255, 255); // Turn off LED
    if (result != 0) {
        fprintf(stderr, "Error: Failed to turn off LED during cleanup\n");
    }

    gpioTerminate();

    return 0;
}

