#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "http://yourserver.com/api/humidity"

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read DHT22 data
int read_dht22(DHT22Data *data) {
    int i, j;
    int data_bits[40];
    int pulse_lengths[85]; // 40 data bits * 2 pulses/bit + initial setup
    int start_seconds, start_micros;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1 ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30 us
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Measure pulse lengths
    gpioTime(0, &start_seconds, &start_micros);
    for (i = 0; i < 85; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1); // Check every microsecond
            if (count > 200) { // Timeout after 200 us
                fprintf(stderr, "DHT22 timeout waiting for pulse %d\n", i);
                gpioTerminate();
                return -1;
            }
        }
        gpioTime(0, &start_seconds, &start_micros);
        pulse_lengths[i] = start_seconds * 1000000 + start_micros - (start_seconds * 1000000 + start_micros);
    }

    // Decode data bits
    for (i = 0; i < 40; i++) {
        int index = 2 * i + 1; // Skip the initial low pulse
        data_bits[i] = (pulse_lengths[index] > 40); // 40 us threshold
    }

    // Calculate checksum
    int checksum = 0;
    for (i = 0; i < 32; i++) {
        checksum += data_bits[i];
    }
    checksum &= 0xFF;

    // Verify checksum
    int received_checksum = 0;
    for (i = 32; i < 40; i++) {
        received_checksum = (received_checksum << 1) | data_bits[i];
    }

    if (checksum != received_checksum) {
        fprintf(stderr, "DHT22 checksum error: calculated = %d, received = %d\n", checksum, received_checksum);
        gpioTerminate();
        return -1;
    }

    // Convert data to temperature and humidity
    int humidity_int = 0;
    for (i = 0; i < 16; i++) {
        humidity_int = (humidity_int << 1) | data_bits[i];
    }

    int temperature_int = 0;
    for (i = 16; i < 32; i++) {
        temperature_int = (temperature_int << 1) | data_bits[i];
    }

    data->humidity = (float)humidity_int / 10.0;
    data->temperature = (float)temperature_int / 10.0;

    gpioTerminate();
    return 0;
}

// Function to format data as JSON
char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    sprintf(json_string, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to send data to the server
int send_data(const char *json_string) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code != 200) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main() {
    DHT22Data dht22_data;
    char *json_string;
    int retries;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_dht22(&dht22_data) == 0) {
                // Data read successfully, format JSON and send
                json_string = format_json(dht22_data.temperature, dht22_data.humidity);
                if (json_string != NULL) {
                    if (send_data(json_string) == 0) {
                        printf("Data sent successfully: %s\n", json_string);
                    } else {
                        fprintf(stderr, "Failed to send data, retrying...\n");
                    }
                    free(json_string);
                } else {
                    fprintf(stderr, "Failed to format JSON, retrying...\n");
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Failed to read DHT22 data, retrying...\n");
                retries++;
                sleep(1); // Wait before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read DHT22 data after %d retries\n", MAX_RETRIES);
        }

        sleep(60); // Wait 60 seconds before next reading
    }

    // Cleanup
    gpioTerminate();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

