    mb = read_int16(BMP180_REG_CAL_MB);
    mc = read_int16(BMP180_REG_CAL_MC);
    md = read_int16(BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        return 1;
    }

    return 0;
}

// Read raw temperature value from BMP180
int read_raw_temperature(int32_t *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return 1;
    }

    gpioDelay(CONVERSION_DELAY); // Wait for conversion

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return 1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Read raw pressure value from BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return 1;
    }

    gpioDelay(CONVERSION_DELAY); // Wait for conversion

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return 1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate pressure in hPa using the full BMP180 compensation algorithm
double calculate_pressure(int32_t raw_temperature, int32_t raw_pressure)
{
    int32_t X1, X2, X3, B3, B5, B6, B7, p;
    uint32_t B4;

    // Temperature calculations
    X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    B5 = X1 + X2;
    double T = (B5 + 8) / pow(2, 4);

    // Pressure calculations
    B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6 / pow(2, 12))) / pow(2, 11);
    X2 = ac2 * B6 / pow(2, 11);
    X3 = X1 + X2;
    B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) / 4;
    X1 = ac3 * B6 / pow(2, 13);
    X2 = (b1 * (B6 * B6 / pow(2, 12))) / pow(2, 16);
    X3 = ((X1 + X2) + 2) / pow(2, 2);
    B4 = (ac4 * (uint32_t)(X3 + 32768)) / pow(2, 15);
    B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (X1 + X2 + 3791) / pow(2, 4);

    return pressure / 100.0; // Convert to hPa
}

// Interrupt handler for push-button
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    uint32_t current_time = tick;

    // Debounce
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        if (logging_enabled) {
            printf("Data logging enabled\n");
        } else {
            printf("Data logging disabled\n");
        }
        last_interrupt_time = current_time;
    }
}

