#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <pigpio.h>

// Constants
#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define POLL_INTERVAL_SEC 5

// Global variables
static volatile int running = 1;
static int max_fan_state = 0;

// Function prototypes
int read_cpu_temp();
int read_fan_state();
int write_fan_state(int state);
int set_fan_speed(int temperature);
void log_message(const char *message);
void signal_handler(int signal);
int get_max_fan_state();

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        running = 0;
        log_message("Received shutdown signal. Shutting down...");
        set_fan_speed(0); // Set fan to 0% on shutdown
        gpioTerminate();
        closelog();
        exit(0);
    }
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temperature = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(CPU_TEMP_FILE, "r");
        if (fp == NULL) {
            log_message("Error opening CPU temperature file.");
            perror("fopen");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) != NULL) {
            temperature = atoi(buffer) / 1000; // Convert to Celsius
        } else {
            log_message("Error reading CPU temperature.");
            perror("fgets");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            fclose(fp);
            continue;
        }

        fclose(fp);
        return temperature;
    }

    log_message("Failed to read CPU temperature after multiple retries.");
    return -1; // Indicate error
}

// Function to read fan state from file
int read_fan_state() {
    FILE *fp;
    char buffer[10];
    int state = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(FAN_STATE_FILE, "r");
        if (fp == NULL) {
            log_message("Error opening fan state file.");
            perror("fopen");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) != NULL) {
            state = atoi(buffer);
        } else {
            log_message("Error reading fan state.");
            perror("fgets");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            fclose(fp);
            continue;
        }

        fclose(fp);
        return state;
    }

    log_message("Failed to read fan state after multiple retries.");
    return -1; // Indicate error
}

// Function to write fan state to file
int write_fan_state(int state) {
    FILE *fp;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(FAN_STATE_FILE, "w");
        if (fp == NULL) {
            log_message("Error opening fan state file for writing.");
            perror("fopen");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (fprintf(fp, "%d", state) < 0) {
            log_message("Error writing fan state.");
            perror("fprintf");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            fclose(fp);
            continue;
        }

        fclose(fp);
        return 0; // Success
    }

    log_message("Failed to write fan state after multiple retries.");
    return -1; // Indicate error
}

// Function to set fan speed based on temperature
int set_fan_speed(int temperature) {
    int current_state = read_fan_state();
    if (current_state == -1) {
        log_message("Failed to read current fan state.");
        return -1;
    }

    int new_state;
    if (temperature < 45) {
        new_state = 0;
    } else if (temperature < 55) {
        new_state = 1;
    } else if (temperature < 65) {
        new_state = 2;
    } else {
        new_state = 3;
    }

    if (new_state > max_fan_state) {
        new_state = max_fan_state;
    }

    if (new_state != current_state) {
        if (write_fan_state(new_state) == 0) {
            char message[100];
            snprintf(message, sizeof(message), "Fan speed changed to state %d (Temperature: %d°C)", new_state, temperature);
            log_message(message);
        } else {
            log_message("Failed to write new fan state.");
            return -1;
        }
    }
    return 0;
}

// Function to log messages to syslog
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_entry[200];
    snprintf(log_entry, sizeof(log_entry), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_entry);
}

// Function to get the maximum fan state
int get_max_fan_state() {
    FILE *fp;
    char buffer[10];
    int state = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen("/sys/class/thermal/cooling_device0/max_state", "r");
        if (fp == NULL) {
            log_message("Error opening max_state file.");
            perror("fopen");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) != NULL) {
            state = atoi(buffer);
        } else {
            log_message("Error reading max_state.");
            perror("fgets");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            fclose(fp);
            continue;
        }

        fclose(fp);
        return state;
    }

    log_message("Failed to read max_state after multiple retries.");
    return 0; // Default to 0 if unable to read
}

int main() {
    // Initialize syslog
    openlog("fan_control", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Get the maximum fan state
    max_fan_state = get_max_fan_state();
    char message[100];
    snprintf(message, sizeof(message), "Maximum fan state: %d", max_fan_state);
    log_message(message);

    // Main loop
    while (running) {
        int temperature = read_cpu_temp();
        if (temperature != -1) {
            set_fan_speed(temperature);
        } else {
            log_message("Failed to read CPU temperature.");
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_fan_speed(0);
    gpioTerminate();
    closelog();
    return 0;
}

