    while (retries < MAX_RETRIES) {
        fp = fopen(FAN_STATE_FILE, "w");
        if (fp == NULL) {
            log_message("Error opening fan state file for writing.");
            perror("fopen");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (fprintf(fp, "%d", state) < 0) {
            log_message("Error writing fan state.");
            perror("fprintf");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            fclose(fp);
            continue;
        }

        fclose(fp);
        return 0; // Success
    }

    log_message("Failed to write fan state after multiple retries.");
    return -1; // Indicate error
}

// Function to set fan speed based on temperature
int set_fan_speed(int temperature) {
    int current_state = read_fan_state();
    if (current_state == -1) {
        log_message("Failed to read current fan state.");
        return -1;
    }

    int new_state;
    if (temperature < 45) {
        new_state = 0;
    } else if (temperature < 55) {
        new_state = 1;
    } else if (temperature < 65) {
        new_state = 2;
    } else {
        new_state = 3;
    }

    if (new_state > max_fan_state) {
        new_state = max_fan_state;
    }

    if (new_state != current_state) {
        if (write_fan_state(new_state) == 0) {
            char message[100];
            snprintf(message, sizeof(message), "Fan speed changed to state %d (Temperature: %d°C)", new_state, temperature);
            log_message(message);
        } else {
            log_message("Failed to write new fan state.");
            return -1;
        }
    }
    return 0;
}

