    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_entry[200];
    snprintf(log_entry, sizeof(log_entry), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_entry);
}

// Function to get the maximum fan state
int get_max_fan_state() {
    FILE *fp;
    char buffer[10];
    int state = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen("/sys/class/thermal/cooling_device0/max_state", "r");
        if (fp == NULL) {
            log_message("Error opening max_state file.");
            perror("fopen");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) != NULL) {
            state = atoi(buffer);
        } else {
            log_message("Error reading max_state.");
            perror("fgets");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            fclose(fp);
            continue;
        }

        fclose(fp);
        return state;
    }

    log_message("Failed to read max_state after multiple retries.");
    return 0; // Default to 0 if unable to read
}

int main() {
    // Initialize syslog
    openlog("fan_control", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Get the maximum fan state
    max_fan_state = get_max_fan_state();
    char message[100];
    snprintf(message, sizeof(message), "Maximum fan state: %d", max_fan_state);
    log_message(message);

    // Main loop
    while (running) {
        int temperature = read_cpu_temp();
        if (temperature != -1) {
            set_fan_speed(temperature);
        } else {
            log_message("Failed to read CPU temperature.");
        }

