#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000000 // pigpio range is 0-1000000
#define TARGET_TEMPERATURE 50.0
#define LOG_FILE "heater_log.txt"

// PID Gains
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

// Failsafe Limits
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double Kp = DEFAULT_KP;
static double Ki = DEFAULT_KI;
static double Kd = DEFAULT_KD;
static double integral = 0.0;
static double previous_error = 0.0;

// Function Prototypes
double read_temperature();
void set_pwm_duty_cycle(int duty_cycle);
double calculate_pid(double current_temperature);
void log_data(double temperature, int duty_cycle, double pid_output);
void handle_fault(uint16_t fault_data);
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Function to read temperature from MAX31855
double read_temperature() {
    char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -273.15; // Return absolute zero on error
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = raw_temp * 0.25;

    // Extract fault data (bits 15:0)
    uint16_t fault_data = ((buffer[2] << 8) | buffer[3]) & 0xFFFF;

    if (fault_data != 0) {
        handle_fault(fault_data);
        return -273.15; // Return absolute zero on fault
    }

    return temperature;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    int pwm_value = (int)((double)duty_cycle / 100.0 * PWM_RANGE);
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = TARGET_TEMPERATURE - current_temperature;

    integral += error;
    if (integral > 100) integral = 100; // Clamp integral term
    if (integral < -100) integral = -100;

    double derivative = error - previous_error;

    double output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    return output;
}

// Function to log data to file
void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle MAX31855 faults
void handle_fault(uint16_t fault_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "%s, Fault detected: 0x%04X\n", timestamp, fault_data);
    fprintf(log_file, "%s, Fault detected: 0x%04X\n", timestamp, fault_data);
    fflush(log_file);

    if (fault_data & 0x0001) {
        fprintf(stderr, "%s, Open circuit fault!\n", timestamp);
        fprintf(log_file, "%s, Open circuit fault!\n", timestamp);
    }
    if (fault_data & 0x0002) {
        fprintf(stderr, "%s, Short to GND fault!\n", timestamp);
        fprintf(log_file, "%s, Short to GND fault!\n", timestamp);
    }
    if (fault_data & 0x0004) {
        fprintf(stderr, "%s, Short to VCC fault!\n", timestamp);
        fprintf(log_file, "%s, Short to VCC fault!\n", timestamp);
    }

    // Disable heater and reset PID state
    set_pwm_duty_cycle(0);
    integral = 0.0;
    previous_error = 0.0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-p") == 0 && i + 1 < argc) {
            Kp = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            Ki = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            Kd = atof(argv[i + 1]);
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-p Kp] [-i Ki] [-d Kd]\n", argv[0]);
            exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature control started. Target temperature: %.2f\u00b0C\n", TARGET_TEMPERATURE);
    printf("Kp: %.2f, Ki: %.2f, Kd: %.2f\n", Kp, Ki, Kd);

    // Main loop
    while (running) {
        double temperature = read_temperature();

        if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
            fprintf(stderr, "Temperature out of range: %.2f\u00b0C. Disabling heater.\n", temperature);
            fprintf(log_file, "Temperature out of range: %.2f\u00b0C. Disabling heater.\n", temperature);
            set_pwm_duty_cycle(0);
            running = 0; // Exit loop
        } else {
            double pid_output = calculate_pid(temperature);
            int duty_cycle = (int)pid_output;

            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > 100) duty_cycle = 100;

            set_pwm_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle, pid_output);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_pwm_duty_cycle(0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

