#include <pigpio.h>
#include <string.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

float read_cpu_temperature() {
    FILE *fp;
    char buffer[10];
    float temperature = -1.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000.0;
    }

    fclose(fp);
    return temperature;
}

int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 100);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_cpu_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature, using default value 40.0\n");
            temperature = 40.0;
        }

        int duty_cycle;
        if (temperature <= 40.0) {
            duty_cycle = 0;
        } else if (temperature >= 70.0) {
            duty_cycle = 100;
        } else {
            duty_cycle = (int)(((temperature - 40.0) / (70.0 - 40.0)) * 100.0);
        }

        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_cycle);
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    set_fan_speed(0);
    gpioTerminate();
    printf("Fan control program terminated.\n");
    return 0;
}

