            duty_cycle = 0;
        } else if (temperature >= 70.0) {
            duty_cycle = 100;
        } else {
            duty_cycle = (int)(((temperature - 40.0) / (70.0 - 40.0)) * 100.0);
        }

        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_cycle);
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    set_fan_speed(0);
    gpioTerminate();
    printf("Fan control program terminated.\n");
    return 0;
}

