    printf("Received signal %d, terminating...\n", signal);
}

// Function to read data from a sensor with retries
int read_sensor(int i2c_handle, unsigned char *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result == 3) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

