                flow1 = convert_flow(sensor1_data);
            } else {
                fprintf(stderr, "CRC check failed for sensor 1\n");
                flow1 = -1.0; // Indicate invalid reading
            }
        } else {
            flow1 = -1.0; // Indicate invalid reading
        }

        // Read sensor 2
        if (read_sensor(i2c_handle2, sensor2_data) == 0) {
            // Validate CRC
            if (crc8(sensor2_data, 2) == sensor2_data[2]) {
                flow2 = convert_flow(sensor2_data);
            } else {
                fprintf(stderr, "CRC check failed for sensor 2\n");
                flow2 = -1.0; // Indicate invalid reading
            }
        } else {
            flow2 = -1.0; // Indicate invalid reading
        }

        // Log data if both readings are valid
        if (flow1 >= 0.0 && flow2 >= 0.0) {
            log_flow_data(flow1, flow2);
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

