#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_encoder();
float calculate_angle(int state);
int log_position(float angle);
void signal_handler(int signal);

// Quadrature state machine states
enum {
    STATE_00 = 0,
    STATE_01 = 1,
    STATE_11 = 2,
    STATE_10 = 3
};

// Quadrature state machine transition table
int next_state[4][2] = {
    {STATE_01, STATE_10}, // Current state: 00
    {STATE_00, STATE_11}, // Current state: 01
    {STATE_11, STATE_01}, // Current state: 11
    {STATE_10, STATE_00}  // Current state: 10
};

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);

    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the current state of the encoder
int read_encoder() {
    int a = gpioRead(ENCODER_A_PIN);
    int b = gpioRead(ENCODER_B_PIN);

    if (a == PI_HIGH && b == PI_LOW) return 0;
    if (a == PI_LOW && b == PI_LOW) return 1;
    if (a == PI_LOW && b == PI_HIGH) return 2;
    if (a == PI_HIGH && b == PI_HIGH) return 3;

    return -1; // Error: Invalid state
}

// Function to calculate the angle from the encoder state
float calculate_angle(int state) {
    return (float)state * 90.0;
}

// Function to log the angle to a file
int log_position(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Angle: %.2f\n", timestamp, angle);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int current_state = STATE_00;
    int previous_state = STATE_00;
    float angle = 0.0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int encoder_state = read_encoder();

        if (encoder_state != -1) {
            current_state = next_state[previous_state][encoder_state];

            if (current_state != previous_state) {
                angle = calculate_angle(current_state);
                if (log_position(angle) != 0) {
                    fprintf(stderr, "Error logging position.\n");
                }
                previous_state = current_state;
            }
        } else {
            fprintf(stderr, "Error reading encoder state.\n");
        }

        gpioDelay(1000); // Delay for 1 millisecond
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

