#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adpd144ri_init();
int adpd144ri_read_data(int *red, int *ir);
void log_data(int red, int ir);
void control_led(int ir);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int red;
    int ir;
} sensor_data_t;

// Function to initialize the ADPD144RI sensor
int adpd144ri_init() {
    // Example initialization sequence (replace with actual datasheet values)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) { // Example register and value
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Small delay after write
    if (i2cWriteByteData(i2c_handle, 0x01, 0x02) < 0) { // Example register and value
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Small delay after write

    return 0;
}

// Function to read data from the ADPD144RI sensor
int adpd144ri_read_data(int *red, int *ir) {
    char buffer[4]; // Assuming 2 bytes for red and 2 for IR

    if (i2cReadI2CBlockData(i2c_handle, 0x02, buffer, 4) != 4) { // Example register
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Convert the raw data to integers (adjust based on sensor's data format)
    *red = (buffer[0] << 8) | buffer[1];
    *ir = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Function to log data to a CSV file
void log_data(int red, int ir) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the LED based on the IR value
void control_led(int ir) {
    if (ir > IR_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (adpd144ri_init() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int red, ir;

    // Main loop
    while (!terminate) {
        if (adpd144ri_read_data(&red, &ir) == 0) {
            log_data(red, ir);
            control_led(ir);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

