#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t mutex;
FILE *log_file = NULL;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user);
void *rpm_calculator_thread(void *arg);
void signal_handler(int signal);

// Interrupt service routine (ISR)
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&mutex);
        pulse_count++;
        pthread_mutex_unlock(&mutex);
    }
}

// RPM calculation thread
void *rpm_calculator_thread(void *arg) {
    while (1) {
        sleep(1);

        pthread_mutex_lock(&mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&mutex);

        double rpm = (double)current_pulse_count * 60.0;

        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (log_file != NULL) {
            fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm);
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Disable interrupt
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register interrupt service routine
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Create RPM calculation thread
    pthread_t rpm_thread;
    if (pthread_create(&rpm_thread, NULL, rpm_calculator_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create RPM calculation thread\n");
        gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
        fclose(log_file);
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop (keep the program running)
    while (1) {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

