#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int configure_gpio();
int detect_rising_edge();
int log_event(int level);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int last_state;
} ProgramState;

ProgramState state = {0}; // Initialize last_state to 0

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to configure GPIO pins
int configure_gpio() {
    // Set AUDIO_INPUT_PIN as input
    if (gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", AUDIO_INPUT_PIN);
        return 1;
    }

    // Set GAIN_SELECT_PIN as output and set it LOW
    if (gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GAIN_SELECT_PIN);
        return 1;
    }
    if (gpioWrite(GAIN_SELECT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write LOW to GPIO%d\n", GAIN_SELECT_PIN);
        return 1;
    }

    return 0;
}

// Function to detect rising edges on the audio input pin
int detect_rising_edge() {
    int current_state = gpioRead(AUDIO_INPUT_PIN);

    if (current_state == 1 && state.last_state == 0) {
        // Rising edge detected
        state.last_state = current_state;
        return 1;
    } else {
        state.last_state = current_state;
        return 0;
    }
}

// Function to log events to a file
int log_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s %d\n", timestamp, level);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
