#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASUREMENT_INTERVAL_MS 1000
#define FLOW_LOG_FILE "flow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_flow_rate(uint16_t *raw_flow_rate);
uint8_t calculate_crc(uint8_t data[], int len);
float convert_to_uL_min(uint16_t raw_flow_rate);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Flow rate reading function
int read_flow_rate(uint16_t *raw_flow_rate) {
    char buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    uint8_t data[2] = {buf[0], buf[1]};
    uint8_t crc = buf[2];

    if (calculate_crc(data, 2) != crc) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *raw_flow_rate = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Flow rate conversion function
float convert_to_uL_min(uint16_t raw_flow_rate) {
    // Assuming a linear relationship for simplicity.
    // Adjust the scaling factor as needed based on the sensor's datasheet.
    return (float)raw_flow_rate * 0.01; // Example scaling factor
}

// Logging function
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t raw_flow_rate;
    float flow_rate_uL_min;

    // Main loop
    while (!terminate) {
        if (read_flow_rate(&raw_flow_rate) == 0) {
            flow_rate_uL_min = convert_to_uL_min(raw_flow_rate);
            log_flow_rate(flow_rate_uL_min);
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

