// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int calculate_iaq_index(uint16_t tvoc, uint16_t eco2, int *iaq_index);
int log_data(int iaq_index, uint16_t tvoc, uint16_t eco2);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the MICS-VZ-89TE
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result;

    // Read 4 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract TVOC and eCO2 values from the buffer
    data->tvoc = (buf[0] << 8) | buf[1];
    data->eco2 = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to calculate the IAQ index
int calculate_iaq_index(uint16_t tvoc, uint16_t eco2, int *iaq_index) {
    // Simple IAQ index calculation (replace with actual formula from datasheet)
    *iaq_index = (tvoc / 10) + (eco2 / 100);
    return 0;
}

// Function to log data to a CSV file
int log_data(int iaq_index, uint16_t tvoc, uint16_t eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open the log file in append mode
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Write data to the log file
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, iaq_index, tvoc, eco2);

    // Close the log file
    fclose(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int iaq_index;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate IAQ index
            if (calculate_iaq_index(sensor_data.tvoc, sensor_data.eco2, &iaq_index) == 0) {
                // Log data
                if (log_data(iaq_index, sensor_data.tvoc, sensor_data.eco2) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error calculating IAQ index\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_DURATION);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

