#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define TAMPER_DURATION_SEC 5

static volatile int running = 1;
static int gpio_initialized = 0;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec start_time, current_time;
    int sensor_value;
    int tamper_detected = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    gpio_initialized = 1;

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Monitoring GPIO %d...\n", GPIO_PIN);

    while (running) {
        // Read sensor value
        sensor_value = gpioRead(GPIO_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (sensor_value == 1) {
            if (!tamper_detected) {
                // Start timer
                if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                    fprintf(stderr, "Failed to get start time: %s\n", strerror(errno));
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
                tamper_detected = 1;
            } else {
                // Check timer
                if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                    fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
                    gpioTerminate();
                    return EXIT_FAILURE;
