#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Constants
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define SAMPLE_SIZE 2 // 16-bit PCM
#define GPIO_CHANNEL_SELECT 17
#define CAPTURE_DURATION 60 // seconds
#define FILENAME "audio_capture.pcm"

// Global variables
snd_pcm_t *pcm_handle;
FILE *output_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int init_gpio(int gpio_pin);
int capture_audio(snd_pcm_t *pcm_handle, FILE *output_file, int gpio_pin);
void signal_handler(int sig);
void cleanup(snd_pcm_t *pcm_handle, FILE *output_file);

// Signal handler for graceful termination
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize ALSA for I2S capture
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Initialize GPIO for channel selection
int init_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0); // Initially select left channel

    return 0;
}

// Capture audio data and write to file
int capture_audio(snd_pcm_t *pcm_handle, FILE *output_file, int gpio_pin) {
    char *buffer;
    int buffer_size = SAMPLE_RATE * NUM_CHANNELS * SAMPLE_SIZE; // 1 second of audio
    int err;

    buffer = (char *) malloc(buffer_size);
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating buffer\n");
        return -1;
    }

    time_t start_time = time(NULL);
    time_t current_time;

    while (!terminate) {
        err = snd_pcm_readi(pcm_handle, buffer, buffer_size / (NUM_CHANNELS * SAMPLE_SIZE));
        if (err == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(err));
            break;
        } else if (err != buffer_size / (NUM_CHANNELS * SAMPLE_SIZE)) {
            fprintf(stderr, "Short read, read %d frames\n", err);
        } else {
            // Write to file
            if (fwrite(buffer, 1, buffer_size, output_file) != buffer_size) {
                fprintf(stderr, "Error writing to file\n");
                break;
            }
        }

        current_time = time(NULL);
        if (difftime(current_time, start_time) >= CAPTURE_DURATION) {
            break;
        }
    }

    free(buffer);
    return 0;
}

// Cleanup resources
void cleanup(snd_pcm_t *pcm_handle, FILE *output_file) {
    printf("Cleaning up...\n");
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (output_file) {
        fclose(output_file);
    }
    gpioWrite(GPIO_CHANNEL_SELECT, 0); // Set to a safe state
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_CHANNEL_SELECT) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup(pcm_handle, NULL);
        return 1;
    }

    // Open output file
    output_file = fopen(FILENAME, "wb");
    if (output_file == NULL) {
        fprintf(stderr, "Error opening output file\n");
        cleanup(pcm_handle, NULL);
        return 1;
    }

    // Capture audio
    printf("Capturing audio for %d seconds...\n", CAPTURE_DURATION);
    if (capture_audio(pcm_handle, output_file, GPIO_CHANNEL_SELECT) != 0) {
        fprintf(stderr, "Audio capture failed\n");
    }

    // Cleanup
    cleanup(pcm_handle, output_file);

    return 0;
}

