#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define timeout duration (seconds)
#define TIMEOUT_DURATION 5

// Global variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int state);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int flame_detected;
    time_t last_reading_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Log program start
    log_event("Program started");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) {
            // Flame detected
            if (!state.flame_detected) {
                log_event("Flame detected");
                control_fan(1); // Turn on fan
                state.flame_detected = 1;
            }
        } else if (flame_detected == 1) {
            // No flame detected
            if (state.flame_detected) {
                log_event("Flame ended");
                control_fan(0); // Turn off fan
                state.flame_detected = 0;
            }
        } else {
            // Timeout occurred
            log_event("Sensor timeout");
            control_fan(0); // Turn off fan
            state.flame_detected = 0;
        }

        // Check for timeout
        time_t current_time = time(NULL);
        if (state.last_reading_time != 0 && difftime(current_time, state.last_reading_time) > TIMEOUT_DURATION) {
            log_event("Sensor timeout");
            control_fan(0); // Turn off fan
            state.flame_detected = 0;
            state.last_reading_time = 0; // Reset last reading time
        } else if (flame_detected != -1) {
            state.last_reading_time = current_time;
        }

        gpioDelay(50); // 50ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 100); // Set PWM range to 0-100 for percentage control

    return 0;
}

// Read flame sensor with debounce
int read_flame_sensor() {
    int reading1 = gpioRead(FLAME_SENSOR_PIN);
    gpioDelay(25); // 25ms delay
    int reading2 = gpioRead(FLAME_SENSOR_PIN);

    if (reading1 == reading2) {
        return reading1;
    } else {
        return -1; // Indicate invalid reading
    }
}

// Control the fan using PWM
void control_fan(int state) {
    if (state == 1) {
        gpioPWM(FAN_PIN, 50); // 50% duty cycle
    } else {
        gpioPWM(FAN_PIN, 0);  // Turn off fan
    }
}

// Log events to file with ISO 8601 timestamp
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Program interrupted");
}

// Cleanup function to reset GPIO and close log file
void cleanup() {
    control_fan(0); // Turn off fan
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Reset to input
    gpioSetMode(FAN_PIN, PI_INPUT); // Reset to input
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    log_event("Program terminated");
}

