static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 UTC format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the flame state to a file
int log_flame_state(int state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        free(timestamp);
        return -1;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, state) < 0) {
        perror("Failed to write to log file");
        free(timestamp);
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0;
}

int main() {
    int current_state, previous_state = -1; // Initialize to an invalid state

