    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", FLAME_SENSOR_GPIO);
            running = 0; // Exit loop on error
            continue;
        }

        // Check for state change
        if (current_state != previous_state) {
            if (log_flame_state(current_state) != 0) {
                fprintf(stderr, "Failed to log flame state.\n");
