#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.0036
#define RETRY_COUNT 3
#define SLEEP_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor(float *lux);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float lux;
    time_t timestamp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    // Continuous conversion mode, auto full-scale range
    uint16_t config_value = 0xCB10; //0b1100101100010000
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the lux value from the OPT3001 sensor
int read_sensor(float *lux) {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading from result register (attempt %d): %d\n", RETRY_COUNT - retries + 1, result);
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        return -1;
    }

    uint16_t raw_data = (buf[0] << 8) | buf[1];
    uint16_t exponent = (raw_data >> 12) & 0x0F;
    uint16_t result_value = raw_data & 0x0FFF;

    *lux = result_value * (1 << exponent) * LUX_SCALE;
    return 0;
}

// Function to log the lux value to a file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s,%.2f\n", buf, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    // Main loop
    while (!terminate) {
        if (read_sensor(&lux) == 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(SLEEP_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

