#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    struct timespec sleep_time = {1, 0}; // 1 second
    int ret;

    // Register signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line as input with pull-up
    ret = gpiod_line_request_input(line, "flame_detect", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break; // Exit loop on error
        }

        // Get current time
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

        // Print flame detection status
        if (value == 0) {
            printf("%s Flame Detected: YES\n", buf);
        } else {
            printf("%s Flame Detected: NO\n", buf);
        }

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                fprintf(stderr, "nanosleep interrupted by signal\n");
            } else {
                perror("nanosleep");
            }
            break; // Exit loop on error
        }
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

