#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 17
#define CENTER_SENSOR 18
#define RIGHT_SENSOR 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int left_value, center_value, right_value;
    int result;

    // Register signal handlers for graceful shutdown
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    result = gpioSetMode(LEFT_SENSOR, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", LEFT_SENSOR, result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(CENTER_SENSOR, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", CENTER_SENSOR, result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", RIGHT_SENSOR, result);
        gpioTerminate();
        return 1;
    }

    // Main loop to read sensor values
    while (!terminate) {
        // Read the digital values from the sensors
        left_value = gpioRead(LEFT_SENSOR);
        center_value = gpioRead(CENTER_SENSOR);
        right_value = gpioRead(RIGHT_SENSOR);

        // Print the sensor values to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

