#include <string.h>

// Define GPIO pins for each channel
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a single channel
int read_channel(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log the state of all channels
void log_channels(int channel_states[]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: ", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf("%d", channel_states[i]);
    }
    printf("\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(gpio_pins[i], PI_INPUT);
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int channel_states[num_channels];

        // Read the state of each channel
        for (int i = 0; i < num_channels; i++) {
            channel_states[i] = read_channel(gpio_pins[i]);
        }

        // Log the channel states
        log_channels(channel_states);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

