#define CH6 7
#define CH7 8
#define CH8 9

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int i, rc;
    unsigned int tick;
    unsigned int level;
    unsigned int seconds, micros;

    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT) failed");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM) failed");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-down resistors
    gpioSetMode(CH1, PI_INPUT);
    gpioSetPullUpDown(CH1, PI_PUD_DOWN);
    gpioSetMode(CH2, PI_INPUT);
    gpioSetPullUpDown(CH2, PI_PUD_DOWN);
    gpioSetMode(CH3, PI_INPUT);
    gpioSetPullUpDown(CH3, PI_PUD_DOWN);
    gpioSetMode(CH4, PI_INPUT);
    gpioSetPullUpDown(CH4, PI_PUD_DOWN);
    gpioSetMode(CH5, PI_INPUT);
    gpioSetPullUpDown(CH5, PI_PUD_DOWN);
    gpioSetMode(CH6, PI_INPUT);
    gpioSetPullUpDown(CH6, PI_PUD_DOWN);
    gpioSetMode(CH7, PI_INPUT);
    gpioSetPullUpDown(CH7, PI_PUD_DOWN);
    gpioSetMode(CH8, PI_INPUT);
    gpioSetPullUpDown(CH8, PI_PUD_DOWN);

    // Main loop to read sensor data
    while (!terminate) {
        // Read sensor data with a 100ms interval
        rc = gpioTime(PI_TIME_RELATIVE, &seconds, &micros);
        if (rc < 0) {
            fprintf(stderr, "gpioTime failed: %d\n", rc);
            break;
        }
        tick = (seconds * 1000000) + micros;

        // Read the state of each channel
        int ch1_val = gpioRead(CH1);
        int ch2_val = gpioRead(CH2);
        int ch3_val = gpioRead(CH3);
        int ch4_val = gpioRead(CH4);
        int ch5_val = gpioRead(CH5);
        int ch6_val = gpioRead(CH6);
        int ch7_val = gpioRead(CH7);
        int ch8_val = gpioRead(CH8);

        // Print the sensor data to the console
        printf("[+%u ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               tick, ch1_val, ch2_val, ch3_val, ch4_val, ch5_val, ch6_val, ch7_val, ch8_val);

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

