#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the TTP226 channels
const int gpio_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a single GPIO pin
int read_gpio(int pin) {
    return gpioRead(pin);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to format the data into a CSV string
char* format_csv(char* timestamp, int* channel_states) {
    char* csv_string = (char*)malloc(200 * sizeof(char)); // Allocate memory for the CSV string
    if (csv_string == NULL) {
        perror("Failed to allocate memory for CSV string");
        return NULL;
    }

    strcpy(csv_string, timestamp);
    for (int i = 0; i < num_channels; i++) {
        char temp[5];
        sprintf(temp, ",%d", channel_states[i]);
        strcat(csv_string, temp);
    }
    strcat(csv_string, "\n");
    return csv_string;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configure GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(gpio_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Failed to disable pull-up/down for GPIO %d\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop
    while (program_running) {
        // Read sensor states
        int channel_states[num_channels];
        for (int i = 0; i < num_channels; i++) {
            channel_states[i] = read_gpio(gpio_pins[i]);
        }

        // Get timestamp
        char* timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp\n");
            continue; // Skip to the next iteration
        }

        // Format CSV string
        char* csv_string = format_csv(timestamp, channel_states);
        if (csv_string == NULL) {
            fprintf(stderr, "Failed to format CSV string\n");
            free(timestamp);
            continue; // Skip to the next iteration
        }

        // Print CSV string to console
        printf("%s", csv_string);

        // Free allocated memory
        free(timestamp);
        free(csv_string);

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Release GPIO resources
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(gpio_pins[i], PI_INPUT); // Set back to input before exiting
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

