#include <pigpio.h>
#include <unistd.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int tilt_state = -1; // Initialize to an invalid state
    int current_tilt_state;

    // Print startup banner
    printf("Raspberry Pi Zero W Tilt Sensor Monitoring\n");
    printf("-----------------------------------------\n");

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        current_tilt_state = gpioRead(TILT_SENSOR_GPIO);

        if (current_tilt_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", TILT_SENSOR_GPIO);
            gpioTerminate();
            return 1;
        }

        if (current_tilt_state != tilt_state) {
            tilt_state = current_tilt_state;

            if (tilt_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
        }

        gpioDelay(100); // Wait 100 milliseconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

