#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define UV_INDEX_REG 0x2C
#define ALS_VISIBLE_REG 0x22
#define CSV_FILENAME "uv_als_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_uv_index(uint8_t *uv_index);
int read_als_visible(uint16_t *als_visible);
void log_data(uint8_t uv_index, uint16_t als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int initialize_sensor() {
    // Reset the sensor (optional, but recommended)
    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) { // Enable UV
        fprintf(stderr, "Error: Failed to enable UV sensor.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x03, 0x01) < 0) { // Enable ALS
        fprintf(stderr, "Error: Failed to enable ALS sensor.\n");
        return -1;
    }

    return 0;
}

// Read the UV index from the sensor
int read_uv_index(uint8_t *uv_index) {
    int result = i2cReadByteData(i2c_handle, UV_INDEX_REG);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read UV index.\n");
        return -1;
    }
    *uv_index = (uint8_t)result;
    return 0;
}

// Read the visible ambient light from the sensor
int read_als_visible(uint16_t *als_visible) {
    int result = i2cReadWordData(i2c_handle, ALS_VISIBLE_REG);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read ALS visible.\n");
        return -1;
    }
    *als_visible = (uint16_t)result;
    return 0;
}

// Log the data to the console and CSV file
void log_data(uint8_t uv_index, uint16_t als_visible) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Print to console
    printf("%s - UV Index: %d, ALS Visible: %d\n", timestamp, uv_index, als_visible);

    // Log to CSV file
    fprintf(log_file, "%s,%d,%d\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t uv_index;
        uint16_t als_visible;

        if (read_uv_index(&uv_index) == 0 && read_als_visible(&als_visible) == 0) {
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying in 1 second.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

