#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int start_sensor(int i2c_handle);
int read_flow_rate(int i2c_handle, float *flow_rate);
uint8_t crc8(const uint8_t *data, int len);
float calculate_average(float flow1, float flow2);
void control_alarm(float average_flow);
void log_data(float flow1, float flow2, float average_flow);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Start sensor measurement
int start_sensor(int i2c_handle) {
    char cmd[2] = {0x36, 0x08};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read flow rate from sensor
int read_flow_rate(int i2c_handle, float *flow_rate) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow rate: %d\n", result);
        return -1;
    }

    uint8_t crc = crc8((uint8_t *)buffer, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 120.0; // Scaling factor from datasheet
    return 0;
}

// Calculate average flow rate
float calculate_average(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Control alarm based on average flow rate
void control_alarm(float average_flow) {
    if (average_flow < FLOW_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Activate alarm
    } else {
        gpioWrite(ALARM_GPIO, 0); // Deactivate alarm
    }
}

// Log data to file
void log_data(float flow1, float flow2, float average_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Average: %.2f ml/min\n",
            timestamp, flow1, flow2, average_flow);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Initialize alarm GPIO
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Start sensors
    if (start_sensor(i2c_handle1) != 0 || start_sensor(i2c_handle2) != 0) {
        cleanup();
        return 1;
    }

    // Wait 100ms
    gpioDelay(100000); // 100ms

    // Main loop
    float flow1, flow2, average_flow;
    while (!terminate) {
        flow1 = -1.0; // Initialize to an invalid value
        flow2 = -1.0;

        if (read_flow_rate(i2c_handle1, &flow1) != 0) {
            fprintf(stderr, "Error reading from sensor 1, skipping...\n");
        }

        if (read_flow_rate(i2c_handle2, &flow2) != 0) {
            fprintf(stderr, "Error reading from sensor 2, skipping...\n");
        }

        if (flow1 >= 0 && flow2 >= 0) {
            average_flow = calculate_average(flow1, flow2);
            control_alarm(average_flow);
            log_data(flow1, flow2, average_flow);
        } else {
            fprintf(stderr, "Skipping average calculation due to sensor errors.\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

