#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and sensor value
typedef struct {
    struct timespec timestamp;
    int sensor_value;
} sensor_data_t;

// Circular buffer
sensor_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int sensor_value);
void print_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) {
            printf("Obstacle detected!\n");
        }

        add_to_buffer(sensor_value);
        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Clean up and exit
    gpioTerminate();
    print_buffer();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initializes the pigpio library and configures the sensor pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);
    return 0;
}

// Reads the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Adds the sensor value to the circular buffer
void add_to_buffer(int sensor_value) {
    clock_gettime(CLOCK_REALTIME, &buffer[buffer_index].timestamp);
    buffer[buffer_index].sensor_value = sensor_value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Prints the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Dump ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[100];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp.tv_sec));
        printf("[%s.%09ld] Sensor Value: %d\n", timestamp_str, buffer[index].timestamp.tv_nsec, buffer[index].sensor_value);
    }
    printf("--- End of Data Dump ---\n\n");
}

// Signal handler for SIGINT
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

