#define CSV_FILENAME "fan_health.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
char* get_iso8601_timestamp();
int write_to_csv(char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the Omron D7S sensor
int configure_sensor() {
    int result = i2cWriteByteData(i2c_handle, MODE_REG, ACTIVE_MODE);
    if (result < 0) {
        fprintf(stderr, "Failed to write to mode register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, X_LSB_REG, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Write data to CSV file
int write_to_csv(char *timestamp, int16_t x, int16_t y, int16_t z) {
    // Check if the file exists and is empty
    FILE *fp = fopen(CSV_FILENAME, "r");
    int is_new_file = 0;
    if (fp == NULL) {
        is_new_file = 1;
    } else {
        fclose(fp);
    }

    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing\n");
        return -1;
    }

    // Write header if it's a new file
    if (is_new_file) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fclose(csv_file);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for sensor to become active (1 second)
    gpioDelay(1000); // Wait 1 second

    int16_t x, y, z;
    char *timestamp;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Write to CSV file
            if (write_to_csv(timestamp, x, y, z) != 0) {
                fprintf(stderr, "Failed to write data to CSV file\n");
            }
            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait 500ms
        gpioDelay(500);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

