#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library and GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set sensor pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR1_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on SENSOR1_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR2_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on SENSOR2_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR1_PIN);
    int sensor2_value = gpioRead(SENSOR2_PIN);

    if (sensor1_value < 0 || sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1; // Indicate error
    }

    return (sensor1_value == 0 || sensor2_value == 0) ? 1 : 0; // Obstacle detected if either sensor is LOW
}

// Function to control the LED
void control_led(int obstacle_detected) {
    if (obstacle_detected) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Function to cleanup GPIO resources
void cleanup() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    fprintf(stderr, "pigpio terminated\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        return 1; // Exit if initialization fails
    }

    fprintf(stderr, "System initialized successfully\n");

    // Main loop
    while (program_running) {
        int obstacle_detected = read_sensors();
        if (obstacle_detected < 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop on sensor read error
        }
        control_led(obstacle_detected);
        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

