#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define STALL_DURATION 2 // seconds
#define LOG_FILE "stall_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to check for stall
int check_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log stall event
int log_stall(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to get current timestamp
int get_timestamp(char *timestamp_str, size_t size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_str, size, "%Y-%m-%d %H:%M:%S", tm_info);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t stall_start_time = 0;
    int stall_detected = 0;

    printf("Conveyor belt stall detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value < 0 || sensor1_value > 1 || sensor2_value < 0 || sensor2_value > 1) {
            fprintf(stderr, "Invalid sensor reading. Skipping stall check.\n");
            gpioDelay(100); // Small delay to avoid spamming errors
            continue;
        }

        if (check_stall(sensor1_value, sensor2_value)) {
            if (!stall_detected) {
                stall_detected = 1;
                stall_start_time = time(NULL);
            } else {
                time_t current_time = time(NULL);
                if (difftime(current_time, stall_start_time) >= STALL_DURATION) {
                    char timestamp[20];
                    if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                        if (log_stall(timestamp) == 0) {
                            printf("Stall detected and logged at %s\n", timestamp);
                        } else {
                            fprintf(stderr, "Failed to log stall event.\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to get timestamp.\n");
                    }
                    stall_detected = 0; // Reset stall detection
                }
            }
        } else {
            stall_detected = 0; // Reset stall detection if sensors are not stalled
        }

        gpioDelay(100); // Check every 100ms
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

