#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TMAG5170 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170 register addresses
#define REG_X_AXIS 0x00
#define REG_Y_AXIS 0x02
#define REG_Z_AXIS 0x04
#define REG_CONFIG 0x06

// Configuration values
#define CONFIG_CONT_CONV 0x00
#define CONFIG_ALL_AXES_EN 0x07
#define CONFIG_50MT_RANGE 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_tmag5170();
int read_tmag5170(int16_t *x, int16_t *y, int16_t *z);
int log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize TMAG5170 sensor
int init_tmag5170() {
    // Configure the sensor for continuous conversion mode, all axes enabled, and 50mT range
    char config_data[2];
    config_data[0] = REG_CONFIG;
    config_data[1] = (CONFIG_CONT_CONV << 6) | (CONFIG_ALL_AXES_EN << 3) | CONFIG_50MT_RANGE;

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read X, Y, and Z magnetic field values from the sensor
int read_tmag5170(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result;

    // Read X axis data
    result = i2cReadI2CBlockData(i2c_handle, REG_X_AXIS, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading X, Y, and Z axis data: %d\n", result);
        return -1;
    }

    // Extract X, Y, and Z values from the buffer
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Log data to CSV file
int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize TMAG5170 sensor
    if (init_tmag5170() != 0) {
        fprintf(stderr, "Error initializing TMAG5170 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_tmag5170(&x, &y, &z) == 0) {
            // Log data to CSV file
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

