#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

// Structure to hold program state
typedef struct {
    volatile unsigned int pulse_count;
    FILE *log_file;
    int running;
} ProgramState;

ProgramState state = {0, NULL, 1}; // Initialize running to 1

// Function prototypes
void pulse_counter_callback(int gpio, int level, uint32_t tick, void *user_data);
void *log_rpm_thread(void *arg);
void signal_handler(int signal);
int setup_gpio();
int open_log_file();
void close_resources();

// Interrupt handler for rising edge detection
void pulse_counter_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        __sync_fetch_and_add(&state.pulse_count, 1);
    }
}

// Thread function to log RPM data
void *log_rpm_thread(void *arg) {
    while (state.running) {
        sleep(1);
        if (!state.running) break; // Check if signal handler set running to 0

        unsigned int current_pulse_count = state.pulse_count;
        state.pulse_count = 0; // Reset pulse count for the next second

        double rpm = (double)current_pulse_count * 60.0;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "%s %.2f\n", timestamp, rpm);

        if (state.log_file != NULL) {
            if (fputs(log_entry, state.log_file) == EOF) {
                perror("Error writing to log file");
            } else {
                fflush(state.log_file);
            }
        } else {
            fprintf(stderr, "Log file is not open.\n");
        }

        printf("%s %.2f\n", timestamp, rpm);
    }
    pthread_exit(NULL);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    state.running = 0; // Signal the thread to stop
}

// Function to set up GPIO pin
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to open the log file
int open_log_file() {
    state.log_file = fopen(LOG_FILE, "a");
    if (state.log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Function to close resources before exiting
void close_resources() {
    printf("Closing resources...\n");
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    // Create logging thread
    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, log_rpm_thread, NULL) != 0) {
        perror("Failed to create logging thread");
        close_resources();
        return 1;
    }

    // Main loop (keep the program running until a signal is received)
    while (state.running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Wait for the logging thread to finish
    pthread_join(log_thread, NULL);

    // Close resources before exiting
    close_resources();

    return 0;
}

