#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define quadrature states
#define QUADRATURE_STATE_0 0
#define QUADRATURE_STATE_1 1
#define QUADRATURE_STATE_2 2
#define QUADRATURE_STATE_3 3

// Define rotation directions
#define CLOCKWISE 1
#define COUNTER_CLOCKWISE -1

// Global variables
static volatile int quadrature_state = QUADRATURE_STATE_0;
static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t mutex;
static pthread_cond_t cond;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void log_rotation(int direction);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    pthread_cond_signal(&cond); // Wake up the main thread
}

// Initialize GPIO pins and pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Initialize mutex and condition variable
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        gpioTerminate();
        return 1;
    }
    if (pthread_cond_init(&cond, NULL) != 0) {
        perror("Condition variable initialization failed");
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup GPIO pins and pigpio library
void cleanup_gpio() {
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);
    gpioTerminate();
}

// Log rotation event to file
void log_rotation(int direction) {
    struct timespec ts;
    char timestamp[30];

    // Get current time with millisecond precision
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime failed");
        return;
    }

    // Format timestamp
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), 10, ".%03ld", ts.tv_nsec / 1000000);

    // Open log file in append mode
    log_file = fopen("rotation_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    // Write to log file
    fprintf(log_file, "%s %s\n", timestamp, (direction == CLOCKWISE) ? "CLOCKWISE" : "COUNTER_CLOCKWISE");

    // Close log file
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing
}

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user) {
    int sensor_b_level;
    int new_quadrature_state;

    pthread_mutex_lock(&mutex);

    sensor_b_level = gpioRead(SENSOR_B_GPIO);

    if (sensor_b_level == 0) {
        new_quadrature_state = (quadrature_state == QUADRATURE_STATE_0) ? QUADRATURE_STATE_1 : QUADRATURE_STATE_0;
    } else {
        new_quadrature_state = (quadrature_state == QUADRATURE_STATE_0) ? QUADRATURE_STATE_3 : QUADRATURE_STATE_2;
    }

    if (new_quadrature_state != quadrature_state) {
        if (new_quadrature_state == QUADRATURE_STATE_1) {
            log_rotation(CLOCKWISE);
        } else if (new_quadrature_state == QUADRATURE_STATE_3) {
            log_rotation(COUNTER_CLOCKWISE);
        }
        quadrature_state = new_quadrature_state;
    }

    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user) {
    int sensor_a_level;
    int new_quadrature_state;

    pthread_mutex_lock(&mutex);

    sensor_a_level = gpioRead(SENSOR_A_GPIO);

    if (sensor_a_level == 0) {
        new_quadrature_state = (quadrature_state == QUADRATURE_STATE_0) ? QUADRATURE_STATE_3 : QUADRATURE_STATE_0;
    } else {
        new_quadrature_state = (quadrature_state == QUADRATURE_STATE_0) ? QUADRATURE_STATE_1 : QUADRATURE_STATE_2;
    }

    if (new_quadrature_state != quadrature_state) {
        if (new_quadrature_state == QUADRATURE_STATE_1) {
            log_rotation(CLOCKWISE);
        } else if (new_quadrature_state == QUADRATURE_STATE_3) {
            log_rotation(COUNTER_CLOCKWISE);
        }
        quadrature_state = new_quadrature_state;
    }

    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up interrupt handlers
    if (gpioSetISRFuncEx(SENSOR_A_GPIO, RISING_EDGE, 0, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Sensor A\n");
        cleanup_gpio();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_B_GPIO, RISING_EDGE, 0, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Sensor B\n");
        cleanup_gpio();
        return 1;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        pthread_mutex_lock(&mutex);
        pthread_cond_wait(&cond, &mutex);
        pthread_mutex_unlock(&mutex);
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

