// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_led(int state);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Open syslog for logging
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Touch sensor and LED control program started.");

    // Main loop
    while (program_running) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // Control LED based on touch sensor state
        if (touch_detected == 0) { // Assuming 0 means touched
            control_led(1); // Turn LED on
            syslog(LOG_INFO, "Touch detected. LED turned on.");
        } else {
            control_led(0); // Turn LED off
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup and exit
    syslog(LOG_INFO, "Touch sensor and LED control program shutting down.");
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN); // Example: Pull-down resistor

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the LED
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0; // Set flag to exit main loop
}

