#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output and initialize to LOW
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write LOW to LED pin\n");
        gpioTerminate();
        return 1;
    }

    // Set touch sensor pin as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on touch sensor pin\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to toggle the LED state
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    if (current_level < 0) {
        fprintf(stderr, "Failed to read LED pin level\n");
        return;
    }
    int new_level = !current_level;
    if (gpioWrite(LED_PIN, new_level) != 0) {
        fprintf(stderr, "Failed to write to LED pin\n");
    }
}

// Function to implement software debounce
void debounce() {
    gpioDelay(DEBOUNCE_TIME * 1000); // Delay in microseconds
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        // Wait for rising edge on the touch sensor pin
        if (gpioWaitForEdge(TOUCH_SENSOR_PIN, RISING_EDGE, -1) != 0) {
            fprintf(stderr, "Error waiting for edge\n");
            break; // Exit loop on error
        }

        // Toggle the LED
        toggle_led();

        // Debounce
        debounce();
    }

    // Clean up GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

