#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define buffer size
#define BUFFER_SIZE 100

// Structure to store event data
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} Event;

// Circular buffer
Event event_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int read_sensor(int pin);
void set_led(int pin, int state);
void log_event(int sensor_pin, int state);
void print_buffer();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);
    set_led(LED_1_PIN, 0);
    set_led(LED_2_PIN, 0);
    gpioTerminate();
    print_buffer();
    exit(0);
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d: %d\n", pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to set LED state
void set_led(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error setting LED on pin %d to state %d: %d\n", pin, state, result);
    }
}

// Function to log event to circular buffer
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp = now;
    event_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        overflow_count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("Event Log:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Start from the oldest event
        printf("  Sensor: %d, Timestamp: %ld, State: %d\n",
               event_buffer[index].sensor_pin, event_buffer[index].timestamp, event_buffer[index].state);
    }
    printf("Overflow Count: %d\n", overflow_count);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            // Error reading sensors, exit gracefully
            signal_handler(SIGTERM);
            return 1;
        }

        // Set LED states
        set_led(LED_1_PIN, sensor1_value);
        set_led(LED_2_PIN, sensor2_value);

        // Log events
        if (sensor1_value != (gpioRead(SENSOR_1_PIN) == 1 ? 1 : 0)) {
            log_event(SENSOR_1_PIN, sensor1_value);
        }
        if (sensor2_value != (gpioRead(SENSOR_2_PIN) == 1 ? 1 : 0)) {
            log_event(SENSOR_2_PIN, sensor2_value);
        }

        // Delay for debouncing
        gpioDelay(50000); // 50ms
    }

    return 0;
}

