// Define the debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Define the log file name
#define LOG_FILE "shaft_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
SensorStates read_sensors();
int debounce(int pin, int current_state);
void log_data(SensorStates states);
double calculate_rpm();
void print_rpm(double rpm);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    return 0; // Indicate success
}

// Function to read the current state of both sensors
SensorStates read_sensors() {
    SensorStates states;
    states.sensor1_state = gpioRead(SENSOR1_PIN);
    states.sensor2_state = gpioRead(SENSOR2_PIN);
    return states;
}

// Function to implement a software debounce
int debounce(int pin, int current_state) {
    int new_state = gpioRead(pin);
    if (new_state != current_state) {
        gpioDelay(DEBOUNCE_TIME * 1000); // Delay for debounce time (in microseconds)
        new_state = gpioRead(pin); // Re-read the pin after the delay
        if (new_state == current_state) {
            return new_state; // Return the debounced state
        }
    }
    return current_state; // Return the original state if debounce failed
}

// Function to log the sensor data to a CSV file
void log_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate the RPM (placeholder - requires actual timing logic)
double calculate_rpm() {
    // This is a placeholder.  A real implementation would need to measure
    // the time between rising edges of the sensors.
    // For simplicity, we'll return a constant RPM.
    return 100.0; // Example RPM
}

// Function to print the calculated RPM to the console
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    SensorStates current_states = read_sensors();
    SensorStates previous_states = current_states;

    while (running) {
        current_states = read_sensors();

        // Debounce the sensor readings
        int debounced_sensor1 = debounce(SENSOR1_PIN, previous_states.sensor1_state);
        int debounced_sensor2 = debounce(SENSOR2_PIN, previous_states.sensor2_state);

        // Check for state changes
        if (debounced_sensor1 != previous_states.sensor1_state || debounced_sensor2 != previous_states.sensor2_state) {
            SensorStates new_states;
            new_states.sensor1_state = debounced_sensor1;
            new_states.sensor2_state = debounced_sensor2;

            // Log the data
            log_data(new_states);

            // Update previous states
            previous_states = new_states;
        }

        // Calculate and print the RPM
        double rpm = calculate_rpm();
        print_rpm(rpm);

        gpioDelay(10000); // Delay for 10ms (10000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

