// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define LOG_FILE "biometric_log.txt"

// Si1182 Register Addresses (Example - adjust based on datasheet)
#define REG_PART_ID 0x00
#define REG_HW_ID 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_INT_EN 0x04
#define REG_RSP0_CFG 0x07
#define REG_RSP1_CFG 0x08
#define REG_RSP2_CFG 0x09
#define REG_RSP3_CFG 0x0A
#define REG_IRQ_STATUS 0x0B
#define REG_ALS_VIS_DATA0 0x10
#define REG_ALS_VIS_DATA1 0x11
#define REG_ALS_IR_DATA0 0x12
#define REG_ALS_IR_DATA1 0x13
#define REG_PS1_DATA0 0x14
#define REG_PS1_DATA1 0x15
#define REG_PS2_DATA0 0x16
#define REG_PS2_DATA1 0x17
#define REG_PS3_DATA0 0x18
#define REG_PS3_DATA1 0x19
#define REG_UV_INDEX0 0x2C
#define REG_UV_INDEX1 0x2D
#define REG_PARAM_WR 0x30
#define REG_COMMAND 0x31
#define REG_RESPONSE0 0x20
#define REG_RESPONSE1 0x21
#define REG_RESPONSE2 0x22
#define REG_RESPONSE3 0x23

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1182_init();
int read_si1182_data(int *heart_rate, int *spo2);
void log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    int heart_rate;
    int spo2;
} sensor_data_t;

// Function to write a byte to a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the Si1182 sensor
int si1182_init() {
    // Reset the sensor
    if (write_register(i2c_handle, REG_COMMAND, CMD_RESET) != 0) {
        fprintf(stderr, "Error resetting Si1182\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration - adjust based on datasheet)
    if (write_register(i2c_handle, REG_RSP0_CFG, 0x03) != 0) return -1; // Example config
    if (write_register(i2c_handle, REG_RSP1_CFG, 0x03) != 0) return -1; // Example config
    if (write_register(i2c_handle, REG_RSP2_CFG, 0x03) != 0) return -1; // Example config
    if (write_register(i2c_handle, REG_RSP3_CFG, 0x03) != 0) return -1; // Example config

    // Enable interrupts (example)
    if (write_register(i2c_handle, REG_INT_EN, 0x01) != 0) return -1;

    // Configure interrupt configuration (example)
    if (write_register(i2c_handle, REG_INT_CFG, 0x03) != 0) return -1;

    return 0;
}

// Function to read heart rate and SpO2 data from the Si1182 sensor
int read_si1182_data(int *heart_rate, int *spo2) {
    uint8_t vis_data0, vis_data1, ir_data0, ir_data1;

    // Trigger a measurement
    if (write_register(i2c_handle, REG_COMMAND, CMD_ALS_FORCE) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    gpioDelay(1); // Wait for measurement to complete

    // Read visible light data
    if (read_register(i2c_handle, REG_ALS_VIS_DATA0, &vis_data0) != 0) return -1;
    if (read_register(i2c_handle, REG_ALS_VIS_DATA1, &vis_data1) != 0) return -1;

    // Read IR light data
    if (read_register(i2c_handle, REG_ALS_IR_DATA0, &ir_data0) != 0) return -1;
    if (read_register(i2c_handle, REG_ALS_IR_DATA1, &ir_data1) != 0) return -1;

    // Combine the data to form 16-bit values
    unsigned int vis = (vis_data1 << 8) | vis_data0;
    unsigned int ir = (ir_data1 << 8) | ir_data0;

    // Basic data validation
    if (vis == 0 || ir == 0) {
        fprintf(stderr, "Invalid sensor data (zero values)\n");
        return -1;
    }

    // Calculate heart rate and SpO2 (example calculations - replace with actual formulas)
    *heart_rate = (int)(vis % 100); // Example: use visible light as a proxy for heart rate
    *spo2 = 95 + (int)(ir % 5);      // Example: use IR light as a proxy for SpO2

    // Data validation
    if (*heart_rate < 40 || *heart_rate > 200) {
        fprintf(stderr, "Heart rate out of range: %d\n", *heart_rate);
        return -1;
    }
    if (*spo2 < 80 || *spo2 > 100) {
        fprintf(stderr, "SpO2 out of range: %d\n", *spo2);
        return -1;
    }

    return 0;
}

// Function to log the data to a file
void log_data(int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1182 sensor
    if (si1182_init() != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int heart_rate, spo2;

    // Main loop
    while (!terminate) {
        if (read_si1182_data(&heart_rate, &spo2) == 0) {
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

