    if (read_register(i2c_handle, REG_ALS_IR_DATA0, &ir_data0) != 0) return -1;
    if (read_register(i2c_handle, REG_ALS_IR_DATA1, &ir_data1) != 0) return -1;

    // Combine the data to form 16-bit values
    unsigned int vis = (vis_data1 << 8) | vis_data0;
    unsigned int ir = (ir_data1 << 8) | ir_data0;

    // Basic data validation
    if (vis == 0 || ir == 0) {
        fprintf(stderr, "Invalid sensor data (zero values)\n");
        return -1;
    }

    // Calculate heart rate and SpO2 (example calculations - replace with actual formulas)
