volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(const char *event_type);
int activate_alarm();
int deactivate_alarm();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
    time_t tilt_start_time;
    int alarm_active;
} SensorData;

SensorData sensor_data = {0, 0, 0, 0};

int main() {
    // Register signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values. Continuing.\n");
            gpioDelay(100); // Small delay to avoid spamming errors
            continue;
        }

        // Check for tilt start
        if ((sensor1_value == 1 || sensor2_value == 1) && (sensor_data.sensor1_state == 0 || sensor_data.sensor2_state == 0)) {
            if (log_event("tilt-start") != 0) {
                fprintf(stderr, "Error logging tilt-start event.\n");
            }
            sensor_data.tilt_start_time = time(NULL);
        }

        // Check for threshold exceeded
        if ((sensor1_value == 1 && sensor2_value == 1) && (sensor_data.sensor1_state == 1 && sensor_data.sensor2_state == 1)) {
            time_t current_time = time(NULL);
            if (difftime(current_time, sensor_data.tilt_start_time) >= ALARM_DURATION && !sensor_data.alarm_active) {
                if (activate_alarm() != 0) {
                    fprintf(stderr, "Error activating alarm.\n");
                }
                if (log_event("threshold-exceeded") != 0) {
                    fprintf(stderr, "Error logging threshold-exceeded event.\n");
                }
                sensor_data.alarm_active = 1;
            }
        }

        // Check for tilt end
        if (sensor1_value == 0 && sensor2_value == 0 && sensor_data.sensor1_state == 1 && sensor_data.sensor2_state == 1) {
            if (log_event("tilt-end") != 0) {
                fprintf(stderr, "Error logging tilt-end event.\n");
            }
            if (sensor_data.alarm_active) {
                deactivate_alarm();
                sensor_data.alarm_active = 0;
            }
        }

        // Update sensor states
        sensor_data.sensor1_state = sensor1_value;
        sensor_data.sensor2_state = sensor2_value;

        // Delay for 100ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

