int log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }
}

// Activate alarm
int activate_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set alarm pin HIGH
    return 0;
}

// Deactivate alarm
int deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0); // Set alarm pin LOW
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    deactivate_alarm(); // Ensure alarm is off

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate(); // Terminate pigpio
}

