#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define LED_GPIO 17
#define THRESHOLD 500
#define NUM_SENSORS 3
#define SENSOR_ADDR_BASE 0x1D
#define CTRL1_REG 0x20
#define CTRL2_REG 0x21
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handles[NUM_SENSORS];
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(int sensor_id, double magnitude);
void control_led(int state);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize sensor
int initialize_sensor(int i2c_handle) {
    // Clear power-down bit in CTRL1
    if (i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL1_REG\n");
        return -1;
    }

    // Set data rate and full scale range in CTRL2 (example values)
    if (i2cWriteByteData(i2c_handle, CTRL2_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL2_REG\n");
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Calculate magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Log event
void log_event(int sensor_id, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, Sensor %d, Magnitude: %.2f\n", timestamp, sensor_id, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
    gpioDelay(1000); // 1 second
    gpioWrite(LED_GPIO, 0); // Turn off after 1 second
}

int main() {
    int i;
    int sensor_addresses[NUM_SENSORS] = {SENSOR_ADDR_BASE, SENSOR_ADDR_BASE + 1, SENSOR_ADDR_BASE + 2};
    int16_t x, y, z;
    double magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C and sensors
    for (i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, sensor_addresses[i], 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error opening I2C device for sensor %d at address 0x%02X\n", i, sensor_addresses[i]);
            // Attempt to close previously opened handles
            for (int j = 0; j < i; j++) {
                i2cClose(i2c_handles[j]);
            }
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        if (initialize_sensor(i2c_handles[i]) < 0) {
            fprintf(stderr, "Error initializing sensor %d\n", i);
            // Attempt to close previously opened handles
            for (int j = 0; j <= i; j++) {
                i2cClose(i2c_handles[j]);
            }
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
        printf("Sensor %d initialized successfully\n", i);
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        for (i = 0; i < NUM_SENSORS; i++) {
            if (read_sensor_data(i2c_handles[i], &x, &y, &z) == 0) {
                magnitude = calculate_magnitude(x, y, z);
                if (magnitude > THRESHOLD) {
                    printf("Event detected on sensor %d, magnitude: %.2f\n", i, magnitude);
                    log_event(i, magnitude);
                    control_led(1); // Turn on LED
                }
            } else {
                fprintf(stderr, "Error reading data from sensor %d\n", i);
            }
        }
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    for (i = 0; i < NUM_SENSORS; i++) {
        i2cClose(i2c_handles[i]);
    }
    fclose(log_file);
    gpioTerminate();

    return 0;
}

