        fprintf(stderr, "Failed to set mode for SENSOR1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR3_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR4_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR4_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_PIN\n");
        gpioTerminate();
        return 1;
    }

