    while (program_running) {
        // Read sensor data
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);
        int sensor4_value = read_sensor(SENSOR4_PIN);

        // Check if any sensor detects an object
        if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0) {
            // Turn on the LED
            control_led(1);
        } else {
            // Turn off the LED
            control_led(0);
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Clean up GPIO resources
    gpioWrite(LED_PIN, 0); // Turn off LED before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

