#include <pigpio.h>

// Define GPIO pins for the flame sensors
#define SENSOR_1_GPIO 2
#define SENSOR_2_GPIO 3
#define SENSOR_3_GPIO 4
#define SENSOR_4_GPIO 17
#define SENSOR_5_GPIO 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Log file path
#define LOG_FILE "/var/log/flame_events.log"

// Structure to hold sensor information
typedef struct {
    int gpio_pin;
    int sensor_id;
    char *sensor_name;
} sensor_t;

// Array of sensor structures
sensor_t sensors[] = {
    {SENSOR_1_GPIO, 1, "Sensor 1"},
    {SENSOR_2_GPIO, 2, "Sensor 2"},
    {SENSOR_3_GPIO, 3, "Sensor 3"},
    {SENSOR_4_GPIO, 4, "Sensor 4"},
    {SENSOR_5_GPIO, 5, "Sensor 5"}
};

const int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int gpio_pin);
int debounce(int gpio_pin);
int log_event(int sensor_id, int gpio_pin);
void signal_handler(int signal);
int setup_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to debounce the sensor reading
int debounce(int gpio_pin) {
    int i;
    int reading = read_sensor(gpio_pin);
    for (i = 0; i < 5; i++) {
        gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds
        if (read_sensor(gpio_pin) != reading) {
            return 0; // Not stable
        }
    }
    return reading; // Stable
}

// Function to log the event to a file
int log_event(int sensor_id, int gpio_pin) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Error opening log file: %s", LOG_FILE);
        perror("fopen");
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Error acquiring lock on log file: %s", LOG_FILE);
        perror("flock");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);
    fflush(fp);

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Error releasing lock on log file: %s", LOG_FILE);
        perror("flock");
    }

    fclose(fp);
    return 0;
}

// Function to initialize GPIO
int setup_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensors[i].gpio_pin, PI_INPUT);
        gpioSetPullUpDown(sensors[i].gpio_pin, PI_PUD_UP); // Enable pull-up resistor
    }
    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting flame monitor...");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() != 0) {
        syslog(LOG_ERR, "GPIO setup failed, exiting...");
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < num_sensors; i++) {
            int reading = read_sensor(sensors[i].gpio_pin);
            if (reading == 0) { // Flame detected (LOW signal)
                if (debounce(sensors[i].gpio_pin)) {
                    if (log_event(sensors[i].sensor_id, sensors[i].gpio_pin) == 0) {
                        syslog(LOG_INFO, "Flame detected by %s (GPIO %d)", sensors[i].sensor_name, sensors[i].gpio_pin);
                    } else {
                        syslog(LOG_ERR, "Failed to log event for %s (GPIO %d)", sensors[i].sensor_name, sensors[i].gpio_pin);
                    }
                }
            }
        }
        gpioDelay(1000000); // 1 second delay (microseconds)
    }

    cleanup_gpio();
    syslog(LOG_INFO, "Flame monitor terminated.");
    closelog();

    return 0;
}

