#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define OUT0 5
#define OUT1 6
#define OUT2 13
#define OUT3 19
#define OUT4 26
#define OUT5 12
#define OUT6 16
#define OUT7 20

// Structure to hold the previous state of each sensor
struct sensor_state {
    int sensor_index;
    int pin_number;
    int previous_state;
};

// Array of sensor states
struct sensor_state sensor_states[] = {
    {0, OUT0, 0},
    {1, OUT1, 0},
    {2, OUT2, 0},
    {3, OUT3, 0},
    {4, OUT4, 0},
    {5, OUT5, 0},
    {6, OUT6, 0},
    {7, OUT7, 0}
};

// Number of sensors
#define NUM_SENSORS (sizeof(sensor_states) / sizeof(sensor_states[0]))

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_SENSORS] = {NULL};

// Function prototypes
int read_sensor(int pin);
void log_event(int sensor_index, int pin_number, int state);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to read the state of a sensor
int read_sensor(int pin) {
    int value;
    value = gpiod_line_get_value(lines[pin]);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor %d (pin %d): %s\n", pin, pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log an event
void log_event(int sensor_index, int pin_number, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s Sensor %d (pin %d): %s\n", timestamp, sensor_index, pin_number, state ? "Touch" : "Release");
}

// Function to set up GPIO lines
int setup_gpio(void) {
    int i;
    int ret;

    chip = gpiod_chip_open(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_states[i].pin_number);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", sensor_states[i].pin_number, strerror(errno));
            cleanup_gpio();
            return -1;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226");
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", sensor_states[i].pin_number, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to clean up GPIO resources
void cleanup_gpio(void) {
    int i;

    if (chip) {
        for (i = 0; i < NUM_SENSORS; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
        gpiod_chip_close(chip);
    }
}

int main() {
    int i, current_state;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        for (i = 0; i < NUM_SENSORS; i++) {
            current_state = read_sensor(i);
            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor %d, exiting.\n", i);
                cleanup_gpio();
                return 1;
            }

            if (current_state != sensor_states[i].previous_state) {
                log_event(sensor_states[i].sensor_index, sensor_states[i].pin_number, current_state);
                sensor_states[i].previous_state = current_state;
            }
        }

        // Delay for 50ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50 * 1000 * 1000; // 50ms
        nanosleep(&delay, NULL);
    }

    return 0;
}

