#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL 1 // seconds

// VEML7700 Registers
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
float read_lux();
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialize VEML7700 sensor
int init_veml7700() {
    // Configuration: Integration time = 100ms, Gain = 2x, Enable ALS
    uint16_t config_value = 0x0000; // Default configuration
    char buf[3];

    buf[0] = VEML7700_CONFIG;
    buf[1] = config_value & 0xFF;
    buf[2] = (config_value >> 8) & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read lux value from VEML7700 sensor
float read_lux() {
    char buf[1];
    char data[2];
    uint16_t als_data;
    float lux;

    buf[0] = VEML7700_ALS_DATA;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to VEML7700 ALS data register: %s\n", strerror(errno));
        return -1.0;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from VEML7700 ALS data register: %s\n", strerror(errno));
        return -1.0;
    }

    als_data = (data[1] << 8) | data[0];

    // Simple lux calculation (adjust as needed based on datasheet)
    lux = (float)als_data * 0.0576; // Example conversion factor

    return lux;
}

// Map lux value to brightness level (0-100)
int map_lux_to_brightness(float lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set LED brightness using hardware PWM
int set_led_brightness(int brightness) {
    if (brightness < 0 || brightness > 100) {
        fprintf(stderr, "Error: Brightness value out of range (0-100)\n");
        return -1;
    }

    int duty_cycle = (int)((float)brightness / 100.0 * 255.0);
    gpioPWM(LED_GPIO, duty_cycle);

    return 0;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() != 0) {
        fprintf(stderr, "Error initializing VEML7700 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        int brightness = 0;
        int error_code = 0;

        if (lux < 0) {
            fprintf(stderr, "Error reading lux value\n");
            error_code = 1;
            log_data(-1.0, 0, error_code);
        } else {
            brightness = map_lux_to_brightness(lux);
            if (set_led_brightness(brightness) != 0) {
                fprintf(stderr, "Error setting LED brightness\n");
                error_code = 2;
            }
            log_data(lux, brightness, error_code);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    set_led_brightness(0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

