#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensors and LED
#define TOUCH_SENSOR_START_PIN 2
#define LED_PIN 17
#define NUM_CHANNELS 8

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold the last touch state for each channel
typedef struct {
    int last_state[NUM_CHANNELS];
} TouchState;

TouchState touch_state = {{0}}; // Initialize all channels to untouched

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int channel);
int debounce_touch(int channel, int current_state);
int log_touch_event(int channel);
int control_led(int state);
void signal_handler(int signal);
int setup_signal_handlers();
int open_log_file();
int close_log_file();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure touch sensor pins as inputs with pull-down resistors
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = TOUCH_SENSOR_START_PIN + i;
        gpioSetMode(pin, PI_INPUT);
        gpioSetPullUpDown(pin, PI_PUD_DOWN);
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the state of a touch sensor channel
int read_touch_sensor(int channel) {
    int pin = TOUCH_SENSOR_START_PIN + channel - 1;
    return gpioRead(pin);
}

// Function to debounce touch sensor readings
int debounce_touch(int channel, int current_state) {
    int pin = TOUCH_SENSOR_START_PIN + channel - 1;
    int debounced_state = current_state;
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    if (gpioRead(pin) != current_state) {
        debounced_state = current_state; // Revert to previous state if changed during debounce
    }
    return debounced_state;
}

// Function to log a touch event to a file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Function to control the LED
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to set up signal handlers
int setup_signal_handlers() {
    struct sigaction sa;

    // Install signal handler for SIGINT
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction (SIGINT)");
        return 1;
    }

    // Install signal handler for SIGTERM
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction (SIGTERM)");
        return 1;
    }

    return 0;
}

// Function to open the log file
int open_log_file() {
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Function to close the log file
int close_log_file() {
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("Error closing log file");
            return 1;
        }
        log_file = NULL;
    }
    return 0;
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    if (setup_signal_handlers() != 0) {
        close_log_file();
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int all_released = 1;
        for (int i = 1; i <= NUM_CHANNELS; i++) {
            int current_state = read_touch_sensor(i);
            int debounced_state = debounce_touch(i, current_state);

            if (debounced_state == 1 && touch_state.last_state[i - 1] == 0) {
                log_touch_event(i);
                control_led(1); // Turn on LED on touch
                all_released = 0; // At least one channel is touched
            }

            touch_state.last_state[i - 1] = debounced_state;
        }

        if (all_released) {
            control_led(0); // Turn off LED when all channels are released
        }

        gpioDelay(50 * 1000); // Delay 50ms
    }

    // Clean up and exit
    control_led(0); // Turn off LED
    close_log_file();
    gpioTerminate();

    printf("Touch sensor monitoring stopped.\n");
    return 0;
}

