// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.0036
#define SLEEP_SEC 1
#define SLEEP_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor(float *lux);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float lux;
    time_t timestamp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    // Continuous conversion mode, 100ms conversion time
    uint16_t config_value = 0xCB10; //0b1100101100010000;
    uint8_t data[2];
    data[0] = (config_value >> 8) & 0xFF; // MSB
    data[1] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the OPT3001 sensor
int read_sensor(float *lux) {
    uint8_t data[2];
    int result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }

    // Convert from big-endian to little-endian
    uint16_t raw_result = (data[0] << 8) | data[1];

    // Extract exponent and result
    int exponent = (raw_result >> 12) & 0x0F;
    uint16_t result_value = raw_result & 0x0FFF;

    // Calculate lux value
    *lux = result_value * (1 << exponent) * LUX_SCALE;
    return 0;
}

// Function to log the data to a file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, %.2f\n", timestamp, lux);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float lux;
    // Main loop
    while (!terminate) {
        if (read_sensor(&lux) == 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping.\n");
        }
        gpioDelay(SLEEP_SEC * 1000); // Sleep for 1 second
        gpioDelay(SLEEP_MS); // Wait 100ms after writing config
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

