#define MIDDLE_SENSOR 27
#define RIGHT_SENSOR 22

// Define the log file name
#define LOG_FILE "path_log.csv"

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
char* get_iso8601_timestamp();
int log_data(FILE *fp, char *timestamp, int left, int middle, int right);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Function to read the sensor value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, char *timestamp, int left, int middle, int right) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", LEFT_SENSOR, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MIDDLE_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", MIDDLE_SENSOR, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", RIGHT_SENSOR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
    }
    rewind(log_file);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int middle_value = read_sensor(MIDDLE_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
        } else {
            // Get the current timestamp
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Log the data to the file
                if (log_data(log_file, timestamp, left_value, middle_value, right_value) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

