#define FLAME_SENSOR_GPIO 4
#define LOG_FILE "flame_events.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the flame event to the console and file
void log_flame_event() {
    char *timestamp = get_timestamp();
    printf("Flame detected at: %s\n", timestamp);

    if (log_file != NULL) {
        fprintf(log_file, "Flame detected at: %s\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Callback function for the flame sensor
void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected (flame)
        log_flame_event();
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up the interrupt handler for falling edge detection
    if (gpioSetAlertFuncEx(FLAME_SENSOR_GPIO, flame_detected_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for GPIO %d\n", FLAME_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to keep the program running until a signal is received
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");
    gpioSetAlertFuncEx(FLAME_SENSOR_GPIO, NULL, NULL); // Disable the callback
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

