int log_event(const char *timestamp, int led_state);
void signal_handler(int sig);
char* iso8601_timestamp();

// GPIO functions
int gpio_get_value(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO value file: %s (errno: %d)\n", path, errno);
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading GPIO value: %s (errno: %d)\n", path, errno);
        close(fd);
        return -1;
    }
    close(fd);
    return (value_str[0] == '1') ? 1 : 0;
}

int gpio_set_value(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO value file for writing: %s (errno: %d)\n", path, errno);
        return -1;
    }
    if (write(fd, value ? "1" : "0", 1) < 0) {
        fprintf(stderr, "Error writing GPIO value: %s (errno: %d)\n", path, errno);
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_request_line(int chip, int pin, const char *label, int *line_fd) {
    struct gpio_line_request line_request;
    struct gpio_line_config line_config;
    int fd;

    fd = open("/dev/gpiochip4", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: /dev/gpiochip4 (errno: %d)\n", errno);
        return -1;
    }

    memset(&line_request, 0, sizeof(line_request));
    line_request.offsets[0] = pin;
    line_request.num_lines = 1;
    line_request.consumer = label;

    if (ioctl(fd, GPIO_LINE_REQUEST, &line_request) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s (errno: %d)\n", label, errno);
        close(fd);
        return -1;
    }

    *line_fd = line_request.lineoffsets[0];

    memset(&line_config, 0, sizeof(line_config));
    line_config.flags = 0; // Default configuration
    line_config.consumer = label;

    if (ioctl(fd, GPIO_GET_LINE_IOCTL, &line_config) < 0) {
        fprintf(stderr, "Error getting GPIO line IOCTL: %s (errno: %d)\n", label, errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_release_line(int line_fd) {
    struct gpio_line_request line_request;
    int fd;

    fd = open("/dev/gpiochip4", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip for release: /dev/gpiochip4 (errno: %d)\n", errno);
        return -1;
    }

    memset(&line_request, 0, sizeof(line_request));
    line_request.lineoffsets[0] = line_fd;
    line_request.num_lines = 1;
    line_request.consumer = "release";

    if (ioctl(fd, GPIO_LINE_UNREQUEST, &line_request) < 0) {
        fprintf(stderr, "Error releasing GPIO line: %s (errno: %d)\n", "release", errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_get_line_value(int line_fd) {
