        fprintf(stderr, "Error getting GPIO line values: %s (errno: %d)\n", "get", errno);
        close(fd);
        return -1;
    }

    close(fd);
    return values.values[0];
}

// SPI functions
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s (errno: %d)\n", "spi", errno);
        return -1;
    }

    return 0;
}

// Logging function
int log_event(const char *timestamp, int led_state) {
    char log_message[256];
    ssize_t bytes_written;

    snprintf(log_message, sizeof(log_message), "%s, LED: %s\n", timestamp, led_state ? "ON" : "OFF");

    bytes_written = write(log_file_fd, log_message, strlen(log_message));
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to log file: %s (errno: %d)\n", LOG_FILE, errno);
        return -1;
    }

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

// Timestamp function
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main() {
    int touch_line_fd = -1;
    int spi_fd = -1;
    unsigned char spi_tx_buf[2] = {0x01, 0x00}; // Example SPI transmit data
    unsigned char spi_rx_buf[2];
    int touch_detected;
    char *timestamp;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file_fd < 0) {
        fprintf(stderr, "Error opening log file: %s (errno: %d)\n", LOG_FILE, errno);
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    if (gpio_request_line(4, TOUCH_SENSOR_PIN, "touch_sensor", &touch_line_fd) < 0) {
        close(log_file_fd);
        return EXIT_FAILURE;
    }

    if (gpio_request_line(4, LED_PIN, "led", &touch_line_fd) < 0) {
        gpio_release_line(touch_line_fd);
