        gpio_release_line(touch_line_fd);
        close(log_file_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read touch sensor value
        touch_detected = gpio_get_line_value(touch_line_fd);
        if (touch_detected < 0) {
            fprintf(stderr, "Error reading touch sensor value. Exiting.\n");
            break;
