            if (gpio_set_value(LED_PIN, led_state) < 0) {
                fprintf(stderr, "Error setting LED value. Exiting.\n");
                break;
            }

            // Perform SPI transfer
            if (spi_transfer(spi_fd, spi_tx_buf, spi_rx_buf, 2) < 0) {
                fprintf(stderr, "Error during SPI transfer. Exiting.\n");
                break;
            }

            // Get timestamp
            timestamp = iso8601_timestamp();

            // Log event
            if (log_event(timestamp, led_state) < 0) {
                fprintf(stderr, "Error logging event. Exiting.\n");
