#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *flame_sensor_line = NULL;
struct gpiod_line *buzzer_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int read_flame_sensor(void);
int activate_buzzer(void);
int log_event(const char *event);
void signal_handler(int signal);
void cleanup(void);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        perror("Error getting flame sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        return -1;
    }

    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret < 0) {
        perror("Error requesting flame sensor line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0); // Initial state LOW
    if (ret < 0) {
        perror("Error requesting buzzer line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    return 0;
}

// Read flame sensor value
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_sensor_line);
    if (value < 0) {
        perror("Error reading flame sensor value");
        return -1;
    }
    return value;
}

// Activate buzzer for 2 seconds
int activate_buzzer(void) {
    int ret;

    ret = gpiod_line_set_value(buzzer_line, 1); // Set HIGH
    if (ret < 0) {
        perror("Error setting buzzer HIGH");
        return -1;
    }
    usleep(2000000); // 2 seconds

    ret = gpiod_line_set_value(buzzer_line, 0); // Set LOW
    if (ret < 0) {
        perror("Error setting buzzer LOW");
        return -1;
    }

    return 0;
}

// Log event to file
int log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    if (t == NULL) {
        perror("Error getting local time");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file

    return 0;
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up resources.\n");

    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0); // Ensure buzzer is off
        gpiod_line_release(buzzer_line);
    }
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int flame_detected = 0;
    int prev_flame_state = 1; // Initialize to HIGH (no flame)
    int current_flame_state;
    int ret;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    // Log system start
    if (log_event("System started") != 0) {
        fprintf(stderr, "Error logging system start\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        current_flame_state = read_flame_sensor();
        if (current_flame_state < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        // Check for flame detection (LOW signal)
        if (current_flame_state == 0 && prev_flame_state == 1) {
            printf("Flame detected!\n");
            if (log_event("FLAME DETECTED") != 0) {
                fprintf(stderr, "Error logging flame detection\n");
            }
            if (activate_buzzer() != 0) {
                fprintf(stderr, "Error activating buzzer\n");
            }
            flame_detected = 1; // Set flag to prevent repeated logging
        } else if (current_flame_state == 1 && flame_detected == 1) {
            // Reset the flag when flame is no longer detected
