#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_TIME 200 // milliseconds

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a timestamp to the log file
int log_timestamp(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: Failed to write to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to toggle the LED state
void toggle_led(int current_state) {
    int new_state = !current_state;
    gpioWrite(LED_PIN, new_state);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int touch_state = 0; // 0 = not touched, 1 = touched
    int last_touch_state = 0;
    unsigned int last_tick = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_touch_state = gpioRead(TOUCH_PIN);

        if (current_touch_state != last_touch_state) {
            unsigned int current_tick = gpioTick();

            if (current_touch_state == 1 && last_touch_state == 0) { // Rising edge
                if (current_tick - last_tick > DEBOUNCE_TIME * 1000) { // Debounce
                    char *timestamp = get_iso8601_timestamp();
                    if (timestamp != NULL) {
                        if (log_timestamp(timestamp) != 0) {
                            fprintf(stderr, "Warning: Failed to log timestamp.\n");
                        }
                        free(timestamp);
                    } else {
                        fprintf(stderr, "Warning: Failed to get timestamp.\n");
                    }

                    toggle_led(touch_state);
                    touch_state = !touch_state;
                    last_tick = current_tick;
                }
            }
            last_touch_state = current_touch_state;
        }

        gpioDelay(10); // Poll every 10 milliseconds
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

