// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_event(int sensor_id, int state);
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} sensor_states_t;

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR1_GPIO);
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR1_GPIO);
        return 1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR2_GPIO);
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR2_GPIO);
        return 1;
    }

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR3_GPIO);
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR3_GPIO);
        return 1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return level;
}

// Function to log an event to the log file
int log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, state == 0 ? "Magnet Present" : "Magnet Removed");
        fflush(log_file); // Ensure data is written to the file immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }
}

