    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    sensor_states_t current_states, previous_states;
    previous_states.sensor1_state = -1; // Initialize to an invalid state
    previous_states.sensor2_state = -1;
    previous_states.sensor3_state = -1;

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping this iteration\n");
            gpioDelay(100); // Wait 100ms
            continue;
        }

        current_states.sensor1_state = sensor1_value;
        current_states.sensor2_state = sensor2_value;
        current_states.sensor3_state = sensor3_value;

        // Log events for sensor 1
        if (previous_states.sensor1_state != -1 && current_states.sensor1_state != previous_states.sensor1_state) {
            log_event(1, current_states.sensor1_state);
        }

        // Log events for sensor 2
        if (previous_states.sensor2_state != -1 && current_states.sensor2_state != previous_states.sensor2_state) {
            log_event(2, current_states.sensor2_state);
        }

        // Log events for sensor 3
        if (previous_states.sensor3_state != -1 && current_states.sensor3_state != previous_states.sensor3_state) {
            log_event(3, current_states.sensor3_state);
        }

        // Update previous states
        previous_states.sensor1_state = current_states.sensor1_state;
        previous_states.sensor2_state = current_states.sensor2_state;
        previous_states.sensor3_state = current_states.sensor3_state;

        gpioDelay(100); // Wait 100ms
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

