#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HR_REG 0x24
#define CONFIG_REG 0x03
#define EXPECTED_PART_ID 0x82
#define EXPECTED_HW_REV 0x01
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220
#define CSV_FILE "heart_rate.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t config_value;
} sensor_config_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *raw_hr);
float apply_moving_average(uint16_t new_value, float *history, int history_size, int *index);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(log_file, "%s: Received signal %d, terminating...\n", __func__, signal);
    fflush(log_file);
}

// Function to initialize the sensor
int initialize_sensor() {
    int retries = 3;
    int status;
    uint8_t part_id, hw_rev;

    // Read PART_ID
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (status >= 0) {
            part_id = (uint8_t)status;
            break;
        } else {
            fprintf(log_file, "%s: Error reading PART_ID, retrying... (%d retries left)\n", __func__, retries);
            fflush(log_file);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(log_file, "%s: Failed to read PART_ID after multiple retries.\n", __func__);
        fflush(log_file);
        return -1;
    }

    // Read HW_REV
    retries = 3;
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, HW_REV_REG);
        if (status >= 0) {
            hw_rev = (uint8_t)status;
            break;
        } else {
            fprintf(log_file, "%s: Error reading HW_REV, retrying... (%d retries left)\n", __func__, retries);
            fflush(log_file);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(log_file, "%s: Failed to read HW_REV after multiple retries.\n", __func__);
        fflush(log_file);
        return -1;
    }

    // Validate PART_ID and HW_REV
    if (part_id != EXPECTED_PART_ID || hw_rev != EXPECTED_HW_REV) {
        fprintf(log_file, "%s: Sensor initialization failed: PART_ID=0x%02X, HW_REV=0x%02X (Expected: 0x%02X, 0x%02X)\n",
                __func__, part_id, hw_rev, EXPECTED_PART_ID, EXPECTED_HW_REV);
        fflush(log_file);
        return -1;
    }

    // Configure the sensor (example: enable heart rate measurement)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01); // Example config value
        if (status == 0) {
            break;
        } else {
            fprintf(log_file, "%s: Error writing to config register, retrying... (%d retries left)\n", __func__, retries);
            fflush(log_file);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(log_file, "%s: Failed to write to config register after multiple retries.\n", __func__);
        fflush(log_file);
        return -1;
    }

    fprintf(log_file, "%s: Sensor initialized successfully.\n", __func__);
    fflush(log_file);
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *raw_hr) {
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, HR_REG);
        if (status >= 0) {
            *raw_hr = (uint16_t)status;
            return 0;
        } else {
            fprintf(log_file, "%s: Error reading HR data, retrying... (%d retries left)\n", __func__, retries);
            fflush(log_file);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(log_file, "%s: Failed to read HR data after multiple retries.\n", __func__);
    fflush(log_file);
    return -1;
}

// Function to apply moving average filter
float apply_moving_average(uint16_t new_value, float *history, int history_size, int *index) {
    float sum = 0.0;
    history[*index] = (float)new_value;
    *index = (*index + 1) % history_size;

    for (int i = 0; i < history_size; i++) {
        sum += history[i];
    }

    return sum / history_size;
}

// Function to validate BPM
int validate_bpm(float bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM);
}

// Function to log data to CSV file
int log_data(float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(log_file, "Error opening I2C bus: %d\n", i2c_handle);
        fflush(log_file);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(log_file, "Sensor initialization failed.\n");
        fflush(log_file);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Moving average filter variables
    float hr_history[MOVING_AVG_SIZE] = {0.0};
    int hr_index = 0;

    // Main loop
    while (!terminate) {
        uint16_t raw_hr;
        float filtered_hr;

        // Read sensor data
        if (read_sensor_data(&raw_hr) == 0) {
            // Apply moving average filter
            filtered_hr = apply_moving_average(raw_hr, hr_history, MOVING_AVG_SIZE, &hr_index);

            // Validate BPM
            if (validate_bpm(filtered_hr)) {
                // Log data
                log_data(filtered_hr);
            } else {
                fprintf(log_file, "Invalid BPM value: %.2f\n", filtered_hr);
                fflush(log_file);
            }
        } else {
            fprintf(log_file, "Failed to read sensor data.\n");
            fflush(log_file);
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

