#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the console and the log file
void log_message(const char *message) {
    char *timestamp = get_timestamp();
    char log_entry[100];

    snprintf(log_entry, sizeof(log_entry), "%s %s\n", timestamp, message);

    printf("%s", log_entry);

    if (log_file != NULL) {
        if (fputs(log_entry, log_file) == EOF) {
            perror("Error writing to log file");
        } else {
            fflush(log_file); // Ensure immediate write
        }
    }
}

int main() {
    int rc;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    int last_state = 1; // Initialize to HIGH (no flame)

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state == 0 && last_state == 1) {
            // Falling edge detected
            log_message("FLAME DETECTED");
        }

        last_state = current_state;
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

