#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define NUM_CHANNELS 8
const int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
const int output_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_lines[NUM_CHANNELS] = {NULL};
static struct gpiod_line *output_lines[NUM_CHANNELS] = {NULL};
static int counter = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensors(void);
int update_outputs(void);
int log_event(int channel);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO pins
int initialize_gpio(void) {
    int i;
    char *chipname = "gpiochip0";

    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Open sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            perror("Error getting sensor line");
            cleanup_gpio();
            return -1;
        }

        if (gpiod_line_request_input(sensor_lines[i], "touch_sensor", 0) < 0) {
            perror("Error requesting sensor line as input");
            cleanup_gpio();
            return -1;
        }
    }

    // Open output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output_lines[i]) {
            perror("Error getting output line");
            cleanup_gpio();
            return -1;
        }

        if (gpiod_line_request_output(output_lines[i], "touch_counter", 0) < 0) {
            perror("Error requesting output line as output");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Read sensor values
int read_sensors(void) {
    int i;
    int value;

    for (i = 0; i < NUM_CHANNELS; i++) {
        value = gpiod_line_get_value(sensor_lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor %d: %s\n", i + 1, strerror(errno));
            continue; // Skip to the next channel
        }
        if (value == 1) {
            return i + 1; // Return the channel number (1-8) if touched
        }
    }
    return 0; // No touch detected
}

// Update output pins
int update_outputs(void) {
    int i;
    int bit;

    for (i = 0; i < NUM_CHANNELS; i++) {
        bit = (counter >> i) & 1; // Extract the i-th bit from the counter
        if (gpiod_line_set_value(output_lines[i], bit) < 0) {
            fprintf(stderr, "Error setting output %d: %s\n", output_pins[i], strerror(errno));
        }
    }
    return 0;
}

// Log touch event
int log_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
