// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4);
void signal_handler(int signal);
int check_file_exists(const char *filename);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to check if the log file exists
int check_file_exists(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp != NULL) {
        fclose(fp);
        return 1; // File exists
    } else {
        return 0; // File does not exist
    }
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR1_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR2_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR3_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR3_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR4_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR4_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR4_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR4_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return 1; // Indicate error
    }
    fflush(fp); // Flush the buffer to ensure data is written
    return 0;      // Indicate success
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("tracking_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);
        int sensor4_value = read_sensor(SENSOR4_PIN);

        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1 || sensor4_value == -1) {
            fprintf(stderr, "Error reading sensor values, continuing...\n");
        } else {
            if (log_data(log_file, sensor1_value, sensor2_value, sensor3_value, sensor4_value) != 0) {
                fprintf(stderr, "Error logging data, continuing...\n");
            }
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

