    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d\n", pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to control the LED
int control_led(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to LED pin %d\n", pin);
        return -1; // Indicate error
    }
    return 0;
}

