int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    int result = fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
    if (result < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1; // Indicate error
    }

    fflush(fp); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

