        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;

        if (control_led(LED_PIN, led_state) != 0) {
            fprintf(stderr, "Error controlling LED, exiting...\n");
            break;
        }

        if (log_data(log_file, sensor1_value, sensor2_value, led_state) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    control_led(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

