#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MICROPHONE_PIN 4
#define LED_PIN 17

// Define sampling rate and LED duration
#define SAMPLING_PERIOD_US 125
#define LED_DURATION_MS 100

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(MICROPHONE_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set microphone pin to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin to output\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read microphone pin
        int level = gpioRead(MICROPHONE_PIN);

        // Check for peak event
        if (level == 1) {
            // Get current time
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                break; // Exit loop on error
            }

            // Print timestamp
            printf("%ld.%03ld\n", ts.tv_sec, ts.tv_nsec / 1000000);

            // Turn on LED
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                break; // Exit loop on error
            }

            // Wait for LED duration
            gpioDelay(LED_DURATION_MS * 1000); // Convert ms to us

            // Turn off LED
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                break; // Exit loop on error
            }
        }

        // Delay for sampling period
        gpioDelay(SAMPLING_PERIOD_US);
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

