#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read ALS data from Si1175
int read_als_data(int i2c_handle, uint16_t *als_value) {
    char buf[2];
    int result;

    // Read LSB
    result = i2cReadI2CBlockData(i2c_handle, SI1175_REG_ALS_VIS_DATA0, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }

    // Combine LSB and MSB
    *als_value = (buf[1] << 8) | buf[0];

    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t als_value;

        // Read ALS data
        if (read_als_data(i2c_handle, &als_value) == 0) {
            // Print raw sensor reading
            printf("ALS Raw Value: %u\n", als_value);
        } else {
            fprintf(stderr, "Failed to read ALS data. Retrying...\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

