    int tp1;
    int tp2;
    int tp3;
    int tp4;
    int tp5;
    int tp6;
    int tp7;
    int tp8;
};

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of a single GPIO pin
int read_gpio(int pin) {
    return gpioRead(pin);
}

// Function to format the output string with timestamp and sensor data
void format_output(char *buffer, size_t buffer_size, struct timespec ts, struct gpio_pins pins) {
    snprintf(buffer, buffer_size, "[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
             ts.tv_sec + ts.tv_nsec / 1000000000.0,
             read_gpio(pins.tp1),
             read_gpio(pins.tp2),
             read_gpio(pins.tp3),
             read_gpio(pins.tp4),
             read_gpio(pins.tp5),
             read_gpio(pins.tp6),
             read_gpio(pins.tp7),
             read_gpio(pins.tp8));
}

