#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define number of interpolation steps
#define NUM_STEPS 50

// Define transition duration (seconds)
#define TRANSITION_DURATION 5

// Structure to represent an RGB color
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating program...");
    terminate = 1;
}

// Function to generate a random hue (0-360 degrees)
int generate_random_hue() {
    return rand() % 361;
}

// Function to convert HSL to RGB
RGBColor hsl_to_rgb(int hue, float saturation, float lightness) {
    float c = (1 - fabs(2 * lightness - 1)) * saturation;
    float x = c * (1 - fabs(fmod(hue / 60.0, 2) - 1));
    float m = lightness - c / 2;

    float r = 0, g = 0, b = 0;

    if (hue >= 0 && hue < 60) {
        r = c; g = x; b = 0;
    } else if (hue >= 60 && hue < 120) {
        r = x; g = c; b = 0;
    } else if (hue >= 120 && hue < 180) {
        r = 0; g = c; b = x;
    } else if (hue >= 180 && hue < 240) {
        r = 0; g = x; b = c;
    } else if (hue >= 240 && hue < 300) {
        r = x; g = 0; b = c;
    } else {
        r = c; g = 0; b = x;
    }

    r = (r + m) * 255;
    g = (g + m) * 255;
    b = (b + m) * 255;

    RGBColor color;
    color.red = (int)r;
    color.green = (int)g;
    color.blue = (int)b;
    return color;
}

// Function to set the PWM duty cycle for each color channel
int set_rgb_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, red) < 0) {
        syslog(LOG_ERR, "Failed to set red PWM duty cycle");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green) < 0) {
        syslog(LOG_ERR, "Failed to set green PWM duty cycle");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue) < 0) {
        syslog(LOG_ERR, "Failed to set blue PWM duty cycle");
        return -1;
    }
    return 0;
}

// Function to perform linear interpolation between two RGB colors
int interpolate_color(RGBColor start_color, RGBColor end_color, int num_steps, int duration_seconds) {
    float red_diff   = (float)(end_color.red   - start_color.red)   / num_steps;
    float green_diff = (float)(end_color.green - start_color.green) / num_steps;
    float blue_diff  = (float)(end_color.blue  - start_color.blue)  / num_steps;

    float red_increment   = red_diff   / duration_seconds;
    float green_increment = green_diff / duration_seconds;
    float blue_increment  = blue_diff  / duration_seconds;

    float current_red   = start_color.red;
    float current_green = start_color.green;
    float current_blue  = start_color.blue;

    for (int i = 0; i < num_steps; ++i) {
        current_red   += red_increment;
        current_green += green_increment;
        current_blue  += blue_increment;

        // Clamp values to 0-255 range
        if (current_red   < 0)   current_red   = 0;
        if (current_red   > 255) current_red   = 255;
        if (current_green < 0)   current_green = 0;
        if (current_green > 255) current_green = 255;
        if (current_blue  < 0)   current_blue  = 0;
        if (current_blue  > 255) current_blue  = 255;

        if (set_rgb_color((int)current_red, (int)current_green, (int)current_blue) < 0) {
            syslog(LOG_ERR, "Failed to set color during interpolation");
            return -1;
        }

        gpioDelay(1000000 / num_steps); // Delay for 1/num_steps seconds (in microseconds)
    }

    return 0;
}

int main() {
    // Initialize syslog
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with /dev/urandom
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        closelog();
        return 1;
    }
    unsigned int seed;
    if (fread(&seed, sizeof(seed), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read seed from /dev/urandom");
        fclose(urandom);
        closelog();
        return 1;
    }
    fclose(urandom);
    srand(seed);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN to output mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN to output mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN to output mode");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for RED_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GREEN_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for BLUE_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set PWM range (0-255)
    if (gpioSetPWMrange(RED_PIN, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range for RED_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range for GREEN_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, 255) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range for BLUE_PIN");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate random hues
        int hue1 = generate_random_hue();
        int hue2 = generate_random_hue();

        // Convert hues to RGB colors
        RGBColor color1 = hsl_to_rgb(hue1, 1.0, 0.5);
        RGBColor color2 = hsl_to_rgb(hue2, 1.0, 0.5);

        // Perform color transition
        if (interpolate_color(color1, color2, NUM_STEPS, TRANSITION_DURATION) < 0) {
            syslog(LOG_ERR, "Color interpolation failed");
            break;
        }
    }

    // Turn off the LED
    set_rgb_color(0, 0, 0);

    // Release pigpio resources
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

