#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define MAX_LUX 1000.0
#define MIN_LUX 0.0
#define MAX_BRIGHTNESS 255
#define MIN_BRIGHTNESS 0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_lux();
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error configuring BH1750\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750
float read_lux() {
    int count;
    unsigned char data[2];

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    count = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (count != 2) {
        fprintf(stderr, "Error reading data from BH1750: %d\n", count);
        return -1.0;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2; // Convert to lux

    return lux;
}

// Map lux value to brightness level (0-255)
int map_lux_to_brightness(float lux) {
    // Clamp lux value to the defined range
    if (lux < MIN_LUX) {
        lux = MIN_LUX;
    } else if (lux > MAX_LUX) {
        lux = MAX_LUX;
    }

    // Use a logarithmic mapping
    float normalized_lux = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    float log_lux = log10(normalized_lux * 9 + 1) / log10(10); // Scale to 0-1, then log10
    int brightness = (int)(log_lux * MAX_BRIGHTNESS);

    return brightness;
}

// Set brightness of all LEDs in the WS2812B strip
void set_led_brightness(int brightness) {
    // WS2812B timing constants (in microseconds)
    const int T0H = 350;  // 0 bit: 0.35us high, 0.8us low
    const int T0L = 800;  // 0 bit: 0.35us high, 0.8us low
    const int T1H = 700;  // 1 bit: 0.7us high, 0.6us low
    const int T1L = 600;  // 1 bit: 0.7us high, 0.6us low
    const int RESET = 50000; // Reset pulse: 50us

    // Calculate the number of bits needed to represent the brightness
    int num_bits = (int)log2(MAX_BRIGHTNESS) + 1;

    // Create the bitstream
    unsigned int bitstream[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) {
        bitstream[i] = 0;
        for (int j = 0; j < num_bits; j++) {
            bitstream[i] <<= 1;
            if ((brightness >> j) & 1) {
                bitstream[i] |= 1;
            }
        }
    }

    // Generate the PWM signal
    gpioWaveClear();
    gpioPulse_t pulse[NUM_LEDS * num_bits * 2 + 1]; // +1 for reset pulse
    int pulse_index = 0;

    for (int i = 0; i < NUM_LEDS; i++) {
        for (int j = num_bits - 1; j >= 0; j--) {
            if ((bitstream[i] >> j) & 1) {
                // 1 bit
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = T1H;
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
                pulse[pulse_index].usDelay = T1L;
                pulse_index++;
            } else {
                // 0 bit
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = T0H;
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
                pulse[pulse_index].usDelay = T0L;
                pulse_index++;
            }
        }
    }

    // Add reset pulse
    pulse[pulse_index].gpioOn = 0;
    pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
    pulse[pulse_index].usDelay = RESET;
    pulse_index++;

    gpioWaveAddGeneric(pulse_index, pulse);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT); // Send wave once
        while (gpioWaveTxBusy()) {
            gpioDelay(100); // Wait for wave to finish
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWaveClear();
    gpioTerminate();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting main loop...\n");

    while (!terminate) {
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying I2C initialization...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        set_led_brightness(brightness);

        gpioDelay(100000); // 100ms delay
    }

    cleanup();
    return 0;
}

