    const int T0H = 350;  // 0 bit: 0.35us high, 0.8us low
    const int T0L = 800;  // 0 bit: 0.35us high, 0.8us low
    const int T1H = 700;  // 1 bit: 0.7us high, 0.6us low
    const int T1L = 600;  // 1 bit: 0.7us high, 0.6us low
    const int RESET = 50000; // Reset pulse: 50us

    // Calculate the number of bits needed to represent the brightness
    int num_bits = (int)log2(MAX_BRIGHTNESS) + 1;

    // Create the bitstream
    unsigned int bitstream[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) {
        bitstream[i] = 0;
        for (int j = 0; j < num_bits; j++) {
            bitstream[i] <<= 1;
            if ((brightness >> j) & 1) {
                bitstream[i] |= 1;
            }
        }
    }

    // Generate the PWM signal
    gpioWaveClear();
    gpioPulse_t pulse[NUM_LEDS * num_bits * 2 + 1]; // +1 for reset pulse
    int pulse_index = 0;

    for (int i = 0; i < NUM_LEDS; i++) {
        for (int j = num_bits - 1; j >= 0; j--) {
            if ((bitstream[i] >> j) & 1) {
                // 1 bit
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = T1H;
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
                pulse[pulse_index].usDelay = T1L;
                pulse_index++;
            } else {
                // 0 bit
                pulse[pulse_index].gpioOn = (1 << WS2812B_GPIO);
                pulse[pulse_index].gpioOff = 0;
                pulse[pulse_index].usDelay = T0H;
                pulse_index++;

                pulse[pulse_index].gpioOn = 0;
                pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
                pulse[pulse_index].usDelay = T0L;
                pulse_index++;
            }
        }
    }

    // Add reset pulse
    pulse[pulse_index].gpioOn = 0;
    pulse[pulse_index].gpioOff = (1 << WS2812B_GPIO);
    pulse[pulse_index].usDelay = RESET;
    pulse_index++;

    gpioWaveAddGeneric(pulse_index, pulse);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT); // Send wave once
        while (gpioWaveTxBusy()) {
            gpioDelay(100); // Wait for wave to finish
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWaveClear();
    gpioTerminate();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting main loop...\n");

    while (!terminate) {
        float lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying I2C initialization...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        set_led_brightness(brightness);

        gpioDelay(100000); // 100ms delay
    }

    cleanup();
    return 0;
}

