// Configuration
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define NUM_LEDS 10
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_BRIGHTNESS 255

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int spi_transfer(int fd, uint8_t *data, int len);
void apa102_send_frame(int fd, uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red);
void apa102_start_frame(int fd);
void apa102_end_frame(int fd);
void set_led_brightness(int fd, int brightness);
void signal_handler(int sig);

// I2C read word function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write error");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read error");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *data, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)NULL, // We are only writing, not reading
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer error");
        return -1;
    }
    return 0;
}

// APA102 send frame function
void apa102_send_frame(int fd, uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red) {
    uint8_t data[4];
    data[0] = 0xE0 | brightness; // Global brightness
    data[1] = blue;
    data[2] = green;
    data[3] = red;
    if (spi_transfer(fd, data, 4) != 0) {
        fprintf(stderr, "Error sending APA102 frame\n");
    }
}

// APA102 start frame function
void apa102_start_frame(int fd) {
    uint8_t data[4] = {0x00, 0x00, 0x00, 0x00};
    if (spi_transfer(fd, data, 4) != 0) {
        fprintf(stderr, "Error sending APA102 start frame\n");
    }
}

// APA102 end frame function
void apa102_end_frame(int fd) {
    uint8_t data[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    if (spi_transfer(fd, data, 4) != 0) {
        fprintf(stderr, "Error sending APA102 end frame\n");
    }
}

// Set LED brightness function
void set_led_brightness(int fd, int brightness) {
    apa102_start_frame(fd);
    for (int i = 0; i < NUM_LEDS; i++) {
        apa102_send_frame(fd, brightness, 0, 0, 0); // Example: all LEDs white
    }
    apa102_end_frame(fd);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BH1750
    if (i2c_write_byte(i2c_fd, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) != 0) {
        fprintf(stderr, "Error initializing BH1750\n");
        close(i2c_fd);
        return 1;
    }

    // Open SPI bus
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI bus");
        close(i2c_fd);
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read light level
        int light_level = i2c_read_word(i2c_fd, 0x00);
        if (light_level < 0) {
            fprintf(stderr, "Error reading light level, retrying...\n");
            usleep(100000); // 100ms
            continue;
        }

        // Scale brightness
        float brightness_float = (float)light_level / 65535.0 * MAX_BRIGHTNESS;
        int brightness = (int)brightness_float;

        // Set LED brightness
        set_led_brightness(spi_fd, brightness);

        // Wait
        usleep(120000); // 120ms
    }

    // Turn off LEDs
    set_led_brightness(spi_fd, 0);

    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

