#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x46
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define NUM_LEDS 10
#define FADE_DURATION_MS 500

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
int i2c_handle_3 = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
float average_lux(float lux1, float lux2, float lux3);
void set_apa102_brightness(int spi_handle, float brightness);
void fade_apa102(int spi_handle, float target_brightness);
void signal_handler(int signal);

// Function to read light intensity from BH1750 sensor
int read_bh1750(int i2c_handle) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Invalid I2C handle.\n");
        return -1;
    }

    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (%d).\n", result);
        return -1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2; // BH1750 datasheet conversion
    return (int)lux;
}

// Function to average light intensity readings
float average_lux(float lux1, float lux2, float lux3) {
    int valid_count = 0;
    float sum = 0.0;

    if (lux1 >= 0) {
        sum += lux1;
        valid_count++;
    }
    if (lux2 >= 0) {
        sum += lux2;
        valid_count++;
    }
    if (lux3 >= 0) {
        sum += lux3;
        valid_count++;
    }

    if (valid_count == 0) {
        return 0.0; // No valid readings
    }

    return sum / valid_count;
}

// Function to set APA102 LED strip brightness
void set_apa102_brightness(int spi_handle, float brightness) {
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Invalid SPI handle.\n");
        return;
    }

    // APA102 frame: start frame (4 bytes 0x00), LED data (4 bytes per LED), end frame (4 bytes 0xFF)
    char frame[4 + NUM_LEDS * 4 + 4];
    int i;

    // Start frame
    frame[0] = 0x00;
    frame[1] = 0x00;
    frame[2] = 0x00;
    frame[3] = 0x00;

    // LED data
    for (i = 0; i < NUM_LEDS; i++) {
        frame[4 + i * 4 + 0] = 0xE0 | (int)(brightness * 31); // Global brightness (0xE0 to 0xFF)
        frame[4 + i * 4 + 1] = 0x00; // Blue
        frame[4 + i * 4 + 2] = 0x00; // Green
        frame[4 + i * 4 + 3] = 0x00; // Red
    }

    // End frame
    frame[4 + NUM_LEDS * 4 + 0] = 0xFF;
    frame[4 + NUM_LEDS * 4 + 1] = 0xFF;
    frame[4 + NUM_LEDS * 4 + 2] = 0xFF;
    frame[4 + NUM_LEDS * 4 + 3] = 0xFF;

    int result = spiWrite(spi_handle, frame, sizeof(frame));
    if (result != sizeof(frame)) {
        fprintf(stderr, "Error: SPI write failed (%d).\n", result);
    }
}

// Function to fade the APA102 LED strip brightness
void fade_apa102(int spi_handle, float target_brightness) {
    // Implement a simple linear fade
    float current_brightness = 0.0; // Assume initial brightness is 0
    float brightness_increment = (target_brightness - current_brightness) / (FADE_DURATION_MS / 10.0); // 10 steps per ms
    float brightness = current_brightness;

    for (int i = 0; i < 10; i++) {
        brightness += brightness_increment;
        if (brightness < 0.0) brightness = 0.0;
        if (brightness > 1.0) brightness = 1.0;
        set_apa102_brightness(spi_handle, brightness);
        gpioDelay(10); // 10ms delay
    }
    set_apa102_brightness(spi_handle, target_brightness); // Ensure final brightness is correct
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle_1 = i2cOpen(I2C_BUS, BH1750_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device 1 at address 0x%02X.\n", BH1750_ADDR_1);
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, BH1750_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device 2 at address 0x%02X.\n", BH1750_ADDR_2);
    }

    i2c_handle_3 = i2cOpen(I2C_BUS, BH1750_ADDR_3, 0);
    if (i2c_handle_3 < 0) {
        fprintf(stderr, "Error: Could not open I2C device 3 at address 0x%02X.\n", BH1750_ADDR_3);
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel.\n");
        // Attempt to close I2C handles before exiting
        if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
        if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
        if (i2c_handle_3 >= 0) i2cClose(i2c_handle_3);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read light intensity from sensors
        int lux1 = (i2c_handle_1 >= 0) ? read_bh1750(i2c_handle_1) : -1;
        int lux2 = (i2c_handle_2 >= 0) ? read_bh1750(i2c_handle_2) : -1;
        int lux3 = (i2c_handle_3 >= 0) ? read_bh1750(i2c_handle_3) : -1;

        // Average light intensity
        float avg_lux = average_lux((float)lux1, (float)lux2, (float)lux3);

        // Map light intensity to brightness (0-1)
        float brightness = avg_lux / 1000.0; // Example mapping
        if (brightness < 0.0) brightness = 0.0;
        if (brightness > 1.0) brightness = 1.0;

        // Fade the LED strip
        fade_apa102(spi_handle, brightness);

        // Delay
        gpioDelay(100); // 100ms
    }

    // Cleanup
    set_apa102_brightness(spi_handle, 0.0); // Turn off LED strip
    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    if (i2c_handle_3 >= 0) i2cClose(i2c_handle_3);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

