#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <time.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// WS2812B GPIO pin
#define WS2812B_PIN 18

// Gamma correction parameters
#define GAMMA 2.2
#define MAX_BRIGHTNESS 255.0

// I2C retry parameters
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Signal handler flag
volatile sig_atomic_t terminate = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int veml7700_init();
float read_veml7700_lux();
uint8_t gamma_correct(float lux);
void set_led_brightness(uint8_t brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// VEML7700 initialization function
int veml7700_init() {
    // Configure the VEML7700 for continuous mode, gain 1/8, integration time 100ms
    // Refer to the VEML7700 datasheet for the correct configuration value
    uint16_t config_value = 0x0000; // Example configuration, adjust as needed
    config_value |= (0x02 << 11); // Integration time: 100ms
    config_value |= (0x01 << 6);  // Gain: 1/8
    config_value |= (0x00 << 1);  // Power saving mode: off
    config_value |= (0x01 << 0);  // Enable ALS

    char buf[3];
    buf[0] = VEML7700_ALS_CONF;
    buf[1] = config_value & 0xFF;
    buf[2] = (config_value >> 8) & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read ambient light data from VEML7700
float read_veml7700_lux() {
    char buf[2];
    int result;
    int retries = 0;

    buf[0] = VEML7700_ALS;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to VEML7700 ALS register (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading from VEML7700 ALS register (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        uint16_t als_data = (buf[1] << 8) | buf[0];
        // Convert raw data to lux (adjust as needed based on gain and integration time)
        // This is a simplified conversion, refer to the datasheet for the correct formula
        float lux = (float)als_data * 0.0576; // Example conversion factor
        return lux;
    }

    fprintf(stderr, "Failed to read VEML7700 data after %d retries.\n", MAX_RETRIES);
    return -1.0; // Indicate error
}

// Function to apply gamma correction
uint8_t gamma_correct(float lux) {
    float brightness = pow(lux / 1000.0, GAMMA) * MAX_BRIGHTNESS; // Assuming max lux is 1000
    if (brightness > MAX_BRIGHTNESS) {
        brightness = MAX_BRIGHTNESS;
    }
    return (uint8_t)brightness;
}

// Function to set the WS2812B LED strip brightness using bit-banging
void set_led_brightness(uint8_t brightness) {
    // WS2812B timing requirements:
    // 0: 0.4us low, 0.85us high
    // 1: 0.7us low, 0.6us high
    // Reset: 50us low, 20us high

    // Calculate the number of bits needed to represent the brightness level
    int num_bits = 8; // Assuming 8-bit brightness

    // Generate the bit sequence for the given brightness level
    uint8_t bit_sequence = brightness; // Use the brightness value directly as the bit sequence

    // Bit-banging the data line
    for (int i = 0; i < num_bits; i++) {
        if ((bit_sequence >> i) & 1) {
            // Send a '1' bit
            gpioWrite(WS2812B_PIN, 1);
            gpioDelay(0.7); // 0.7us
            gpioWrite(WS2812B_PIN, 0);
            gpioDelay(0.6); // 0.6us
        } else {
            // Send a '0' bit
            gpioWrite(WS2812B_PIN, 1);
            gpioDelay(0.4); // 0.4us
            gpioWrite(WS2812B_PIN, 0);
            gpioDelay(0.85); // 0.85us
        }
    }

    // Send reset pulse (at least 50us low, 20us high)
    gpioWrite(WS2812B_PIN, 0);
    gpioDelay(50); // 50us
    gpioWrite(WS2812B_PIN, 1);
    gpioDelay(20); // 20us
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700
    if (veml7700_init() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ambient light
        float lux = read_veml7700_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value\n");
        } else {
            // Apply gamma correction
            uint8_t brightness = gamma_correct(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            // Print lux and brightness values
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        }

        // Pause for 200ms
        gpioDelay(200 * 1000); // Delay in microseconds
    }

    // Cleanup
    set_led_brightness(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

