#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define NUM_SAMPLES 5
#define SAMPLE_DELAY_MS 100
#define LED_BLINK_DELAY_MS 500
#define LED_ERROR_BLINK_DELAY_MS 100
#define BUZZER_SHORT_MS 200
#define BUZZER_LONG_MS 600
#define BUZZER_ERROR_REPEATS 3
#define MAIN_LOOP_DELAY_MS 50

// Global variables
static volatile int running = 1;

// Function prototypes
int read_flame_sensor();
void activate_buzzer();
void deactivate_buzzer();
void activate_led();
void deactivate_led();
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
        deactivate_buzzer();
        deactivate_led();
        gpioTerminate();
        exit(0);
    }
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // HIGH to activate
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0); // LOW to deactivate
}

// Function to activate the LED
void activate_led() {
    gpioWrite(LED_PIN, 1); // HIGH to activate
}

// Function to deactivate the LED
void deactivate_led() {
    gpioWrite(LED_PIN, 0); // LOW to deactivate
}

// Function to log events with timestamps
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, event);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set FLAME_SENSOR_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Self-test
    printf("Starting self-test...\n");
    int flame_detected = 0;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < NUM_SAMPLES; j++) {
            if (read_flame_sensor() == 0) {
                flame_detected = 1;
            }
            gpioDelay(SAMPLE_DELAY_MS * 1000); // Convert ms to microseconds
        }
        if (flame_detected) {
            break;
        }
        activate_led();
        gpioDelay(LED_BLINK_DELAY_MS * 1000);
        deactivate_led();
        gpioDelay(LED_BLINK_DELAY_MS * 1000);
    }

    if (flame_detected) {
        printf("Flame detected during self-test.\n");
        log_event("ERROR: Flame detected during self-test.");
        // Error signal
        for (int i = 0; i < BUZZER_ERROR_REPEATS; i++) {
            activate_buzzer();
            gpioDelay(BUZZER_SHORT_MS * 1000);
            deactivate_buzzer();
            gpioDelay(BUZZER_SHORT_MS * 1000);
            activate_buzzer();
            gpioDelay(BUZZER_LONG_MS * 1000);
            deactivate_buzzer();
            gpioDelay(BUZZER_SHORT_MS * 1000);
        }
        deactivate_led();
        gpioTerminate();
        return 1;
    } else {
        printf("Self-test passed.\n");
