#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0
#define MIN_LUX 1000.0
#define MAX_LUX 2000.0

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
float read_bh1750();
void add_to_buffer(float lux);
float calculate_average();
void set_led_frequency(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Set BH1750 to continuous high-resolution mode
    uint8_t mode = CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &mode, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750
float read_bh1750() {
    uint8_t buffer[2];
    int result;

    result = read(i2c_fd, buffer, 2);
    if (result != 2) {
        perror("Error reading from I2C device");
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// Add lux value to circular buffer
void add_to_buffer(float lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average lux value from circular buffer
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Set LED frequency based on lux value
void set_led_frequency(float lux) {
    float frequency = MIN_FREQUENCY + (lux - MIN_LUX) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_LUX - MIN_LUX);
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    }
    if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    int period_us = (int)(1000000.0 / frequency); // Period in microseconds
    int duty_cycle_us = period_us / 2; // 50% duty cycle

    gpioWaveClear();

    gpioPulse_t pulse[2];
    pulse[0].gpioOn = (1 << GPIO_LED);
    pulse[0].gpioOff = 0;
    pulse[0].usDelay = duty_cycle_us;

    pulse[1].gpioOn = 0;
    pulse[1].gpioOff = (1 << GPIO_LED);
    pulse[1].usDelay = period_us - duty_cycle_us;

    gpioWaveAddGeneric(2, pulse);

    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_REPEAT);
        while (gpioWaveTxBusy()) {
            usleep(100);
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Error creating wave: %d\n", wave_id);
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWaveTxStop();
    gpioSetMode(GPIO_LED, PI_INPUT); // Set back to input to avoid leaving the pin high
    gpioTerminate();
    close(i2c_fd);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer with 0.0
    for (int i = 0; i < BUFFER_SIZE; i++) {
        lux_buffer[i] = 0.0;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting light sensor program...\n");

    while (!terminate) {
        float lux = read_bh1750();
        if (lux < 0) {
            fprintf(stderr, "Error reading BH1750, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        add_to_buffer(lux);
        float average_lux = calculate_average();

        printf("Lux: %.2f, Average Lux: %.2f\n", lux, average_lux);

        set_led_frequency(average_lux);

        sleep(1);
    }

    cleanup();
    return 0;
}

