#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>
#include <unistd.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Function to shift out data to the 74HC595
void shiftOut(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the current bit
        digitalWrite(DATA_PIN, (data >> (7 - i)) & 0x01);

        // Clock high
        digitalWrite(CLOCK_PIN, HIGH);
        delayMicroseconds(1); // Small delay for clock stability

        // Clock low
        digitalWrite(CLOCK_PIN, LOW);
        delayMicroseconds(1); // Small delay for clock stability
    }

    // Latch the data
    digitalWrite(LATCH_PIN, HIGH);
    delayMicroseconds(1); // Small delay for latch stability
    digitalWrite(LATCH_PIN, LOW);
}

int main() {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi.\n");
        return 1;
    }

    // Set pin modes
    pinMode(DATA_PIN, OUTPUT);
    pinMode(CLOCK_PIN, OUTPUT);
    pinMode(LATCH_PIN, OUTPUT);

    // Define the pattern for digit '5' (common cathode)
    unsigned char digit5_pattern = 0b00100100; // Example pattern, adjust as needed

    // Main loop
    while (1) {
        // Shift out the digit '5' pattern
        shiftOut(digit5_pattern);

        // Wait 500ms
        delay(500);

        // Shift out all zeros to turn off the display
        shiftOut(0x00);

        // Wait 500ms
        delay(500);
    }

    return 0;
}

