#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;

// Signal handler function
void signal_handler(int sig)
{
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to blink the LED
void blink_led(struct gpiod_line *led_line)
{
    int ret;
    struct timespec on_time = {1, 0};  // 1 second
    struct timespec off_time = {1, 0}; // 1 second

    while (program_running) {
        // Turn LED on
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting LED value: %d\n", ret);
            break;
        }
        nanosleep(&on_time, NULL);

        // Turn LED off
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting LED value: %d\n", ret);
            break;
        }
        nanosleep(&off_time, NULL);
    }
}

// Function to wait for button press
int wait_for_button_press(struct gpiod_line *button_line)
{
    int ret;
    struct timespec timeout = {1, 0}; // 1 second timeout

    ret = gpiod_line_event_wait(button_line, &timeout);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for button event: %d\n", ret);
        return -1; // Indicate error
    } else if (ret == 0) {
        // Timeout occurred
        return 0; // Indicate timeout
    } else {
        // Event occurred
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error reading button event: %d\n", ret);
            return -1; // Indicate error
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            return 1; // Indicate button press
        } else {
            return 0; // Should not happen, but handle it anyway
        }
    }
}

int main()
{
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %d\n", GPIOCHIP, -1);
        return 1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line: %d\n", -1);
        goto cleanup_chip;
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output: %d\n", ret);
        goto cleanup_led_line;
    }

    // Request button line as input with pull-up and falling edge detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting button line: %d\n", -1);
        goto cleanup_led_line;
    }

    ret = gpiod_line_request_input(button_line, "blink_button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting button line as input: %d\n", ret);
        goto cleanup_button_line;
    }

    ret = gpiod_line_request_event(button_line, "blink_button", GPIOD_LINE_EDGE_FALLING);
    if (ret < 0) {
        fprintf(stderr, "Error requesting button line event: %d\n", ret);
        goto cleanup_button_line;
    }

    // Blink LED in a separate thread (simulated with threads)
    // In a real application, you would use pthreads or similar.
    // For simplicity, we'll just call the function directly here.
    blink_led(led_line);

    // Wait for button press
    printf("Waiting for button press...\n");
    ret = wait_for_button_press(button_line);
    if (ret < 0) {
        fprintf(stderr, "Error waiting for button press, exiting.\n");
        goto cleanup_button_line;
    } else if (ret == 1) {
        printf("Button pressed! Stopping blink and exiting.\n");
    } else {
        printf("Timeout waiting for button press, exiting.\n");
    }

    // Cleanup
    program_running = 0; // Ensure LED blinking stops
    ret = gpiod_line_set_value(led_line, 0); // Turn off LED
    if (ret < 0) {
        fprintf(stderr, "Error turning off LED: %d\n", ret);
    }

cleanup_button_line:
    ret = gpiod_line_release(button_line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing button line: %d\n", ret);
    }

cleanup_led_line:
    ret = gpiod_line_release(led_line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing LED line: %d\n", ret);
    }

cleanup_chip:
    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        fprintf(stderr, "Error closing GPIO chip: %d\n", ret);
    }

    return 0;
}

