// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Configure button pin as input with pull-down resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on button pin\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Check if button is pressed
        if (gpioRead(BUTTON_PIN) == 1) {
            // Blink LED while button is pressed
            gpioWrite(LED_PIN, 1); // Turn LED on
            gpioDelay(500);        // Wait 500ms
            gpioWrite(LED_PIN, 0); // Turn LED off
            gpioDelay(500);        // Wait 500ms
        } else {
            // Ensure LED is off when button is not pressed
            gpioWrite(LED_PIN, 0);
        }
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    return 0;
}

