#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// PWM period (seconds)
#define PWM_PERIOD (1.0 / PWM_FREQUENCY)

// Function prototypes
void set_color(int red, int green, int blue);
void generate_random_color(int *red, int *green, int *blue);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RED_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GREEN_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BLUE_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int red, green, blue;

    // Main loop
    while (program_running) {
        // Generate random color values
        generate_random_color(&red, &green, &blue);

        // Set the color of the LED
        set_color(red, green, blue);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to set the color of the RGB LED using software PWM
void set_color(int red, int green, int blue) {
    // Calculate PWM duty cycles for each color channel
    float red_duty_cycle = (float)red / 100.0;
    float green_duty_cycle = (float)green / 100.0;
    float blue_duty_cycle = (float)blue / 100.0;

    // Calculate PWM on/off times for each color channel
    int red_on_time = (int)(red_duty_cycle * PWM_PERIOD * 1000000); // in microseconds
    int green_on_time = (int)(green_duty_cycle * PWM_PERIOD * 1000000); // in microseconds
    int blue_on_time = (int)(blue_duty_cycle * PWM_PERIOD * 1000000); // in microseconds

    // PWM loop
    for (int i = 0; i < PWM_PERIOD * 1000000; ++i) {
        if (i < red_on_time) {
            gpioWrite(RED_PIN, 0); // Red ON
        } else {
            gpioWrite(RED_PIN, 1); // Red OFF
        }

        if (i < green_on_time) {
            gpioWrite(GREEN_PIN, 0); // Green ON
        } else {
            gpioWrite(GREEN_PIN, 1); // Green OFF
        }

        if (i < blue_on_time) {
            gpioWrite(BLUE_PIN, 0); // Blue ON
        } else {
            gpioWrite(BLUE_PIN, 1); // Blue OFF
        }

        gpioDelay(1); // Small delay to achieve 100Hz
    }
}

// Function to generate random color values
void generate_random_color(int *red, int *green, int *blue) {
    *red = rand() % 101;   // Random value between 0 and 100
    *green = rand() % 101; // Random value between 0 and 100
    *blue = rand() % 101;  // Random value between 0 and 100
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
}

