                log_data(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer, retrying...\n");
        }

        gpioDelay(100000); // 100ms delay (10Hz sampling)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

