#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define LED_GPIO 18
#define PWM_FREQ 1000 // Hz
#define PWM_RANGE 1000 // 0-1000 for 0-100% duty cycle
#define SAMPLE_INTERVAL_MS 500

// ADPD188BI Register Addresses
#define ADPD188BI_ALS_LSB 0x00
#define ADPD188BI_ALS_MSB 0x01
#define ADPD188BI_RED_LSB 0x02
#define ADPD188BI_RED_MSB 0x03
#define ADPD188BI_GREEN_LSB 0x04
#define ADPD188BI_GREEN_MSB 0x05
#define ADPD188BI_BLUE_LSB 0x06
#define ADPD188BI_BLUE_MSB 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adpd188bi_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void control_led(uint16_t als);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to read data from ADPD188BI
int read_adpd188bi_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[8];
    int result;

    // Read ALS data
    result = i2cReadI2CBlockData(i2c_handle, ADPD188BI_ALS_LSB, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading ADPD188BI data: %s\n", strerror(errno));
        return -1;
    }

    *als = (uint16_t)buf[1] << 8 | (uint16_t)buf[0];
    *red = (uint16_t)buf[3] << 8 | (uint16_t)buf[2];
    *green = (uint16_t)buf[5] << 8 | (uint16_t)buf[4];
    *blue = (uint16_t)buf[7] << 8 | (uint16_t)buf[6];

    return 0;
}

// Function to log data to CSV file
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control LED brightness using PWM
void control_led(uint16_t als) {
    // Map ALS value to PWM duty cycle (0-1000)
    int duty_cycle = (int)(((float)als / 65535.0) * PWM_RANGE);

    // Limit duty cycle to 0-1000
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(LED_GPIO, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off LED
    gpioPWM(LED_GPIO, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_adpd188bi_data(&sensor_data.als, &sensor_data.red, &sensor_data.green, &sensor_data.blue) == 0) {
            // Log data
            log_data(sensor_data.als, sensor_data.red, sensor_data.green, sensor_data.blue);

            // Control LED brightness
            control_led(sensor_data.als);
        } else {
            fprintf(stderr, "Retrying in 100ms...\n");
            gpioDelay(100); // Retry after 100ms
            continue;
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

