#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_STATUS 0x00
#define FXOS8700CQ_OUT_X_MSB 0x01

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_fxos8700cq();
sensor_data_t read_sensor_data();
float calculate_magnitude(sensor_data_t data);
void log_impact(sensor_data_t data, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X (expected 0xC7)\n", who_am_i);
        return -1;
    }
    printf("FXOS8700CQ WHO_AM_I value: 0x%02X\n", who_am_i);

    // Set to standby mode
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error setting standby mode\n");
        return -1;
    }

    // Configure for ±2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error configuring range\n");
        return -1;
    }

    // Set to active mode with 200 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x01 | (0x03 << 3)) < 0) { // Active mode, 200 Hz ODR
        fprintf(stderr, "Error setting active mode and ODR\n");
        return -1;
    }

    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char raw_data[6];

    // Read 6 bytes of data (X_MSB, X_LSB, Y_MSB, Y_LSB, Z_MSB, Z_LSB)
    if (i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }

    // Combine MSB and LSB for each axis
    data.x = (int16_t)((raw_data[0] << 8) | raw_data[1]) >> 2;
    data.y = (int16_t)((raw_data[2] << 8) | raw_data[3]) >> 2;
    data.z = (int16_t)((raw_data[4] << 8) | raw_data[5]) >> 2;

    return data;
}

// Calculate acceleration magnitude
float calculate_magnitude(sensor_data_t data) {
    float x = (float)data.x / 4096.0; // Convert to g (assuming ±2g range)
    float y = (float)data.y / 4096.0;
    float z = (float)data.z / 4096.0;
    return sqrt(x * x + y * y + z * z);
}

// Log impact data to file
void log_impact(sensor_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, (float)data.x, (float)data.y, (float)data.z, magnitude);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_fxos8700cq() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        float magnitude = calculate_magnitude(data);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(data, magnitude);
            printf("Impact detected! Magnitude: %.3f g\n", magnitude);
        }

        gpioDelay(50); // 50 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

