#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDRESS 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SAMPLE_RATE 20 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds
#define CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD 50.0 // dps
#define GYRO_SENSITIVITY 0.00875 // dps/digit

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int init_i2c();
int init_gyro();
int calibrate_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void apply_calibration(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
void log_data(float calibrated_x, float calibrated_y, float calibrated_z);
void check_alert(float calibrated_x, float calibrated_y, float calibrated_z);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize gyroscope
int init_gyro() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%X (expected 0x%X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 200Hz ODR, enable all axes)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", i2c_handle);
        return -1;
    }

    // Configure CTRL_REG4 (Full scale selection, 245 dps)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Calibrate gyroscope
int calibrate_gyro() {
    int16_t x, y, z;
    long x_sum = 0, y_sum = 0, z_sum = 0;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&x, &y, &z) != 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return -1;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        gpioDelay(1000); // 1ms delay
    }

    x_offset = (float)x_sum / CALIBRATION_SAMPLES;
    y_offset = (float)y_sum / CALIBRATION_SAMPLES;
    z_offset = (float)z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);
    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", i2c_handle);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Apply calibration offsets
void apply_calibration(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x - x_offset;
    *calibrated_y = (float)y - y_offset;
    *calibrated_z = (float)z - z_offset;

    *calibrated_x *= GYRO_SENSITIVITY;
    *calibrated_y *= GYRO_SENSITIVITY;
    *calibrated_z *= GYRO_SENSITIVITY;
}

// Log data to file
void log_data(float calibrated_x, float calibrated_y, float calibrated_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check for alert condition
void check_alert(float calibrated_x, float calibrated_y, float calibrated_z) {
    if (fabs(calibrated_x) > ALERT_THRESHOLD || fabs(calibrated_y) > ALERT_THRESHOLD || fabs(calibrated_z) > ALERT_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        fprintf(log_file, "%s,ALERT: X=%.2f, Y=%.2f, Z=%.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z);
        fflush(log_file);
        fprintf(stderr, "ALERT: X=%.2f, Y=%.2f, Z=%.2f\n", calibrated_x, calibrated_y, calibrated_z);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate gyroscope
    if (calibrate_gyro() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float calibrated_x, calibrated_y, calibrated_z;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            apply_calibration(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);
            log_data(calibrated_x, calibrated_y, calibrated_z);
            check_alert(calibrated_x, calibrated_y, calibrated_z);
        } else {
            fprintf(stderr, "Error reading gyro data in main loop\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

