#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

// LSM303DLHC register addresses
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A  0x28
#define LSM303_MAG_MR_REG_M     0x02
#define LSM303_MAG_OUT_X_H_M    0x03

// Global variables
int i2c_handle_accel, i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_accel_data(int16_t *x, int16_t *y, int16_t *z);
int read_mag_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t mag_x, int16_t mag_y, int16_t mag_z, float accel_x, float accel_y, float accel_z);
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C device for accelerometer: %d\n", i2c_handle_accel);
        return -1;
    }

    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        return -1;
    }

    // Configure accelerometer: 100Hz, normal mode, all axes enabled
    if (i2cWriteByteData(i2c_handle_accel, LSM303_ACCEL_CTRL_REG1_A, 0x67) < 0) {
        fprintf(stderr, "Error writing to accelerometer control register\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        return -1;
    }

    // Configure magnetometer: continuous conversion mode
    if (i2cWriteByteData(i2c_handle_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer mode register\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to read magnetometer data
int read_mag_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, LSM303_MAG_OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate tilt-compensated heading
float calculate_heading(int16_t mag_x, int16_t mag_y, int16_t mag_z, float accel_x, float accel_y, float accel_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Function to log data to file
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading (degrees),Accel_X (g),Accel_Y (g),Accel_Z (g),Mag_X (gauss),Mag_Y (gauss),Mag_Z (gauss)\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z;
    int16_t mag_x, mag_y, mag_z;
    float heading, accel_x_g, accel_y_g, accel_z_g, mag_x_gauss, mag_y_gauss, mag_z_gauss;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_accel_data(&accel_x, &accel_y, &accel_z) == 0 &&
            read_mag_data(&mag_x, &mag_y, &mag_z) == 0) {

            // Convert raw data to g and gauss
            accel_x_g = (float)accel_x / 16384.0f; // Assuming +/- 2g range
            accel_y_g = (float)accel_y / 16384.0f;
            accel_z_g = (float)accel_z / 16384.0f;
            mag_x_gauss = (float)mag_x / 1100.0f; // Assuming +/- 1.3 Gauss range
            mag_y_gauss = (float)mag_y / 1100.0f;
            mag_z_gauss = (float)mag_z / 1100.0f;

            // Calculate heading
            heading = calculate_heading(mag_x, mag_y, mag_z, accel_x_g, accel_y_g, accel_z_g);

            // Log data
            log_data(heading, accel_x_g, accel_y_g, accel_z_g, mag_x_gauss, mag_y_gauss, mag_z_gauss);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(100); // Sample every 100ms
    }

    // Close I2C and log file
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

