#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C bus
#define I2C_BUS 1

// Define sampling interval (in milliseconds)
#define SAMPLING_INTERVAL 10

// Define TDOA window (in milliseconds)
#define TDOA_WINDOW 5

// Global variables for I2C handles and log file
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int i2c_handle);
int calculate_tdoa(int sensor1_sample, int sensor2_sample);
void log_data(FILE *fp, struct timespec ts, int sensor1_sample, int sensor2_sample, int tdoa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file if it is open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read a single sample from the sensor
int read_sensor(int i2c_handle) {
    char buffer[2];
    int bytes_read;
    int16_t sample;

    bytes_read = i2cReadDevice(i2c_handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return 0; // Return 0 on error
    }

    // Combine the two bytes into a 16-bit signed integer
    sample = (int16_t)((buffer[0] << 8) | buffer[1]);

    return sample;
}

// Function to calculate the time difference of arrival (TDOA)
int calculate_tdoa(int sensor1_sample, int sensor2_sample) {
    // This is a placeholder.  A real TDOA calculation would involve
    // cross-correlation or a more sophisticated algorithm.
    // For simplicity, we just return the difference between the samples.
    return sensor1_sample - sensor2_sample;
}

// Function to log the data to a CSV file
void log_data(FILE *fp, struct timespec ts, int sensor1_sample, int sensor2_sample, int tdoa) {
    fprintf(fp, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_sample, sensor2_sample, tdoa);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    struct timespec ts;
    int sensor1_sample, sensor2_sample, tdoa;
    int retry_count;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %s\n", strerror(errno));
        i2c_handle1 = -1; // Set to -1 to indicate failure
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %s\n", strerror(errno));
        i2c_handle2 = -1; // Set to -1 to indicate failure
    }

    // Open the log file in append mode
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        // Clean up I2C handles if they were opened
        if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
        if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
            continue; // Skip to the next iteration
        }

        // Read samples from sensor 1
        retry_count = 0;
        sensor1_sample = 0; // Initialize to 0 in case of retry failure
        while (retry_count < 3) {
            if (i2c_handle1 >= 0) {
                sensor1_sample = read_sensor(i2c_handle1);
                if (sensor1_sample != 0) break; // Exit retry loop if read is successful
            }
            fprintf(stderr, "Retrying sensor 1 read (%d/3)\n", retry_count + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retry_count++;
        }

        // Read samples from sensor 2
        retry_count = 0;
        sensor2_sample = 0; // Initialize to 0 in case of retry failure
        while (retry_count < 3) {
            if (i2c_handle2 >= 0) {
                sensor2_sample = read_sensor(i2c_handle2);
                if (sensor2_sample != 0) break; // Exit retry loop if read is successful
            }
            fprintf(stderr, "Retrying sensor 2 read (%d/3)\n", retry_count + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retry_count++;
        }

        // Calculate TDOA
        tdoa = calculate_tdoa(sensor1_sample, sensor2_sample);

        // Log the data
        log_data(log_file, ts, sensor1_sample, sensor2_sample, tdoa);

        // Wait for the next sampling interval
        gpioDelay(SAMPLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

