        imu_data.gyro_x = (double)raw_gyro_x * GYRO_SENSITIVITY;
        imu_data.gyro_y = (double)raw_gyro_y * GYRO_SENSITIVITY;
        imu_data.gyro_z = (double)raw_gyro_z * GYRO_SENSITIVITY;
