        imu_data.accel_y = (double)raw_accel_y * ACCEL_SENSITIVITY;
        imu_data.accel_z = (double)raw_accel_z * ACCEL_SENSITIVITY;

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            continue;
        }

        // Write data to CSV file
        fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                ts.tv_sec, ts.tv_nsec,
                imu_data.gyro_x, imu_data.gyro_y, imu_data.gyro_z,
                imu_data.accel_x, imu_data.accel_y, imu_data.accel_z);
        fflush(fp); // Ensure data is written to file immediately

        // Delay for 100ms (non-blocking)
        gpioDelay(100000); // 100ms
    }

    return 0;
