#include <pigpio.h>

// ADIS16448 Register Addresses
#define ADIS16448_REG_GYRO_XOUT 0x04
#define ADIS16448_REG_GYRO_YOUT 0x06
#define ADIS16448_REG_GYRO_ZOUT 0x08
#define ADIS16448_REG_ACCL_XOUT 0x0A
#define ADIS16448_REG_ACCL_YOUT 0x0C
#define ADIS16448_REG_ACCL_ZOUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.02  // dps/LSB
#define ACCEL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define CS_PIN 8 // BCM GPIO8

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read a single register from ADIS16448
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of register address for read operation
    tx_buf[0] = reg_addr | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte for reading data

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate CS initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
        float gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g;

        // Read gyroscope data
        if (spi_read_register(spi_handle, ADIS16448_REG_GYRO_XOUT, &gyro_x) != 0) {
            fprintf(stderr, "Error reading gyro X\n");
            continue; // Skip to the next iteration
        }
        if (spi_read_register(spi_handle, ADIS16448_REG_GYRO_YOUT, &gyro_y) != 0) {
            fprintf(stderr, "Error reading gyro Y\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16448_REG_GYRO_ZOUT, &gyro_z) != 0) {
            fprintf(stderr, "Error reading gyro Z\n");
            continue;
        }

        // Read accelerometer data
        if (spi_read_register(spi_handle, ADIS16448_REG_ACCL_XOUT, &accel_x) != 0) {
            fprintf(stderr, "Error reading accel X\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16448_REG_ACCL_YOUT, &accel_y) != 0) {
            fprintf(stderr, "Error reading accel Y\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADIS16448_REG_ACCL_ZOUT, &accel_z) != 0) {
            fprintf(stderr, "Error reading accel Z\n");
            continue;
        }

        // Convert raw data to physical units
        gyro_x_dps = gyro_x * GYRO_SCALE;
        gyro_y_dps = gyro_y * GYRO_SCALE;
        gyro_z_dps = gyro_z * GYRO_SCALE;
        accel_x_g = accel_x * ACCEL_SCALE;
        accel_y_g = accel_y * ACCEL_SCALE;
        accel_z_g = accel_z * ACCEL_SCALE;

        // Print the data
        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accel X: %.4f g, Accel Y: %.4f g, Accel Z: %.4f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close SPI device
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

