#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the MPU-6886
int16_t read_mpu6886_value(int i2c_handle, uint8_t reg_addr) {
    int retries = 3;
    int16_t value;

    while (retries > 0) {
        value = i2cReadWordData(i2c_handle, reg_addr);
        if (value >= 0) {
            // Success, return the value
            return value;
        } else {
            // Error occurred, retry
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg_addr, value);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    // All retries failed
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg_addr);
    return -1; // Indicate failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read accelerometer values
        int16_t accel_x = read_mpu6886_value(i2c_handle, ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6886_value(i2c_handle, ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6886_value(i2c_handle, ACCEL_XOUT_H + 4);

        // Read gyroscope values
        int16_t gyro_x = read_mpu6886_value(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = read_mpu6886_value(i2c_handle, GYRO_XOUT_H + 2);
        int16_t gyro_z = read_mpu6886_value(i2c_handle, GYRO_XOUT_H + 4);

        // Print the values
        printf("Accel: X=%6d, Y=%6d, Z=%6d  |  Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Wait 50ms
        gpioDelay(50000);
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

