// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / SCALE_FACTOR;
    float y_g = (float)y / SCALE_FACTOR;
    float z_g = (float)z / SCALE_FACTOR;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log impact event
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f g\n", timestamp, x, y, z, magnitude);
    fflush(log_file);
}

