    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Turn on LED
                control_led(1);

                // Log impact event
                log_impact(x, y, z, magnitude);

                // Wait for 500ms
                gpioDelay(500);

                // Turn off LED
                control_led(0);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Wait 10ms
        gpioDelay(10);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

