// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 Registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Sensitivity scales (adjust as needed based on your configuration)
#define ACCEL_SCALE 16384.0f // +/- 2g
#define GYRO_SCALE  131.0f   // +/- 250 dps

// Global variables for signal handling
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

// Function prototypes
int init_imu(int i2c_handle);
int read_imu_data(int i2c_handle, imu_data_t *data);
void log_data(FILE *fp, imu_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ICM-20602
int init_imu(int i2c_handle) {
    // Wake up the device (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up ICM-20602: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Short delay after waking up
    return 0;
}

// Read accelerometer and gyroscope data
int read_imu_data(int i2c_handle, imu_data_t *data) {
    char buf[12];
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 12) != 12) {
        fprintf(stderr, "Error: Could not read IMU data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for accelerometer
    accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Combine high and low bytes for gyroscope
    gyro_x = (int16_t)((buf[6] << 8) | buf[7]);
    gyro_y = (int16_t)((buf[8] << 8) | buf[9]);
    gyro_z = (int16_t)((buf[10] << 8) | buf[11]);

    // Convert to g and degrees/second
    data->accel_x = (float)accel_x / ACCEL_SCALE;
    data->accel_y = (float)accel_y / ACCEL_SCALE;
    data->accel_z = (float)accel_z / ACCEL_SCALE;
    data->gyro_x = (float)gyro_x / GYRO_SCALE;
    data->gyro_y = (float)gyro_y / GYRO_SCALE;
    data->gyro_z = (float)gyro_z / GYRO_SCALE;

    return 0;
}

// Log data to CSV file
void log_data(FILE *fp, imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            ts.tv_sec, ts.tv_nsec,
            data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(fp); // Ensure data is written to disk immediately
}

