#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define WHO_AM_I 0x0D
#define WHO_AM_I_VALUE 0x2A
#define LED_GPIO 17
#define ACCEL_RANGE 2.0f // +/- 2g
#define ACCEL_SENSITIVITY 1024.0f
#define IMPACT_THRESHOLD 2.0f
#define POLL_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int verify_sensor_id();
int configure_sensor();
accelerometer_data_t read_accelerometer_data();
float calculate_magnitude(accelerometer_data_t data);
void log_data(accelerometer_data_t data, float magnitude);
void control_led(int on);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sensor ID verification function
int verify_sensor_id() {
    char buf[1];
    if (i2cReadI2CBlockData(i2c_handle, WHO_AM_I, buf, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (buf[0] != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", buf[0], WHO_AM_I_VALUE);
        return -1;
    }
    printf("Sensor ID verified successfully.\n");
    return 0;
}

// Sensor configuration function
int configure_sensor() {
    // Set accelerometer range to +/- 2g
    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG register\n");
        return -1;
    }

    // Activate the accelerometer (set active mode in CTRL_REG1)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
        return -1;
    }

    return 0;
}

// Data acquisition function
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0f;
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    raw_x = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    raw_y = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    raw_z = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    data.x = (float)raw_x / ACCEL_SENSITIVITY * ACCEL_RANGE;
    data.y = (float)raw_y / ACCEL_SENSITIVITY * ACCEL_RANGE;
    data.z = (float)raw_z / ACCEL_SENSITIVITY * ACCEL_RANGE;

    return data;
}

// Impact detection function
float calculate_magnitude(accelerometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Logging function
void log_data(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n",
            timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// LED control function
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_magnitude(data);

        log_data(data, magnitude);

        if (magnitude > IMPACT_THRESHOLD) {
            control_led(1);
            gpioDelay(500); // 500ms
            control_led(0);
        }

        gpioDelay(POLL_INTERVAL_MS); // 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

