    raw_z = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    data.x = (float)raw_x / ACCEL_SENSITIVITY * ACCEL_RANGE;
    data.y = (float)raw_y / ACCEL_SENSITIVITY * ACCEL_RANGE;
    data.z = (float)raw_z / ACCEL_SENSITIVITY * ACCEL_RANGE;

    return data;
}

// Impact detection function
float calculate_magnitude(accelerometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Logging function
void log_data(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n",
            timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// LED control function
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_magnitude(data);

        log_data(data, magnitude);

        if (magnitude > IMPACT_THRESHOLD) {
            control_led(1);
            gpioDelay(500); // 500ms
            control_led(0);
        }

        gpioDelay(POLL_INTERVAL_MS); // 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

