#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TMAG5273_ADDR 0x08
#define CONFIG_REG 0x00
#define DATA_REG_X 0x01
#define DATA_REG_Y 0x03
#define DATA_REG_Z 0x05
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE_HZ)
#define CSV_FILE "magnetic_field_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int configure_sensor(int fd);
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
void cleanup();

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to configure the TMAG5273 sensor
int configure_sensor(int fd) {
    uint8_t config_value = 0x03; // Continuous measurement mode, 10 Hz ODR
    uint8_t write_buffer[2];
    write_buffer[0] = CONFIG_REG;
    write_buffer[1] = config_value;

    if (write(fd, write_buffer, 2) != 2) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t read_buffer[6];
    uint8_t reg_addr;

    // Read X data
    reg_addr = DATA_REG_X;
    if (write(fd, &reg_addr, 1) != 1) {
        fprintf(stderr, "Error writing to data register (X): %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, read_buffer, 2) != 2) {
        fprintf(stderr, "Error reading X data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((read_buffer[0] << 8) | read_buffer[1]);

    // Read Y data
    reg_addr = DATA_REG_Y;
    if (write(fd, &reg_addr, 1) != 1) {
        fprintf(stderr, "Error writing to data register (Y): %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, read_buffer, 2) != 2) {
        fprintf(stderr, "Error reading Y data: %s\n", strerror(errno));
        return -1;
    }
    *y = (int16_t)((read_buffer[0] << 8) | read_buffer[1]);

    // Read Z data
    reg_addr = DATA_REG_Z;
    if (write(fd, &reg_addr, 1) != 1) {
        fprintf(stderr, "Error writing to data register (Z): %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, read_buffer, 2) != 2) {
        fprintf(stderr, "Error reading Z data: %s\n", strerror(errno));
        return -1;
    }
    *z = (int16_t)((read_buffer[0] << 8) | read_buffer[1]);

    return 0;
}

// Function to log data to a CSV file
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, TMAG5273_ADDR);
    if (i2c_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure sensor
    if (configure_sensor(i2c_fd) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    struct timespec req, rem;
    req.tv_sec = 0;
    req.tv_nsec = SAMPLE_PERIOD_NS;

    sensor_data_t sensor_data;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            // Log data
            log_data(log_file, sensor_data.x, sensor_data.y, sensor_data.z);
        } else {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
        }

        // Sleep for the remaining time
        nanosleep(&req, &rem);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

