#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_FREEFALL 0x28

// Freefall threshold (LSB)
#define FREEFALL_THRESHOLD 0x0A

// GPIO pin for interrupt
#define INTERRUPT_GPIO 17

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init(int i2c_fd);
int adxl345_read_acceleration(int i2c_fd, int16_t *x, int16_t *y, int16_t *z);
int adxl345_enable_freefall_interrupt(int i2c_fd);
int adxl345_disable_freefall_interrupt(int i2c_fd);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);
int log_data(FILE *log_file, int16_t x, int16_t y, int16_t z);

// Function to write a byte to an I2C register
int i2c_write_reg(int i2c_fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int i2c_fd, uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to initialize the ADXL345
int adxl345_init(int i2c_fd) {
    uint8_t devid;

    // Verify device ID
    if (i2c_read_reg(i2c_fd, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set freefall threshold
    if (i2c_write_reg(i2c_fd, ADXL345_REG_FREEFALL, FREEFALL_THRESHOLD) != 0) {
        fprintf(stderr, "Error setting freefall threshold\n");
        return -1;
    }

    // Enable freefall interrupt
    if (adxl345_enable_freefall_interrupt(i2c_fd) != 0) {
        fprintf(stderr, "Error enabling freefall interrupt\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int adxl345_read_acceleration(int i2c_fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    uint8_t reg = ADXL345_REG_DATAX0;

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    if (read(i2c_fd, buf, 6) != 6) {
        perror("I2C read failed");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to enable freefall interrupt
int adxl345_enable_freefall_interrupt(int i2c_fd) {
    // Enable freefall interrupt on INT1 pin
    if (i2c_write_reg(i2c_fd, ADXL345_REG_INT_ENABLE, 0x40) != 0) {
        fprintf(stderr, "Error enabling freefall interrupt\n");
        return -1;
    }

    // Map freefall interrupt to INT1 pin
    if (i2c_write_reg(i2c_fd, ADXL345_REG_INT_MAP, 0x40) != 0) {
        fprintf(stderr, "Error mapping freefall interrupt\n");
        return -1;
    }

    return 0;
}

// Function to disable freefall interrupt
int adxl345_disable_freefall_interrupt(int i2c_fd) {
    // Disable freefall interrupt
    if (i2c_write_reg(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00) != 0) {
        fprintf(stderr, "Error disabling freefall interrupt\n");
        return -1;
    }

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    int16_t x, y, z;

    if (level == 0) { // Falling edge
        if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data in interrupt handler\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to log data to CSV file
int log_data(FILE *log_file, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler
    gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Disable freefall interrupt
    adxl345_disable_freefall_interrupt(i2c_fd);

    // Close I2C bus
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

