#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Accelerometer and gyroscope ranges
#define ACCEL_RANGE 2.0f  // +/- 2g
#define GYRO_RANGE 250.0f // +/- 250 dps

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f  // 0.2g
#define IMPACT_THRESHOLD 2.5f    // 2.5g
#define IMPACT_WINDOW 1.0f       // 1 second

// Scaling factors
#define ACCEL_SCALE (ACCEL_RANGE / 32768.0f)
#define GYRO_SCALE (GYRO_RANGE / 32768.0f)

// State machine states
typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} state_t;

// Global variables
int i2c_handle;
FILE *log_file;
state_t state = IDLE;
double last_freefall_time = 0.0;

// Function prototypes
int init_lsm6dsr();
int read_sensor_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z);
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z);
void fall_detection(float accel_magnitude);
void signal_handler(int signal);

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 104 Hz, +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: 104 Hz, +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    raw_accel_x = (int16_t)((i2cReadByteData(i2c_handle, OUTX_H_XL) << 8) | i2cReadByteData(i2c_handle, OUTX_L_XL));
    raw_accel_y = (int16_t)((i2cReadByteData(i2c_handle, OUTY_H_XL) << 8) | i2cReadByteData(i2c_handle, OUTY_L_XL));
    raw_accel_z = (int16_t)((i2cReadByteData(i2c_handle, OUTZ_H_XL) << 8) | i2cReadByteData(i2c_handle, OUTZ_L_XL));

    // Read gyroscope data
    raw_gyro_x = (int16_t)((i2cReadByteData(i2c_handle, OUTX_H_G) << 8) | i2cReadByteData(i2c_handle, OUTX_L_G));
    raw_gyro_y = (int16_t)((i2cReadByteData(i2c_handle, OUTY_H_G) << 8) | i2cReadByteData(i2c_handle, OUTY_L_G));
    raw_gyro_z = (int16_t)((i2cReadByteData(i2c_handle, OUTZ_H_G) << 8) | i2cReadByteData(i2c_handle, OUTZ_L_G));

    // Convert to g and dps
    *accel_x = (float)raw_accel_x * ACCEL_SCALE;
    *accel_y = (float)raw_accel_y * ACCEL_SCALE;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE;
    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;

    return 0;
}

// Function to log data to a CSV file
void log_data(float accel_x, float accel_y, float accel_z, float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to implement fall detection state machine
void fall_detection(float accel_magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    switch (state) {
        case IDLE:
            if (accel_magnitude < FREEFALL_THRESHOLD) {
                state = FREEFALL;
                last_freefall_time = time(NULL);
                printf("%s - State: FREEFALL\n", timestamp);
            }
            break;
        case FREEFALL:
            if (accel_magnitude > IMPACT_THRESHOLD) {
                state = IMPACT;
                printf("%s - State: IMPACT\n", timestamp);
            } else if (time(NULL) - last_freefall_time > IMPACT_WINDOW) {
                state = IDLE;
                printf("%s - State: IDLE (timeout)\n", timestamp);
            }
            break;
        case IMPACT:
            state = IDLE;
            printf("%s - State: IDLE (impact resolved)\n", timestamp);
            break;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float accel_magnitude;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate acceleration magnitude
            accel_magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);

            // Log data
            log_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

            // Fall detection
            fall_detection(accel_magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for approximately 10ms (100Hz)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    return 0;
}

