            } else if (time(NULL) - last_freefall_time > IMPACT_WINDOW) {
                state = IDLE;
                printf("%s - State: IDLE (timeout)\n", timestamp);
            }
            break;
        case IMPACT:
            state = IDLE;
            printf("%s - State: IDLE (impact resolved)\n", timestamp);
            break;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float accel_magnitude;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate acceleration magnitude
            accel_magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);

            // Log data
            log_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

            // Fall detection
            fall_detection(accel_magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for approximately 10ms (100Hz)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    return 0;
}

