#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C address of the GY-50 gyroscope
#define GYRO_ADDRESS 0x69

// Define the WHO_AM_I register address
#define WHO_AM_I 0x0F

// Define the CTRL_REG1 register address
#define CTRL_REG1 0x20

// Define the CTRL_REG4 register address
#define CTRL_REG4 0x23

// Define the OUT_X_L and OUT_X_H registers
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Define the sensitivity of the gyroscope (8.75 mdps/LSB)
#define SENSITIVITY 8.75f

// Define the scaling factor (114.285)
#define SCALE_FACTOR 114.285f

// Global variables for I2C handle and file pointer
int i2c_handle;
FILE *log_file;

// Function prototypes
int initialize_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_data(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps);
void log_data(float x_dps, float y_dps, float z_dps);
void signal_handler(int signal);

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function to initialize the gyroscope
int initialize_gyro() {
    int retries = 3;
    int status;

    // Check WHO_AM_I register
    int who_am_i;
    while (retries > 0) {
        who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %d. Retrying...\n", who_am_i);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I register value is incorrect: 0x%X\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100 Hz data rate)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1: %d. Retrying...\n", status);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (Full scale selection: +/- 250 dps)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4: %d. Retrying...\n", status);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    // Read 6 bytes of data (X_L, X_H, Y_L, Y_H, Z_L, Z_H)
    status = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6); // Enable auto-increment
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    // Combine low and high bytes to form 16-bit values
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_data(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / SCALE_FACTOR;
    *y_dps = (float)y / SCALE_FACTOR;
    *z_dps = (float)z / SCALE_FACTOR;
}

// Function to log data to a CSV file
void log_data(float x_dps, float y_dps, float z_dps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_dps, y_dps, z_dps);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, GYRO_ADDRESS, 0); // Bus 1, address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
