static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a flame event to the log file
int log_flame_event(int flame_detected) {
    char* timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (flame_detected == 0) {
        fprintf(log_file, "%s – Flame detected: YES\n", timestamp);
        printf("FLAME DETECTED!\n");
    } else {
        fprintf(log_file, "%s – Flame detected: NO\n", timestamp);
    }

    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

int main() {
    int gpio_status;

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Enable the internal pull-up resistor on GPIO17
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to continuously monitor the flame sensor
    while (running) {
        gpio_status = gpioRead(FLAME_SENSOR_GPIO);

        if (gpio_status == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            fprintf(log_file, "%s – Error reading GPIO %d\n", get_timestamp(), FLAME_SENSOR_GPIO);
            fflush(log_file);
        } else {
            log_flame_event(gpio_status);
        }

        gpioDelay(500); // Wait for 500 milliseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

