#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define SAMPLE_RATE_MS 100
#define CSV_FILENAME "vibration_log.csv"

// Global variables
int i2c_handle = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
char* get_iso8601_timestamp();
int write_to_csv(const char *timestamp, const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the D7S-0001
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Write data to CSV file
int write_to_csv(const char *timestamp, const sensor_data_t *data) {
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILENAME);
        return -1;
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data->x, data->y, data->z);
    fclose(csv_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    char *timestamp;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Write to CSV file
            if (write_to_csv(timestamp, &sensor_data) != 0) {
                fprintf(stderr, "Error writing to CSV file.\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample.\n");
        }

        // Delay for 100ms
        gpioDelay(SAMPLE_RATE_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

