#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define TILT_THRESHOLD 45.0
#define LOG_FILE "fall_log.txt"

// Global variables for signal handling
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int verify_sensor();
int configure_sensor();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt(int16_t x, int16_t y, int16_t z);
void log_fall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    accelerometer_data_t data;

    // Main loop
    while (1) {
        // Read accelerometer data
        if (read_accelerometer(&data.x, &data.y, &data.z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data. Continuing...\n");
            gpioDelay(10000); // Sleep for 10ms
            continue;
        }

        // Calculate tilt
        double tilt = calculate_tilt(data.x, data.y, data.z);

        // Check for fall
        if (tilt > TILT_THRESHOLD) {
            log_fall(data.x, data.y, data.z);
        }

        gpioDelay(10000); // Sleep for 10ms
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8452Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Verify sensor
int verify_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return 1;
    }

    if (who_am_i != 0x2A) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x2A)\n", who_am_i);
        return 1;
    }

    printf("MMA8452Q sensor verified.\n");
    return 0;
}

// Configure sensor
int configure_sensor() {
    // Place sensor in standby mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", strerror(errno));
        return 1;
    }

    // Configure data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", strerror(errno));
        return 1;
    }

    // Re-enable active mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01 | 0x01) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", strerror(errno));
        return 1;
    }

    printf("MMA8452Q sensor configured.\n");
    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        return 1;
    }

    *x = ((int16_t)buffer[0] << 8 | (int16_t)buffer[1]) >> 4;
    *y = ((int16_t)buffer[2] << 8 | (int16_t)buffer[3]) >> 4;
    *z = ((int16_t)buffer[4] << 8 | (int16_t)buffer[5]) >> 4;

    return 0;
}

// Calculate tilt
double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 4096.0; // Convert to g
    double y_g = (double)y / 4096.0; // Convert to g
    double z_g = (double)z / 4096.0; // Convert to g

    double tilt_x = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
    double tilt_y = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / M_PI;

    return fabs(tilt_x) > fabs(tilt_y) ? fabs(tilt_x) : fabs(tilt_y);
}

// Log fall
void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file);

    printf("Fall detected and logged: %s, %d, %d, %d\n", timestamp, x, y, z);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

