#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <string.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants (replace with your actual values)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detector threshold
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_magnetometer();
magnetometer_data_t read_magnetometer_data();
magnetometer_data_t calibrate_magnetometer_data(magnetometer_data_t raw_data);
void log_magnetometer_data(magnetometer_data_t calibrated_data);
void metal_detector_alert(magnetometer_data_t calibrated_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize the LIS3MDL magnetometer
int initialize_magnetometer() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Configure CTRL_REG1: 10 Hz, continuous conversion
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70); //0b01110000
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1: %d, retries left: %d\n", status, retries - 1);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Configure CTRL_REG3: Continuous conversion mode
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG3: %d, retries left: %d\n", status, retries - 1);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Configure CTRL_REG4: ±4 gauss full scale
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG4, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG4: %d, retries left: %d\n", status, retries - 1);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        fprintf(stderr, "Magnetometer initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Magnetometer initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Read raw magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t raw_data;
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", status);
        raw_data.x = 0.0;
        raw_data.y = 0.0;
        raw_data.z = 0.0;
        return raw_data;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    raw_data.x = (float)x;
    raw_data.y = (float)y;
    raw_data.z = (float)z;

    return raw_data;
}

// Calibrate magnetometer data
magnetometer_data_t calibrate_magnetometer_data(magnetometer_data_t raw_data) {
    magnetometer_data_t calibrated_data;

    calibrated_data.x = (raw_data.x - X_OFFSET) * X_SCALE * 0.146; // Convert to mG
    calibrated_data.y = (raw_data.y - Y_OFFSET) * Y_SCALE * 0.146; // Convert to mG
    calibrated_data.z = (raw_data.z - Z_OFFSET) * Z_SCALE * 0.146; // Convert to mG

    return calibrated_data;
}

// Log magnetometer data to file
void log_magnetometer_data(magnetometer_data_t calibrated_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, calibrated_data.x, calibrated_data.y, calibrated_data.z);
    fflush(log_file);
}

// Metal detector alert
void metal_detector_alert(magnetometer_data_t calibrated_data) {
    float magnitude = sqrt(calibrated_data.x * calibrated_data.x + calibrated_data.y * calibrated_data.y + calibrated_data.z * calibrated_data.z);

    if (magnitude > METAL_THRESHOLD) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(stderr, "%s - Metal Detected! Magnitude: %.3f mG\n", timestamp, magnitude);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
