#define ADXL354B_REG_DEVID_MST 0x01
#define ADXL354B_REG_PARTID 0x02
#define ADXL354B_REG_REVID 0x03
#define ADXL354B_REG_XDATA_L 0x08
#define ADXL354B_REG_XDATA_H 0x09
#define ADXL354B_REG_XDATA_U 0x0A
#define ADXL354B_REG_YDATA_L 0x0B
#define ADXL354B_REG_YDATA_H 0x0C
#define ADXL354B_REG_YDATA_U 0x0D
#define ADXL354B_REG_ZDATA_L 0x0E
#define ADXL354B_REG_ZDATA_H 0x0F
#define ADXL354B_REG_ZDATA_U 0x10
#define ADXL354B_REG_STATUS 0x14
#define ADXL354B_REG_FIFO_ENTRIES_L 0x15
#define ADXL354B_REG_FIFO_ENTRIES_H 0x16
#define ADXL354B_REG_FIFO_DATA 0x17
#define ADXL354B_REG_FIFO_CONTROL 0x18
#define ADXL354B_REG_INTMAP1 0x19
#define ADXL354B_REG_INTMAP2 0x1A
#define ADXL354B_REG_FILTER_CONTROL 0x2C
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_SELF_TEST 0x2E
#define ADXL354B_REG_RESET 0x1F

// ADXL354B Expected Values
#define ADXL354B_PARTID 0xAD

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int adxl354b_reset(int handle);
int adxl354b_verify_partid(int handle);
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z);
int log_data(FILE *fp, int32_t x, int32_t y, int32_t z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set MSB for read
    tx[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }

    return rx[1];
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write
    tx[1] = value;

    if (spiWrite(handle, tx, 2) != 0) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay
    return 0;
}

// ADXL354B Verify PARTID Function
int adxl354b_verify_partid(int handle) {
    int partid = spi_read_register(handle, ADXL354B_REG_PARTID);
    if (partid < 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }

    if (partid != ADXL354B_PARTID) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354B_PARTID);
        return -1;
    }

    printf("ADXL354B PARTID: 0x%02X (correct)\n", partid);
    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z) {
    char tx[7], rx[7];
    tx[0] = ADXL354B_REG_XDATA_L | 0xC0; // Read X, Y, and Z data (multi-byte)

    for (int i = 1; i < 7; i++) {
        tx[i] = 0x00; // Dummy bytes
    }

    if (spiXfer(handle, tx, rx, 7) != 0) {
        fprintf(stderr, "SPI read acceleration data failed\n");
        return -1;
    }

    // Combine the 20-bit data
    *x = ((int32_t)rx[1] << 12) | ((int32_t)rx[2] << 4) | ((int32_t)rx[3] >> 4);
    *y = ((int32_t)rx[4] << 12) | ((int32_t)rx[5] << 4) | ((int32_t)rx[6] >> 4);
    *z = ((int32_t)rx[1] << 12) | ((int32_t)rx[2] << 4) | ((int32_t)rx[3] >> 4);

    // Sign extend to 32 bits
    if (*x & 0x80000) {
        *x |= 0xFFF00000;
    }
    if (*y & 0x80000) {
        *y |= 0xFFF00000;
    }
    if (*z & 0x80000) {
        *z |= 0xFFF00000;
    }

    return 0;
}

// Log Data Function
int log_data(FILE *fp, int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Reset ADXL354B
    if (adxl354b_reset(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B reset failed, exiting\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify PARTID
    if (adxl354b_verify_partid(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B PARTID verification failed, exiting\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADXL354B (example: set filter and power control)
    spi_write_register(spi_handle, ADXL354B_REG_FILTER_CONTROL, 0x03); // ODR = 125 Hz
    spi_write_register(spi_handle, ADXL354B_REG_POWER_CTL, 0x02);    // Enable measurement mode

    // Main loop
    int32_t x, y, z;
    while (!terminate) {
        // Read acceleration data
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            // Log data
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data, retrying...\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

