// Define the GPIO pin and chip number
#define GPIO_PIN 17
#define GPIO_CHIP 4

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log a message with a timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin as an input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    log_message("Program started");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) {
            log_message("Self-parking sequence started");
            sleep(5);
            log_message("Self-parking sequence completed");
        } else if (sensor_value < 0) {
            // Error reading sensor, exit loop
            break;
        }
        sleep(1);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    log_message("Program terminated");

    return 0;
}

