#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int sensor1_status, sensor2_status;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20]; // Buffer to hold the formatted timestamp

    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Main loop to continuously poll the sensors
    while (program_running) {
        // Read the sensor values using gpioRead
        sensor1_status = gpioRead(SENSOR1_GPIO);
        if (sensor1_status < 0) {
            fprintf(stderr, "Error reading sensor 1 (GPIO%d)\n", SENSOR1_GPIO);
            gpioTerminate();
            return 1;
        }

        sensor2_status = gpioRead(SENSOR2_GPIO);
        if (sensor2_status < 0) {
            fprintf(stderr, "Error reading sensor 2 (GPIO%d)\n", SENSOR2_GPIO);
            gpioTerminate();
            return 1;
        }

        // Get the current time
        current_time = time(NULL);
        if (current_time == (time_t)(-1)) {
            perror("Failed to get current time");
            gpioTerminate();
            return 1;
        }

        // Convert the time to a human-readable format
        time_info = localtime(&current_time);
        if (time_info == NULL) {
            perror("Failed to convert time to local time");
            gpioTerminate();
            return 1;
        }

        // Format the timestamp
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info) == 0) {
            fprintf(stderr, "Failed to format timestamp\n");
            gpioTerminate();
            return 1;
        }

        // Log the sensor status and timestamp to the console
        printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
               (sensor1_status == 0) ? "Obstacle Detected" : "Path Clear",
               (sensor2_status == 0) ? "Obstacle Detected" : "Path Clear");

        // Wait for 100 milliseconds
        gpioDelay(100000); // pigpio uses microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

