        sensor1_status = gpioRead(SENSOR1_GPIO);
        if (sensor1_status < 0) {
            fprintf(stderr, "Error reading sensor 1 (GPIO%d)\n", SENSOR1_GPIO);
            gpioTerminate();
            return 1;
        }

        sensor2_status = gpioRead(SENSOR2_GPIO);
        if (sensor2_status < 0) {
            fprintf(stderr, "Error reading sensor 2 (GPIO%d)\n", SENSOR2_GPIO);
            gpioTerminate();
            return 1;
        }

        // Get the current time
        current_time = time(NULL);
        if (current_time == (time_t)(-1)) {
            perror("Failed to get current time");
            gpioTerminate();
            return 1;
        }

        // Convert the time to a human-readable format
        time_info = localtime(&current_time);
        if (time_info == NULL) {
            perror("Failed to convert time to local time");
            gpioTerminate();
            return 1;
        }

        // Format the timestamp
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info) == 0) {
            fprintf(stderr, "Failed to format timestamp\n");
            gpioTerminate();
            return 1;
        }

        // Log the sensor status and timestamp to the console
        printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
               (sensor1_status == 0) ? "Obstacle Detected" : "Path Clear",
               (sensor2_status == 0) ? "Obstacle Detected" : "Path Clear");

        // Wait for 100 milliseconds
        gpioDelay(100000); // pigpio uses microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

