// ADIS16266 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scale Factor
#define SCALE_FACTOR 0.02 // deg/sec per LSB

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t address, uint16_t *data);
int spi_write_register(int handle, uint8_t address, uint16_t data);
int initialize_spi();
void cleanup_spi();
void signal_handler(int signal);
void log_data(float x, float y, float z);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// SPI Read Register Function
int spi_read_register(int handle, uint8_t address, uint16_t *data) {
    char tx[3];
    char rx[3];

    tx[0] = address | 0x80; // Set MSB for read
    tx[1] = 0x00; // Dummy byte
    tx[2] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    *data = (rx[1] << 8) | rx[2];
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t address, uint16_t data) {
    char tx[3];
    char rx[3];

    tx[0] = address & 0x7F; // Clear MSB for write
    tx[1] = (data >> 8) & 0xFF; // MSB
    tx[2] = data & 0xFF;      // LSB

    if (spiXfer(handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

