int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Cleanup SPI
void cleanup_spi() {
    spiClose(spi_handle);
}

// Log Data Function
void log_data(float x, float y, float z) {
    printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x, y, z);
}

