        // Read X, Y, and Z gyroscope data
        if (spi_read_register(spi_handle, XGYRO_OUT, &raw_x) != 0) {
            fprintf(stderr, "Error reading X gyro data\n");
        } else {
            x_rate = (float)((int16_t)raw_x) * SCALE_FACTOR;
        }

        if (spi_read_register(spi_handle, YGYRO_OUT, &raw_y) != 0) {
            fprintf(stderr, "Error reading Y gyro data\n");
        } else {
            y_rate = (float)((int16_t)raw_y) * SCALE_FACTOR;
        }

        if (spi_read_register(spi_handle, ZGYRO_OUT, &raw_z) != 0) {
            fprintf(stderr, "Error reading Z gyro data\n");
        } else {
            z_rate = (float)((int16_t)raw_z) * SCALE_FACTOR;
        }

        // Log the data
        log_data(x_rate, y_rate, z_rate);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    cleanup_spi();
    gpioTerminate();

    return 0;
}

