#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_A 0x28
#define OUTX_H_A 0x29
#define OUTY_L_A 0x2A
#define OUTY_H_A 0x2B
#define OUTZ_L_A 0x2C
#define OUTZ_H_A 0x2D
#define WHO_AM_I 0x0F

// Accelerometer and gyroscope ranges
#define ACCEL_RANGE 2.0f  // +/- 2g
#define GYRO_RANGE 250.0f // +/- 250 dps

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lsm6dsr();
int read_accel_gyro(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize the LSM6DSR
int init_lsm6dsr() {
    // Enable accelerometer and gyroscope (104 Hz, +/- 2g, +/- 250 dps)
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x69, got 0x%x\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data
int read_accel_gyro(float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_A, buffer, 12) != 12) {
        fprintf(stderr, "Error reading accelerometer and gyroscope data\n");
        return -1;
    }

    // Combine low and high bytes for accelerometer
    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine low and high bytes for gyroscope
    raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to g and dps
    *accel_x = (float)raw_accel_x / 32768.0f * ACCEL_RANGE;
    *accel_y = (float)raw_accel_y / 32768.0f * ACCEL_RANGE;
    *accel_z = (float)raw_accel_z / 32768.0f * ACCEL_RANGE;
    *gyro_x = (float)raw_gyro_x / 32768.0f * GYRO_RANGE;
    *gyro_y = (float)raw_gyro_y / 32768.0f * GYRO_RANGE;
    *gyro_z = (float)raw_gyro_z / 32768.0f * GYRO_RANGE;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Main loop
    while (!terminate) {
        // Read accelerometer and gyroscope data
        if (read_accel_gyro(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print data to stdout
            printf("%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

