#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_REG_STATUS 0x00
#define FXOS8700_REG_OUT_X_MSB_ACCEL 0x01
#define FXOS8700_REG_OUT_X_MSB_MAG 0x33
#define FXOS8700_REG_CTRL_REG1 0x2A
#define FXOS8700_REG_CTRL_REG2 0x2B
#define FXOS8700_REG_M_CTRL_REG1 0x5B
#define FXOS8700_REG_M_CTRL_REG2 0x5C
#define FXOS8700_REG_WHOAMI 0x0D

// Expected WHOAMI value
#define FXOS8700_WHOAMI_VALUE 0xC7

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig)
{
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a register
int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d, retries left: %d\n", reg, result, retries - 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to write a register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing register 0x%02X: %d, retries left: %d\n", reg, result, retries - 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to write register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to initialize the FXOS8700 sensor
int initialize_sensor(int handle)
{
    // Set accelerometer to active mode, 100 Hz ODR
    if (write_register(handle, FXOS8700_REG_CTRL_REG1, 0x01 | (0x01 << 3)) != 0) {
        fprintf(stderr, "Error setting accelerometer mode.\n");
        return -1;
    }

    // Set magnetometer to hybrid mode, 10 Hz ODR
    if (write_register(handle, FXOS8700_REG_M_CTRL_REG1, 0x1F) != 0) {
        fprintf(stderr, "Error setting magnetometer mode.\n");
        return -1;
