#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE_MS 5000
#define SAMPLE_INTERVAL_MS 1
#define STATUS_INTERVAL_S 1

static volatile int running = 1;
static int threshold = 0;

void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value.  Must be a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int high_count = 0;
        for (int i = 0; i < WINDOW_SIZE_MS; i += SAMPLE_INTERVAL_MS) {
            int level = gpioRead(GPIO_PIN);
            if (level < 0) {
                fprintf(stderr, "Error: Failed to read GPIO%d\n", GPIO_PIN);
                running = 0;
                break;
            }
            if (level == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS);
        }

        if (!running) break;

        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        if (high_count > threshold) {
            printf("%s ALERT\n", buf);
        } else {
            printf("%s OK\n", buf);
        }

        gpioDelay(STATUS_INTERVAL_S * 1000);
    }

    gpioTerminate();
    return 0;
}

