#define PIR_PIN 4

// Define GPIO pin for DHT22 sensor (using sysfs for simplicity)
#define DHT22_PIN 22

// Define GPIO pin for relay control (simulating DHT22 power)
#define DHT22_POWER_PIN 23

// Define constants
#define UNLOCK_DURATION_SEC 5
#define LOG_FILE "access_log.txt"
#define DHT22_SYSFS_PATH "/sys/bus/w1/devices/28-000000000000/w1_slave" // Replace with your actual sysfs path

// Global variables
