static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *dht22_power_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int generate_security_code();
int read_user_input(int *user_code);
int compare_codes(int generated_code, int user_code);
int log_access(int code);
int unlock_door(int door_pin);
