        fprintf(stderr, "Error opening DHT22 sysfs file: %s\n", strerror(errno));
        // Power off the DHT22 sensor
        if (gpiod_line_set_value(dht22_power_line, 0) < 0) {
            fprintf(stderr, "Error powering off DHT22 sensor: %s\n", strerror(errno));
        }
        return -1;
    }

    // Read the file line by line
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading DHT22 sysfs file: %s\n", strerror(errno));
        fclose(fp);
        // Power off the DHT22 sensor
        if (gpiod_line_set_value(dht22_power_line, 0) < 0) {
            fprintf(stderr, "Error powering off DHT22 sensor: %s\n", strerror(errno));
        }
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading DHT22 sysfs file: %s\n", strerror(errno));
        fclose(fp);
        // Power off the DHT22 sensor
        if (gpiod_line_set_value(dht22_power_line, 0) < 0) {
            fprintf(stderr, "Error powering off DHT22 sensor: %s\n", strerror(errno));
        }
        return -1;
    }

    fclose(fp);

    // Parse the temperature and humidity values
    token = strstr(buffer, "t=");
    if (token != NULL) {
        temp = (float)atoi(token + 2) / 1000.0;
    }

    token = strstr(buffer, "h=");
    if (token != NULL) {
        hum = (float)atoi(token + 2) / 1000.0;
    }

    // Power off the DHT22 sensor
    if (gpiod_line_set_value(dht22_power_line, 0) < 0) {
        fprintf(stderr, "Error powering off DHT22 sensor: %s\n", strerror(errno));
    }

    if (temp == -999.0 || hum == -999.0) {
        fprintf(stderr, "Error reading DHT22 sensor data.\n");
        return -1;
    }

    *temperature = temp;
    *humidity = hum;

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to set up GPIO lines
int setup_gpio() {
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

