    if (!pir_line) {
        fprintf(stderr, "Error getting GPIO line for PIR sensor: %s\n", strerror(errno));
        goto err_chip;
    }

    dht22_power_line = gpiod_chip_get_line(chip, DHT22_POWER_PIN);
    if (!dht22_power_line) {
        fprintf(stderr, "Error getting GPIO line for DHT22 power: %s\n", strerror(errno));
        goto err_chip;
    }

    ret = gpiod_line_request_output(door_a_line, "door_access", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for door A as output: %s\n", strerror(errno));
        goto err_chip;
    }

    ret = gpiod_line_request_output(door_b_line, "door_access", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for door B as output: %s\n", strerror(errno));
        goto err_chip;
    }

    ret = gpiod_line_request_input(pir_line, "door_access");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for PIR sensor as input: %s\n", strerror(errno));
        goto err_chip;
    }

    ret = gpiod_line_request_output(dht22_power_line, "door_access", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for DHT22 power as output: %s\n", strerror(errno));
        goto err_chip;
    }

    return 0;

err_chip:
    gpiod_chip_close(chip);
    return -1;
