#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_PIN 18 // GPIO18 (BCM)
#define PWM_FREQ 440
#define PWM_RANGE 1000
#define TCP_PORT 12345
#define SHARED_SECRET "MySecretKey"
#define MOTION_DETECTED_PREFIX "MOTION_DETECTED:"
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int tcp_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_data(unsigned short *touch_data);
int tcp_authenticate(int client_socket);
void play_tone(int frequency);
void log_frequency(int frequency);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x0F) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x0A) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure baseline filtering (example values)
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x07) < 0) { // MHD_R
        fprintf(stderr, "Error: Failed to set MHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) { // NHD_R
        fprintf(stderr, "Error: Failed to set NHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x01) < 0) { // NCL_R
        fprintf(stderr, "Error: Failed to set NCL_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x0E) < 0) { // FDL_R
        fprintf(stderr, "Error: Failed to set FDL_R\n");
        return -1;
    }

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // ELEPROX_EN
        fprintf(stderr, "Error: Failed to set ELEPROX_EN\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x01) < 0) { // NCL_R
        fprintf(stderr, "Error: Failed to set NCL_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x0E) < 0) { // FDL_R
        fprintf(stderr, "Error: Failed to set FDL_R\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // ELEPROX_EN
        fprintf(stderr, "Error: Failed to set ELEPROX_EN\n");
        return -1;
    }

    return 0;
}

// MPR121 read touch data function
int mpr121_read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }
    *touch_data = ((unsigned short)buf[1] << 8) | (unsigned short)buf[0];
    return 0;
}

// TCP authentication function
int tcp_authenticate(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received <= 0) {
        fprintf(stderr, "Error: Failed to receive data or connection closed\n");
        return -1;
    }
    buffer[bytes_received] = '\0';

    if (strncmp(buffer, MOTION_DETECTED_PREFIX, strlen(MOTION_DETECTED_PREFIX)) == 0) {
        char *secret = strstr(buffer, SHARED_SECRET);
        if (secret != NULL) {
            printf("Authentication successful\n");
            return 0;
        }
    }

    fprintf(stderr, "Error: Authentication failed\n");
    return -1;
}

// Play tone function
void play_tone(int frequency) {
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioPWM(PWM_PIN, 500); // 50% duty cycle
    gpioDelay(5000); // 5 seconds
    gpioPWM(PWM_PIN, 0); // Stop PWM
}

// Log frequency function
void log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure PWM
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create TCP socket
    tcp_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (tcp_socket < 0) {
        fprintf(stderr, "Error: Socket creation failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(TCP_PORT);

    if (bind(tcp_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        fprintf(stderr, "Error: Socket bind failed\n");
        close(tcp_socket);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(tcp_socket, 5) < 0) {
        fprintf(stderr, "Error: Socket listen failed\n");
        close(tcp_socket);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Listening for connections on port %d...\n", TCP_PORT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_socket = accept(tcp_socket, (struct sockaddr *)&client_address, &client_len);
        if (client_socket < 0) {
            fprintf(stderr, "Error: Socket accept failed\n");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        if (tcp_authenticate(client_socket) == 0) {
            unsigned short touch_data;
            int frequency = PWM_FREQ; // Initial frequency

            // Play tone and log frequency
            play_tone(frequency);
            log_frequency(frequency);

            // Sample touch data every 20ms during playback
            for (int i = 0; i < 250; i++) { // 5 seconds * 50 Hz = 250 samples
                if (mpr121_read_touch_data(&touch_data) == 0) {
                    // Map touch data to frequency range (e.g., 200Hz - 800Hz)
                    float touch_value = (float)touch_data / 4095.0; // Normalize to 0-1
                    frequency = 200 + (int)(touch_value * 600); // Map to 200-800Hz

                    // Play tone with new frequency
                    play_tone(frequency);
                    log_frequency(frequency);
                } else {
                    fprintf(stderr, "Error: Failed to read touch data during playback\n");
                }
                gpioDelay(20); // 20ms delay
            }
        }

        close(client_socket);
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    close(tcp_socket);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

