#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_REG_MAG_X_L 0x08
#define LSM303_REG_MAG_X_H 0x09
#define LSM303_REG_MAG_Y_L 0x0A
#define LSM303_REG_MAG_Y_H 0x0B
#define LSM303_REG_MAG_Z_L 0x0C
#define LSM303_REG_MAG_Z_H 0x0D
#define LSM303_REG_MAG_CTRL_REG1 0x20

// GPIO pin for LED
#define LED_PIN 17

// I2C bus
#define I2C_BUS 1

// PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int initialize_i2c();
int initialize_magnetometer();
magnetometer_data_t read_magnetometer_data();
float calculate_magnitude(magnetometer_data_t data);
void set_led_brightness(float magnitude);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Magnetometer initialization function
int initialize_magnetometer() {
    // Enable continuous measurement mode
    if (i2cWriteByteData(i2c_handle, LSM303_REG_MAG_CTRL_REG1, 0x1C) < 0) {
        log_error("Failed to write to magnetometer control register");
        return -1;
    }
    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LSM303_REG_MAG_X_L, buffer, 6) != 6) {
        log_error("Failed to read magnetometer data");
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to calculate the magnitude of the Z-axis
float calculate_magnitude(magnetometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to set the LED brightness using PWM
void set_led_brightness(float magnitude) {
    // Scale the magnitude to the PWM range (0-255)
    int duty_cycle = (int)(magnitude * 255.0 / 4096.0); // Assuming max magnitude is 4096
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(LED_PIN, duty_cycle);
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer() != 0) {
        cleanup();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_PIN, PWM_FREQUENCY);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data();

        // Calculate magnitude
        float magnitude = calculate_magnitude(data);

        // Set LED brightness
        set_led_brightness(magnitude);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

