#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Number of samples for hard-iron offset calculation
#define NUM_SAMPLES 100

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold hard-iron offsets
typedef struct {
    int32_t x_offset;
    int32_t y_offset;
    int32_t z_offset;
} hard_iron_offsets_t;

// Circular buffer for storing magnetometer data
magnetometer_data_t magnetometer_data[NUM_SAMPLES];
int data_index = 0;

// Function prototypes
int initialize_hmc5883l();
magnetometer_data_t read_magnetometer_data();
hard_iron_offsets_t calculate_hard_iron_offsets();
magnetometer_data_t apply_hard_iron_offsets(magnetometer_data_t raw_data, hard_iron_offsets_t offsets);
void print_corrected_data(magnetometer_data_t corrected_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initializes the HMC5883L magnetometer
int initialize_hmc5883l() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE\n");
        return -1;
    }

    return 0;
}

// Reads raw magnetometer data from the HMC5883L
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; // Set to 0 to avoid using uninitialized data
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Calculates the hard-iron offsets from the last NUM_SAMPLES readings
hard_iron_offsets_t calculate_hard_iron_offsets() {
    hard_iron_offsets_t offsets = {0, 0, 0};
    for (int i = 0; i < NUM_SAMPLES; i++) {
        offsets.x_offset += magnetometer_data[i].x;
        offsets.y_offset += magnetometer_data[i].y;
        offsets.z_offset += magnetometer_data[i].z;
    }
    offsets.x_offset /= NUM_SAMPLES;
    offsets.y_offset /= NUM_SAMPLES;
    offsets.z_offset /= NUM_SAMPLES;
    return offsets;
}

// Applies the hard-iron offsets to the raw magnetometer data
magnetometer_data_t apply_hard_iron_offsets(magnetometer_data_t raw_data, hard_iron_offsets_t offsets) {
    magnetometer_data_t corrected_data;
    corrected_data.x = raw_data.x - offsets.x_offset;
    corrected_data.y = raw_data.y - offsets.y_offset;
    corrected_data.z = raw_data.z - offsets.z_offset;
    return corrected_data;
}

// Prints the offset-corrected X, Y, and Z components to stdout
void print_corrected_data(magnetometer_data_t corrected_data) {
    printf("X: %d, Y: %d, Z: %d\n", corrected_data.x, corrected_data.y, corrected_data.z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data[data_index] = read_magnetometer_data();
        data_index = (data_index + 1) % NUM_SAMPLES;

        // Calculate hard-iron offsets
        hard_iron_offsets_t offsets = calculate_hard_iron_offsets();

        // Apply hard-iron offsets
        magnetometer_data_t corrected_data = apply_hard_iron_offsets(magnetometer_data[data_index], offsets);

        // Print corrected data
        print_corrected_data(corrected_data);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

