        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data[data_index] = read_magnetometer_data();
        data_index = (data_index + 1) % NUM_SAMPLES;

        // Calculate hard-iron offsets
        hard_iron_offsets_t offsets = calculate_hard_iron_offsets();

        // Apply hard-iron offsets
        magnetometer_data_t corrected_data = apply_hard_iron_offsets(magnetometer_data[data_index], offsets);

        // Print corrected data
        print_corrected_data(corrected_data);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

