void signal_handler(int signum);

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, INT1_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(gpio_line, "lsm303d_mon", GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_EVENT_RISING_EDGE) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize LSM303D
int init_lsm303d() {
    uint8_t who_am_i;

    // Verify device identity
    if (read_register(WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0xD4) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 100Hz, enable all axes
    if (write_register(CTRL_REG1_A, 0x57) != 0) {
        fprintf(stderr, "Error writing CTRL_REG1_A\n");
        return -1;
    }

    // Configure accelerometer: +/- 2g range
    if (write_register(CTRL_REG4_A, 0x00) != 0) {
        fprintf(stderr, "Error writing CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Read a register
int read_register(int reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Write a register
int write_register(int reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Read accelerometer data
void read_accelerometer_data(accelerometer_data_t *data) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    if (read_register(OUT_X_L_A, &x_l) != 0 ||
        read_register(OUT_X_H_A, &x_h) != 0 ||
        read_register(OUT_Y_L_A, &y_l) != 0 ||
        read_register(OUT_Y_H_A, &y_h) != 0 ||
        read_register(OUT_Z_L_A, &z_l) != 0 ||
        read_register(OUT_Z_H_A, &z_h) != 0) {
