        data->x = 0; // Set to 0 to avoid garbage values
        data->y = 0;
        data->z = 0;
        return;
    }

    data->x = (int16_t)((x_h << 8) | x_l);
    data->y = (int16_t)((y_h << 8) | y_l);
    data->z = (int16_t)((z_h << 8) | z_l);
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Dump buffer contents
void dump_buffer(circular_buffer_t *buffer) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s: ", timestamp);
    int start = (buffer->head - 10 + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < 10; i++) {
