        printf("(%6d, %6d, %6d) ", buffer->data[index].x, buffer->data[index].y, buffer->data[index].z);
    }
    printf("\n");
}

// Interrupt handler
void interrupt_handler(int signum) {
    dump_buffer(&buffer);
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;

        // Disable accelerometer
        write_register(CTRL_REG1_A, 0x00);

        // Close I2C
        close(i2c_fd);

        // Release GPIO
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);

        exit(0);
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() != 0) {
        fprintf(stderr, "LSM303D initialization failed\n");
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set up interrupt handler
    struct gpiod_line_event event;
    struct timespec timeout;

    printf("Monitoring LSM303D...\n");

    while (!terminate) {
        accelerometer_data_t data;
        read_accelerometer_data(&data);
        add_to_buffer(&buffer, data);

        // Wait for interrupt
        timeout.tv_sec = 0;
        timeout.tv_nsec = 10000000; // 10ms
        int ret = gpiod_line_event_wait(gpio_line, &timeout);

        if (ret > 0) {
            // Interrupt occurred
            if (gpiod_line_event_read(gpio_line, &event) == 0) {
                if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    interrupt_handler(0);
                }
            } else {
                perror("Error reading GPIO event");
            }
        } else if (ret < 0) {
            perror("Error waiting for GPIO event");
        }
    }

    return 0;
}

