    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    // Ensure both solenoids are initially off
    if (set_solenoid_state(SOLENOID_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 1\n");
        gpioTerminate();
        return 1;
    }
    if (set_solenoid_state(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 2\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to set the state of a solenoid
int set_solenoid_state(int solenoid_pin, int state) {
    if (gpioWrite(solenoid_pin, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", solenoid_pin);
        return 1;
    }
    return 0;
}

// Function to switch the active solenoid
int switch_solenoid() {
    int inactive_solenoid_pin;

    // Determine the inactive solenoid pin
    if (active_solenoid == 0) {
        inactive_solenoid_pin = SOLENOID_2_PIN;
    } else {
        inactive_solenoid_pin = SOLENOID_1_PIN;
    }

    // Deactivate the inactive solenoid
    if (set_solenoid_state(inactive_solenoid_pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid %d\n", inactive_solenoid_pin);
        return 1;
    }

    // Activate the active solenoid
    if (set_solenoid_state(active_solenoid == 0 ? SOLENOID_1_PIN : SOLENOID_2_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid %d\n", active_solenoid == 0 ? SOLENOID_1_PIN : SOLENOID_2_PIN);
        return 1;
    }

    // Toggle the active solenoid
    active_solenoid = 1 - active_solenoid;

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Switch solenoid
        if (switch_solenoid() != 0) {
            fprintf(stderr, "Failed to switch solenoid, exiting.\n");
            break;
        }

        // Delay for 500 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500 milliseconds
        if (nanosleep(&delay, NULL) != 0) {
            fprintf(stderr, "nanosleep failed\n");
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    signal_handler(SIGTERM);

    return 0;
}

