// Define GPIO pins for the relays
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART ports
#define UART1_PORT "/dev/serial0"
#define UART2_PORT "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout in seconds
#define TIMEOUT_SEC 5

// Define expected code
#define EXPECTED_CODE "123456"

// Global variables for UART file descriptors
int uart1_fd = -1;
int uart2_fd = -1;

// Function prototypes
int initialize_uart(const char *port);
int read_code(int fd, char *code);
int constant_time_compare(const char *a, const char *b);
int control_relay(int gpio, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");

    // Close UART ports
    if (uart1_fd != -1) {
        close(uart1_fd);
    }
    if (uart2_fd != -1) {
        close(uart2_fd);
    }

    // Set relays to LOW (locked)
    control_relay(LOCK1_GPIO, 0);
    control_relay(LOCK2_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize a UART port
int initialize_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART port %s\n", port);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes for %s\n", port);
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = TIMEOUT_SEC * 10; // 0.1 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, B9600) != 0 || cfsetispeed(&tty, B9600) != 0) {
        fprintf(stderr, "Error setting baud rate for %s\n", port);
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes for %s\n", port);
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a 6-digit code from a UART port
int read_code(int fd, char *code) {
    int i = 0;
    char c;
    ssize_t bytes_read;
    time_t start_time = time(NULL);

    while (i < 6) {
        bytes_read = read(fd, &c, 1);
        if (bytes_read > 0) {
            if (c >= '0' && c <= '9') {
                code[i++] = c;
            } else {
                // Non-digit character received, reset the buffer
                i = 0;
                code[0] = '\0';
            }
        } else if (bytes_read == 0) {
            // Timeout or no data available
            if (time(NULL) - start_time >= TIMEOUT_SEC) {
                fprintf(stderr, "Timeout reading from UART\n");
                return -1; // Timeout
            }
            usleep(10000); // Sleep for 10ms to avoid busy-waiting
        } else {
            fprintf(stderr, "Error reading from UART\n");
            return -1; // Error
        }
    }
    code[6] = '\0'; // Null-terminate the string
    return 0; // Success
}

// Function to perform a constant-time string comparison
int constant_time_compare(const char *a, const char *b) {
    int result = 0;
    for (int i = 0; i < strlen(EXPECTED_CODE); i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

// Function to control a relay
int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize UART ports
    uart1_fd = initialize_uart(UART1_PORT);
    if (uart1_fd == -1) {
        gpioTerminate();
        return 1;
    }

    uart2_fd = initialize_uart(UART2_PORT);
    if (uart2_fd == -1) {
        close(uart1_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Main loop
    char code1[7] = {0};
    char code2[7] = {0};
    int lock1_unlocked = 0;
    int lock2_unlocked = 0;

    while (1) {
        // Read codes from UART ports
        int read1 = read_code(uart1_fd, code1);
        int read2 = read_code(uart2_fd, code2);

        // Check if both codes are valid and match
        if (read1 == 0 && read2 == 0 && constant_time_compare(code1, code2)) {
            // Unlock both locks
            if (!lock1_unlocked) {
                if (control_relay(LOCK1_GPIO, 1) == 0) {
                    lock1_unlocked = 1;
                }
            }
            if (!lock2_unlocked) {
                if (control_relay(LOCK2_GPIO, 1) == 0) {
                    lock2_unlocked = 1;
                }
            }

            // Wait for 2 seconds
            gpioDelay(2000);

            // Lock both locks
            if (lock1_unlocked) {
                if (control_relay(LOCK1_GPIO, 0) == 0) {
                    lock1_unlocked = 0;
                }
            }
            if (lock2_unlocked) {
                if (control_relay(LOCK2_GPIO, 0) == 0) {
                    lock2_unlocked = 0;
                }
            }
        }

        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }

    return 0;
}

