#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define POLL_INTERVAL_MS 50
#define RELAY_DURATION_S 1
#define FAILSAFE_TIMEOUT_S 10

// Global variables
static volatile int running = 1;
static int pir_state = 0;
static time_t last_motion_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
int log_event(int priority, const char *message);
void failsafe();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        log_event(LOG_ERR, "Failed to set PIR sensor pin as input");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        log_event(LOG_ERR, "Failed to set relay pin as output");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    int value = gpioRead(PIR_SENSOR_PIN);
    if (value < 0) {
        log_event(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        log_event(LOG_ERR, "Failed to write to relay pin");
        return -1;
    }
    return 0;
}

// Function to log events to syslog
int log_event(int priority, const char *message) {
    syslog(priority, message);
    return 0;
}

// Failsafe function
void failsafe() {
    log_event(LOG_WARNING, "Failsafe triggered: PIR signal continuously HIGH");
    control_relay(0); // De-energize relay
    log_event(LOG_ERR, "System shutdown due to failsafe");
    cleanup();
    exit(1);
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    log_event(LOG_INFO, "Signal received, shutting down...");
}

// Cleanup function
void cleanup() {
    control_relay(0); // Ensure relay is off
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("pir_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event(LOG_INFO, "PIR monitor started");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            running = 0; // Exit on error
            break;
        }

        if (pir_value == 1) {
            if (pir_state == 0) {
                // Motion detected
                log_event(LOG_INFO, "Motion detected");
                control_relay(1); // Activate relay
                log_event(LOG_INFO, "Relay activated");
                last_motion_time = time(NULL);
                pir_state = 1;
            } else {
                // Check for failsafe timeout
                time_t current_time = time(NULL);
                if (difftime(current_time, last_motion_time) > FAILSAFE_TIMEOUT_S) {
                    failsafe();
                }
            }
        } else {
            // No motion
            if (pir_state == 1) {
                control_relay(0); // De-activate relay
                log_event(LOG_INFO, "Relay deactivated");
                pir_state = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for poll interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

