#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <syslog.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define PWR_MGMT_1 0x6B
#define SAMPLE_RATE 100 // Hz
#define BUFFER_SIZE 1000
#define DRIVER_PATH "/sys/kernel/mpu6050_accel/latest"
#define UDP_IP "127.0.0.1" // Replace with your server IP
#define UDP_PORT 5000
#define SENSOR_FAILURE_THRESHOLD 5 // Number of consecutive failures before marking sensor as failed
#define SENSOR_RETRY_DELAY 1 // Seconds to wait before retrying a failed sensor

// Data Structures
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelData;

typedef struct {
    AccelData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global Variables
int i2c_fd = -1;
int udp_socket = -1;
struct sockaddr_in server_addr;
CircularBuffer buffer;
volatile sig_atomic_t program_running = 1;
int sensor_failed = 0;
int sensor_failure_count = 0;

// Function Prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
void buffer_init(CircularBuffer *buffer);
void buffer_add(CircularBuffer *buffer, AccelData data);
AccelData buffer_get_latest(CircularBuffer *buffer);
void signal_handler(int sig);
int setup_udp_socket(const char *ip, int port);
void *sensor_thread(void *arg);
void *udp_thread(void *arg);
void cleanup();

// I2C Functions
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (reg select) failed: %s", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Circular Buffer Functions
void buffer_init(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

void buffer_add(CircularBuffer *buffer, AccelData data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

AccelData buffer_get_latest(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        AccelData empty = {0, 0, 0};
        return empty;
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[index];
}

// Signal Handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    program_running = 0;
}

// UDP Socket Setup
int setup_udp_socket(const char *ip, int port) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", strerror(errno));
        close(sock);
        return -1;
    }

    return sock;
}

// Thread Functions
void *sensor_thread(void *arg) {
    struct timespec req, rem;
    req.tv_sec = 0;
    req.tv_nsec = 10000000; // 10ms (100Hz)

    while (program_running) {
        AccelData data;
        uint8_t raw_data[6];

        if (sensor_failed) {
            nanosleep(&req, &rem);
            continue;
        }

        if (i2c_read_reg(i2c_fd, ACCEL_XOUT_H, raw_data, 6) == 0) {
            data.x = (int16_t)((raw_data[0] << 8) | raw_data[1]);
            data.y = (int16_t)((raw_data[2] << 8) | raw_data[3]);
            data.z = (int16_t)((raw_data[4] << 8) | raw_data[5]);

            buffer_add(&buffer, data);
            sensor_failure_count = 0; // Reset failure count on successful read
        } else {
            sensor_failure_count++;
            syslog(LOG_ERR, "Sensor read failed, count: %d", sensor_failure_count);
            if (sensor_failure_count >= SENSOR_FAILURE_THRESHOLD) {
                sensor_failed = 1;
                syslog(LOG_ERR, "Sensor marked as failed!");
            }
        }

        nanosleep(&req, &rem);
    }

    pthread_exit(NULL);
}

void *udp_thread(void *arg) {
    while (program_running) {
        AccelData latest_data = buffer_get_latest(&buffer);
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "%d,%d,%d", latest_data.x, latest_data.y, latest_data.z);

        if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            syslog(LOG_ERR, "UDP send failed: %s", strerror(errno));
        }

        usleep(10000); // 10ms
    }

    pthread_exit(NULL);
}

// Cleanup Function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close UDP socket
    if (udp_socket != -1) {
        close(udp_socket);
    }

    // Unmap driver memory (if mapped)
    // This part is omitted as it requires specific driver implementation details.
    // In a real implementation, you would unmap the memory here.

    // Remove driver file (if created)
    // This part is omitted as it requires specific driver implementation details.
    // In a real implementation, you would remove the file here.

    closelog();
}

int main() {
    openlog("mpu6050_driver", LOG_PID | LOG_CONS, LOG_USER);

    // Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C Initialization
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Wake up MPU6050
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        syslog(LOG_ERR, "Failed to wake up MPU6050: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize Circular Buffer
    buffer_init(&buffer);

    // Setup UDP Socket
    udp_socket = setup_udp_socket(UDP_IP, UDP_PORT);
    if (udp_socket < 0) {
        cleanup();
        return 1;
    }

    // Create Threads
    pthread_t sensor_thread_id, udp_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create sensor thread: %s", strerror(errno));
        cleanup();
        return 1;
    }
    if (pthread_create(&udp_thread_id, NULL, udp_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create UDP thread: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Wait for threads to finish
    pthread_join(sensor_thread_id, NULL);
    pthread_join(udp_thread_id, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

