#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay
int set_relay_state(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error setting relay %d to state %d: %d\n", gpio_pin, state, result);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to toggle the state of a relay
int toggle_relay_state(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    if (current_state < 0) {
        fprintf(stderr, "Error reading relay %d state: %d\n", gpio_pin, current_state);
        return -1; // Indicate failure
    }
    int new_state = !current_state;
    return set_relay_state(gpio_pin, new_state);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY3_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY4_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Toggle relay 1
        if (toggle_relay_state(RELAY1_PIN) != 0) {
            terminate = 1; // Exit loop on error
            break;
        }
        gpioDelay(INTERVAL1 * 1000000); // Delay for INTERVAL1 seconds

        // Toggle relay 2
        if (toggle_relay_state(RELAY2_PIN) != 0) {
            terminate = 1; // Exit loop on error
            break;
        }
        gpioDelay(INTERVAL2 * 1000000); // Delay for INTERVAL2 seconds

        // Toggle relay 3
        if (toggle_relay_state(RELAY3_PIN) != 0) {
            terminate = 1; // Exit loop on error
            break;
        }
        gpioDelay(INTERVAL3 * 1000000); // Delay for INTERVAL3 seconds

        // Toggle relay 4
        if (toggle_relay_state(RELAY4_PIN) != 0) {
            terminate = 1; // Exit loop on error
            break;
        }
        gpioDelay(INTERVAL4 * 1000000); // Delay for INTERVAL4 seconds
    }

    // Turn off all relays
    if (set_relay_state(RELAY1_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off relay 1\n");
    }
    if (set_relay_state(RELAY2_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off relay 2\n");
    }
    if (set_relay_state(RELAY3_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off relay 3\n");
    }
    if (set_relay_state(RELAY4_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off relay 4\n");
    }

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

