#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 3000

// Define relay activation time in milliseconds
#define RELAY_ACTIVATION_TIME 3000

// Global variables
static volatile int running = 1;
static volatile unsigned long last_relay_activation = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int deactivate_relay();
int log_alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    deactivate_relay();
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay
int activate_relay() {
    unsigned long current_time = gpioTick();
    if (current_time - last_relay_activation < DEBOUNCE_TIME * 1000) {
        // Debounce period not elapsed, do not activate relay
        return 1;
    }

    gpioWrite(RELAY_PIN, 1); // Activate relay
    last_relay_activation = current_time;
    return 0;
}

// Deactivate the relay
int deactivate_relay() {
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    return 0;
}

// Log alarm event to file
int log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Alarm triggered\n", s);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sound sensor
        int sound_detected = read_sound_sensor();

        // If sound is detected, activate relay and log alarm
        if (sound_detected == 0) {
            if (activate_relay() == 0) {
                log_alarm();
                gpioDelay(RELAY_ACTIVATION_TIME * 1000); // Wait for relay activation time
                deactivate_relay();
            }
        }

        gpioDelay(100 * 1000); // Poll every 100 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_relay();
    gpioTerminate();

    return 0;
}

