#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c(int address);
int init_mpu6050(int fd);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_angular_velocity(int16_t x, int16_t y, int16_t z);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void check_threshold(float angular_velocity, void (*callback)(float));
void signal_handler(int signal);
void cleanup(int fd);

// Callback function prototype
typedef void (*ThresholdCallback)(float);

// Circular buffer implementation
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// I2C initialization function
int init_i2c(int address) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU-6050 initialization function
int init_mpu6050(int fd) {
    // Wake up the MPU-6050
    uint8_t wake_up = 0x00;
    if (write(fd, &wake_up, 1) != 1) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Configure gyroscope sensitivity (optional)
    uint8_t gyro_config = 0x00; // Full scale range +/- 250 degrees/second
    if (write(fd, &gyro_config, 1) != 1) {
        perror("Error writing to GYRO_CONFIG");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    // Read 6 bytes of data starting from GYRO_XOUT_H
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate angular velocity magnitude
float calculate_angular_velocity(int16_t x, int16_t y, int16_t z) {
    // Convert raw values to degrees/second (assuming sensitivity of 131 LSB/deg/s)
    float x_dps = (float)x / 131.0;
    float y_dps = (float)y / 131.0;
    float z_dps = (float)z / 131.0;

    // Calculate magnitude
    return sqrt(x_dps * x_dps + y_dps * y_dps + z_dps * z_dps);
}

// Function to check if angular velocity exceeds the threshold
void check_threshold(float angular_velocity, void (*callback)(float)) {
    if (angular_velocity > ANGULAR_VELOCITY_THRESHOLD) {
        callback(angular_velocity);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to close I2C device
void cleanup(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        cleanup(i2c_fd);
        return 1;
    }

    // Circular buffer
    CircularBuffer angular_velocity_buffer = {{0.0}, 0, 0};

    // Callback function
    ThresholdCallback threshold_callback = [](float velocity) {
        printf("Threshold exceeded: %.2f degrees/second\n", velocity);
    };

    // Main loop
    while (program_running) {
        int16_t gyro_x, gyro_y, gyro_z;

        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate angular velocity
            float angular_velocity = calculate_angular_velocity(gyro_x, gyro_y, gyro_z);

            // Add to circular buffer
            add_to_buffer(&angular_velocity_buffer, angular_velocity);

            // Check threshold
            check_threshold(angular_velocity, threshold_callback);

            // Print angular velocity
            printf("Angular Velocity: %.2f degrees/second\n", angular_velocity);
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }

        // Delay
        usleep(10000); // 10ms
    }

    // Cleanup
    cleanup(i2c_fd);

    return 0;
}

