#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CO2_RESPONSE_LENGTH 9
#define SAMPLE_INTERVAL_SEC 5
#define TIMEOUT_MS 1000
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int uart_fd = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;

// Structure to hold sensor data
typedef struct {
    long long timestamp_us;
    int ppm;
    int error;
} sensor_data_t;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_co2_data(int fd, unsigned char *buffer, int buffer_size, int timeout_ms);
int validate_checksum(const unsigned char *data, int length);
sensor_data_t parse_co2_data(const unsigned char *data);
int log_data(const sensor_data_t *data, const char *log_file);
int log_error(const char *message, const char *error_log_file);
void signal_handler(int signal);
void cleanup();

// Function to initialize the UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = serOpen(device, baud_rate, 0); // 0 for default flags
    if (fd < 0) {
        fprintf(stderr, "Error opening UART: %s\n", device);
        return -1;
    }
    return fd;
}

// Function to read data from the UART with timeout
int read_co2_data(int fd, unsigned char *buffer, int buffer_size, int timeout_ms) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read = 0;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = timeout_ms / 1000;
    timeout.tv_usec = (timeout_ms % 1000) * 1000;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select()");
        return -1;
    } else if (retval) {
        bytes_read = serRead(fd, buffer, buffer_size);
        if (bytes_read < 0) {
            perror("serRead()");
            return -1;
        }
    } else {
        // Timeout occurred
        return 0;
    }

    return bytes_read;
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data, int length) {
    unsigned char checksum = 0;
    for (int i = 1; i < length - 1; i++) {
        checksum += data[i];
    }
    checksum = 0xFF - checksum + 1;

    return (checksum == data[length - 1]);
}

// Function to parse the CO2 data
sensor_data_t parse_co2_data(const unsigned char *data) {
    sensor_data_t sensor_data;
    struct timeval tv;

    gettimeofday(&tv, NULL);
    sensor_data.timestamp_us = (long long)tv.tv_sec * 1000000 + tv.tv_usec;
    sensor_data.ppm = (data[2] << 8) | data[3];
    sensor_data.error = 0;

    return sensor_data;
}

// Function to log the data to a file
int log_data(const sensor_data_t *data, const char *log_file) {
    FILE *fp = fopen(log_file, "a");
    if (fp == NULL) {
        perror("fopen()");
        return -1;
    }

    fprintf(fp, "{\"timestamp\":%lld,\"ppm\":%d,\"error\":%d}\n", data->timestamp_us, data->ppm, data->error);
    fflush(fp);
    fclose(fp);
    return 0;
}

// Function to log errors to a file
int log_error(const char *message, const char *error_log_file) {
    FILE *fp = fopen(error_log_file, "a");
    if (fp == NULL) {
        perror("fopen()");
        return -1;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    long long timestamp_us = (long long)tv.tv_sec * 1000000 + tv.tv_usec;

    fprintf(fp, "{\"timestamp\":%lld,\"error\":\"%s\"}\n", timestamp_us, message);
    fflush(fp);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function
void cleanup() {
    if (uart_fd != -1) {
        serClose(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char co2_command[] = CO2_COMMAND;
        unsigned char co2_response[CO2_RESPONSE_LENGTH];
        int bytes_read;
        sensor_data_t sensor_data;

        // Send CO2 command
        if (serWrite(uart_fd, co2_command, sizeof(co2_command)) != sizeof(co2_command)) {
            log_error("Failed to write CO2 command", ERROR_LOG_FILE);
            fprintf(stderr, "Failed to write CO2 command\n");
        }

        // Read CO2 data with timeout
        bytes_read = read_co2_data(uart_fd, co2_response, CO2_RESPONSE_LENGTH, TIMEOUT_MS);

        if (bytes_read == CO2_RESPONSE_LENGTH) {
            // Validate checksum
            if (validate_checksum(co2_response, CO2_RESPONSE_LENGTH)) {
                // Parse CO2 data
                sensor_data = parse_co2_data(co2_response);

                // Log data
                if (log_data(&sensor_data, LOG_FILE) != 0) {
                    log_error("Failed to log data", ERROR_LOG_FILE);
                    fprintf(stderr, "Failed to log data\n");
                }

                // Print data to stdout
                printf("{\"timestamp\":%lld,\"ppm\":%d,\"error\":%d}\n", sensor_data.timestamp_us, sensor_data.ppm, sensor_data.error);
            } else {
                log_error("Checksum mismatch", ERROR_LOG_FILE);
                fprintf(stderr, "Checksum mismatch\n");
            }
        } else if (bytes_read > 0) {
            log_error("Incomplete data received", ERROR_LOG_FILE);
            fprintf(stderr, "Incomplete data received (%d bytes)\n", bytes_read);
        } else if (bytes_read < 0) {
            log_error("Error reading from UART", ERROR_LOG_FILE);
            fprintf(stderr, "Error reading from UART\n");
        } else {
            log_error("Timeout reading from UART", ERROR_LOG_FILE);
            fprintf(stderr, "Timeout reading from UART\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

