#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_REG_A 0x00
#define CONFIG_REG_B 0x01
#define MODE_REG 0x02
#define DATA_X_MSB 0x03
#define DATA_X_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define DATA_Y_MSB 0x07
#define DATA_Y_LSB 0x08
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float compensate_heading(int16_t x, int16_t y, int16_t z);
void update_circular_buffer(float heading);
bool check_heading_deviation(float heading);
void set_gpio_output(bool state);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize HMC5883L
int initialize_hmc5883l() {
    // Configuration register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, CONFIG_REG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configuration register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, CONFIG_REG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Mode register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Compensate heading
float compensate_heading(int16_t x, int16_t y, int16_t z) {
    float heading = atan2((float)y - 50, (float)x - 100) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Update circular buffer
void update_circular_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check heading deviation
bool check_heading_deviation(float heading) {
    float diff = fabs(heading - TARGET_HEADING);
    if (diff > 180.0) {
        diff = 360.0 - diff;
    }
    return (diff > HEADING_THRESHOLD);
}

// Set GPIO output
void set_gpio_output(bool state) {
    gpioWrite(GPIO_PIN, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

