#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define BH1750_ADDR 0x23
#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_MED 150.0
#define LUX_THRESHOLD_HIGH 300.0
#define LOG_FILE "lighting_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
void control_relays(float lux);
void log_data(float lux);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char config[1] = {0x10}; // Continuous high resolution mode
    char buffer[2];
    int lux = -1; // Default to error value

    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    gpioDelay(120); // Wait for conversion (at least 120ms)

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    lux = (buffer[0] << 8) | buffer[1];
    return lux;
}

// Control RGB relays based on lux value
void control_relays(float lux) {
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    if (lux < LUX_THRESHOLD_LOW) {
        gpioWrite(RED_PIN, 1);
    } else if (lux >= LUX_THRESHOLD_LOW && lux < LUX_THRESHOLD_MED) {
        gpioWrite(GREEN_PIN, 1);
    } else if (lux >= LUX_THRESHOLD_MED && lux < LUX_THRESHOLD_HIGH) {
        gpioWrite(BLUE_PIN, 1);
    } else if (lux >= LUX_THRESHOLD_HIGH) {
        gpioWrite(RED_PIN, 1);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN, 1);
    }
}

// Log data to file
void log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, gpioRead(RED_PIN), gpioRead(GREEN_PIN), gpioRead(BLUE_PIN));
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    while (!terminate) {
        int lux = read_bh1750(i2c_handle);
        if (lux >= 0) {
            control_relays((float)lux);
            log_data((float)lux);
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

