// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Proportional gain
#define PROPORTIONAL_GAIN 2.0

// Distance thresholds (cm)
#define FORWARD_THRESHOLD 50.0
#define BACKWARD_THRESHOLD 50.0

// Distance range (cm)
#define MIN_DISTANCE 10.0
#define MAX_DISTANCE 100.0

// Global variables for distance readings
float distance_a = 0.0;
float distance_b = 0.0;

// Function prototypes
int initialize_gpio();
void set_motor_direction(int motor, int direction);
void set_motor_speed(int motor, int speed);
void stop_motor(int motor);
void set_motor_a_direction(int direction);
void set_motor_b_direction(int direction);
void set_motor_a_speed(int speed);
void set_motor_b_speed(int speed);
void stop_motor_a();
void stop_motor_b();
void stop_all_motors();
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    stop_all_motors();
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for Motor A
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for MOTOR_A_IN1\n");
        return 1;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for MOTOR_A_IN2\n");
        return 1;
    }

    // Set GPIO modes for Motor B
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for MOTOR_B_IN3\n");
        return 1;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for MOTOR_B_IN4\n");
        return 1;
    }

    // Set PWM frequency for Motor A
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for MOTOR_A_IN2\n");
        return 1;
    }

    // Set PWM frequency for Motor B
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for MOTOR_B_IN4\n");
        return 1;
    }

    return 0;
}

// Set motor direction
void set_motor_direction(int motor, int direction) {
    int in1, in2, in3, in4;

    if (motor == 0) { // Motor A
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
    } else { // Motor B
        in1 = MOTOR_B_IN3;
        in2 = MOTOR_B_IN4;
    }

    if (direction == 1) { // Forward
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
    } else if (direction == -1) { // Backward
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
    } else { // Stop
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
    }
}

// Set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    int in2, in4;

    if (motor == 0) { // Motor A
        in2 = MOTOR_A_IN2;
    } else { // Motor B
        in4 = MOTOR_B_IN4;
    }

    if (motor == 0) {
        gpioPWM(in2, speed);
    } else {
        gpioPWM(in4, speed);
    }
}

// Stop a specific motor
void stop_motor(int motor) {
    set_motor_direction(motor, 0);
    set_motor_speed(motor, 0);
}

// Convenience functions for Motor A
void set_motor_a_direction(int direction) {
    set_motor_direction(0, direction);
}

void set_motor_a_speed(int speed) {
    set_motor_speed(0, speed);
}

void stop_motor_a() {
    stop_motor(0);
}

// Convenience functions for Motor B
void set_motor_b_direction(int direction) {
    set_motor_direction(1, direction);
}

void set_motor_b_speed(int speed) {
    set_motor_speed(1, speed);
}

void stop_motor_b() {
    stop_motor(1);
}

// Stop all motors
void stop_all_motors() {
    stop_motor_a();
    stop_motor_b();
}

// Parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        exit(1);
    }

    distance_a = atof(argv[1]);
    distance_b = atof(argv[2]);

    if (distance_a < MIN_DISTANCE || distance_a > MAX_DISTANCE) {
        fprintf(stderr, "Error: distance_a must be between %f and %f\n", MIN_DISTANCE, MAX_DISTANCE);
        exit(1);
    }

    if (distance_b < MIN_DISTANCE || distance_b > MAX_DISTANCE) {
        fprintf(stderr, "Error: distance_b must be between %f and %f\n", MIN_DISTANCE, MAX_DISTANCE);
        exit(1);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (1) {
        // Calculate PWM duty cycle for Motor A
        int duty_cycle_a = 0;
        if (distance_a < FORWARD_THRESHOLD) {
            duty_cycle_a = (int)(PROPORTIONAL_GAIN * (FORWARD_THRESHOLD - distance_a));
            if (duty_cycle_a > 255) {
                duty_cycle_a = 255;
            }
            set_motor_a_direction(1); // Forward
        } else if (distance_a >= FORWARD_THRESHOLD && distance_a < BACKWARD_THRESHOLD) {
            duty_cycle_a = 0;
            set_motor_a_direction(0); // Stop
        } else {
            duty_cycle_a = (int)(PROPORTIONAL_GAIN * (distance_a - BACKWARD_THRESHOLD));
            if (duty_cycle_a > 255) {
                duty_cycle_a = 255;
            }
            set_motor_a_direction(-1); // Backward
        }
        set_motor_a_speed(duty_cycle_a);

        // Calculate PWM duty cycle for Motor B
        int duty_cycle_b = 0;
        if (distance_b < FORWARD_THRESHOLD) {
            duty_cycle_b = (int)(PROPORTIONAL_GAIN * (FORWARD_THRESHOLD - distance_b));
            if (duty_cycle_b > 255) {
                duty_cycle_b = 255;
            }
            set_motor_b_direction(1); // Forward
        } else if (distance_b >= FORWARD_THRESHOLD && distance_b < BACKWARD_THRESHOLD) {
            duty_cycle_b = 0;
            set_motor_b_direction(0); // Stop
        } else {
            duty_cycle_b = (int)(PROPORTIONAL_GAIN * (distance_b - BACKWARD_THRESHOLD));
            if (duty_cycle_b > 255) {
                duty_cycle_b = 255;
            }
            set_motor_b_direction(-1); // Backward
        }
        set_motor_b_speed(duty_cycle_b);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

