#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Configuration
#define MPU6050_ADDR 0x68
#define SDA_PIN 2
#define SCL_PIN 3
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 20000000 // 20ms (50Hz)
#define LOG_FILE "solar_tracker.log"

// MPU6050 Registers
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int init_mpu6050(int fd);
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int position);
void signal_handler(int sig);

// I2C read with exponential backoff
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < 5) {
        result = i2c_smbus_read_i2c_block_data(fd, reg, len, (char *)data);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %s\n", reg, len, strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, len %d)\n", reg, len);
    return -1; // Failure
}

// I2C write with exponential backoff
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < 5) {
        result = i2c_smbus_write_byte_data(fd, reg, data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, data 0x%02X): %s\n", reg, data, strerror(errno));
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, data 0x%02X)\n", reg, data);
    return -1; // Failure
}

// Initialize MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_write_reg(fd, MPU6050_PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Read MPU6050 data
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t data[14];

    if (i2c_read_reg(fd, MPU6050_ACCEL_XOUT_H, data, 14) != 0) {
        fprintf(stderr, "Failed to read MPU6050 data\n");
        return -1;
    }

    *accel_x = (int16_t)((data[0] << 8) | data[1]);
    *accel_y = (int16_t)((data[2] << 8) | data[3]);
    *accel_z = (int16_t)((data[4] << 8) | data[5]);
    *gyro_x = (int16_t)((data[8] << 8) | data[9]);
    *gyro_y = (int16_t)((data[10] << 8) | data[11]);
    *gyro_z = (int16_t)((data[12] << 8) | data[13]);

    return 0;
}

// Calculate pitch and roll from accelerometer data
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll) {
    float ax = (float)accel_x;
    float ay = (float)accel_y;
    float az = (float)accel_z;

    *pitch = atan2(ax, sqrt(ay * ay + az * az)) * 180 / M_PI;
    *roll = atan2(ay, sqrt(ax * ax + az * az)) * 180 / M_PI;
}

// Set servo angle using PWM
int set_servo_angle(int angle) {
    char buffer[64];
    int duty_cycle;

    // Map angle (0-180) to duty cycle (500000 - 2500000)
    duty_cycle = 500000 + (int)((float)angle / 180.0 * 2000000.0);

    // Export PWM channel if not already exported
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_NUM);
    if (access(buffer, F_OK) == -1) {
        snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
        int export_fd = open(buffer, O_WRONLY);
        if (export_fd == -1) {
            fprintf(stderr, "Failed to open PWM export file: %s\n", strerror(errno));
            return -1;
        }
        dprintf(export_fd, "%d", PWM_NUM);
        close(export_fd);
        usleep(100000); // Wait for the PWM channel to be created
    }

    // Set PWM period
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    int period_fd = open(buffer, O_WRONLY);
    if (period_fd == -1) {
        fprintf(stderr, "Failed to open PWM period file: %s\n", strerror(errno));
        return -1;
    }
    dprintf(period_fd, "%d", PWM_PERIOD);
    close(period_fd);

    // Set PWM duty cycle
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    int duty_cycle_fd = open(buffer, O_WRONLY);
    if (duty_cycle_fd == -1) {
        fprintf(stderr, "Failed to open PWM duty_cycle file: %s\n", strerror(errno));
        return -1;
    }
    dprintf(duty_cycle_fd, "%d", duty_cycle);
    close(duty_cycle_fd);

    // Enable PWM
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    int enable_fd = open(buffer, O_WRONLY);
    if (enable_fd == -1) {
        fprintf(stderr, "Failed to open PWM enable file: %s\n", strerror(errno));
        return -1;
    }
    dprintf(enable_fd, "1");
    close(enable_fd);

    return 0;
}

// Log data to file
int log_data(float pitch, float roll, int position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, position);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main() {
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int angle = 90; // Initial angle
    int position;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
