#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the fade duration in seconds
#define FADE_DURATION 1800

// Define the PWM frequency in Hz
#define PWM_FREQUENCY 100

// Define the number of PWM steps
#define PWM_STEPS 100

// Define the delay between PWM steps in microseconds
#define PWM_DELAY (1000000 / PWM_FREQUENCY / PWM_STEPS)

// Global variables
static volatile int running = 1;
static FILE *schedule_file = NULL;

// Function prototypes
int parse_schedule_line(char *line, int *relay_number, int *state);
int time_to_seconds(char *time_str);
int compare_time(int current_time, int scheduled_time);
void set_relay_state(int relay_number, int state);
void fade_lamp(int relay_number, int target_state);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);
    gpioWrite(RELAY3_GPIO, 0);
    gpioWrite(RELAY4_GPIO, 0);

    gpioTerminate();
}

// Function to parse a line from the schedule file
int parse_schedule_line(char *line, int *relay_number, int *state) {
    char *token;
    char *rest = line;

    // Extract time
    token = strtok_r(rest, ",", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid schedule format (missing time)\n");
        return 1;
    }
    int scheduled_time = time_to_seconds(token);
    if (scheduled_time == -1) {
        fprintf(stderr, "Error: Invalid time format: %s\n", token);
        return 1;
    }

    // Extract relay number and state
    token = strtok_r(rest, ";", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid schedule format (missing relay/state)\n");
        return 1;
    }

    char *relay_str = strtok(token, ",");
    char *state_str = strtok(NULL, ",");

    if (relay_str == NULL || state_str == NULL) {
        fprintf(stderr, "Error: Invalid schedule format (missing relay/state values)\n");
        return 1;
    }

    *relay_number = atoi(relay_str);
    if (*relay_number < 1 || *relay_number > 4) {
        fprintf(stderr, "Error: Invalid relay number: %d\n", *relay_number);
        return 1;
    }

    if (strcmp(state_str, "on") == 0) {
        *state = 1;
    } else if (strcmp(state_str, "off") == 0) {
        *state = 0;
    } else {
        fprintf(stderr, "Error: Invalid state: %s\n", state_str);
        return 1;
    }

    return 0;
}

// Function to convert time string to seconds since midnight
int time_to_seconds(char *time_str) {
    int hours, minutes, seconds;
    if (sscanf(time_str, "%d:%d:%d", &hours, &minutes, &seconds) != 3) {
        return -1;
    }
    if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59 || seconds < 0 || seconds > 59) {
        return -1;
    }
    return hours * 3600 + minutes * 60 + seconds;
}

// Function to compare current time with scheduled time
int compare_time(int current_time, int scheduled_time) {
    return current_time - scheduled_time;
}

// Function to set the state of a relay
void set_relay_state(int relay_number, int state) {
    int gpio_pin;
    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
            return;
    }
    gpioWrite(gpio_pin, state);
}

// Function to fade a lamp
void fade_lamp(int relay_number, int target_state) {
    int current_state = gpioRead(switch relay_number); // Get current state
    if (current_state == target_state) return; // No fade needed

    int step_delay = PWM_DELAY; // Initial delay
    int num_steps = FADE_DURATION * PWM_FREQUENCY;

    if (current_state == 0 && target_state == 1) { // Fading on
        for (int i = 0; i <= num_steps; i++) {
            int duty_cycle = (int)(((float)i / num_steps) * 100);
            gpioPWM(switch relay_number, duty_cycle);
            gpioDelay(step_delay);
            step_delay = (int)(((float)i / num_steps) * PWM_DELAY); // Gradually decrease delay
        }
        gpioWrite(switch relay_number, 1); // Ensure relay is on
    } else { // Fading off
        for (int i = num_steps; i >= 0; i--) {
            int duty_cycle = (int)(((float)i / num_steps) * 100);
            gpioPWM(switch relay_number, duty_cycle);
            gpioDelay(step_delay);
            step_delay = (int)(((float)i / num_steps) * PWM_DELAY); // Gradually decrease delay
        }
        gpioWrite(switch relay_number, 0); // Ensure relay is off
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the schedule file
    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        fprintf(stderr, "Error: Could not open schedule file %s\n", SCHEDULE_FILE);
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (running) {
        // Get current time
        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        int current_time = local_time->tm_hour * 3600 + local_time->tm_min * 60 + local_time->tm_sec;

        // Read the schedule file line by line
        char line[256];
        while (fgets(line, sizeof(line), schedule_file) != NULL) {
            int relay_number, state;
            if (parse_schedule_line(line, &relay_number, &state) == 0) {
                int scheduled_time = time_to_seconds(strtok(line, ","));
                if (compare_time(current_time, scheduled_time) >= 0) {
                    fade_lamp(relay_number, state);
                }
            }
        }

        // Reset file pointer to the beginning of the file
        rewind(schedule_file);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    fclose(schedule_file);
    cleanup_gpio();
    return 0;
}

