    if (sscanf(time_str, "%d:%d:%d", &hours, &minutes, &seconds) != 3) {
        return -1;
    }
    if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59 || seconds < 0 || seconds > 59) {
        return -1;
    }
    return hours * 3600 + minutes * 60 + seconds;
}

// Function to compare current time with scheduled time
int compare_time(int current_time, int scheduled_time) {
    return current_time - scheduled_time;
}

// Function to set the state of a relay
void set_relay_state(int relay_number, int state) {
    int gpio_pin;
    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
            return;
    }
    gpioWrite(gpio_pin, state);
}

// Function to fade a lamp
void fade_lamp(int relay_number, int target_state) {
    int current_state = gpioRead(switch relay_number); // Get current state
    if (current_state == target_state) return; // No fade needed

    int step_delay = PWM_DELAY; // Initial delay
    int num_steps = FADE_DURATION * PWM_FREQUENCY;

    if (current_state == 0 && target_state == 1) { // Fading on
        for (int i = 0; i <= num_steps; i++) {
            int duty_cycle = (int)(((float)i / num_steps) * 100);
            gpioPWM(switch relay_number, duty_cycle);
            gpioDelay(step_delay);
            step_delay = (int)(((float)i / num_steps) * PWM_DELAY); // Gradually decrease delay
        }
        gpioWrite(switch relay_number, 1); // Ensure relay is on
    } else { // Fading off
        for (int i = num_steps; i >= 0; i--) {
            int duty_cycle = (int)(((float)i / num_steps) * 100);
            gpioPWM(switch relay_number, duty_cycle);
            gpioDelay(step_delay);
            step_delay = (int)(((float)i / num_steps) * PWM_DELAY); // Gradually decrease delay
        }
        gpioWrite(switch relay_number, 0); // Ensure relay is off
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the schedule file
    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        fprintf(stderr, "Error: Could not open schedule file %s\n", SCHEDULE_FILE);
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (running) {
        // Get current time
        time_t now = time(NULL);
        struct tm *local_time = localtime(&now);
        int current_time = local_time->tm_hour * 3600 + local_time->tm_min * 60 + local_time->tm_sec;

        // Read the schedule file line by line
        char line[256];
        while (fgets(line, sizeof(line), schedule_file) != NULL) {
            int relay_number, state;
            if (parse_schedule_line(line, &relay_number, &state) == 0) {
                int scheduled_time = time_to_seconds(strtok(line, ","));
                if (compare_time(current_time, scheduled_time) >= 0) {
                    fade_lamp(relay_number, state);
                }
            }
        }

        // Reset file pointer to the beginning of the file
        rewind(schedule_file);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    fclose(schedule_file);
    cleanup_gpio();
    return 0;
}

