#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 20.0
#define TIMEOUT_US 50000 // 50ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
float measure_distance();
float distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo signal timeout (start)\n");
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo signal timeout (end)\n");
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    if (diff_tick < 0) {
        diff_tick += 0xFFFFFFFF; // Handle tick rollover
    }

    float time_taken = (float)diff_tick / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

// Function to map distance to frequency
float distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set buzzer frequency using PWM
void set_buzzer_frequency(float frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    int dutycycle = (int)(frequency * 1000.0 / 1000000.0 * 255.0); // Calculate duty cycle (0-255)
    gpioPWM(BUZZER_PIN, dutycycle);
}

// Function to cleanup GPIO and terminate pigpio
void cleanup() {
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);
    gpioSetPWMfrequency(BUZZER_PIN, 1000); // Set PWM frequency to 1 kHz

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed\n");
        } else {
            float frequency = distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
        }

        gpioDelay(20); // 20 ms delay (50 Hz loop)
    }

    cleanup();
    return 0;
}

