// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to calculate the RGB color values based on the proximity value
void calculate_rgb(float proximity, int *red, int *green, int *blue) {
    // Map the proximity value (0.0 to 1.0) to a sine wave
    float angle = proximity * 2 * M_PI;
    float sine_value = sin(angle);

    // Scale the sine value to the range 0-255
    int color_value = (int)((sine_value + 1.0) * 127.5);

    // Assign the color values to the RGB components
    *red   = color_value;
    *green = color_value;
    *blue  = color_value;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for all pins
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency for GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM range for all pins
    if (gpioSetPWMrange(RED_PIN, 255) != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, 255) != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, 255) != 0) {
        fprintf(stderr, "Error setting PWM range for GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    float proximity = 0.0;
    int red, green, blue;
    while (program_running) {
        // Calculate RGB values based on the proximity value
        calculate_rgb(proximity, &red, &green, &blue);

        // Set the PWM duty cycles for each GPIO pin
        if (set_pwm_duty_cycle(RED_PIN, red) != 0) {
            program_running = 0; // Exit loop on error
        }
        if (set_pwm_duty_cycle(GREEN_PIN, green) != 0) {
            program_running = 0; // Exit loop on error
        }
        if (set_pwm_duty_cycle(BLUE_PIN, blue) != 0) {
            program_running = 0; // Exit loop on error
        }

        // Increment the proximity value
        proximity += 0.01;
        if (proximity > 1.0) {
            proximity = 0.0;
        }

        // Delay for a short period
        gpioDelay(10000); // 10ms
    }

    // Turn off the LED
    if (set_pwm_duty_cycle(RED_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off LED (Red)\n");
    }
    if (set_pwm_duty_cycle(GREEN_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off LED (Green)\n");
    }
    if (set_pwm_duty_cycle(BLUE_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off LED (Blue)\n");
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

