#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody notes (frequencies in Hz)
const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile sig_atomic_t program_running = 1;
volatile sig_atomic_t button_pressed = 0;
volatile sig_atomic_t melody_playing = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// ISR for button press
void button_isr(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) // Convert ms to us
    {
        button_pressed = 1;
        last_tick = current_tick;
    }
}

// Function to play the melody
void play_melody()
{
    int i;
    for (i = 0; i < melody_length; i++)
    {
        if (!melody_playing) return; // Check if melody should be stopped
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
        gpioSetPWMfrequency(BUZZER_PIN, melody[i]);
        gpioDelay(200); // Play each note for 200ms
        gpioPWM(BUZZER_PIN, 0); // Stop the tone
        gpioDelay(50); // Short pause between notes
    }
    melody_playing = 0; // Reset flag after melody is done
}

// Function to stop the melody
void stop_melody()
{
    melody_playing = 0;
    gpioPWM(BUZZER_PIN, 0); // Stop the tone
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal)
{
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM frequency (initial value, will be changed in play_melody)
    gpioSetPWMfrequency(BUZZER_PIN, 440); // Initial frequency

    // Set PWM duty cycle (50% = 128)
    gpioPWM(BUZZER_PIN, 0); // Initially off

    // Set up interrupt on button pin (falling edge)
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running)
    {
        if (button_pressed)
        {
            button_pressed = 0; // Reset the flag
            if (!melody_playing)
            {
                melody_playing = 1;
                play_melody();
            }
            else
            {
                stop_melody();
            }
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

