#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT 1000

// Structure to hold event data
typedef struct {
    int value;
    char timestamp[32];
} Event;

// Global variables
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;
static int timeout_ms = DEFAULT_TIMEOUT;

// Function prototypes
int init_gpio();
int read_sensor(int *value);
int get_iso8601_timestamp(char *timestamp);
int log_event(int value, const char *timestamp);
int check_earthquake(int *window);
int print_alert(const char *timestamp);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Read sensor value
int read_sensor(int *value) {
    *value = gpioRead(GPIO_PIN);
    return 0;
}

// Get ISO 8601 timestamp
int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    return 0;
}

// Log event to file
int log_event(int value, const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%d\n", timestamp, value);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Check for earthquake alert
int check_earthquake(int *window) {
    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (window[i].value == 1) {
            high_count++;
        }
    }
    return (high_count >= 3) ? 1 : 0;
}

// Print earthquake alert
int print_alert(const char *timestamp) {
    printf("EARTHQUAKE ALERT: %s\n", timestamp);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    int sensor_value;
    char timestamp[32];
    Event event_window[WINDOW_SIZE];
    int window_index = 0;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                timeout_ms = atoi(optarg);
                if (timeout_ms <= 0) {
                    fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT);
                    timeout_ms = DEFAULT_TIMEOUT;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t timeout_ms]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring vibration sensor... (Timeout: %d ms)\n", timeout_ms);

    // Main loop
    while (!terminate) {
        // Read sensor value
        if (read_sensor(&sensor_value) != 0) {
            fprintf(stderr, "Error reading sensor value\n");
            continue; // Continue to the next iteration
        }

        // Get timestamp
        if (get_iso8601_timestamp(timestamp) != 0) {
            fprintf(stderr, "Error getting timestamp\n");
            continue; // Continue to the next iteration
        }

        // Log event
        if (log_event(sensor_value, timestamp) != 0) {
            fprintf(stderr, "Error logging event\n");
        }

        // Update event window
        event_window[window_index].value = sensor_value;
        strncpy(event_window[window_index].timestamp, timestamp, sizeof(event_window[window_index].timestamp) - 1);
        event_window[window_index].timestamp[sizeof(event_window[window_index].timestamp) - 1] = '\0'; // Ensure null termination
        window_index = (window_index + 1) % WINDOW_SIZE;

        // Check for earthquake alert
        if (check_earthquake((int *)event_window)) {
            print_alert(timestamp);
        }

        // Wait for the specified timeout
        gpioDelay(timeout_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

