#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// Magnetometer Registers
#define CRA_REG_M 0x00
#define CRB_REG_M 0x01
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Compass directions
const char *compass_directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

// Global variables for cleanup
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_magnetometer(int i2c_handle);
int read_magnetometer_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
void calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z, int16_t *x_calibrated, int16_t *y_calibrated, int16_t *z_calibrated);
float calculate_heading(int16_t x, int16_t y);
const char *map_heading_to_direction(float heading);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float heading);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initializes the LSM303DLHC magnetometer
int initialize_magnetometer(int i2c_handle) {
    // Set gain to +/- 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, CRB_REG_M, 0x20) < 0) {
        fprintf(stderr, "Error writing to CRB_REG_M\n");
        return -1;
    }

    // Set continuous conversion mode
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Reads raw magnetometer data from the LSM303DLHC
int read_magnetometer_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Applies hard-iron calibration offsets to the magnetometer data
void calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z, int16_t *x_calibrated, int16_t *y_calibrated, int16_t *z_calibrated) {
    *x_calibrated = x - X_OFFSET;
    *y_calibrated = y - Y_OFFSET;
    *z_calibrated = z - Z_OFFSET;
}

// Calculates the heading in degrees from the calibrated magnetometer data
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y, (float)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Maps the heading in degrees to one of the eight compass directions
const char *map_heading_to_direction(float heading) {
    int index = (int)(heading / 45) % 8;
    return compass_directions[index];
}

// Logs the timestamp, calibrated X, Y, Z values, and numeric heading to the CSV file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float heading) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d,%d,%d,%.2f\n", timestamp, x, y, z, heading) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer(i2c_handle) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z, x_calibrated, y_calibrated, z_calibrated;
    float heading;
    const char *direction;

    // Main loop
    while (1) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_handle, &x, &y, &z) == 0) {
