#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define log file name
#define LOG_FILE "relay_log.json"

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void touch_callback(int gpio, int level, unsigned int tick, void *user_data);
void toggle_relay();
int log_relay_state();
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pin as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin pull-down resistor\n");
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Ensure relay is initially OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    return 0;
}

// Callback function for touch sensor interrupt
void touch_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    // Debounce logic
    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        toggle_relay();
        last_touch_time = current_time;
    }
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    log_relay_state();
}

// Function to log relay state to file
int log_relay_state() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            free(timestamp);
            return 1;
        }
    }

    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);

    return 0;
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Log the final OFF state
    log_relay_state();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for touch sensor
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        gpioDelay(100); // Reduce CPU usage
    }

    return 0;
}

