#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 100

// Define servo pulse widths (microseconds)
#define VALVE_CLOSED_PULSE 500
#define VALVE_OPEN_PULSE 1500
#define NOZZLE_0_DEGREE_PULSE 500
#define NOZZLE_45_DEGREE_PULSE 1000
#define NOZZLE_90_DEGREE_PULSE 1500
#define NOZZLE_135_DEGREE_PULSE 2000
#define NOZZLE_180_DEGREE_PULSE 2500

// Define watering cycle parameters
#define WATERING_CYCLE_DELAY 5 // seconds
#define NOZZLE_STEP_DURATION 2 // seconds
#define SPRAY_DURATION 5 // seconds

// Define soil moisture simulation parameters
#define MOISTURE_CYCLE_DELAY 1 // seconds
#define MOISTURE_CYCLE_LENGTH 5 // seconds

// Define retry parameters
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Define error codes
#define ERROR_SERVO_SET_FAILED -1
#define ERROR_SERVO_OPEN_FAILED -2
#define ERROR_SERVO_CLOSE_FAILED -3
#define ERROR_SERVO_CLEANUP_FAILED -4
#define ERROR_SIGNAL_HANDLER_FAILED -5

// Global variables
volatile sig_atomic_t terminate = 0;
int moisture_level = 20; // Initial moisture level
int moisture_index = 0;
int moisture_cycle[5] = {20, 40, 60, 80, 100};

// Function prototypes
int set_servo_pulse(int gpio, int pulse_width);
int open_valve();
int close_valve();
int sweep_nozzle();
int stop_servos();
void signal_handler(int signal);
void log_error(const char *message);
void simulate_moisture();

// Function to set the pulse width of a servo motor
int set_servo_pulse(int gpio, int pulse_width) {
    int result, retries = 0;
    while (retries < MAX_RETRIES) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Failed to set servo pulse for GPIO %d: %d", gpio, result);
            log_error(error_message);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }
    return ERROR_SERVO_SET_FAILED;
}

// Function to open the valve
int open_valve() {
    return set_servo_pulse(VALVE_SERVO_PIN, VALVE_OPEN_PULSE);
}

// Function to close the valve
int close_valve() {
    int result = set_servo_pulse(VALVE_SERVO_PIN, VALVE_CLOSED_PULSE);
    if (result != 0) {
        log_error("Failed to close valve.");
    }
    return result;
}

// Function to sweep the nozzle through predefined angles
int sweep_nozzle() {
    int pulse_widths[] = {NOZZLE_0_DEGREE_PULSE, NOZZLE_45_DEGREE_PULSE, NOZZLE_90_DEGREE_PULSE, NOZZLE_135_DEGREE_PULSE, NOZZLE_180_DEGREE_PULSE};
    int num_angles = sizeof(pulse_widths) / sizeof(pulse_widths[0]);
    int result;

    for (int i = 0; i < num_angles; i++) {
        result = set_servo_pulse(NOZZLE_SERVO_PIN, pulse_widths[i]);
        if (result != 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Failed to set nozzle angle %d: %d", i, result);
            log_error(error_message);
            continue; // Continue to the next angle
        }
        gpioDelay(NOZZLE_STEP_DURATION * 1000000); // Convert seconds to microseconds
    }
    return 0; // Return 0 to indicate success
}

// Function to stop both servos
int stop_servos() {
    int result_valve = set_servo_pulse(VALVE_SERVO_PIN, 0);
    int result_nozzle = set_servo_pulse(NOZZLE_SERVO_PIN, 0);

    if (result_valve != 0 || result_nozzle != 0) {
        log_error("Failed to stop servos.");
        return ERROR_SERVO_CLOSE_FAILED;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program.\n", signal);
    terminate = 1;
    stop_servos();
    gpioTerminate();
    exit(0);
}

// Function to log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen("watering.log", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Failed to open log file");
    }
}

// Function to simulate soil moisture
void simulate_moisture() {
    static time_t last_update = 0;
    time_t now = time(NULL);

    if (last_update == 0) {
        last_update = now;
    }

    if (now - last_update >= MOISTURE_CYCLE_DELAY) {
        moisture_level = moisture_cycle[moisture_index];
        moisture_index = (moisture_index + 1) % 5;
        last_update = now;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        simulate_moisture();

        printf("Moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD_LOW) {
            printf("Moisture level below threshold. Starting watering cycle.\n");

            // Open valve
            if (open_valve() != 0) {
                log_error("Failed to open valve. Aborting watering cycle.");
                gpioDelay(WATERING_CYCLE_DELAY * 1000000); // Wait before next cycle
                continue;
            }

            // Sweep nozzle
            if (sweep_nozzle() != 0) {
                log_error("Failed to sweep nozzle. Continuing to next angle.");
            }

            // Hold spray
            gpioDelay(SPRAY_DURATION * 1000000);

            // Close valve
            if (close_valve() != 0) {
                log_error("Failed to close valve.");
            }

            // Wait before next cycle
            gpioDelay(WATERING_CYCLE_DELAY * 1000000);
        } else {
            printf("Moisture level above threshold. Skipping watering cycle.\n");
            gpioDelay(WATERING_CYCLE_DELAY * 1000000); // Wait before checking again
        }
    }

    // Cleanup
    stop_servos();
    gpioTerminate();

    return 0;
}

