    signal(SIGTERM, signal_handler);

    int16_t gyro_x, gyro_y, gyro_z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 milliseconds (10 Hz)

