#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variable for I2C handle
int i2c_handle;

// Signal handler function
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the MPU-6050
int init_mpu6050()
{
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int16_t gyro_x, gyro_y, gyro_z;

        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n", gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    return 0;
}

