#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the watering cycle duration (24 hours in seconds)
#define WATERING_CYCLE_DURATION 86400

// Define the watering duration (5 seconds)
#define WATERING_DURATION 5

// Define the delay between relay activations (60 seconds)
#define DELAY_BETWEEN_ACTIVATIONS 60

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void log_watering_cycle();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    cleanup();
    exit(0);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY1_PIN);
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY2_PIN);
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY3_PIN);
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY4_PIN);
        return 1;
    }

    // Set all relays to inactive (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to activate a relay (set GPIO pin LOW)
void activate_relay(int pin) {
    gpioWrite(pin, 0); // Set pin LOW to activate relay
    printf("Activating relay on GPIO%d\n", pin);
}

// Function to deactivate a relay (set GPIO pin HIGH)
void deactivate_relay(int pin) {
    gpioWrite(pin, 1); // Set pin HIGH to deactivate relay
    printf("Deactivating relay on GPIO%d\n", pin);
}

// Function to log the watering cycle start time to a file
void log_watering_cycle() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    FILE *fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening watering_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s\n", buf);
    fclose(fp);
    printf("Logged watering cycle start time: %s\n", buf);
}

// Function to clean up GPIO resources before exiting
void cleanup() {
    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Plant watering system started\n");

    // Main loop
    while (program_running) {
        // Activate relays sequentially
        activate_relay(RELAY1_PIN);
        gpioDelay(WATERING_DURATION * 1000000); // Delay for watering duration (microseconds)
        deactivate_relay(RELAY1_PIN);
        gpioDelay(DELAY_BETWEEN_ACTIVATIONS * 1000000); // Delay between activations (microseconds)

        activate_relay(RELAY2_PIN);
        gpioDelay(WATERING_DURATION * 1000000);
        deactivate_relay(RELAY2_PIN);
        gpioDelay(DELAY_BETWEEN_ACTIVATIONS * 1000000);

        activate_relay(RELAY3_PIN);
        gpioDelay(WATERING_DURATION * 1000000);
        deactivate_relay(RELAY3_PIN);
        gpioDelay(DELAY_BETWEEN_ACTIVATIONS * 1000000);

        activate_relay(RELAY4_PIN);
        gpioDelay(WATERING_DURATION * 1000000);
        deactivate_relay(RELAY4_PIN);
        gpioDelay(DELAY_BETWEEN_ACTIVATIONS * 1000000);

        // Log the watering cycle start time
        log_watering_cycle();

        // Wait for the next watering cycle
        gpioDelay(WATERING_CYCLE_DURATION * 1000000); // Wait for 24 hours (microseconds)
    }

    return 0;
}

