#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define the log file name
#define LOG_FILE "smart_lighting.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int set_pwm_frequency(int pin, int frequency);
int set_pwm_duty_cycle(int pin, int duty_cycle);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received signal, shutting down...");
        running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        log_event("Failed to set GPIO17 to output mode");
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        log_event("Failed to set GPIO18 to output mode");
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        log_event("Failed to set GPIO27 to output mode");
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        log_event("Failed to set GPIO22 to output mode");
        return 1;
    }

    // Set PWM frequency for each pin
    if (set_pwm_frequency(RELAY1_PIN, PWM_FREQUENCY) != 0) return 1;
    if (set_pwm_frequency(RELAY2_PIN, PWM_FREQUENCY) != 0) return 1;
    if (set_pwm_frequency(RELAY3_PIN, PWM_FREQUENCY) != 0) return 1;
    if (set_pwm_frequency(RELAY4_PIN, PWM_FREQUENCY) != 0) return 1;

    return 0;
}

// Function to set PWM frequency for a given pin
int set_pwm_frequency(int pin, int frequency) {
    if (gpioSetPWMfrequency(pin, frequency) != frequency) {
        char message[100];
        sprintf(message, "Failed to set PWM frequency for GPIO%d to %d Hz", pin, frequency);
