    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        cleanup();
        return 1;
    }

    // Sunrise simulation loop
    for (int duty_cycle = 0; duty_cycle <= 255 && running; duty_cycle++) {
        // Set PWM duty cycle for all relays
        if (set_pwm_duty_cycle(RELAY1_PIN, duty_cycle) != 0) break;
        if (set_pwm_duty_cycle(RELAY2_PIN, duty_cycle) != 0) break;
        if (set_pwm_duty_cycle(RELAY3_PIN, duty_cycle) != 0) break;
        if (set_pwm_duty_cycle(RELAY4_PIN, duty_cycle) != 0) break;

