#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// LED GPIO pin
#define LED_PIN 17

// Sampling rate (Hz)
#define SAMPLE_RATE 20

// Sampling period (ms)
#define SAMPLE_PERIOD (1000 / SAMPLE_RATE)

// Circular buffer size
#define BUFFER_SIZE 100

// Gyroscope sensitivity (degrees/sec/LSB)
#define GYRO_SENSITIVITY 131.0

// Structure to hold gyroscope data
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
bool running = true;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z);
bool check_threshold(float x, float y, float z);
void control_led(bool on);
void signal_handler(int signal);
void init_circular_buffer(circular_buffer_t *buffer);

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    raw_x = (buf[0] << 8) | buf[1];
    raw_y = (buf[2] << 8) | buf[3];
    raw_z = (buf[4] << 8) | buf[5];

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    buffer->data[buffer->head].timestamp = ts;
    buffer->data[buffer->head].x = x;
    buffer->data[buffer->head].y = y;
    buffer->data[buffer->head].z = z;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if any axis exceeds the threshold
bool check_threshold(float x, float y, float z) {
    return (fabs(x) > 250.0 || fabs(y) > 250.0 || fabs(z) > 250.0);
}

// Control the LED
void control_led(bool on) {
    gpioWrite(LED_PIN, on ? 1 : 0);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050 with retry
    int init_attempts = 0;
    while (init_attempts < 3) {
        if (init_mpu6050() == 0) {
            break;
        } else {
            fprintf(stderr, "Attempting to re-initialize MPU-6050...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not open I2C bus for re-initialization\n");
                gpioTerminate();
                return 1;
            }
            init_attempts++;
            gpioDelay(100); // Wait before retrying
        }
    }

    if (init_attempts == 3) {
        fprintf(stderr, "Error: MPU-6050 initialization failed after multiple attempts\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    bool led_on = false;

    // Main loop
    while (running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(&gyro_buffer, x, y, z);

            bool threshold_exceeded = check_threshold(x, y, z);

            if (threshold_exceeded && !led_on) {
                control_led(true);
                led_on = true;
            } else if (!threshold_exceeded && led_on) {
                control_led(false);
                led_on = false;
            }
        } else {
            fprintf(stderr, "Error reading gyro data. Attempting re-initialization...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not open I2C bus for re-initialization\n");
                running = false; // Exit loop if re-initialization fails
            } else {
                init_attempts = 0; // Reset init attempts after successful re-init
                if (init_mpu6050() != 0) {
                    fprintf(stderr, "Error: MPU-6050 re-initialization failed\n");
                    running = false;
                }
            }
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    // Clean up
    i2cClose(i2c_handle);
    control_led(false);
    gpioTerminate();

    return 0;
}

