static int spi_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_spi();
int init_gpio();
int read_gyro_data(int16_t *x_rate, int16_t *y_rate, int16_t *z_rate);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, int16_t x_rate, int16_t y_rate, int16_t z_rate);
void signal_handler(int signal);
void cleanup();

// Structure for grouping SPI configuration
typedef struct {
    int channel;
    int speed;
    int mode;
    int cs_pin;
} spi_config_t;

// Structure for grouping gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
    int16_t z_rate;
