        cleanup();
        return 1;
    }

    // Initialize GPIO for Chip Select
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data;
        char *timestamp;

        // Read gyroscope data
        if (read_gyro_data(&gyro_data.x_rate, &gyro_data.y_rate, &gyro_data.z_rate) != 0) {
