    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // De-assert chip select
    return 0;
}

// Read gyroscope data from MPU-9250
int read_gyro_data(int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    char tx_buffer[7];
    char rx_buffer[7];
    int retries = 3;
    int result;

    // Construct the transmit buffer
    tx_buffer[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes
    memset(tx_buffer + 1, 0, 6); // Dummy data for reading

    while (retries > 0) {
        gpioWrite(CS_PIN, 0); // Assert chip select
        result = spiXfer(spi_handle, tx_buffer, rx_buffer, 7);
        gpioWrite(CS_PIN, 1); // De-assert chip select

        if (result == 7) {
            // Success
            *x_rate = (int16_t)((rx_buffer[1] << 8) | rx_buffer[2]);
            *y_rate = (int16_t)((rx_buffer[3] << 8) | rx_buffer[4]);
            *z_rate = (int16_t)((rx_buffer[5] << 8) | rx_buffer[6]);
            return 0;
        } else {
            fprintf(stderr, "SPI transfer failed (result = %d), retries remaining = %d\n", result, retries - 1);
            retries--;
            gpioDelay(1000); // 1 ms delay before retry
        }
    }

    fprintf(stderr, "Failed to read gyro data after multiple retries\n");
    return 1;
}

