char* get_iso8601_timestamp() {
    struct timespec ts;
    char *timestamp = malloc(30 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        free(timestamp);
        return NULL;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + 19, 11, ".%09ldZ", ts.tv_nsec);

    return timestamp;
}

// Log data to CSV file
int log_data(const char *timestamp, int16_t x_rate, int16_t y_rate, int16_t z_rate) {
    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("Failed to write to log file");
        return 1;
    }
    fflush(log_file); // Flush the buffer to ensure data is written
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(CS_PIN, 1); // De-assert chip select
    gpioTerminate();
}

