#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define SPI_MODE 0
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s for +/- 250 deg/s range
#define THRESHOLD 200.0
#define BUFFER_SIZE 64
#define LED_GPIO 17

// MPU-6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Data structure for gyroscope data
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void print_buffer_to_csv();
void signal_handler(int signal);
void blink_led(int gpio, int duration_ms);

// Global flag for program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    float x, y, z;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(x, y, z);

            // Check for threshold exceedance
            if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
                blink_led(LED_GPIO, 500);
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms = 10000 us
    }

    // Print buffer to CSV file
    print_buffer_to_csv();

    // Close SPI interface
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    char buf[2];
    buf[0] = PWR_MGMT_1;
    buf[1] = 0x00;
    spiWrite(spi_handle, buf, 2);

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[7];
    buf[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes starting from GYRO_XOUT_H

    if (spiXfer(spi_handle, buf, buf, 7) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return 1;
    }

    // Combine high and low bytes for each axis
    int16_t gyro_x = (buf[1] << 8) | buf[2];
    int16_t gyro_y = (buf[3] << 8) | buf[4];
    int16_t gyro_z = (buf[5] << 8) | buf[6];

    // Convert to degrees per second
    *x = (float)gyro_x / GYRO_SENSITIVITY;
    *y = (float)gyro_y / GYRO_SENSITIVITY;
    *z = (float)gyro_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print buffer to CSV file
void print_buffer_to_csv() {
    FILE *fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return;
    }

    fprintf(fp, "Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        fprintf(fp, "%ld.%09ld,%f,%f,%f\n",
                gyro_buffer[index].timestamp.tv_sec,
                gyro_buffer[index].timestamp.tv_nsec,
                gyro_buffer[index].x,
                gyro_buffer[index].y,
                gyro_buffer[index].z);
    }

    fclose(fp);
    printf("Data saved to gyro_data.csv\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    program_running = 0;
}

// Blink LED
void blink_led(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for duration_ms milliseconds
    gpioWrite(gpio, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay for duration_ms milliseconds
}

