#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define GPIO_LED 17
#define PROXIMITY_THRESHOLD 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Si1145 Registers
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02

#define REG_UCOEF0 0x13
#define REG_UCOEF1 0x14
#define REG_UCOEF2 0x15
#define REG_UCOEF3 0x16

#define REG_PARAM_WR 0x17
#define REG_COMMAND 0x18
#define REG_RESPONSE0 0x20
#define REG_RESPONSE1 0x21
#define REG_RESPONSE2 0x22
#define REG_RESPONSE3 0x23

#define REG_IRQ_ENABLE 0x03
#define REG_IRQ_MODE1 0x04
#define REG_IRQ_MODE2 0x05

#define REG_HW_KEY 0x07

#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09

#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0 0x24
#define REG_PS1_DATA1 0x25

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, unsigned char reg);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int si1145_init(int fd);
int read_si1145_data(int fd, int *ambient_light, int *proximity);
void log_data(FILE *fp, int ambient_light, int proximity);
void control_led(int gpio, int state);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register address) failed");
        return -1;
    }
    unsigned char value;
    if (read(fd, &value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return value;
}

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Si1145 initialization function
int si1145_init(int fd) {
    // Reset the device
    if (i2c_write_reg(fd, REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration - adjust as needed)
    if (i2c_write_reg(fd, REG_HW_KEY, 0x17) < 0) return -1; // Unlock
    if (i2c_write_reg(fd, REG_MEAS_RATE0, 0xFF) < 0) return -1; // Set measurement rate
    if (i2c_write_reg(fd, REG_MEAS_RATE1, 0x01) < 0) return -1; // Set measurement rate
    if (i2c_write_reg(fd, REG_IRQ_ENABLE, 0x00) < 0) return -1; // Disable interrupts
    if (i2c_write_reg(fd, REG_IRQ_MODE1, 0x00) < 0) return -1; // Set interrupt mode
    if (i2c_write_reg(fd, REG_IRQ_MODE2, 0x00) < 0) return -1; // Set interrupt mode

    // Enable ALS and Proximity measurements
    if (i2c_write_reg(fd, REG_COMMAND, CMD_ALS_FORCE) < 0) return -1;

    return 0;
}

// Function to read ambient light and proximity data
int read_si1145_data(int fd, int *ambient_light, int *proximity) {
    int als_low, als_high, prox_low, prox_high;

    als_low = i2c_read_reg(fd, REG_ALS_VIS_DATA0);
    als_high = i2c_read_reg(fd, REG_ALS_VIS_DATA1);
    prox_low = i2c_read_reg(fd, REG_PS1_DATA0);
    prox_high = i2c_read_reg(fd, REG_PS1_DATA1);

    if (als_low < 0 || als_high < 0 || prox_low < 0 || prox_high < 0) {
        return -1; // Indicate error
    }

    *ambient_light = (als_high << 8) | als_low;
    *proximity = (prox_high << 8) | prox_low;

    return 0; // Indicate success
}

// Function to log data to file
void log_data(FILE *fp, int ambient_light, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:%d,Proximity:%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to control the LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    int ambient_light, proximity;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (si1145_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        retries = 0;
        do {
            if (read_si1145_data(i2c_fd, &ambient_light, &proximity) == 0) {
                log_data(log_file, ambient_light, proximity);
                if (proximity > PROXIMITY_THRESHOLD) {
                    control_led(GPIO_LED, 1); // Turn on LED
                } else {
                    control_led(GPIO_LED, 0); // Turn off LED
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(RETRY_DELAY_MS);
            }
        } while (retries < MAX_RETRIES);

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    control_led(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

