    fflush(fp); // Ensure data is written to disk immediately
}

// Function to control the LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    int ambient_light, proximity;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (si1145_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        retries = 0;
        do {
            if (read_si1145_data(i2c_fd, &ambient_light, &proximity) == 0) {
                log_data(log_file, ambient_light, proximity);
                if (proximity > PROXIMITY_THRESHOLD) {
                    control_led(GPIO_LED, 1); // Turn on LED
                } else {
                    control_led(GPIO_LED, 0); // Turn off LED
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(RETRY_DELAY_MS);
            }
        } while (retries < MAX_RETRIES);

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    control_led(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

