#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// ADXRS290 Register Addresses
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02
#define ADXRS290_REG_TEMP   0x04
#define ADXRS290_REG_DIAG   0x06
#define ADXRS290_REG_PID    0x08
#define ADXRS290_REG_SN     0x0A
#define ADXRS290_REG_GLOB   0x0C
#define ADXRS290_REG_X_FILT 0x0E
#define ADXRS290_REG_Y_FILT 0x10
#define ADXRS290_REG_X_OFF  0x12
#define ADXRS290_REG_Y_OFF  0x14
#define ADXRS290_REG_X_SENS 0x16
#define ADXRS290_REG_Y_SENS 0x18
#define ADXRS290_REG_SOFT_RESET 0x1A

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data);
int read_gyro_data(int handle, int16_t *x_rate, int16_t *y_rate);
int log_data(FILE *fp, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);
int initialize_spi();
int initialize_file();
void cleanup();

// Function to read a register from the ADXRS290
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// Function to write a register to the ADXRS290
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int handle, int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb;

    if (spi_read_register(handle, ADXRS290_REG_X_RATE, &x_msb) != 0) return -1;
    if (spi_read_register(handle, ADXRS290_REG_X_RATE + 1, &x_lsb) != 0) return -1;
    if (spi_read_register(handle, ADXRS290_REG_Y_RATE, &y_msb) != 0) return -1;
    if (spi_read_register(handle, ADXRS290_REG_Y_RATE + 1, &y_lsb) != 0) return -1;

    *x_rate = (int16_t)((x_msb << 8) | x_lsb);
    *y_rate = (int16_t)((y_msb << 8) | y_lsb);

    return 0;
}

// Function to log data to a file
int log_data(FILE *fp, int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    if (fprintf(fp, "%lf,%d,%d\n", timestamp, x_rate, y_rate) < 0) {
        perror("fprintf");
        return -1;
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize SPI
int initialize_spi() {
    int retries = 3;
    while (retries > 0) {
        spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        if (spi_handle >= 0) {
            fprintf(stderr, "SPI initialized successfully.\n");
            return 0;
        } else {
            fprintf(stderr, "Error: SPI initialization failed (attempt %d). Retrying...\n", 4 - retries);
            gpioDelay(1000000); // 1 second delay
            retries--;
        }
    }
    fprintf(stderr, "Error: SPI initialization failed after multiple retries.\n");
    return -1;
}

// Function to initialize the CSV file
int initialize_file() {
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }
    fprintf(fp, "timestamp,x_rate,y_rate\n"); // Write header
    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        fprintf(stderr, "SPI closed.\n");
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fprintf(stderr, "File closed.\n");
    }
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize file
    if (initialize_file() != 0) {
        cleanup();
        return 1;
    }

    int16_t x_rate, y_rate;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(spi_handle, &x_rate, &y_rate) == 0) {
            if (log_data(fp, x_rate, y_rate) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data.\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

