#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define alert duration and delay
#define ALERT_DURATION 2.0  // seconds
#define ALERT_DELAY 0.5     // seconds

// Define log file name
#define LOG_FILE "seismic_events.txt"

// Global variables
static volatile int sensor1_state = 0;
static volatile int sensor2_state = 0;
static volatile int alert_active = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);
void trigger_alert();
void log_event();
void signal_handler(int signal);

// Structure to hold sensor data and callback information
typedef struct {
    int pin;
    int *state;
    void (*callback)(int, int, uint32_t);
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is initially LOW

    return 0;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    sensor1_state = level;
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    sensor2_state = level;
}

// Function to trigger the alert
void trigger_alert() {
    if (!alert_active) {
        alert_active = 1;
        gpioWrite(ALERT_PIN, 1);
        gpioDelay(ALERT_DURATION * 1000000); // Convert seconds to microseconds
        gpioWrite(ALERT_PIN, 0);
        alert_active = 0;
    }
}

// Function to log the event
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR1_PIN, sensor1_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for sensor 1!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR2_PIN, sensor2_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for sensor 2!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (sensor1_state == 1 && sensor2_state == 1) {
            trigger_alert();
            log_event();
            gpioDelay(ALERT_DELAY * 1000000); // Delay to prevent multiple triggers
        }
        gpioDelay(10000); // Check every 10ms
    }

    return 0;
}

