// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, terminating program...\n", signal);
}

// Function to set the brightness of a lamp using hardware PWM
void set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
