void fade_lamp(int gpio, int duration_seconds) {
    int num_steps = 100; // Number of steps in the fade
    int delay_ms = (duration_seconds * 1000) / num_steps; // Delay between steps in milliseconds
    int brightness;

    for (int i = 0; i <= num_steps; i++) {
        brightness = 255 - (int)((float)i / num_steps * 255);
        set_lamp_brightness(gpio, brightness);
        gpioDelay(delay_ms * 1000); // pigpioDelay takes microseconds
    }
}

// Function to perform the sunset sequence
void sunset_sequence(int duration_seconds) {
    printf("Starting sunset sequence for %d seconds...\n", duration_seconds);

    // Fade Lamp 1
    printf("Fading Lamp 1...\n");
    fade_lamp(LAMP1_GPIO, duration_seconds);

    // Fade Lamp 2
    printf("Fading Lamp 2...\n");
    fade_lamp(LAMP2_GPIO, duration_seconds);

    // Fade Lamp 3
    printf("Fading Lamp 3...\n");
    fade_lamp(LAMP3_GPIO, duration_seconds);

    printf("Sunset sequence complete!\n");
}

int main(int argc, char *argv[]) {
    int duration_seconds;

    // Check for correct number of command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return 1;
