    // Parse the duration from the command-line argument
    duration_seconds = atoi(argv[1]);

    // Validate the duration
    if (duration_seconds < 1 || duration_seconds > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency for all lamps
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range for all lamps
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    // Register signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Run the sunset sequence
    sunset_sequence(duration_seconds);

    // Clean up and terminate the pigpio library
    printf("Terminating pigpio...\n");
    gpioTerminate();

    return 0;
