#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the traffic light
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

// Function prototypes
void red_light();
void red_yellow_light();
void green_light();
void yellow_light();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to turn on the red light
void red_light() {
    gpioWrite(RED_PIN, 0);   // Turn on red (LOW)
    gpioWrite(YELLOW_PIN, 1); // Turn off yellow (HIGH)
    gpioWrite(GREEN_PIN, 1);  // Turn off green (HIGH)
    gpioWrite(BLUE_PIN, 1);   // Turn off blue (HIGH)
    printf("Red\n");
}

// Function to turn on the red and yellow lights
void red_yellow_light() {
    gpioWrite(RED_PIN, 0);   // Turn on red (LOW)
    gpioWrite(YELLOW_PIN, 0); // Turn on yellow (LOW)
    gpioWrite(GREEN_PIN, 1);  // Turn off green (HIGH)
    gpioWrite(BLUE_PIN, 1);   // Turn off blue (HIGH)
    printf("Red + Yellow\n");
}

// Function to turn on the green light
void green_light() {
    gpioWrite(RED_PIN, 1);   // Turn off red (HIGH)
    gpioWrite(YELLOW_PIN, 1); // Turn off yellow (HIGH)
    gpioWrite(GREEN_PIN, 0);  // Turn on green (LOW)
    gpioWrite(BLUE_PIN, 1);   // Turn off blue (HIGH)
    printf("Green\n");
}

// Function to turn on the yellow light
void yellow_light() {
    gpioWrite(RED_PIN, 1);   // Turn off red (HIGH)
    gpioWrite(YELLOW_PIN, 0); // Turn on yellow (LOW)
    gpioWrite(GREEN_PIN, 1);  // Turn off green (HIGH)
    gpioWrite(BLUE_PIN, 1);   // Turn off blue (HIGH)
    printf("Yellow\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RED_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(YELLOW_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set YELLOW_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GREEN_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BLUE_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set initial state to all lights off
    gpioWrite(RED_PIN, 1);
    gpioWrite(YELLOW_PIN, 1);
    gpioWrite(GREEN_PIN, 1);
    gpioWrite(BLUE_PIN, 1);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to cycle through the traffic light states
    while (1) {
        red_light();
        sleep(10);
        red_yellow_light();
        sleep(2);
        green_light();
        sleep(10);
        yellow_light();
        sleep(3);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

