#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define READ_DELAY_MS 10
#define NUM_ELECTRODES 12

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int configure_mpr121();
int read_touch_status(uint16_t *touch_status);
int debounce_touch(uint16_t current_status, uint16_t *last_status);
int toggle_relay();
int log_message(const char *message);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    uint16_t last_touch_status;
} ProgramState;

ProgramState state = {0}; // Initialize last_touch_status to 0

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to LOW
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to open I2C device: %d", i2c_handle);
        log_message(error_message);
        return -1;
    }
    return 0;
}

// Function to configure MPR121
int configure_mpr121() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Failed to set MPR121 to stop mode");
        return -1;
    }
    gpioDelay(1); // Small delay after writing to the device

    // Electrode configuration
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode Configuration to enable all 12 electrodes
        log_message("Failed to set MPR121 electrode configuration");
        return -1;
    }
    gpioDelay(1);

    // Touch and release thresholds (example values)
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Failed to set touch threshold for electrode %d", i);
            log_message(error_message);
            return -1;
        }
        gpioDelay(1);
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Failed to set release threshold for electrode %d", i);
            log_message(error_message);
            return -1;
        }
        gpioDelay(1);
    }

    // Start mode
    if (i2cWriteByteData(i2c_handle, 0x80, 0x10) < 0) {
        log_message("Failed to set MPR121 to start mode");
        return -1;
    }
    gpioDelay(1);

    return 0;
}

// Function to read touch status
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_message("Failed to read touch status");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to debounce touch events
int debounce_touch(uint16_t current_status, uint16_t *last_status) {
    if (current_status != *last_status) {
        gpioDelay(DEBOUNCE_DELAY_MS);
        uint16_t new_status;
        if (read_touch_status(&new_status) == 0) {
            if (new_status == current_status) {
                *last_status = current_status;
                return 1; // Debounced touch detected
            }
        }
    }
    return 0; // No debounced touch
}

// Function to toggle the relay
int toggle_relay() {
    int current_level = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_level);
    return 0;
}

// Function to log messages with timestamps
int log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
}

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Configure MPR121
    if (configure_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_message("Initialization complete");

    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (debounce_touch(touch_status, &state.last_touch_status)) {
                if (touch_status & 0x01) { // Check if electrode 0 is touched
                    toggle_relay();
                    log_message("Electrode 0 touched, relay toggled");
                }
            }
        }
        gpioDelay(READ_DELAY_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Set relay to LOW before exiting
    gpioTerminate();
    fclose(log_file);

    log_message("Program terminated");
    return 0;
}

