    fflush(log_file); // Ensure the message is written to the file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
}

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Configure MPR121
    if (configure_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_message("Initialization complete");

    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (debounce_touch(touch_status, &state.last_touch_status)) {
                if (touch_status & 0x01) { // Check if electrode 0 is touched
                    toggle_relay();
                    log_message("Electrode 0 touched, relay toggled");
                }
            }
        }
        gpioDelay(READ_DELAY_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Set relay to LOW before exiting
    gpioTerminate();
    fclose(log_file);

    log_message("Program terminated");
    return 0;
}

