// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense interval (milliseconds)
#define DISPENSE_INTERVAL 1000

// Define solenoid activation durations (milliseconds)
#define SOLENOID_1_DURATION (DISPENSE_INTERVAL / 2)
#define SOLENOID_2_DURATION (DISPENSE_INTERVAL - SOLENOID_1_DURATION)

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int pin, int duration_ms);
int deactivate_solenoid(int pin);
int dispense();
int log_event(int solenoid_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to activate a solenoid
int activate_solenoid(int pin, int duration_ms) {
    gpioWrite(pin, 1); // Set pin HIGH
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    return 0;
}

// Function to deactivate a solenoid
int deactivate_solenoid(int pin) {
    gpioWrite(pin, 0); // Set pin LOW
    return 0;
}

// Function to perform the dispensing sequence
int dispense() {
    if (activate_solenoid(SOLENOID_1_PIN, SOLENOID_1_DURATION) != 0) {
        fprintf(stderr, "Error activating solenoid 1\n");
        return 1;
    }
    if (activate_solenoid(SOLENOID_2_PIN, SOLENOID_2_DURATION) != 0) {
        fprintf(stderr, "Error activating solenoid 2\n");
        return 1;
    }
    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) {
        fprintf(stderr, "Error deactivating solenoid 1\n");
        return 1;
    }
    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) {
        fprintf(stderr, "Error deactivating solenoid 2\n");
        return 1;
    }
    return 0;
}

// Function to log dispense events to a file
int log_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Solenoid: %d, Duration: %d ms\n", timestamp, solenoid_pin, duration_ms);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (dispense() != 0) {
            fprintf(stderr, "Dispense failed\n");
        }

        if (log_event(SOLENOID_1_PIN, SOLENOID_1_DURATION) != 0) {
            fprintf(stderr, "Logging failed for solenoid 1\n");
        }
        if (log_event(SOLENOID_2_PIN, SOLENOID_2_DURATION) != 0) {
            fprintf(stderr, "Logging failed for solenoid 2\n");
        }

        gpioDelay(5000000); // Wait 5 seconds (microseconds)
    }

    // Cleanup before exiting
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();

    printf("Dispensing system stopped.\n");
    return 0;
}

