#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B GPIO pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Motor enable pins
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

// PID constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_motor_speed(int motor, int speed);
void stop_motors();
float calculate_pid(float setpoint, float actual_value, float *integral, float *previous_error);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
float simulate_tilt_error();
float simulate_distance();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor control pins as outputs
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    // Set enable pins as outputs and set HIGH
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);
    gpioWrite(MOTOR_A_ENABLE, 1);
    gpioWrite(MOTOR_B_ENABLE, 1);

    return 0;
}

// Set motor speed and direction
void set_motor_speed(int motor, int speed) {
    int forward_pin, backward_pin;

    if (motor == 0) { // Motor A
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
    } else { // Motor B
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
    }

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, 0);
        gpioPWM(backward_pin, 0);
    }
}

// Stop both motors
void stop_motors() {
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);
}

// Calculate PID output
float calculate_pid(float setpoint, float actual_value, float *integral, float *previous_error) {
    float error = setpoint - actual_value;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Simulate tilt error
float simulate_tilt_error() {
    return ((float)rand() / RAND_MAX) * 20.0 - 10.0;
}

// Simulate distance sensor reading
float simulate_distance() {
    return ((float)rand() / RAND_MAX) * 380.0 + 2.0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        stop_motors();
        gpioTerminate();
        return 1;
    }

    float tilt_error, distance, pid_output;
    int motor_a_speed, motor_b_speed;
    float integral = 0.0, previous_error = 0.0;
    float setpoint = 0.0; // Desired tilt angle

    // Main loop
    while (running) {
        // Simulate sensor readings
        tilt_error = simulate_tilt_error();
        distance = simulate_distance();

        // Calculate PID output
        pid_output = calculate_pid(setpoint, tilt_error, &integral, &previous_error);

        // Determine motor speeds based on PID output
        motor_a_speed = (int)pid_output;
        motor_b_speed = (int)pid_output;

        // Obstacle avoidance
        if (distance < 20.0) {
            motor_a_speed = -128; // Reverse Motor A
            motor_b_speed = -128; // Reverse Motor B
        }

        // Clamp motor speeds to ±255
        if (motor_a_speed > 255) motor_a_speed = 255;
        if (motor_a_speed < -255) motor_a_speed = -255;
        if (motor_b_speed > 255) motor_b_speed = 255;
        if (motor_b_speed < -255) motor_b_speed = -255;

        // Set motor speeds
        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Wait 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

