#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void debounce();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pin as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin as input\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    if (control_relay(0) != 0) {
        fprintf(stderr, "Failed to initialize relay\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control relay state
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to relay pin\n");
        return 1;
    }
    relay_state = state;
    return 0;
}

// Debounce delay
void debounce() {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
}

// Cleanup GPIO resources
void cleanup_gpio() {
    // Ensure relay is OFF before exiting
    control_relay(0);
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // If touch is detected and relay is OFF, turn it ON
        if (touch_detected && !relay_state) {
            if (control_relay(1) == 0) {
                printf("Relay turned ON\n");
            }
            debounce();
        }
        // If touch is not detected and relay is ON, turn it OFF
        else if (!touch_detected && relay_state) {
            if (control_relay(0) == 0) {
                printf("Relay turned OFF\n");
            }
            debounce();
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms
    }

    return 0;
}

