#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Configuration
#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define NUM_CHANNELS 1
#define SENSITIVITY_DEFAULT 1.0
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // PWM range for pigpio

// GPIO pins for RGB LED
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

// ALSA parameters
#define ALSA_DEVICE "default"
#define ALSA_FORMAT SND_PCM_FORMAT_S16_LE

// Global variables
snd_pcm_t *pcm_handle = NULL;
double sensitivity = SENSITIVITY_DEFAULT;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames);
double calculate_rms(const short *buffer, int frames);
void map_amplitude_to_color(double amplitude, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int sig);
void cleanup();

// ALSA Initialization
int init_alsa(snd_pcm_t **pcm_handle) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device %s: %s\n", ALSA_DEVICE, snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, ALSA_FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Audio Capture
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames) {
    int err;

    if ((err = snd_pcm_readi(pcm_handle, buffer, frames)) != frames) {
        fprintf(stderr, "Error reading audio: %s\n", snd_strerror(err));
        if (err == -EPIPE) {
            fprintf(stderr, "Recovering from EPIPE\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err == -ESTRPIPE) {
            fprintf(stderr, "Recovering from ESTRPIPE\n");
            snd_pcm_resume(pcm_handle);
        } else {
            return -1;
        }
    }

    return 0;
}

// RMS Amplitude Calculation
double calculate_rms(const short *buffer, int frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / frames);
}

// Non-linear Amplitude Mapping to RGB Color
void map_amplitude_to_color(double amplitude, int *red, int *green, int *blue) {
    // Non-linear mapping (logarithmic)
    double log_amplitude = log10(1.0 + amplitude * sensitivity); // Avoid log(0)
    double hue = fmod(log_amplitude * 120.0, 360.0); // Map to 0-360 degrees

    // HSL to RGB conversion (simplified)
    double r = 0.0, g = 0.0, b = 0.0;
    double h = hue / 60.0;
    double c = 1.0; // Chroma
    double x = c * (1.0 - fabs(fmod(h, 2.0) - 1.0));
    double m = 0.0; // Lightness

    if (h < 1.0) {
        r = c; g = x; b = 0.0;
    } else if (h < 2.0) {
        r = x; g = c; b = 0.0;
    } else if (h < 3.0) {
        r = 0.0; g = c; b = x;
    } else if (h < 4.0) {
        r = 0.0; g = x; b = c;
    } else if (h < 5.0) {
        r = x; g = 0.0; b = c;
    } else {
        r = c; g = 0.0; b = x;
    }

    r = (r + m) * 255.0;
    g = (g + m) * 255.0;
    b = (b + m) * 255.0;

    *red = (int)r;
    *green = (int)g;
    *blue = (int)b;
}

// RGB LED Control
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    int opt;
    short *buffer;
    int red, green, blue;
    double rms_amplitude;
    struct timespec sleep_time;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0) {
                    fprintf(stderr, "Invalid sensitivity value. Using default.\n");
                    sensitivity = SENSITIVITY_DEFAULT;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for PWM output
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Allocate audio buffer
    buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        cleanup();
        return 1;
    }

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        free(buffer);
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10ms

    while (!terminate) {
        if (capture_audio(pcm_handle, buffer, PERIOD_SIZE) == 0) {
            rms_amplitude = calculate_rms(buffer, PERIOD_SIZE);
            map_amplitude_to_color(rms_amplitude, &red, &green, &blue);
            set_led_color(red, green, blue);
        } else {
            fprintf(stderr, "Error capturing audio, exiting.\n");
            break;
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    free(buffer);
    cleanup();
    return 0;
}

