#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Calibration parameters
float c_offset = 0.0;
float r_offset = 0.0;
float g_offset = 0.0;
float b_offset = 0.0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_sensor();
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);
int safe_i2c_write_byte_data(int handle, int reg, int val);
int safe_i2c_read_word_data(int handle, int reg);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Safe I2C write function
int safe_i2c_write_byte_data(int handle, int reg, int val) {
    int result = i2cWriteByteData(handle, reg, val);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Safe I2C read function
int safe_i2c_read_word_data(int handle, int reg) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return result;
}

// Initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable the sensor
    if (safe_i2c_write_byte_data(i2c_handle, TCS34725_ENABLE, 0x03) != 0) {
        return -1;
    }

    // Set integration time to 154ms
    if (safe_i2c_write_byte_data(i2c_handle, TCS34725_ATIME, 0xEB) != 0) {
        return -1;
    }

    // Set gain to 60x
    if (safe_i2c_write_byte_data(i2c_handle, TCS34725_CONTROL, 0x01) != 0) {
        return -1;
    }

    return 0;
}

// Read color data from the sensor
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int c, r, g, b;

    c = safe_i2c_read_word_data(i2c_handle, TCS34725_CDATA);
    r = safe_i2c_read_word_data(i2c_handle, TCS34725_RDATA);
    g = safe_i2c_read_word_data(i2c_handle, TCS34725_GDATA);
    b = safe_i2c_read_word_data(i2c_handle, TCS34725_BDATA);

    if (c < 0 || r < 0 || g < 0 || b < 0) {
        return -1;
    }

    *clear = (uint16_t)c;
    *red = (uint16_t)r;
    *green = (uint16_t)g;
    *blue = (uint16_t)b;

    return 0;
}

// Calibrate the sensor by reading a set of baseline readings
void calibrate_sensor() {
    uint16_t clear, red, green, blue;
    float c_sum = 0.0, r_sum = 0.0, g_sum = 0.0, b_sum = 0.0;
    int num_samples = 10;

    fprintf(stderr, "Calibrating sensor...\n");

    for (int i = 0; i < num_samples; i++) {
        if (read_sensor_data(&clear, &red, &green, &blue) == 0) {
            c_sum += clear;
            r_sum += red;
            g_sum += green;
            b_sum += blue;
        } else {
            fprintf(stderr, "Error reading sensor data during calibration.\n");
            return; // Exit calibration if there's an error
        }
        gpioDelay(50); // Small delay between samples
    }

    c_offset = c_sum / num_samples;
    r_offset = r_sum / num_samples;
    g_offset = g_sum / num_samples;
    b_offset = b_sum / num_samples;

    fprintf(stderr, "Calibration complete. Offsets: C=%.2f, R=%.2f, G=%.2f, B=%.2f\n", c_offset, r_offset, g_offset, b_offset);
}

// Log the color data to a CSV file
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    float calibrated_clear = clear - c_offset;
    float calibrated_red = red - r_offset;
    float calibrated_green = green - g_offset;
    float calibrated_blue = blue - b_offset;

    fprintf(fp, "%ld,%.2f,%.2f,%.2f,%.2f\n", now, calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate the sensor
    calibrate_sensor();

    // Open the CSV file for writing
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,C,R,G,B\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t clear, red, green, blue;
    while (!terminate) {
        if (read_sensor_data(&clear, &red, &green, &blue) == 0) {
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data, logging zeros.\n");
            log_data(0, 0, 0, 0);
        }
        gpioDelay(500); // Sample every 500ms
    }

    // Cleanup
    fprintf(stderr, "Closing I2C bus...\n");
    i2cClose(i2c_handle);

    fprintf(stderr, "Closing CSV file...\n");
    fclose(fp);

    fprintf(stderr, "Terminating pigpio...\n");
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

