#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600   // 1 hour
#define DAYTIME_DURATION 21600  // 6 hours
#define SUNSET_DURATION 3600    // 1 hour
#define NIGHTTIME_DURATION 57600 // 14.4 hours

// Define the number of steps in the PWM-like cycle
#define NUM_STEPS 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay (0 for off, 1 for on)
int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO pin %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to turn off all relays
int turn_off_all_relays() {
    if (set_relay_state(RELAY1_PIN, 1) != 0) return -1;
    if (set_relay_state(RELAY2_PIN, 1) != 0) return -1;
    if (set_relay_state(RELAY3_PIN, 1) != 0) return -1;
    if (set_relay_state(RELAY4_PIN, 1) != 0) return -1;
    return 0;
}

// Function to simulate sunrise
int simulate_sunrise() {
    for (int i = 0; i <= NUM_STEPS; ++i) {
        if (!program_running) return -1; // Check for termination signal
        if (set_relay_state(RELAY1_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY2_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY3_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY4_PIN, 0) != 0) return -1;
        gpioDelay(i * SUNRISE_DURATION / NUM_STEPS / 1000); // Delay in milliseconds
    }
    return 0;
}

// Function to simulate sunset
int simulate_sunset() {
    for (int i = NUM_STEPS; i >= 0; --i) {
        if (!program_running) return -1; // Check for termination signal
        if (set_relay_state(RELAY1_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY2_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY3_PIN, 0) != 0) return -1;
        if (set_relay_state(RELAY4_PIN, 0) != 0) return -1;
        gpioDelay(i * SUNSET_DURATION / NUM_STEPS / 1000); // Delay in milliseconds
    }
    return 0;
}

// Function to simulate daytime
int simulate_daytime() {
    if (!program_running) return -1; // Check for termination signal
    if (set_relay_state(RELAY1_PIN, 0) != 0) return -1;
    if (set_relay_state(RELAY2_PIN, 0) != 0) return -1;
    if (set_relay_state(RELAY3_PIN, 0) != 0) return -1;
    if (set_relay_state(RELAY4_PIN, 0) != 0) return -1;
    gpioDelay(DAYTIME_DURATION * 1000); // Delay in milliseconds
    return 0;
}

// Function to simulate nighttime
int simulate_nighttime() {
    if (!program_running) return -1; // Check for termination signal
    if (set_relay_state(RELAY1_PIN, 1) != 0) return -1;
    if (set_relay_state(RELAY2_PIN, 1) != 0) return -1;
    if (set_relay_state(RELAY3_PIN, 1) != 0) return -1;
    if (set_relay_state(RELAY4_PIN, 1) != 0) return -1;
    gpioDelay(NIGHTTIME_DURATION * 1000); // Delay in milliseconds
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to simulate the lighting cycle
    while (program_running) {
        if (simulate_sunrise() != 0) break;
        if (simulate_daytime() != 0) break;
        if (simulate_sunset() != 0) break;
        if (simulate_nighttime() != 0) break;
    }

    // Turn off all relays before exiting
    if (turn_off_all_relays() != 0) {
        fprintf(stderr, "Error turning off relays\n");
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

