#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DURATION_S 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to create the video filename based on the current timestamp
char* create_video_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(50 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 50, "%Y%m%d_%H%M%S.h264", timeinfo);
    return filename;
}

// Function to capture video using raspivid
int capture_video(const char *filename) {
    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s/%s -t %d", VIDEO_DIR, filename, CAPTURE_DURATION_S * 1000);

    printf("Executing command: %s\n", command);
    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to log the motion event to a file
int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Create the video directory if it doesn't exist
    struct stat st = {0};
    if (stat(VIDEO_DIR, &st) == -1) {
        if (mkdir(VIDEO_DIR, 0777) == -1) {
            perror("Failed to create video directory");
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(GPIO_PIN);

        // Check for motion (LOW signal)
        if (sensor_value == 0) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read the sensor value after the delay
            int debounced_value = gpioRead(GPIO_PIN);

            // If the value is still LOW, it's a valid trigger
            if (debounced_value == 0) {
                printf("Motion detected!\n");

                // Get the current timestamp
                char *timestamp = get_iso8601_timestamp();
                if (timestamp == NULL) {
                    fprintf(stderr, "Failed to get timestamp.\n");
                    continue; // Continue to the next iteration
                }

                // Create the video filename
                char *filename = create_video_filename();
                if (filename == NULL) {
                    fprintf(stderr, "Failed to create filename.\n");
                    free(timestamp);
                    continue; // Continue to the next iteration
                }

                // Capture the video
                if (capture_video(filename) != 0) {
                    fprintf(stderr, "Failed to capture video.\n");
                }

                // Log the motion event
                if (log_motion_event(timestamp) != 0) {
                    fprintf(stderr, "Failed to log motion event.\n");
                }

                // Free the allocated memory
                free(timestamp);
                free(filename);

                // Wait for a while before checking again
                gpioDelay(1000 * 1000); // Wait 1 second
            }
        }

        gpioDelay(100 * 1000); // Check every 100ms
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

