#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Freefall threshold (0.2g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (0.5 seconds)
#define FREEFALL_DURATION 500

// Alarm GPIO pin
#define ALARM_GPIO 27

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_adxl345();
int read_acceleration(float *x, float *y, float *z);
int detect_freefall(float x, float y, float z);
void trigger_alarm();
void log_freefall(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int init_adxl345() {
    // Set POWER_CTL register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not initialize ADXL345: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert raw data to g-force units (assuming +/- 2g range)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Function to detect freefall
int detect_freefall(float x, float y, float z) {
    static int freefall_count = 0;
    static int freefall_detected = 0;

    if (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD) {
        freefall_count++;
        if (freefall_count >= FREEFALL_DURATION / 100) { // Check every 100ms
            freefall_detected = 1;
        }
    } else {
        freefall_count = 0;
        freefall_detected = 0;
    }

    return freefall_detected;
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    gpioDelay(5000);          // Wait for 5 seconds
    gpioWrite(ALARM_GPIO, 0); // Set GPIO low
}

// Function to log freefall events
void log_freefall(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set ALARM_GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure it starts low

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Detect freefall
            if (detect_freefall(x, y, z)) {
                printf("Freefall detected!\n");
                log_freefall(x, y, z);
                trigger_alarm();
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data. Continuing...\n");
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

