#include <pigpio.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define MAX_PULSE_WIDTH 23200 // Maximum pulse width in microseconds
#define TIMEOUT_DURATION 100  // Timeout duration in milliseconds
#define TRIGGER_DELAY 200     // Trigger delay in milliseconds

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_rising_edge(int gpio, int level, uint32_t tick);
void echo_falling_edge(int gpio, int level, uint32_t tick);
void timeout_handler();
void signal_handler(int signal);
int log_distance(uint32_t timestamp_ns, float distance_cm);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for rising edge of echo signal
void echo_rising_edge(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pthread_mutex_lock(&mutex);
        start_tick = tick;
        echo_received = 1;
        pthread_mutex_unlock(&mutex);
    }
}

// Callback function for falling edge of echo signal
void echo_falling_edge(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        pthread_mutex_lock(&mutex);
        end_tick = tick;
        echo_received = 0;
        pthread_mutex_unlock(&mutex);
    }
}

// Timeout handler function
void timeout_handler() {
    pthread_mutex_lock(&mutex);
    if (echo_received) {
        fprintf(stderr, "Error: Timeout - No falling edge detected within %d ms\n", TIMEOUT_DURATION);
        log_distance(0, -1.0); // Log error
    }
    pthread_mutex_unlock(&mutex);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to log distance to file
int log_distance(uint32_t timestamp_ns, float distance_cm) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    if (distance_cm < 0) {
        fprintf(log_file, "%u,ERROR\n", timestamp_ns);
    } else {
        fprintf(log_file, "%u,%.2f\n", timestamp_ns, distance_cm);
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

