    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Error: Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up interrupt callbacks
    gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge, NULL);

    // Set up timer for timeout
    gpioSetTimerFuncEx(0, TIMEOUT_DURATION, timeout_handler, NULL);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for a short period
        gpioDelay(50); // 50 us delay

        // Calculate distance
        pthread_mutex_lock(&mutex);
        uint32_t pulse_width = end_tick - start_tick;
        pthread_mutex_unlock(&mutex);

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        uint32_t timestamp_ns = (uint32_t)((ts.tv_sec * 1000000000ULL) + ts.tv_nsec);

        // Validate pulse width
        if (pulse_width > 0 && pulse_width <= MAX_PULSE_WIDTH) {
            float distance_cm = (pulse_width / 29.0) / 2.0; // Speed of sound: 29 us/cm
            log_distance(timestamp_ns, distance_cm);
        } else {
            fprintf(stderr, "Error: Invalid pulse width: %u us\n", pulse_width);
            log_distance(timestamp_ns, -1.0); // Log error
        }

        // Wait before next measurement
        gpioDelay(TRIGGER_DELAY);
    }

    // Clean up
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callbacks
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

