#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define LOG_FILE "/var/log/high_acceleration.log"

// LIS3DH Registers
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
int i2c_address = DEFAULT_I2C_ADDRESS;

// Function prototypes
int init_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
double convert_to_g(int16_t raw_value);
int check_threshold(double x, double y, double z, double threshold);
void log_acceleration(double x, double y, double z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    double x;
    double y;
    double z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x18 || i2c_address > 0x1F) {
                    fprintf(stderr, "Error: Invalid I2C address. Must be between 0x18 and 0x1F.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtod(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Error: Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "Error: LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    double x_g, y_g, z_g;

    while (1) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Error: Failed to read acceleration data\n");
            // Return zeros and continue
            raw_x = 0; raw_y = 0; raw_z = 0;
        }

        // Convert to g-force units
        x_g = convert_to_g(raw_x);
        y_g = convert_to_g(raw_y);
        z_g = convert_to_g(raw_z);

        // Check if threshold is exceeded
        if (check_threshold(x_g, y_g, z_g, threshold)) {
            log_acceleration(x_g, y_g, z_g);
            system("sudo shutdown -h now");
            break; // Exit loop after shutdown
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup (should not reach here if shutdown is called)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize LIS3DH
int init_lis3dh(int i2c_handle) {
    // Configure CTRL_REG1 (ODR = 100Hz, Enable X, Y, Z axes)
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL1, 0x77) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4 (FS = ±2g, High-resolution mode)
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL4, 0x88) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read all six registers at once
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw value to g-force units
double convert_to_g(int16_t raw_value) {
    // Assuming ±2g range and 12-bit resolution
    return (double)raw_value / 4096.0;
}

// Check if threshold is exceeded
int check_threshold(double x, double y, double z, double threshold) {
    return (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold);
}

// Log acceleration data to file
void log_acceleration(double x, double y, double z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %.4f g, Y: %.4f g, Z: %.4f g\n", s, x, y, z);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

