#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure for circular buffer
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer center_buffer;
int running = 1;

// Function prototypes
void init_gpio();
int read_sensor(int pin);
void update_circular_buffer(CircularBuffer *cb, int value);
int check_buffer(CircularBuffer *cb);
void move_forward();
void turn_left();
void turn_right();
void stop();
void alert();
void signal_handler(int signal);

// Initialize GPIO pins
void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Initialize circular buffer
    center_buffer.head = 0;
    center_buffer.count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        center_buffer.buffer[i] = 1; // Initialize with no line detected
    }
}

// Read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d\n", pin);
        return -1; // Indicate error
    }
    return value;
}

// Update circular buffer
void update_circular_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Check if all values in the buffer are 1
int check_buffer(CircularBuffer *cb) {
    if (cb->count != BUFFER_SIZE) return 0; // Buffer not full yet
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (cb->buffer[i] == 0) {
            return 0; // Found a 0, no line detected for 5 readings
        }
    }
    return 1; // All 1s, no line detected for 5 readings
}

// Motor control functions (placeholders)
void move_forward() {
    printf("Moving forward\n");
}

void turn_left() {
    printf("Turning left\n");
}

void turn_right() {
    printf("Turning right\n");
}

void stop() {
    printf("Stopping\n");
}

// Alert function
void alert() {
    gpioWrite(ALERT_PIN, 1); // Turn on alert
    gpioDelay(2000);         // Wait for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Turn off alert
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(ALERT_PIN, 0); // Ensure alert is off
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize GPIO
    init_gpio();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int center_value = read_sensor(CENTER_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        if (left_value < 0 || center_value < 0 || right_value < 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop if there's an error reading sensors
        }

        // Update circular buffer with center sensor value
        update_circular_buffer(&center_buffer, center_value);

        // Check if no line detected for 5 readings
        if (check_buffer(&center_buffer)) {
            alert();
        }

        // Line following logic
        if (center_value == 0) {
            move_forward();
        } else if (left_value == 0) {
            turn_left();
        } else if (right_value == 0) {
            turn_right();
        } else {
            stop();
        }

        gpioDelay(10); // Poll every 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();

    return 0;
}

