#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"

int server_fd, new_socket;
FILE *log_file;

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Function to handle relay ON command
void relay_on() {
    gpioWrite(GPIO_PIN, 1); // Assuming HIGH activates the relay
    log_event("Relay ON");
}

// Function to handle relay OFF command
void relay_off() {
    gpioWrite(GPIO_PIN, 0); // Assuming LOW deactivates the relay
    log_event("Relay OFF");
}

// Function to parse the command
void parse_command(char *command) {
    // Remove trailing whitespace
    int i = strlen(command) - 1;
    while (i >= 0 && (command[i] == ' ' || command[i] == '\t' || command[i] == '\n' || command[i] == '\r')) {
        command[i] = '\0';
        i--;
    }

    if (strcasecmp(command, "ON") == 0) {
        relay_on();
    } else if (strcasecmp(command, "OFF") == 0) {
        relay_off();
    } else {
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Invalid command: %s", command);
        log_event(log_message);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        log_event("Shutting down...");
        relay_off(); // Ensure relay is OFF
        close(new_socket);
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        exit(0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("Socket creation failed");
        log_event("Socket creation failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        log_event("Bind failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        log_event("Listen failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Listening for connections...");

    // Accept connection
    int addrlen = sizeof(address);
    new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
    if (new_socket < 0) {
        perror("Accept failed");
        log_event("Accept failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Connection accepted\n");
    log_event("Connection accepted");

    char buffer[1024] = {0};
    ssize_t valread;

    // Receive and process commands
    while ((valread = recv(new_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[valread] = '\0'; // Null-terminate the received data
        printf("Received: %s\n", buffer);
        parse_command(buffer);
    }

    if (valread == 0) {
        printf("Client disconnected\n");
        log_event("Client disconnected");
    } else if (valread < 0) {
        perror("Receive failed");
        log_event("Receive failed");
    }

    // Clean up
    close(new_socket);
    close(server_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

