#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define POLLING_INTERVAL_MS 100
#define START_MEASUREMENT_CMD1 0x36
#define START_MEASUREMENT_CMD2 0x08

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int start_measurement(int handle);
int read_flow_rate(int handle, float *flow_rate);
uint8_t crc8(const uint8_t *data, int len);
void control_relay(int gpio, int state);
void log_flow_rate(float flow_rate1, float flow_rate2);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Start measurement on the sensor
int start_measurement(int handle) {
    char cmd[2] = {START_MEASUREMENT_CMD1, START_MEASUREMENT_CMD2};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
