#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control parameters
#define MOTOR_DURATION_MS 5000 // 5 seconds
#define DEBOUNCE_POLLS 3       // 3 polls * 200ms = 600ms

// Global variables
static volatile int running = 1;
static int rain_detected = 0;
static int debounce_counter = 0;

// Function prototypes
void signal_handler(int signal);
int setup_gpio();
int read_rain_sensor();
int control_motor(int enable, int in1, int in2);
int log_message(int priority, const char *message);
int cleanup_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Setup GPIO pins
int setup_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set RAIN_SENSOR_PIN as input");
        return -1;
    }
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN as output");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN as output");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN as output");
        return -1;
    }

    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Control the DC motor
int control_motor(int enable, int in1, int in2) {
    if (gpioWrite(MOTOR_ENA_PIN, enable) != 0) {
        log_message(LOG_ERR, "Failed to write to MOTOR_ENA_PIN");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, in1) != 0) {
        log_message(LOG_ERR, "Failed to write to MOTOR_IN1_PIN");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, in2) != 0) {
        log_message(LOG_ERR, "Failed to write to MOTOR_IN2_PIN");
        return -1;
    }
    return 0;
}

// Log messages to syslog
int log_message(int priority, const char *message) {
    syslog(priority, message);
    return 0;
}

// Cleanup GPIO pins
int cleanup_gpio() {
    if (control_motor(0, 0, 0) != 0) {
        log_message(LOG_ERR, "Failed to stop motor during cleanup");
    }
    gpioTerminate();
    return 0;
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        log_message(LOG_ERR, "GPIO setup failed, exiting");
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Rain sensor monitoring started");

    // Main loop
    while (running) {
        int sensor_value = read_rain_sensor();

        if (sensor_value == 1) { // Dry
            if (!rain_detected) {
                rain_detected = 1;
                log_message(LOG_INFO, "Rain detected, starting motor");
                if (control_motor(1, 1, 0) != 0) {
                    log_message(LOG_ERR, "Failed to start motor");
                } else {
                    usleep(MOTOR_DURATION_MS * 1000); // Run motor for 5 seconds
                    if (control_motor(0, 0, 0) != 0) {
                        log_message(LOG_ERR, "Failed to stop motor");
                    }
                    log_message(LOG_INFO, "Motor stopped");
                }
            }
            debounce_counter++;
            if (debounce_counter >= DEBOUNCE_POLLS) {
                rain_detected = 0;
                debounce_counter = 0;
            }
        } else { // Wet
            rain_detected = 0;
            debounce_counter = 0;
        }

        usleep(200000); // Poll every 200ms
    }

    // Cleanup and exit
    cleanup_gpio();
    log_message(LOG_INFO, "Rain sensor monitoring stopped");
    closelog();
    return 0;
}

