#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths for servo control
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000
#define STOP_PULSE_WIDTH 0

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Function prototypes
int lock_door();
int unlock_door();
int stop_servo();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            if (lock_door() != 0) {
                fprintf(stderr, "Failed to lock the door\n");
            }
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        // Check for unlock button press
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            if (unlock_door() != 0) {
                fprintf(stderr, "Failed to unlock the door\n");
            }
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(1000); // Small delay to reduce CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    printf("Door lock control program terminated.\n");
    return 0;
}

// Function to lock the door
int lock_door() {
    if (gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to set servo pulse width for lock\n");
        return 1;
    }
    printf("Door locked\n");
    return 0;
}

// Function to unlock the door
int unlock_door() {
    if (gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to set servo pulse width for unlock\n");
        return 1;
    }
    printf("Door unlocked\n");
    return 0;
}

// Function to stop the servo
int stop_servo() {
    if (gpioServo(SERVO_PIN, STOP_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to set servo pulse width to stop\n");
        return 1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;

    // Stop the servo
    if (stop_servo() != 0) {
        fprintf(stderr, "Failed to stop servo during shutdown\n");
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

