#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define LED_PIN 17

// Define constants
#define LED_ON_TIME 60 // seconds
#define POLLING_INTERVAL 100 // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, double duration);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    int led_state;
    time_t led_start_time;
} ProgramState;

ProgramState state = {0, 0, 0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }
    state.gpio_initialized = 1;

    // Open log file
    log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_pir_sensor() == 1) {
            // Motion detected
            if (state.led_state == 0) {
                printf("Motion detected! Activating LED.\n");
                if (control_led(1) == 0) {
                    state.led_state = 1;
                    state.led_start_time = time(NULL);
                    log_event("Activation", 0.0);
                } else {
                    fprintf(stderr, "Error controlling LED. Deactivating.\n");
                    control_led(0);
                }
            }
        }

        // Check if LED should be turned off
        if (state.led_state == 1) {
            time_t current_time = time(NULL);
            double duration = difftime(current_time, state.led_start_time);
            if (duration >= LED_ON_TIME) {
                printf("LED on time reached. Deactivating LED.\n");
                if (control_led(0) == 0) {
                    state.led_state = 0;
                    log_event("Deactivation", duration);
                } else {
                    fprintf(stderr, "Error deactivating LED.\n");
                }
            }
        }

        gpioDelay(POLLING_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

