int log_event(const char *event_type, double duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - Duration: %.2f seconds\n", timestamp, event_type, duration);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }
}

