void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off LED
    control_led(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    if (state.gpio_initialized) {
        gpioTerminate();
    }
}

