#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// GPIO pin for relay control
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static int i2c_fd;
static volatile bool relay_state = false; // false = OFF, true = ON
static volatile unsigned long last_touch_time = 0;

// Function prototypes
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void relay_on(int pin);
void relay_off(int pin);
void signal_handler(int signal);

// Function to write a byte to an MPR121 register
int mpr121_write_register(int fd, uint8_t reg, uint8_t value) {
    int result = wiringPiI2CWriteReg8(fd, reg, value);
    if (result == -1) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from an MPR121 register
int mpr121_read_register(int fd, uint8_t reg) {
    int result = wiringPiI2CReadReg8(fd, reg);
    if (result == -1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to initialize the MPR121
int mpr121_init(int fd) {
    // Soft reset
    if (mpr121_write_register(fd, 0x80, 0x63) == -1) return -1;
    delay(1); // Wait for reset to complete

    // Stop mode
    if (mpr121_write_register(fd, MPR121_ECR, 0x00) == -1) return -1;

    // Configure baseline filtering
    if (mpr121_write_register(fd, MPR121_MHDR, 0x01) == -1) return -1;
    if (mpr121_write_register(fd, MPR121_NHDR, 0x01) == -1) return -1;
    if (mpr121_write_register(fd, MPR121_NCLR, 0x0E) == -1) return -1;
    if (mpr121_write_register(fd, MPR121_FDLR, 0x00) == -1) return -1;

    // Configure touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_register(fd, MPR121_FILTERTH_L + 2 * i, 0x0A) == -1) return -1; // Touch threshold
        if (mpr121_write_register(fd, MPR121_FILTERTH_H + 2 * i, 0x05) == -1) return -1; // Release threshold
    }

    // Configure debounce
    if (mpr121_write_register(fd, 0x2B, 0x01) == -1) return -1;
    if (mpr121_write_register(fd, 0x2C, 0x01) == -1) return -1;

    // Configure FFI, SFI, and CDT
    if (mpr121_write_register(fd, 0x29, 0x01) == -1) return -1; // FFI
    if (mpr121_write_register(fd, 0x2A, 0x01) == -1) return -1; // SFI
    if (mpr121_write_register(fd, 0x27, 0x01) == -1) return -1; // CDT

    // Enable auto-config
    if (mpr121_write_register(fd, 0x5C, 0x24) == -1) return -1; // Enable auto-config, set range

    // Enable electrodes
    if (mpr121_write_register(fd, MPR121_ECR, 0x8F) == -1) return -1; // Enable all 12 electrodes

    // Enter run mode
    if (mpr121_write_register(fd, MPR121_CONFIG1, 0x10) == -1) return -1; // Set sample configuration
    if (mpr121_write_register(fd, MPR121_CONFIG2, 0x20) == -1) return -1; // Set electrode configuration
    if (mpr121_write_register(fd, MPR121_ECR, 0x8F) == -1) return -1; // Enable electrodes

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int fd) {
    int touch_status_l = mpr121_read_register(fd, MPR121_TOUCHSTATUS_L);
    int touch_status_h = mpr121_read_register(fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_l == -1 || touch_status_h == -1) {
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to turn the relay ON
void relay_on(int pin) {
    digitalWrite(pin, HIGH);
    relay_state = true;
    printf("Relay ON\n");
}

// Function to turn the relay OFF
void relay_off(int pin) {
    digitalWrite(pin, LOW);
    relay_state = false;
    printf("Relay OFF\n");
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    relay_off(RELAY_PIN);
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) == -1) {
        fprintf(stderr, "Error initializing MPR121\n");
        close(i2c_fd);
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);

    // Ensure relay is OFF on startup
    relay_off(RELAY_PIN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status == -1) {
            fprintf(stderr, "Error reading touch status\n");
            delay(100); // Small delay to avoid spamming errors
            continue;
        }

        // Check if electrode 0 is touched
        if ((touch_status & 0x01) && (millis() - last_touch_time > DEBOUNCE_TIME)) {
            // Toggle relay state
            if (relay_state) {
                relay_off(RELAY_PIN);
            } else {
                relay_on(RELAY_PIN);
            }
            last_touch_time = millis();
        }

        delay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

