            delay(100); // Small delay to avoid spamming errors
            continue;
        }

        // Check if electrode 0 is touched
        if ((touch_status & 0x01) && (millis() - last_touch_time > DEBOUNCE_TIME)) {
            // Toggle relay state
            if (relay_state) {
                relay_off(RELAY_PIN);
            } else {
                relay_on(RELAY_PIN);
            }
            last_touch_time = millis();
        }

        delay(10); // Small delay to avoid busy-waiting
    }

    return 0;
