#include <pigpio.h>
#include <errno.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define PWM_RANGE 20000 // 20ms period (50Hz)
#define MIN_PULSE_WIDTH 1000 // 1ms
#define MAX_PULSE_WIDTH 2000 // 2ms

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_gpio();
void set_servo_angle(int angle);
int read_pir_sensor();
int handle_client(int client_fd);
void log_message(const char *format, ...);
void signal_handler(int signum);
void cleanup();

// Function to initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message("GPIO initialization failed: %s", strerror(errno));
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN); // Optional: Pull-down resistor

    // Set PWM frequency and range
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, PWM_RANGE);

    return 0;
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message("Invalid servo angle: %d", angle);
        return;
    }

    // Calculate pulse width based on angle (0-180 degrees)
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set the PWM duty cycle
    gpioPWM(SERVO_PIN, pulse_width);

    log_message("Servo angle set to: %d, pulse width: %d", angle, pulse_width);
}

// Function to read the PIR sensor
int read_pir_sensor() {
    int pir_value = gpioRead(PIR_PIN);
    log_message("PIR sensor value: %d", pir_value);
    return pir_value;
}

// Function to handle client connections
int handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_received;

    while (program_running) {
        memset(buffer, 0, sizeof(buffer));
        bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            log_message("Error receiving data: %s", strerror(errno));
            break;
        } else if (bytes_received == 0) {
            log_message("Client disconnected");
            break;
        }

        log_message("Received command: %s", buffer);

        if (strncmp(buffer, "setServoAngle", 13) == 0) {
            int angle;
            if (sscanf(buffer, "setServoAngle %d", &angle) == 1) {
                set_servo_angle(angle);
                send(client_fd, "OK", strlen("OK"), 0);
            } else {
                log_message("Invalid setServoAngle command format");
                send(client_fd, "ERROR", strlen("ERROR"), 0);
            }
        } else if (strcmp(buffer, "PIR") == 0) {
            int pir_value = read_pir_sensor();
            char response[10];
            snprintf(response, sizeof(response), "PIR:%d", pir_value);
            send(client_fd, response, strlen(response), 0);
        } else {
            log_message("Unknown command: %s", buffer);
            send(client_fd, "ERROR", strlen("ERROR"), 0);
        }
    }

    close(client_fd);
    return 0;
}

// Function to log messages to syslog and file
void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    vsyslog(LOG_USER, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    log_message("Signal received: %d. Shutting down...", signum);
}

// Cleanup function to release resources
void cleanup() {
    log_message("Cleaning up resources...");

    // Close socket
    if (server_fd != -1) {
        close(server_fd);
        log_message("Socket closed");
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        log_message("Log file closed");
    }

    // Terminate pigpio
    gpioTerminate();
    log_message("pigpio terminated");

    closelog();
}

int main() {
    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Open syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        log_message("Error creating socket: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message("Error binding socket: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_message("Error listening on socket: %s", strerror(errno));
        cleanup();
        return 1;
    }

    log_message("Listening on port %d", PORT);

    // Main loop to accept connections
    while (program_running) {
        struct sockaddr_in client_address;
        int client_fd;
        socklen_t client_len = sizeof(client_address);

        client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (program_running) {
                log_message("Error accepting connection: %s", strerror(errno));
            }
            break;
        }

        log_message("Client connected from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        // Handle client connection
        handle_client(client_fd);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

