#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LUX_THRESHOLD 150
#define RELAY_GPIO 23
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_lux(float *lux);
int control_relay(int state);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int bh1750_address;
    int lux_threshold;
    int relay_gpio;
    char *log_file_name;
} Config;

Config config = {BH1750_ADDR, LUX_THRESHOLD, RELAY_GPIO, LOG_FILE};

int main() {
    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_lux(&lux) == 0) {
            // Control relay based on lux value
            if (lux < config.lux_threshold && relay_state == 0) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                }
            } else if (lux >= config.lux_threshold && relay_state == 1) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                }
            }

            // Log data
            if (log_data(lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(2000); // Sample every 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, config.bh1750_address, 0); // I2C1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Set BH1750 to continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Failed to set BH1750 mode\n");
        return 1;
    }

    return 0;
}

// Read lux value from BH1750
int read_lux(float *lux) {
    unsigned char buffer[2];
    int result;

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data from BH1750: %d\n", result);
        return 1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control the relay
int control_relay(int state) {
    gpioSetMode(config.relay_gpio, PI_OUTPUT);
    gpioWrite(config.relay_gpio, state);
    return 0;
}

// Log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.relay_gpio, 0); // Deactivate relay
    gpioTerminate();
}

