#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Function to set the relay state (ON/OFF)
int set_relay_state(const char *state) {
    if (strcmp(state, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1); // HIGH
        syslog(LOG_INFO, "Relay set to ON");
        return 0;
    } else if (strcmp(state, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0); // LOW
        syslog(LOG_INFO, "Relay set to OFF");
        return 0;
    } else {
        syslog(LOG_ERR, "Invalid payload received: %s", state);
        return -1;
    }
}

// Callback function for when the MQTT client connects to the broker
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe: %s", mosquitto_strerror(subscribe_result));
        }
    } else {
        syslog(LOG_ERR, "Connection failed: %s", mosquitto_strerror(result));
    }
}

// Callback function for when the MQTT client disconnects from the broker
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        syslog(LOG_WARNING, "Disconnected unexpectedly, reconnecting...");
    } else {
        syslog(LOG_INFO, "Disconnected from MQTT broker");
    }
}

// Callback function for when a message is received on a subscribed topic
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);
        if (set_relay_state(payload) != 0) {
            syslog(LOG_ERR, "Failed to set relay state for payload: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Received empty message on topic %s", message->topic);
    }
}

int main() {
    // Initialize syslog
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize to OFF

    // Initialize mosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        gpioTerminate();
        closelog();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to MQTT broker
    int connect_result = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(connect_result));
        gpioTerminate();
        closelog();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int loop_result = mosquitto_loop(mosq, -1, 1);
        if (loop_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(loop_result));
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();

    return 0;
}

