#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define pulse width limits (in microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define target pulse widths for each servo
#define SERVO1_PULSE_WIDTH 1000
#define SERVO2_PULSE_WIDTH 1500
#define SERVO3_PULSE_WIDTH 2000
#define SERVO4_PULSE_WIDTH 500
#define SERVO5_PULSE_WIDTH 2500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to set the pulse width for a servo
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width %d is out of range (%d-%d).\n", pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1; // Indicate an error
    }

    gpioPWM(gpio_pin, pulse_width); // Set the pulse width
    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set GPIO pins as outputs
    gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    gpioSetMode(SERVO5_PIN, PI_OUTPUT);

    // Main loop to move the servos
    while (program_running) {
        // Move Servo 1
        if (set_servo_pulse_width(SERVO1_PIN, SERVO1_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Error setting Servo 1 pulse width.\n");
        }
        sleep(3);

        // Move Servo 2
        if (set_servo_pulse_width(SERVO2_PIN, SERVO2_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Error setting Servo 2 pulse width.\n");
        }
        sleep(3);

        // Move Servo 3
        if (set_servo_pulse_width(SERVO3_PIN, SERVO3_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Error setting Servo 3 pulse width.\n");
        }
        sleep(3);

        // Move Servo 4
        if (set_servo_pulse_width(SERVO4_PIN, SERVO4_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Error setting Servo 4 pulse width.\n");
        }
        sleep(3);

        // Move Servo 5
        if (set_servo_pulse_width(SERVO5_PIN, SERVO5_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Error setting Servo 5 pulse width.\n");
        }
        sleep(3);
    }

    // Stop PWM and release resources
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    gpioTerminate();

    return 0;
}

