#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target RPM
#define TARGET_RPM 50.0

// Encoder ticks per revolution
#define TICKS_PER_REVOLUTION 64.0

// PI controller gains
#define KP 0.5
#define KI 0.1

// PWM frequency (Hz)
#define PWM_FREQUENCY 10000

// Stall detection timeout (seconds)
#define STALL_TIMEOUT 2.0

// Global variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
double integral_a = 0.0;
double integral_b = 0.0;
int running = 1;

// Function prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks, double time_interval);
double pi_control(double setpoint, double actual, double *integral, double kp, double ki);
void set_motor_pwm(int motor, int pwm_value);
void set_motor_direction(int motor, int direction);
void stall_detection(int motor, int ticks);
void signal_handler(int signal);

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    int b_level = gpioRead(ENCODER_A_B);
    if (level == 1) {
        if (b_level == 0) {
            encoder_a_ticks++;
        } else {
            encoder_a_ticks--;
        }
    } else {
        if (b_level == 0) {
            encoder_a_ticks--;
        } else {
            encoder_a_ticks++;
        }
    }
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    int b_level = gpioRead(ENCODER_B_B);
    if (level == 1) {
        if (b_level == 0) {
            encoder_b_ticks++;
        } else {
            encoder_b_ticks--;
        }
    } else {
        if (b_level == 0) {
            encoder_b_ticks--;
        } else {
            encoder_b_ticks++;
        }
    }
}

// Calculate RPM
double calculate_rpm(int ticks, double time_interval) {
    double revolutions = (double)ticks / TICKS_PER_REVOLUTION;
    return (revolutions / time_interval) * 60.0;
}

// PI controller
double pi_control(double setpoint, double actual, double *integral, double kp, double ki) {
    double error = setpoint - actual;
    *integral += error;

    // Anti-windup clamping
    if (*integral > 255.0) {
        *integral = 255.0;
    } else if (*integral < -255.0) {
        *integral = -255.0;
    }

    return (kp * error) + (ki * (*integral));
}

// Set motor PWM
void set_motor_pwm(int motor, int pwm_value) {
    if (pwm_value < 0) {
        pwm_value = 0;
    } else if (pwm_value > 255) {
        pwm_value = 255;
    }

    if (motor == 0) { // Motor A
        gpioPWM(MOTOR_A_PWM, pwm_value);
    } else { // Motor B
        gpioPWM(MOTOR_B_PWM, pwm_value);
    }
}

// Set motor direction
void set_motor_direction(int motor, int direction) {
    if (motor == 0) { // Motor A
        gpioWrite(MOTOR_A_DIR, direction);
    } else { // Motor B
        gpioWrite(MOTOR_B_DIR, direction);
    }
}

// Stall detection
void stall_detection(int motor, int ticks) {
    static time_t last_tick_time_a = 0;
    static time_t last_tick_time_b = 0;
    time_t current_time = time(NULL);

    if (ticks == 0) {
        if (motor == 0) { // Motor A
            if (last_tick_time_a == 0) {
                last_tick_time_a = current_time;
            } else if (difftime(current_time, last_tick_time_a) > STALL_TIMEOUT) {
                fprintf(stderr, "Warning: Motor A stalled!\n");
                last_tick_time_a = 0; // Reset to avoid repeated warnings
            }
        } else { // Motor B
            if (last_tick_time_b == 0) {
                last_tick_time_b = current_time;
            } else if (difftime(current_time, last_tick_time_b) > STALL_TIMEOUT) {
                fprintf(stderr, "Warning: Motor B stalled!\n");
                last_tick_time_b = 0; // Reset to avoid repeated warnings
            }
        }
    } else {
        if (motor == 0) {
            last_tick_time_a = 0; // Reset if ticks are non-zero
        } else {
            last_tick_time_b = 0; // Reset if ticks are non-zero
        }
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;
    set_motor_pwm(0, 0);
    set_motor_pwm(1, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_PWM, 255);
    gpioSetPWMrange(MOTOR_B_PWM, 255);

    // Register ISRs
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_A, FALLING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, FALLING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, FALLING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, FALLING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B B\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read encoder ticks
        int current_encoder_a_ticks = encoder_a_ticks;
        int current_encoder_b_ticks = encoder_b_ticks;

        // Reset encoder tick counters
        encoder_a_ticks = 0;
        encoder_b_ticks = 0;

        // Calculate RPM
        double rpm_a = calculate_rpm(current_encoder_a_ticks, 0.1); // 0.1 seconds
        double rpm_b = calculate_rpm(current_encoder_b_ticks, 0.1); // 0.1 seconds

        // PI control
        double pwm_a = pi_control(TARGET_RPM, rpm_a, &integral_a, KP, KI);
        double pwm_b = pi_control(TARGET_RPM, rpm_b, &integral_b, KP, KI);

        // Set motor PWM and direction
        set_motor_pwm(0, (int)pwm_a);
        set_motor_direction(0, 1); // Forward
        set_motor_pwm(1, (int)pwm_b);
        set_motor_direction(1, 1); // Forward

        // Stall detection
        stall_detection(0, current_encoder_a_ticks);
        stall_detection(1, current_encoder_b_ticks);

        // Print RPM and PWM duty cycle
        printf("Motor A: RPM = %.2f, PWM = %d, Motor B: RPM = %.2f, PWM = %d\n", rpm_a, (int)pwm_a, rpm_b, (int)pwm_b);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up
    set_motor_pwm(0, 0);
    set_motor_pwm(1, 0);
    gpioTerminate();

    return 0;
}

