#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_RELAY 17
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_HIGH 200.0
#define LUX_HYSTERESIS 10.0
#define POLL_INTERVAL_SEC 5
#define MODE_COMMAND_DELAY_MS 180

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor and relay state
typedef struct {
    float lux;
    int relay_state;
} SystemState;

SystemState current_state = {0.0, 0}; // Initialize relay to OFF

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        fprintf(stderr, "Logging initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            current_state.lux = lux;

            // Hysteresis control
            if (current_state.lux < LUX_THRESHOLD_LOW && current_state.relay_state == 0) {
                if (control_relay(1) == 0) {
                    current_state.relay_state = 1;
                }
            } else if (current_state.lux > LUX_THRESHOLD_HIGH && current_state.relay_state == 1) {
                if (control_relay(0) == 0) {
                    current_state.relay_state = 0;
                }
            }

            log_data(lux, current_state.relay_state);
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor\n");
            log_data(-1.0, current_state.relay_state); // Log error
        }

