#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int reading1, reading2;

    reading1 = gpioRead(TOUCH_SENSOR_PIN);
    if (reading1 < 0) {
        fprintf(stderr, "Error reading touch sensor (first read): %d\n", reading1);
        return -1; // Indicate an error
    }

    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds

    reading2 = gpioRead(TOUCH_SENSOR_PIN);
    if (reading2 < 0) {
        fprintf(stderr, "Error reading touch sensor (second read): %d\n", reading2);
        return -1; // Indicate an error
    }

    if (reading1 == 1 && reading2 == 1) {
        return 1; // Valid touch
    } else {
        return 0; // No touch
    }
}

// Function to control the relay
void control_relay(int state) {
    int result = gpioWrite(RELAY_PIN, state);
    if (result < 0) {
        fprintf(stderr, "Error writing to relay: %d\n", result);
    }
    relay_state = state; // Update the global relay state
}

// Function to log the relay state with ISO 8601 timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is %s\n", timestamp, (state == 1) ? "ON" : "OFF");
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_relay(0); // Turn off the relay
    gpioTerminate();   // Release pigpio resources
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    int mode_result = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (mode_result < 0) {
        fprintf(stderr, "Error setting touch sensor pin mode: %d\n", mode_result);
        gpioTerminate();
        return 1;
    }

    mode_result = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (mode_result < 0) {
        fprintf(stderr, "Error setting relay pin mode: %d\n", mode_result);
        gpioTerminate();
        return 1;
    }

    // Set pull-down resistor on the touch sensor pin
    int pullup_result = gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);
    if (pullup_result < 0) {
        fprintf(stderr, "Error setting pull-up/down resistor: %d\n", pullup_result);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int touch_detected = read_touch_sensor();
        if (touch_detected == 1) {
            // Toggle the relay state
            relay_state = !relay_state;
            control_relay(relay_state);
            log_relay_state(relay_state);

            // Wait for the sensor to return LOW
            while (gpioRead(TOUCH_SENSOR_PIN) == 1) {
                gpioDelay(1000); // Small delay to avoid busy-waiting
            }
        } else if (touch_detected < 0) {
            // Error reading touch sensor, exit
            fprintf(stderr, "Error reading touch sensor, exiting...\n");
            gpioTerminate();
            return 1;
        }

        gpioDelay(10000); // Sleep for 10 milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

