#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define FLOW_RATE_THRESHOLD_HIGH 5.0
#define FLOW_RATE_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT_MS 1000
#define PULSES_PER_LITER 7.5
#define LOG_FILE_NAME "water_flow.log"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count);
void control_solenoid(double flow_rate);
void log_event(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine (ISR) for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIMEOUT_MS * 1000) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
        last_tick = current_tick;
    }
}

// Function to calculate flow rate in liters per minute
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double flow_rate) {
    static int solenoid_state = 1; // 1 = open, 0 = closed

    if (flow_rate > FLOW_RATE_THRESHOLD_HIGH && solenoid_state == 1) {
        gpioWrite(SOLENOID_GPIO, 0); // Close the solenoid
        solenoid_state = 0;
        log_event("Solenoid closed");
    } else if (flow_rate < FLOW_RATE_THRESHOLD_LOW && solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1); // Open the solenoid
        solenoid_state = 1;
        log_event("Solenoid opened");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    char message[100];
    snprintf(message, sizeof(message), "Received signal %d, shutting down...", signal);
    log_event(message);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Initialize solenoid to open state
    gpioWrite(SOLENOID_GPIO, 1);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    int current_pulse_count = 0;
    double flow_rate;

    while (running) {
        // Sample pulse count every second
        gpioDelay(1000); // Wait for 1 second

        pthread_mutex_lock(&pulse_mutex);
        int new_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next second
        pthread_mutex_unlock(&pulse_mutex);

        int pulse_difference = new_pulse_count - current_pulse_count;
        current_pulse_count = new_pulse_count;

        // Calculate flow rate
        flow_rate = calculate_flow_rate(pulse_difference);

        // Control solenoid
        control_solenoid(flow_rate);

        // Log flow rate
        char message[100];
        snprintf(message, sizeof(message), "Flow rate: %.2f LPM", flow_rate);
        log_event(message);
    }

    // Ensure solenoid is open before exiting
    gpioWrite(SOLENOID_GPIO, 1);
    log_event("Solenoid opened (shutdown)");

    cleanup();
    return 0;
}

