    while (running) {
        // Sample pulse count every second
        gpioDelay(1000); // Wait for 1 second

        pthread_mutex_lock(&pulse_mutex);
        int new_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next second
        pthread_mutex_unlock(&pulse_mutex);

        int pulse_difference = new_pulse_count - current_pulse_count;
        current_pulse_count = new_pulse_count;

        // Calculate flow rate
        flow_rate = calculate_flow_rate(pulse_difference);

        // Control solenoid
        control_solenoid(flow_rate);

