        char message[100];
        snprintf(message, sizeof(message), "Flow rate: %.2f LPM", flow_rate);
        log_event(message);
    }

    // Ensure solenoid is open before exiting
    gpioWrite(SOLENOID_GPIO, 1);
    log_event("Solenoid opened (shutdown)");

    cleanup();
    return 0;
}

