#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_KNOWN_WEIGHT 100.0
#define DEFAULT_TARGET_WEIGHT 50.0
#define DEFAULT_ERROR_WEIGHT -1.0

// Global variables
static volatile int running = 1;
static int server_fd = -1;
