int log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
void cleanup();

// HX711 read function (bit-banged)
double read_hx711() {
    int i;
    unsigned long data = 0;
    int attempts = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);

    // Wait for DATA pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && attempts < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        attempts++;
    }

    if (attempts >= 1000) {
        fprintf(stderr, "Error: HX711 timeout waiting for DATA pin to go low.\n");
        log_event(DEFAULT_TARGET_WEIGHT, DEFAULT_ERROR_WEIGHT, "HX711 timeout waiting for DATA pin to go low.");
        return DEFAULT_ERROR_WEIGHT;
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // Pulse SCK 25th time to set the HX711 for the next reading
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return (double)data;
}

