int map_weight_to_pulse_width(double target_weight) {
    // Assuming a linear relationship between target weight and pulse width
    // Adjust the min and max target weights and pulse widths as needed
    double min_target_weight = 0.0; // Example: Minimum target weight
    double max_target_weight = 100.0; // Example: Maximum target weight
    int min_pulse_width = 1000; // Minimum pulse width
    int max_pulse_width = 2000; // Maximum pulse width

    if (target_weight < min_target_weight || target_weight > max_target_weight) {
        fprintf(stderr, "Error: Target weight out of range: %.2f. Must be between %.2f and %.2f.\n", target_weight, min_target_weight, max_target_weight);
        log_event(DEFAULT_TARGET_WEIGHT, DEFAULT_ERROR_WEIGHT, "Target weight out of range.");
        return -1;
    }

    return (int)(((target_weight - min_target_weight) / (max_target_weight - min_target_weight)) * (max_pulse_width - min_pulse_width) + min_pulse_width);
}

// Logging function
int log_event(double target_weight, double actual_weight, const char *error_message) {
    json_t *root = json_object();
