    if (init_gpio() != 0) {
        return 1;
    }

    // Read configuration
    read_config();

    // Initialize socket
    if (init_socket() != 0) {
        cleanup();
        return 1;
    }

    printf("Server listening on 127.0.0.1:%d\n", PORT);

    while (running) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
