        buffer[valread] = '\0'; // Null-terminate the buffer

        target_weight = atof(buffer);
        printf("Received target weight: %.2f grams\n", target_weight);

        // Dispense ingredient
        if (dispense(target_weight) == 0) {
            gpioDelay(1000); // Wait for 1 second
            raw_weight = read_hx711();
            if (raw_weight == DEFAULT_ERROR_WEIGHT) {
                actual_weight = DEFAULT_ERROR_WEIGHT;
                error_message = "Error reading weight from HX711.";
            } else {
                actual_weight = calibrate_weight(raw_weight);
                error_message = "";
            }
        } else {
            actual_weight = DEFAULT_ERROR_WEIGHT;
            error_message = "Error dispensing ingredient.";
        }

        // Log the event
        log_event(target_weight, actual_weight, error_message);

        // Send actual weight back to client
        char response[50];
        snprintf(response, sizeof(response), "%.2f", actual_weight);
        send(new_socket, response, strlen(response), 0);
        printf("Sent actual weight: %.2f grams\n", actual_weight);

        close(new_socket);
    }

    cleanup();
    return 0;
}

