#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define DEFAULT_PULSE_WIDTH 1500

static volatile int running = 1;
static struct termios old_term, new_term;

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d)\n", pulse_width);
        return -1;
    }
    gpioPWM(gpio, pulse_width);
    return 0;
}

// Function to handle keyboard input
int handle_keyboard_input(int *angle) {
    int key = getchar();
    if (key == '+') {
        *angle += 10;
        if (*angle > 180) {
            *angle = 180;
        }
    } else if (key == '-') {
        *angle -= 10;
        if (*angle < 0) {
            *angle = 0;
        }
    } else if (key == 'q' || key == EOF) {
        running = 0;
    }
    return key;
}

// Signal handler for SIGINT
void signal_handler(int signal) {
    running = 0;
}

// Function to restore terminal settings
void restore_terminal_settings() {
    tcsetattr(STDIN_FILENO, TCSANOW, &old_term);
}

int main() {
    int angle = 90;
    int pulse_width;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set initial pulse width
    pulse_width = DEFAULT_PULSE_WIDTH;
    if (set_servo_pulse_width(SERVO_PIN, pulse_width) != 0) {
        gpioTerminate();
        return 1;
    }

    // Save terminal settings
    tcgetattr(STDIN_FILENO, &old_term);
    new_term = old_term;
    new_term.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new_term);

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Use '+' and '-' to adjust the servo angle. Press 'q' to quit.\n");

    while (running) {
        // Handle keyboard input
        if (handle_keyboard_input(&angle) == EOF) {
            break;
        }

        // Calculate pulse width based on angle
        pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle - 0) / (180 - 0)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

        // Set servo pulse width
        if (set_servo_pulse_width(SERVO_PIN, pulse_width) != 0) {
            running = 0;
            break;
        }

        // Print current angle
        printf("Angle: %d\n", angle);
    }

    // Stop PWM pulses
    gpioPWM(SERVO_PIN, 0);

    // Restore terminal settings
    restore_terminal_settings();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

