#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_US 2000 // 2 milliseconds
#define LOG_FILE "motor_rpm.log"
#define SAMPLE_INTERVAL_SEC 5

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    unsigned long long last_pulse_time;
    double rpm;
} ProgramState;

ProgramState state = {0, 0.0};

// Function prototypes
int initialize_gpio();
void pulse_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_rpm(unsigned long long pulse_count, double time_interval_sec);
int log_rpm(double rpm);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the pigpio library and configures the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Callback function for pulse detection
void pulse_callback(int gpio, int level, unsigned int tick, void *user_data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    unsigned long long current_time = (unsigned long long)ts.tv_sec * 1000000000ULL + ts.tv_nsec;

    if (current_time - state.last_pulse_time > DEBOUNCE_DELAY_US * 1000) {
        state.last_pulse_time = current_time;
        // Increment pulse count (not directly used here, but could be passed via user_data)
        // For simplicity, we'll just calculate RPM in the main loop
    }
}

// Calculates the RPM based on the pulse count and time interval
double calculate_rpm(unsigned long long pulse_count, double time_interval_sec) {
    return (double)pulse_count / time_interval_sec * 60.0;
}

// Logs the RPM to a file in CSV format
int log_rpm(double rpm) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file);
    free(timestamp);
    return 0;
}

// Gets the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up edge detection
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    unsigned long long pulse_count = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    fprintf(stderr, "Monitoring RPM... Press Ctrl+C to exit.\n");

    while (program_running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        if (elapsed_time >= SAMPLE_INTERVAL_SEC) {
            // Calculate RPM
            state.rpm = calculate_rpm(pulse_count, SAMPLE_INTERVAL_SEC);

            // Log RPM
            if (log_rpm(state.rpm) != 0) {
                fprintf(stderr, "Failed to log RPM\n");
            }

            // Print RPM to stdout
            printf("RPM: %.2f\n", state.rpm);

            // Reset pulse count and start time
            pulse_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        gpioDelay(100); // Check every 100ms
    }

    // Clean up
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

