#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define POLLING_INTERVAL_MS 50
#define LONG_PRESS_DURATION_S 10

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int relay_state;
    time_t last_touch_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected) {
            time_t current_time = time(NULL);

            if (state.relay_state == 0) {
                // Toggle relay state
                state.relay_state = 1;
                if (control_relay(state.relay_state) != 0) {
                    log_event("Failed to control relay.");
                }
                log_event("Relay toggled ON.");
