#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM frequency
#define PWM_FREQUENCY 1000 // Hz

// Define proportional gain
#define KP 1.0

// Define sampling interval
#define SAMPLING_INTERVAL_MS 100

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate();
int calculate_valve_position(double flow_rate);
void log_data(double flow_rate, int valve_position);
void signal_handler(int signal);

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    pulse_count++;
}

// Function to calculate flow rate
double calculate_flow_rate()
{
    // Assuming 1 pulse per mL
    double flow_rate = (double)pulse_count / (SAMPLING_INTERVAL_MS / 1000.0);
    pulse_count = 0; // Reset pulse count
    return flow_rate;
}

// Function to calculate valve position using proportional control
int calculate_valve_position(double flow_rate)
{
    int valve_position = (int)(KP * (target_flow_rate - flow_rate));

    // Clamp valve position to 0-255 range
    if (valve_position < 0)
    {
        valve_position = 0;
    }
    else if (valve_position > 255)
    {
        valve_position = 255;
    }

    return valve_position;
}

// Function to log data to CSV file
void log_data(double flow_rate, int valve_position)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, shutting down...\n", signal);

    // Disable valve
    gpioWrite(VALVE_ENABLE_PIN, 0);

    // Set PWM duty cycle to 0
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[])
{
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1)
    {
        switch (opt)
        {
        case 't':
            target_flow_rate = atof(optarg);
            if (target_flow_rate <= 0)
            {
                fprintf(stderr, "Error: Invalid target flow rate. Must be greater than 0.\n");
                return 1;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
            return 1;
        }
    }

    if (target_flow_rate == 0.0)
    {
        fprintf(stderr, "Error: Target flow rate not specified.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Enable valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(VALVE_PWM_PIN, 255);

    // Register interrupt service routine for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0)
    {
        fprintf(stderr, "Error: Failed to register ISR for flow sensor\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1)
    {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate();

        // Calculate valve position
        int valve_position = calculate_valve_position(flow_rate);

        // Set PWM duty cycle
        gpioPWM(VALVE_PWM_PIN, valve_position);

        // Log data
        log_data(flow_rate, valve_position);

        // Wait for sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    return 0;
}

