#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define BUTTON_GPIO 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz
#define TAG_LENGTH 10
#define VALID_TAG "1234567890"
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_tag(unsigned char *tag);
int button_pressed();
void lock_door();
void unlock_door();
void log_event(const char *event);
void signal_handler(int signal);

// Function to read the RFID tag from the SPI interface
int spi_read_tag(unsigned char *tag) {
    int i, result;
    unsigned char buffer[TAG_LENGTH];

    // Read TAG_LENGTH bytes from the SPI interface
    for (i = 0; i < TAG_LENGTH; i++) {
        result = spiRead(spi_handle, &buffer[i], 1);
        if (result != 1) {
            log_event("SPI read error");
            return -1; // Indicate failure
        }
    }

    // Check if the tag is all zeros (no tag present)
    int all_zeros = 1;
    for (i = 0; i < TAG_LENGTH; i++) {
        if (buffer[i] != 0) {
            all_zeros = 0;
            break;
        }
    }

    if (all_zeros) {
        return 0; // No tag present
    }

    // Copy the tag data to the provided buffer
    memcpy(tag, buffer, TAG_LENGTH);
    return 1; // Tag read successfully
}

// Function to check if the button is pressed
int button_pressed() {
    static int last_state = 1; // Initialize to released state (pull-up)
    static unsigned long last_debounce_time = 0;
    int current_state = gpioRead(BUTTON_GPIO);
    unsigned long now = gpioTick();

    if (current_state != last_state) {
        last_debounce_time = now;
    }

    if ((now - last_debounce_time) > 50000) { // 50ms debounce
        if (current_state != last_state) {
            last_state = current_state;
            if (current_state == 0) { // Button pressed (active low)
                return 1;
            }
        }
    }
    return 0;
}

// Function to lock the door
void lock_door() {
    gpioWrite(LOCK1_GPIO, 0); // Lock 1
    gpioWrite(LOCK2_GPIO, 0); // Lock 2
}

// Function to unlock the door
void unlock_door() {
    gpioWrite(LOCK1_GPIO, 1); // Unlock 1
    gpioWrite(LOCK2_GPIO, 1); // Unlock 2
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Received signal, shutting down...");
    terminate = 1;
}

int main() {
    unsigned char tag[TAG_LENGTH];
    int spi_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Door access control system started");

    // Main loop
    while (!terminate) {
        spi_result = spi_read_tag(tag);

        if (spi_result == 1) {
            // Tag read successfully
            if (memcmp(tag, VALID_TAG, TAG_LENGTH) == 0) {
                // Valid tag
                log_event("Valid tag read");
                if (button_pressed()) {
                    log_event("Button pressed");
                    lock_door();
                    gpioDelay(5000000); // 5 seconds
                    unlock_door();
                    log_event("Door unlocked");
                } else {
                    log_event("Button press required");
                }
            } else {
                // Invalid tag
                log_event("Invalid tag read");
            }
        } else if (spi_result == 0) {
            // No tag present
            // Do nothing, just wait for a tag
        } else {
            // SPI read error
            // Already logged in spi_read_tag function
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    log_event("Door access control system stopped");
    fclose(log_file);
    spiClose(spi_handle);
    unlock_door(); // Ensure locks are unlocked on exit
    gpioTerminate();

    return 0;
}

