#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Parameters
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Target Speed (RPM)
#define TARGET_SPEED 60.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100

// Sample Time (ms)
#define SAMPLE_TIME 100

// Global Variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
int running = 1;

// Function Prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
void signal_handler(int signal);
void set_motor_direction(int motor, int direction);
void set_motor_speed(int motor, int speed);
double calculate_rpm(int encoder_count);
double pid_control(double setpoint, double actual_speed, double *integral, double *previous_error);
void log_data(double rpm1, double rpm2, double p, double i, double d, double output);

// Encoder AISR (Interrupt Service Routine)
void encoder1_AISR(int gpio, int level, uint32_t tick, void *user)
{
    int b_level = gpioRead(ENCODER1_B);
    pthread_mutex_lock(&encoder1_mutex);
    if (b_level == 0) {
        encoder1_count++;
    } else {
        encoder1_count--;
    }
    pthread_mutex_unlock(&encoder1_mutex);
}

// Encoder BISR (Interrupt Service Routine)
void encoder2_BISR(int gpio, int level, uint32_t tick, void *user)
{
    int a_level = gpioRead(ENCODER2_A);
    pthread_mutex_lock(&encoder2_mutex);
    if (a_level == 0) {
        encoder2_count++;
    } else {
        encoder2_count--;
    }
    pthread_mutex_unlock(&encoder2_mutex);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENA, 255);
    gpioSetPWMrange(MOTOR2_ENB, 255);

    // Initialize Encoder AISR
    if (gpioSetISRFuncEx(ENCODER1_A, EITHER_EDGE, 0, encoder1_AISR, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder 1 A\n");
        gpioTerminate();
        return 1;
    }

    // Initialize Encoder BISR
    if (gpioSetISRFuncEx(ENCODER2_B, EITHER_EDGE, 0, encoder2_BISR, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder 2 B\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,P,I,D,Output\n");
    fflush(log_file);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create encoder threads
    pthread_t encoder1_thread_id, encoder2_thread_id;
    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder 1 thread\n");
        signal_handler(SIGTERM);
        return 1;
    }
    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder 2 thread\n");
        signal_handler(SIGTERM);
        return 1;
    }

    // PID variables
    double integral1 = 0.0;
    double previous_error1 = 0.0;
    double integral2 = 0.0;
    double previous_error2 = 0.0;

    // Main loop
    while (running) {
        // Calculate RPM
        double rpm1 = calculate_rpm(encoder1_count);
        double rpm2 = calculate_rpm(encoder2_count);

        // PID control
        double output1 = pid_control(TARGET_SPEED, rpm1, &integral1, &previous_error1);
        double output2 = pid_control(TARGET_SPEED, rpm2, &integral2, &previous_error2);

        // Set motor speeds
        set_motor_speed(1, (int)fabs(output1));
        set_motor_direction(1, (output1 > 0) ? 1 : -1); // Forward if output > 0, backward otherwise
        set_motor_speed(2, (int)fabs(output2));
        set_motor_direction(2, (output2 > 0) ? 1 : -1); // Forward if output > 0, backward otherwise

        // Log data
        log_data(rpm1, rpm2, KP * previous_error1, KI * integral1, KD * (previous_error1 - previous_error1), output1);

        // Wait for sample time
        gpioDelay(SAMPLE_TIME * 1000); // Convert ms to us
    }

    // Clean up
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Encoder 1 thread function
void *encoder1_thread(void *arg)
{
    while (running) {
        // Do nothing, just keep the thread alive
        gpioDelay(10000); // Sleep for 10ms
    }
    return NULL;
}

// Encoder 2 thread function
void *encoder2_thread(void *arg)
{
    while (running) {
        // Do nothing, just keep the thread alive
        gpioDelay(10000); // Sleep for 10ms
    }
    return NULL;
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Release GPIO lines
    gpioSetMode(MOTOR1_ENA, PI_INPUT);
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Set motor direction function
void set_motor_direction(int motor, int direction)
{
    if (motor == 1) {
        if (direction == 1) {
            gpioWrite(MOTOR1_IN1, 1);
            gpioWrite(MOTOR1_IN2, 0);
        } else {
            gpioWrite(MOTOR1_IN1, 0);
            gpioWrite(MOTOR1_IN2, 1);
        }
    } else if (motor == 2) {
        if (direction == 1) {
            gpioWrite(MOTOR2_IN3, 1);
            gpioWrite(MOTOR2_IN4, 0);
        } else {
            gpioWrite(MOTOR2_IN3, 0);
            gpioWrite(MOTOR2_IN4, 1);
        }
    }
}

// Set motor speed function
void set_motor_speed(int motor, int speed)
{
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    if (motor == 1) {
        gpioPWM(MOTOR1_ENA, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENB, speed);
    }
}

// Calculate RPM function
double calculate_rpm(int encoder_count)
{
    double rpm;
    pthread_mutex_lock(&encoder1_mutex);
    int count = encoder1_count;
    encoder1_count = 0; // Reset count after reading
    pthread_mutex_unlock(&encoder1_mutex);

    // Assuming 1 pulse per revolution
    rpm = (double)count * 60.0 / SAMPLE_TIME; // pulses / second * 60 seconds / minute
    return rpm;
}

// PID control function
double pid_control(double setpoint, double actual_speed, double *integral, double *previous_error)
{
    double error = setpoint - actual_speed;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Log data function
void log_data(double rpm1, double rpm2, double p, double i, double d, double output)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, rpm1, rpm2, p, i, d, output);
    fflush(log_file);
}

