#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define POLL_INTERVAL_MS 50

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ELE0_FILTERTH 0x2B
#define MPR121_ELE0_TOUCHTH 0x41
#define MPR121_ELE0_RELEASETH 0x42
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize MPR121
int mpr121_init() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x80); // Reset
    if (status < 0) {
        fprintf(stderr, "Error: Soft reset failed (%d).\n", status);
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure filtering parameters
    status = i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01); // MHD_R
    if (status < 0) {
        fprintf(stderr, "Error: Setting MHD_R failed (%d).\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01); // NHD_R
    if (status < 0) {
        fprintf(stderr, "Error: Setting NHD_R failed (%d).\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E); // NCLR
    if (status < 0) {
        fprintf(stderr, "Error: Setting NCLR failed (%d).\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x00); // FDLR
    if (status < 0) {
        fprintf(stderr, "Error: Setting FDLR failed (%d).\n", status);
        return -1;
    }

    // Set touch and release thresholds
    for (int i = 0; i < 12; i++) {
        status = i2cWriteByteData(i2c_handle, MPR121_ELE0_TOUCHTH + 2 * i, 0x30); // Touch threshold
        if (status < 0) {
            fprintf(stderr, "Error: Setting touch threshold for electrode %d failed (%d).\n", i, status);
            return -1;
        }
        status = i2cWriteByteData(i2c_handle, MPR121_ELE0_RELEASETH + 2 * i, 0x10); // Release threshold
        if (status < 0) {
            fprintf(stderr, "Error: Setting release threshold for electrode %d failed (%d).\n", i, status);
            return -1;
        }
    }

    // Enable run mode
    status = i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x10); // ELEPROX_EN = 1
    if (status < 0) {
        fprintf(stderr, "Error: Setting ELEPROX_EN failed (%d).\n", status);
        return -1;
    }
