// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation durations (in milliseconds)
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define valve activation pause durations (in seconds)
#define VALVE1_PAUSE 5
#define VALVE2_PAUSE 10

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void activate_valve(int gpio_pin, int duration_ms);
void pause_execution(int duration_s);
char* get_iso8601_timestamp();
int log_event(const char *timestamp, int valve_number);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    // Ensure valves are initially closed
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    return 0; // Indicate success
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Activate the valve
    gpioDelay(duration_ms * 1000); // Delay for the specified duration (in microseconds)
    gpioWrite(gpio_pin, 0); // Deactivate the valve
}

// Function to pause execution for a specified duration
void pause_execution(int duration_s) {
    gpioDelay(duration_s * 1000000); // Delay for the specified duration (in microseconds)
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation failed for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log an event to the log file
int log_event(const char *timestamp, int valve_number) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1; // Indicate failure
    }

    fprintf(log_file, "%s - Valve %d activated\n", timestamp, valve_number);
    fflush(log_file); // Ensure the log is written immediately

    return 0; // Indicate success
}

// Function to perform cleanup operations before exiting
void cleanup() {
    printf("Cleaning up...\n");

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Deactivate both valves
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and configure GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file for appending
    log_file = fopen("valve_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1; // Exit if file opening fails
    }

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    // Main loop to control the valves
    while (program_running) {
        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, continuing...\n");
            continue; // Skip to the next iteration
        }

        // Activate Valve 1
        activate_valve(VALVE1_GPIO, VALVE1_DURATION);
        log_event(timestamp, 1);

        // Pause execution
        pause_execution(VALVE1_PAUSE);

        // Activate Valve 2
        activate_valve(VALVE2_GPIO, VALVE2_DURATION);
        log_event(timestamp, 2);

        // Pause execution
        pause_execution(VALVE2_PAUSE);

        free(timestamp); // Free the allocated memory for the timestamp
    }

    // Perform cleanup operations before exiting
    cleanup();

    return 0;
}

