#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FILTER_CONFIG 0x2B
#define MPR121_CHARGECURRENT 0x2C
#define MPR121_CHARGEDELAY 0x2D

// GPIO pin for relay control
#define RELAY_PIN 17

// Global variables
int i2c_fd;
bool relay_state = false;

// Function prototypes
int mpr121_init(int fd);
int mpr121_set_thresholds(int fd, int touch_threshold, int release_threshold);
int mpr121_set_filter_charge(int fd, int filter_config, int charge_current, int charge_delay);
int mpr121_read_touch_status(int fd);
void relay_toggle(int pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    wiringPiSetupGpio(); // Reinitialize to avoid issues
    pinMode(RELAY_PIN, INPUT); // Set to input to avoid leaving it high
    exit(0);
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Stop mode
    if (wiringPiI2CWriteReg8(fd, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to MPR121_ELECTRODE_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    delay(1); // Small delay after writing to the register

    // Set touch and release thresholds
    if (mpr121_set_thresholds(fd, 12, 6) < 0) {
        return -1;
    }

    // Set filter and charge time
    if (mpr121_set_filter_charge(fd, 0x10, 0x0F, 0x01) < 0) {
        return -1;
    }

    // Run mode
    if (wiringPiI2CWriteReg8(fd, MPR121_ELECTRODE_CONFIG, 0x10) < 0) {
        fprintf(stderr, "Error writing to MPR121_ELECTRODE_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    delay(1); // Small delay after writing to the register

    return 0;
}

// MPR121 set thresholds function
int mpr121_set_thresholds(int fd, int touch_threshold, int release_threshold) {
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(fd, MPR121_TOUCHTH_0 + 2 * i, touch_threshold) < 0) {
            fprintf(stderr, "Error writing to MPR121_TOUCHTH_%d: %s\n", i, strerror(errno));
            return -1;
        }
        if (wiringPiI2CWriteReg8(fd, MPR121_RELEASETH_0 + 2 * i, release_threshold) < 0) {
            fprintf(stderr, "Error writing to MPR121_RELEASETH_%d: %s\n", i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// MPR121 set filter and charge time function
int mpr121_set_filter_charge(int fd, int filter_config, int charge_current, int charge_delay) {
    if (wiringPiI2CWriteReg8(fd, MPR121_FILTER_CONFIG, filter_config) < 0) {
        fprintf(stderr, "Error writing to MPR121_FILTER_CONFIG: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_CHARGECURRENT, charge_current) < 0) {
        fprintf(stderr, "Error writing to MPR121_CHARGECURRENT: %s\n", strerror(errno));
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_CHARGEDELAY, charge_delay) < 0) {
        fprintf(stderr, "Error writing to MPR121_CHARGEDELAY: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int fd) {
    int touch_status_l = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error reading MPR121_TOUCHSTATUS_L: %s\n", strerror(errno));
        return -1;
