#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define timing constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_MS 2000
#define POLLING_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_unlock_time = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void log_event(const char *event_type);
void unlock_door();
void rate_limit();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

// Log event to file
void log_event(const char *event_type) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    unsigned long timestamp_ms = (unsigned long)(ts.tv_sec) * 1000 + (unsigned long)(ts.tv_nsec) / 1000000;

    fprintf(log_file, "%s,%lu\n", event_type, timestamp_ms);
    fflush(log_file); // Ensure immediate write to file
}

// Unlock the door
void unlock_door() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    log_event("Door Unlocked");
    gpioDelay(UNLOCK_DURATION_MS);
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
}

// Implement rate limiting
void rate_limit() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    last_unlock_time = (unsigned long)(ts.tv_sec) * 1000 + (unsigned long)(ts.tv_nsec) / 1000000;
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    printf("Door unlock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int pir_value = gpioRead(PIR_SENSOR_PIN);

        if (pir_value == 1) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            unsigned long current_time = (unsigned long)(ts.tv_sec) * 1000 + (unsigned long)(ts.tv_nsec) / 1000000;

            if (current_time - last_unlock_time >= RATE_LIMIT_DURATION_MS) {
                log_event("Motion Detected");
                unlock_door();
                rate_limit();
            } else {
                log_event("Rate Limited");
            }
        }

        gpioDelay(POLLING_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup_gpio();
    fclose(log_file);
    printf("Door unlock system stopped.\n");
    return 0;
}

