#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define the number of steps in a pattern
#define NUM_STEPS 10

// Define the minimum and maximum step durations (in milliseconds)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Structure to represent a single step in the haptic pattern
typedef struct {
    int motor1_duty_cycle;
    int motor2_duty_cycle;
    int duration_ms;
} Step;

// Structure to represent a haptic pattern
typedef struct {
    Step steps[NUM_STEPS];
} Pattern;

// Global variable to indicate program shutdown
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    shutdown_flag = 1;
    fprintf(stderr, "\nCaught SIGINT, shutting down...\n");
}

// Function to generate a random integer within a specified range
int random_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random haptic pattern
Pattern generate_pattern() {
    Pattern pattern;

    for (int i = 0; i < NUM_STEPS; i++) {
        pattern.steps[i].motor1_duty_cycle = random_range(0, 255);
        pattern.steps[i].motor2_duty_cycle = random_range(0, 255);
        pattern.steps[i].duration_ms = random_range(MIN_DURATION, MAX_DURATION);
    }

    return pattern;
}

// Function to play a haptic pattern
void play_pattern(const Pattern *pattern) {
    for (int i = 0; i < NUM_STEPS; i++) {
        gpioPWM(MOTOR1_GPIO, pattern->steps[i].motor1_duty_cycle);
        gpioPWM(MOTOR2_GPIO, pattern->steps[i].motor2_duty_cycle);
        gpioDelay(pattern->steps[i].duration_ms * 1000); // Convert milliseconds to microseconds
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the motors
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to generate and play patterns
    while (!shutdown_flag) {
        // Generate a random pattern
        Pattern pattern = generate_pattern();

        // Play the pattern
        play_pattern(&pattern);
    }

    // Stop both motors
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

