#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define TIMEOUT_US 500000 // 0.5 seconds in microseconds
#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0 // kg
#define LOG_FILE "weight_log.txt"
#define CALIBRATION_FILE "calibration.txt"

// Global variables
static volatile int running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;

// Function prototypes
int read_hx711(int data_pin, int clock_pin, long *raw_value);
double calculate_weight(long raw_value, double scale_factor, double offset);
void control_solenoid(int solenoid_pin, int state);
void log_weight(double weight);
int load_calibration_data(const char *filename, double *scale_factor, double *offset);
int save_calibration_data(const char *filename, double scale_factor, double offset);
void signal_handler(int signal);
int calibrate_offset(int data_pin, int clock_pin, double *offset);

// Function to read data from HX711 with timeout
int read_hx711(int data_pin, int clock_pin, long *raw_value) {
    long value = 0;
    int i;
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for data pin to go low
    while (gpioRead(data_pin) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if ((now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
            fprintf(stderr, "Timeout reading HX711\n");
            return -1; // Timeout
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // Small delay for clock stability
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *raw_value = value;
    return 0;
}

// Function to calculate weight
double calculate_weight(long raw_value, double scale_factor, double offset) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid
void control_solenoid(int solenoid_pin, int state) {
    gpioWrite(solenoid_pin, state);
}

// Function to log weight to file
void log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
}

// Function to load calibration data from file
int load_calibration_data(const char *filename, double *scale_factor, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found, using default values.\n");
        return -1;
    }

    if (fscanf(fp, "%lf %lf", scale_factor, offset) != 2) {
        fprintf(stderr, "Invalid calibration file format, using default values.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
