    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to calibrate the offset
int calibrate_offset(int data_pin, int clock_pin, double *offset) {
    long sum = 0;
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        long raw_value;
        if (read_hx711(data_pin, clock_pin, &raw_value) != 0) {
            fprintf(stderr, "Error reading HX711 during calibration.\n");
            return -1;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    *offset = (double)sum / NUM_CALIBRATION_READINGS;
