#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define RAIN_THRESHOLD 3
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define MOTOR_PWM_FREQUENCY 1000
#define MOTOR_PWM_DUTY_CYCLE 150
#define MOTOR_RUN_DURATION_SEC 5
#define MOTOR_STOP_DELAY_SEC 60
#define SENSOR_CHECK_INTERVAL_SEC 60

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_rain_sensor();
int debounce_rain_sensor();
int control_motor(int in1, int in2, int pwm);
int log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor
int read_rain_sensor() {
    int value = gpioRead(RAIN_SENSOR_PIN);
    if (value < 0) {
        log_event("Error reading rain sensor.");
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce the rain sensor
int debounce_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int sensor_value = read_rain_sensor();
        if (sensor_value < 0) return -1; // Propagate error
        if (sensor_value == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0;
}

// Function to control the motor
int control_motor(int in1, int in2, int pwm) {
    if (gpioWrite(MOTOR_IN1_PIN, in1) < 0) {
        log_event("Error setting MOTOR_IN1_PIN.");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, in2) < 0) {
        log_event("Error setting MOTOR_IN2_PIN.");
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, pwm) < 0) {
        log_event("Error setting MOTOR_PWM_PIN.");
        return -1;
    }
    return 0;
}

// Function to log events to syslog
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);

    syslog(LOG_INFO, "%s", log_message);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, stopping motor and exiting...");
    control_motor(0, 0, 0); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQUENCY);

    // Open syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Window control system started.");

    time_t last_check_time = time(NULL);
    int motor_running = 0;
    time_t motor_start_time = 0;

    while (running) {
        time_t current_time = time(NULL);

        if (!motor_running && difftime(current_time, last_check_time) >= SENSOR_CHECK_INTERVAL_SEC) {
            int rain_detected = debounce_rain_sensor();
            if (rain_detected > 0) {
                log_event("Rain detected!");
                if (control_motor(1, 0, MOTOR_PWM_DUTY_CYCLE) == 0) {
                    log_event("Motor started.");
                    motor_running = 1;
                    motor_start_time = current_time;
                } else {
                    log_event("Failed to start motor.");
                }
            } else if (rain_detected < 0) {
                log_event("Error during rain detection.");
            }
            last_check_time = current_time;
        }

        if (motor_running) {
            if (difftime(current_time, motor_start_time) >= MOTOR_RUN_DURATION_SEC) {
                if (control_motor(0, 0, 0) == 0) {
                    log_event("Motor stopped after duration.");
                    motor_running = 0;
                    time_t stop_time = time(NULL);
                    last_check_time = stop_time + MOTOR_STOP_DELAY_SEC; // Schedule next check after delay
                } else {
                    log_event("Failed to stop motor.");
                    motor_running = 0; // Stop the loop if stopping fails
                }
            }
        }

        gpioDelay(100000); // Check every 0.1 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motor(0, 0, 0);
    gpioTerminate();
    closelog();

    return 0;
}

