#define LOCK_DURATION 5        // seconds
#define TIMEOUT_MS 100         // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711(int dt_pin, int sck_pin, long *raw_value);
double convert_to_weight(long raw_value, double calibration_factor);
int control_solenoid(int solenoid_pin, int state);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read raw data from HX711
int read_hx711(int dt_pin, int sck_pin, long *raw_value) {
    int i;
    long data = 0;

    gpioSetMode(dt_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);

    // Wait for DT to go low
    int timeout_counter = 0;
    while (gpioRead(dt_pin) == 1 && timeout_counter < TIMEOUT_MS * 1000) {
        gpioDelay(1); // 1 us delay
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_MS * 1000) {
        log_event("HX711 read timeout");
        return -1; // Timeout
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(dt_pin)) {
            data++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // 1 us delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(sck_pin, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(sck_pin, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    *raw_value = data;
    return 0;
}

