    FILE *fp;
    double factor;

    fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found.  Calibration required.\n");
        return -1;
    }

    if (fscanf(fp, "%lf", &factor) != 1) {
        fprintf(stderr, "Error: Invalid calibration data in file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    calibration_factor = factor;
    printf("Calibration factor loaded: %lf\n", calibration_factor);
    return 0;
}

