int save_calibration(double factor) {
    FILE *fp;

    fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing\n");
        return -1;
    }

    fprintf(fp, "%lf", factor);
    fclose(fp);
    return 0;
}

