        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration factor
    if (load_calibration() != 0) {
        printf("Calibration required.\n");
