#include <string.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define log file name
#define LOG_FILE "relay_events.log"

// Global variable to store the current relay state
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_sensor();
int toggle_relay(int current_state);
int log_event(int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit program
}

// Function to read the sensor value
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", sensor_value);
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to toggle the relay state
int toggle_relay(int current_state) {
    int new_state = !current_state;
    int result = gpioWrite(RELAY_PIN, new_state);
    if (result != 0) {
        fprintf(stderr, "Error writing to relay pin: %d\n", result);
        return -1; // Indicate error
    }
    return new_state;
}

// Function to log the event to a file
int log_event(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1; // Indicate error
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, Relay: %s\n", timestamp, relay_state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-up/down resistor for the sensor pin (optional, depending on sensor)
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP); // Or PI_PUD_DOWN if needed

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break; // Exit loop on sensor read error
        }

        // Check for obstacle detection (sensor is active low)
        if (sensor_value == 0) {
            int new_relay_state = toggle_relay(relay_state);
            if (new_relay_state >= 0) {
                relay_state = new_relay_state;
                if (log_event(relay_state) != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
            } else {
                fprintf(stderr, "Error toggling relay.\n");
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup before exiting (in case the loop breaks due to an error)
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio

    return 0;
}

