#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_PIN 18
#define DEFAULT_DURATION 600 // 10 minutes

volatile sig_atomic_t terminate = 0;

// Function to read the watering duration from the configuration file
int read_configuration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open configuration file %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Configuration file %s is empty\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Parse the line
    char *key = strtok(line, "=");
    char *value_str = strtok(NULL, "=");

    if (key == NULL || value_str == NULL) {
        fprintf(stderr, "Error: Malformed configuration file %s\n", filename);
        return -1;
    }

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Error: Invalid key in configuration file %s\n", filename);
        return -1;
    }

    char *endptr;
    long value = strtol(value_str, &endptr, 10);

    if (*endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Error: Invalid value in configuration file %s\n", filename);
        return -1;
    }

    if (value < 1 || value > 3600) {
        fprintf(stderr, "Error: Watering duration out of range (1-3600 seconds) in configuration file %s\n", filename);
        return -1;
    }

    *duration = (int)value;
    return 0;
}

// Function to set the GPIO pin state
int set_gpio_state(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to state %d (error code %d)\n", pin, state, result);
        return -1;
    }
    return 0;
}

// Function to sleep for a specified duration
void sleep_duration(int duration) {
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < duration && !terminate) {
        gpioDelay(100); // Check every 100ms
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int duration = DEFAULT_DURATION;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Read configuration from file
    if (read_configuration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Using default watering duration: %d seconds\n", DEFAULT_DURATION);
        duration = DEFAULT_DURATION;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        printf("Watering for %d seconds...\n", duration);

        // Turn valve on
        if (set_gpio_state(GPIO_PIN, 1) != 0) {
            break;
        }

        // Sleep for the specified duration
        sleep_duration(duration);

        // Turn valve off
        if (set_gpio_state(GPIO_PIN, 0) != 0) {
            break;
        }

        printf("Watering complete.\n");
        break; // Exit the loop after one cycle
    }

    // Clean up and exit
    gpioWrite(GPIO_PIN, 0); // Ensure valve is off
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

