#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_FORWARD 22
#define LEFT_MOTOR_BACKWARD 23
#define RIGHT_MOTOR_FORWARD 24
#define RIGHT_MOTOR_BACKWARD 25

// Define motor speeds
#define BASE_SPEED 150
#define TURN_SPEED 75

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio);
void set_motor_speed(int left_gpio_forward, int left_gpio_backward, int right_gpio_forward, int right_gpio_backward, int left_speed, int right_speed);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio) {
    return !gpioRead(gpio); // Active-low
}

// Function to set motor speed
void set_motor_speed(int left_gpio_forward, int left_gpio_backward, int right_gpio_forward, int right_gpio_backward, int left_speed, int right_speed) {
    if (left_speed > 0) {
        gpioWrite(left_gpio_forward, 1);
        gpioPWM(left_gpio_forward, left_speed);
        gpioWrite(left_gpio_backward, 0);
    } else {
        gpioWrite(left_gpio_forward, 0);
        gpioWrite(left_gpio_backward, 0);
    }

    if (right_speed > 0) {
        gpioWrite(right_gpio_forward, 1);
        gpioPWM(right_gpio_forward, right_speed);
        gpioWrite(right_gpio_backward, 0);
    } else {
        gpioWrite(right_gpio_forward, 0);
        gpioWrite(right_gpio_backward, 0);
    }
}

// Function to log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;
    set_motor_speed(LEFT_MOTOR_FORWARD, LEFT_MOTOR_BACKWARD, RIGHT_MOTOR_FORWARD, RIGHT_MOTOR_BACKWARD, 0, 0); // Stop motors
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(LEFT_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_BACKWARD, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_FORWARD, 1000);
    gpioSetPWMfrequency(RIGHT_MOTOR_FORWARD, 1000);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int left_sensor = read_sensor(LEFT_SENSOR);
        int middle_sensor = read_sensor(MIDDLE_SENSOR);
        int right_sensor = read_sensor(RIGHT_SENSOR);

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (middle_sensor == 0) {
            // Line detected, maintain base speed
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            // Turn right
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            // Turn left
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            // No line detected, stop
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speed(LEFT_MOTOR_FORWARD, LEFT_MOTOR_BACKWARD, RIGHT_MOTOR_FORWARD, RIGHT_MOTOR_BACKWARD, left_speed, right_speed);
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_motor_speed(LEFT_MOTOR_FORWARD, LEFT_MOTOR_BACKWARD, RIGHT_MOTOR_FORWARD, RIGHT_MOTOR_BACKWARD, 0, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

