    while (running) {
        int left_sensor = read_sensor(LEFT_SENSOR);
        int middle_sensor = read_sensor(MIDDLE_SENSOR);
        int right_sensor = read_sensor(RIGHT_SENSOR);

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (middle_sensor == 0) {
            // Line detected, maintain base speed
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            // Turn right
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            // Turn left
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            // No line detected, stop
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speed(LEFT_MOTOR_FORWARD, LEFT_MOTOR_BACKWARD, RIGHT_MOTOR_FORWARD, RIGHT_MOTOR_BACKWARD, left_speed, right_speed);
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_motor_speed(LEFT_MOTOR_FORWARD, LEFT_MOTOR_BACKWARD, RIGHT_MOTOR_FORWARD, RIGHT_MOTOR_BACKWARD, 0, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

