#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Function prototypes
int initialize_gpio();
int read_button(int pin);
int set_servo_pulse_width(int pin, int pulse_width);
void lock_door();
void unlock_door();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Install signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read lock button
        if (read_button(LOCK_BUTTON_PIN) == 0) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        // Read unlock button
        if (read_button(UNLOCK_BUTTON_PIN) == 0) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set button pins as input with pull-up resistors
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Read button state with debouncing
int read_button(int pin) {
    int button_state = gpioRead(pin);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    return button_state;
}

// Set servo pulse width
int set_servo_pulse_width(int pin, int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Error: Invalid pulse width. Must be between 500 and 2500.\n");
        return 1;
    }

    gpioServo(pin, pulse_width);
    return 0;
}

// Lock the door
void lock_door() {
    if (set_servo_pulse_width(SERVO_PIN, LOCK_PULSE_WIDTH) == 0) {
        printf("Door locked.\n");
    } else {
        fprintf(stderr, "Error locking door.\n");
    }
}

// Unlock the door
void unlock_door() {
    if (set_servo_pulse_width(SERVO_PIN, UNLOCK_PULSE_WIDTH) == 0) {
        printf("Door unlocked.\n");
    } else {
        fprintf(stderr, "Error unlocking door.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting gracefully.\n");
    program_running = 0;

    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

