#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <zmq.h>
#include <time.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://localhost:5555"

// Define ZeroMQ topic
#define ZMQ_TOPIC "SOUND_ALERTS"

// Define alarm duration (seconds)
#define ALARM_DURATION 1

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
void *context = NULL;
void *publisher = NULL;
void *subscriber = NULL;

// Function prototypes
int init_gpio();
int init_zmq();
void sound_sensor_mode();
void alarm_node_mode();
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int sound_sensor_pin;
    int alarm_led_pin;
    char zmq_endpoint[256];
    char zmq_topic[256];
    int alarm_duration;
} config_t;

config_t config = {
    SOUND_SENSOR_PIN,
    ALARM_LED_PIN,
    ZMQ_ENDPOINT,
    ZMQ_TOPIC,
    ALARM_DURATION
};

int main(int argc, char *argv[]) {
    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    // Initialize pigpio
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Initialize ZeroMQ
    if (init_zmq() != 0) {
        fprintf(stderr, "Failed to initialize ZeroMQ.\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Run the appropriate mode
    if (strcmp(argv[1], "sound_sensor") == 0) {
        sound_sensor_mode();
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        alarm_node_mode();
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        cleanup();
        return 1;
    }

    // Clean up and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.sound_sensor_pin, PI_INPUT);
    gpioSetMode(config.alarm_led_pin, PI_OUTPUT);

    return 0;
}

// Initialize ZeroMQ
int init_zmq() {
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Error creating ZeroMQ context\n");
        return 1;
    }

    return 0;
}

// Sound sensor mode
void sound_sensor_mode() {
    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "Error creating ZeroMQ publisher socket\n");
        cleanup();
        return;
    }

    int rc = zmq_bind(publisher, config.zmq_endpoint);
    if (rc != 0) {
        fprintf(stderr, "Error binding ZeroMQ publisher socket: %s\n", zmq_strerror(zmq_errno()));
        cleanup();
        return;
    }

    printf("Sound sensor mode started. Listening on GPIO%d\n", config.sound_sensor_pin);

    while (!terminate) {
        // Read sound sensor
        int sound_detected = (gpioRead(config.sound_sensor_pin) == 0);

        if (sound_detected) {
            // Publish alert
            char message[256];
            snprintf(message, sizeof(message), "%s: Sound detected at %ld", config.zmq_topic, time(NULL));
            zmq_msg_t zmq_message;
            zmq_msg_init_size(&zmq_message, strlen(message));
            memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

