#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

// Configuration
#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 256
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define MAX_PULSE_WIDTH 2000 // Maximum acceptable pulse width (microseconds)

// Global variables
static volatile int pulse_index = 0;
static volatile uint32_t pulse_buffer[PULSE_BUFFER_SIZE];
static volatile int pulse_count = 0;
static volatile int nec_frame_complete = 0;
static struct mosquitto *mosq = NULL;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
int decode_nec(uint32_t *pulse_buffer, int pulse_count, uint32_t *address, uint32_t *command);
int validate_checksum(uint32_t address, uint32_t command, uint32_t inverted_address);
int publish_mqtt(uint32_t address, uint32_t command);
void signal_handler(int signum);
int initialize_gpio();
int initialize_mqtt();
void cleanup();

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t pulse_width;

    if (level != PI_OFF && level != PI_ON) return; // Ignore spurious levels

    if (last_tick != 0) {
        pulse_width = tick - last_tick;
        if (pulse_width > MAX_PULSE_WIDTH) {
            syslog(LOG_ERR, "Pulse width exceeded maximum value: %u", pulse_width);
            last_tick = tick;
            return;
        }

        if (pulse_index < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_index++] = pulse_width;
            pulse_count++;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
            pulse_index = 0; // Reset index to prevent further overflow
            pulse_count = 0;
            nec_frame_complete = 0; // Reset frame completion flag
        }
    }
    last_tick = tick;

    if (level == PI_OFF) {
        nec_frame_complete = 1; // Set frame complete flag on falling edge
    }
}

// NEC decoding function
int decode_nec(uint32_t *pulse_buffer, int pulse_count, uint32_t *address, uint32_t *command) {
    if (pulse_count < 68) {
        syslog(LOG_ERR, "Incomplete NEC frame: %d pulses", pulse_count);
        return -1;
    }

    // Verify header
    if (pulse_buffer[0] < NEC_HEADER_MARK * 0.8 || pulse_buffer[0] > NEC_HEADER_MARK * 1.2 ||
        pulse_buffer[1] < NEC_HEADER_SPACE * 0.8 || pulse_buffer[1] > NEC_HEADER_SPACE * 1.2) {
        syslog(LOG_ERR, "Invalid NEC header");
        return -1;
    }

    *address = 0;
    *command = 0;

    // Decode address and command (32 bits)
    for (int i = 2; i < 34; i++) {
        if (pulse_buffer[2 * i] < NEC_BIT_MARK * 0.8 || pulse_buffer[2 * i] > NEC_BIT_MARK * 1.2) {
            syslog(LOG_ERR, "Invalid bit mark at index %d", i);
            return -1;
        }

        if (pulse_buffer[2 * i + 1] > NEC_ONE_SPACE * 0.8 && pulse_buffer[2 * i + 1] < NEC_ONE_SPACE * 1.2) {
            if (i < 18) {
                *address = (*address << 1) | 1;
            } else {
                *command = (*command << 1) | 1;
            }
        } else if (pulse_buffer[2 * i + 1] > NEC_ZERO_SPACE * 0.8 && pulse_buffer[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
            if (i < 18) {
                *address = (*address << 1) | 0;
            } else {
                *command = (*command << 1) | 0;
            }
        } else {
            syslog(LOG_ERR, "Invalid bit space at index %d", i);
            return -1;
        }
    }

    return 0;
}

// Checksum validation function
int validate_checksum(uint32_t address, uint32_t command, uint32_t inverted_address) {
    uint8_t checksum = (uint8_t)(address + (address >> 8) + command + (command >> 8));
    uint8_t calculated_checksum = (uint8_t)(~checksum & 0xFF);

    if (calculated_checksum != (uint8_t)(inverted_address & 0xFF)) {
        syslog(LOG_ERR, "Checksum mismatch: calculated 0x%02X, received 0x%02X", calculated_checksum, (uint8_t)(inverted_address & 0xFF));
        return -1;
    }

    return 0;
}

// MQTT publishing function
int publish_mqtt(uint32_t address, uint32_t command) {
    cJSON *root = cJSON_CreateObject();
    cJSON_AddNumberToObject(root, "address", address);
    cJSON_AddNumberToObject(root, "command", command);

    char *json_string = cJSON_PrintUnformatted(root);
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to create JSON string");
        cJSON_Delete(root);
        return -1;
    }

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(json_string), json_string, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        cJSON_Delete(root);
        free(json_string);
        return -1;
    }

    syslog(LOG_INFO, "Published to MQTT: %s", json_string);
    cJSON_Delete(root);
    free(json_string);

    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received: %d. Cleaning up...", signum);
    cleanup();
    exit(0);
}

// GPIO initialization function
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    gpioSetAlertFunc(GPIO_PIN, pulse_callback);

    return 0;
}

// MQTT initialization function
int initialize_mqtt() {
    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_loop_start(mosq);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop start error: %s", mosquitto_strerror(ret));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
    closelog();
}

int main() {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (initialize_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT initialization failed. Exiting.");
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "IR decoder started");

    uint32_t address, command;

    while (1) {
        if (nec_frame_complete) {
            nec_frame_complete = 0; // Reset flag

            if (decode_nec(pulse_buffer, pulse_count, &address, &command) == 0) {
                syslog(LOG_INFO, "Decoded NEC: Address = 0x%08X, Command = 0x%08X", address, command);

                if (publish_mqtt(address, command) != 0) {
                    syslog(LOG_ERR, "Failed to publish MQTT message");
                }
            } else {
                syslog(LOG_ERR, "NEC decoding failed");
            }

            pulse_index = 0;
            pulse_count = 0;
        }
        gpioDelay(1000); // Check every 1ms
    }

    return 0;
}

