    uint32_t address, command;

    while (1) {
        if (nec_frame_complete) {
            nec_frame_complete = 0; // Reset flag

            if (decode_nec(pulse_buffer, pulse_count, &address, &command) == 0) {
                syslog(LOG_INFO, "Decoded NEC: Address = 0x%08X, Command = 0x%08X", address, command);

                if (publish_mqtt(address, command) != 0) {
