#include <errno.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define SLEEP_MS 180
#define SLEEP_S 1

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;
int udp_socket = -1;

// Function prototypes
int init_i2c(const char *bus);
int set_i2c_slave(int fd, int addr);
int write_i2c(int fd, const char *buf, int len);
int read_i2c(int fd, char *buf, int len);
int start_measurement(int fd);
int read_measurement(int fd, unsigned short *lux);
float convert_to_lux(unsigned short raw_value);
int create_udp_socket(void);
int send_udp_packet(int sockfd, const char *packet);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold sensor data
typedef struct {
    int id;
    float lux;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to set I2C slave address
int set_i2c_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to write to I2C
int write_i2c(int fd, const char *buf, int len) {
    int ret = write(fd, buf, len);
    if (ret < 0) {
        perror("Error writing to I2C");
        return -1;
    }
    return ret;
}

// Function to read from I2C
int read_i2c(int fd, char *buf, int len) {
    int ret = read(fd, buf, len);
    if (ret < 0) {
        perror("Error reading from I2C");
        return -1;
    }
    return ret;
}

// Function to start measurement
int start_measurement(int fd) {
    char buf[1] = {CONTINUOUS_HIGH_RES_MODE};
    if (write_i2c(fd, buf, 1) < 0) {
        return -1;
    }
    return 0;
}

// Function to read measurement
int read_measurement(int fd, unsigned short *lux) {
    char buf[2];
    if (read_i2c(fd, buf, 2) < 0) {
        return -1;
    }
    *lux = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to create UDP socket
int create_udp_socket(void) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Set multicast TTL
    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Function to send UDP packet
int send_udp_packet(int sockfd, const char *packet) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, packet, strlen(packet), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Initialize UDP socket
    udp_socket = create_udp_socket();
    if (udp_socket < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data[NUM_SENSORS];
        char packet[256] = {0}; // Buffer for the UDP packet
        char *ptr = packet;
        int packet_len = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_data[i].id = i + 1;

            // Set I2C slave address
            if (set_i2c_slave(i2c_fd, BH1750_ADDR) < 0) {
                sensor_data[i].lux = NAN;
                continue;
            }

            // Start measurement
            if (start_measurement(i2c_fd) < 0) {
                sensor_data[i].lux = NAN;
                continue;
