            // Wait for measurement
            gpioDelay(SLEEP_MS * 1000); // pigpioDelay takes microseconds

            unsigned short raw_value;
            // Read measurement
            if (read_measurement(i2c_fd, &raw_value) < 0) {
                sensor_data[i].lux = NAN;
                continue;
            }

            // Convert to lux
            sensor_data[i].lux = convert_to_lux(raw_value);

            // Format data for UDP packet
            int len = snprintf(ptr, packet_len + 256 - packet_len, "%d,%.1f", sensor_data[i].id, sensor_data[i].lux);
            if (len < 0 || len >= (packet_len + 256 - packet_len)) {
                fprintf(stderr, "Error formatting sensor data\n");
                sensor_data[i].lux = NAN;
                continue;
            }
            packet_len += len;
            ptr += len;

            if (i < NUM_SENSORS - 1) {
                *ptr++ = ';';
                packet_len++;
            }
        }

        // Send UDP packet
        if (send_udp_packet(udp_socket, packet) < 0) {
            fprintf(stderr, "Error sending UDP packet\n");
        }

        // Sleep for 1 second
        sleep(SLEEP_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

