#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define FLOW_REG 0x00
#define SLPM_PER_PASCAL 0.01
#define LOG_FILE "airflow_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_flow_rate(int *raw_flow);
float convert_to_slpm(int raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sensor_address;
    float slpm_per_pascal;
    char *log_file_name;
} config_t;

config_t config = {I2C_BUS, AWM7300V_ADDR, SLPM_PER_PASCAL, LOG_FILE};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int raw_flow;
    float flow_rate;

    // Main loop
    while (!terminate) {
        // Read flow rate
        if (read_flow_rate(&raw_flow) == 0) {
            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_flow);

            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Failed to log flow rate\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.sensor_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Read flow rate from sensor
int read_flow_rate(int *raw_flow) {
    char buf[2];
    int result, retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Success
            *raw_flow = ((buf[0] << 8) | buf[1]) & 0x3FFF; // Mask 14 bits
            return 0;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS); // pigpio's delay function
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return 1;
}

// Convert raw flow to SLPM
float convert_to_slpm(int raw_flow) {
    return (float)raw_flow * config.slpm_per_pascal;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

