#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x1D
#define DEFAULT_SAMPLING_INTERVAL 1.0
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"
#define DEFAULT_ERROR_LOG_FILENAME "seismic_error.log"
#define DEFAULT_SCALE_FACTOR 0.001 // 1 mg/LSB = 0.001 g/LSB

// D7S Register Addresses
#define D7S_REG_X_AXIS_LSB 0x28
#define D7S_REG_X_AXIS_MSB 0x29
#define D7S_REG_Y_AXIS_LSB 0x2A
#define D7S_REG_Y_AXIS_MSB 0x2B
#define D7S_REG_Z_AXIS_LSB 0x2C
#define D7S_REG_Z_AXIS_MSB 0x2D

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;
double sampling_interval = DEFAULT_SAMPLING_INTERVAL;
int i2c_address = DEFAULT_I2C_ADDRESS;
char *output_filename = DEFAULT_OUTPUT_FILENAME;
char *error_log_filename = DEFAULT_ERROR_LOG_FILENAME;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    double x_g;
    double y_g;
    double z_g;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(sensor_data_t *data);
int write_data_to_file(sensor_data_t data);
int write_error_to_file(const char *message);
void signal_handler(int signal);
void cleanup();
void print_usage(const char *program_name);

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, D7S_REG_X_AXIS_LSB, buffer, 6);
        if (bytes_read == 6) {
            // Combine LSB and MSB, convert to g
            int16_t x_raw = (buffer[1] << 8) | buffer[0];
            int16_t y_raw = (buffer[3] << 8) | buffer[2];
            int16_t z_raw = (buffer[5] << 8) | buffer[4];

            data->x_g = (double)x_raw * DEFAULT_SCALE_FACTOR;
            data->y_g = (double)y_raw * DEFAULT_SCALE_FACTOR;
            data->z_g = (double)z_raw * DEFAULT_SCALE_FACTOR;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", bytes_read, retries - 1);
            write_error_to_file("I2C read error");
            gpioDelay(10); // 10 ms delay
            retries--;
        }
    }
    return -1; // Failure after retries
}

// Function to write data to file
int write_data_to_file(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data_file != NULL) {
        fprintf(data_file, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x_g, data.y_g, data.z_g);
        fflush(data_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Data file is not open.\n");
        write_error_to_file("Data file is not open");
        return -1;
    }
}

// Function to write error to file
int write_error_to_file(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (error_file != NULL) {
        fprintf(error_file, "%s: %s\n", timestamp, message);
        fflush(error_file);
        return 0;
    } else {
        fprintf(stderr, "Error file is not open.\n");
        return -1;
    }
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fflush(data_file);
        fclose(data_file);
    }
    if (error_file != NULL) {
        fflush(error_file);
        fclose(error_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

// Print usage information
void print_usage(const char *program_name) {
    printf("Usage: %s [-a i2c_address] [-i sampling_interval] [-f output_filename]\n", program_name);
    printf("  -a i2c_address: I2C address of the D7S sensor (default: 0x1D)\n");
    printf("  -i sampling_interval: Sampling interval in seconds (default: 1.0)\n");
    printf("  -f output_filename: Output CSV filename (default: seismic_data.csv)\n");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = strtod(optarg, NULL);
                if (sampling_interval <= 0) {
                    fprintf(stderr, "Invalid sampling interval. Using default value.\n");
                    sampling_interval = DEFAULT_SAMPLING_INTERVAL;
                }
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                print_usage(argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen(output_filename, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file: %s\n", output_filename);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen(error_log_filename, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file: %s\n", error_log_filename);
        fclose(data_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (write_data_to_file(sensor_data) != 0) {
                fprintf(stderr, "Error writing data to file.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        gpioDelay(sampling_interval * 1000); // Convert seconds to milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

