#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/time.h>

// Define constants
#define UART_PORT "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_LENGTH 8
#define MAGIC_WORD {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07}
#define MAX_BUFFER_SIZE 4096
#define MAX_OBJECTS 10
#define CSV_FILE "radar_data.csv"

// Structure for TLV header
typedef struct {
    unsigned short type;
    unsigned short length;
} tlv_header_t;

// Structure for object data
typedef struct {
    float range;
    float velocity;
} object_data_t;

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *csv_file = NULL;

// Function prototypes
int init_uart(const char *port, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int max_length);
int find_magic_word(const unsigned char *buffer, int length);
int validate_tlv_payload(const unsigned char *buffer, int offset, int length);
int extract_object_data(const unsigned char *buffer, int offset, object_data_t *object);
int write_to_csv(FILE *fp, time_t timestamp, int object_index, float range, float velocity);
void signal_handler(int signum);
void cleanup();

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

// Initialize UART
int init_uart(const char *port, int baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_iflag = 0;
    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 5; // Timeout of 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART with timeout
int read_uart_data(int fd, unsigned char *buffer, int max_length) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 1; // Timeout of 1 second
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select()");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        int bytes_read = read(fd, buffer, max_length);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        }
        return bytes_read;
    }
}

// Find magic word in buffer
int find_magic_word(const unsigned char *buffer, int length) {
    const unsigned char magic_word[] = MAGIC_WORD;
    for (int i = 0; i <= length - MAGIC_WORD_LENGTH; ++i) {
        if (memcmp(buffer + i, magic_word, MAGIC_WORD_LENGTH) == 0) {
            return i;
        }
    }
    return -1;
}

// Validate TLV payload
int validate_tlv_payload(const unsigned char *buffer, int offset, int length) {
    if (offset + sizeof(tlv_header_t) > length) {
        fprintf(stderr, "Error: TLV header exceeds buffer length\n");
        return -1;
    }

    tlv_header_t *header = (tlv_header_t *)(buffer + offset);
    unsigned short type = header->type;
    unsigned short tlv_length = header->length;

    if (offset + sizeof(tlv_header_t) + tlv_length > length) {
        fprintf(stderr, "Error: TLV payload exceeds buffer length\n");
        return -1;
    }

    // Add more specific validation based on TLV type (e.g., check for valid range/velocity values)
    // For now, just check if the length is reasonable
    if (tlv_length > 1000) {
        fprintf(stderr, "Error: TLV payload length is too large\n");
        return -1;
    }

    return 0;
}

// Extract object data from TLV payload
int extract_object_data(const unsigned char *buffer, int offset, object_data_t *object) {
    tlv_header_t *header = (tlv_header_t *)(buffer + offset);
    unsigned short tlv_length = header->length;

    // Assuming the object data is a simple struct of range and velocity
    if (tlv_length == sizeof(object_data_t)) {
        memcpy(object, buffer + offset + sizeof(tlv_header_t), sizeof(object_data_t));
        return 0;
    } else {
        fprintf(stderr, "Error: TLV payload length does not match expected object data size\n");
        return -1;
    }
}

// Write data to CSV file
int write_to_csv(FILE *fp, time_t timestamp, int object_index, float range, float velocity) {
    if (fprintf(fp, "%ld,%d,%.2f,%.2f\n", timestamp, object_index, range, velocity) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    unsigned char buffer[MAX_BUFFER_SIZE];
    int buffer_length = 0;
    time_t timestamp;
    object_data_t object_data[MAX_OBJECTS];
    int num_objects;

    while (program_running) {
        // Read data from UART
        int bytes_read = read_uart_data(uart_fd, buffer + buffer_length, MAX_BUFFER_SIZE - buffer_length);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART. Continuing...\n");
            continue;
        } else if (bytes_read == 0) {
            // Timeout occurred, continue to the next iteration
            continue;
        }

        buffer_length += bytes_read;

        // Find magic word
        int magic_word_index = find_magic_word(buffer, buffer_length);
        if (magic_word_index != -1) {
            // Process data after the magic word
            timestamp = time(NULL);

            // Extract number of objects (assuming it's the first byte after the magic word)
            num_objects = buffer[magic_word_index + MAGIC_WORD_LENGTH];

            if (num_objects > MAX_OBJECTS) {
                fprintf(stderr, "Error: Number of objects exceeds maximum allowed\n");
                num_objects = MAX_OBJECTS;
            }

            int offset = magic_word_index + MAGIC_WORD_LENGTH + 1; // Skip magic word and number of objects

            for (int i = 0; i < num_objects; ++i) {
                // Find the next TLV
                int tlv_index = find_magic_word(buffer + offset, buffer_length - offset);
                if (tlv_index == -1) {
                    fprintf(stderr, "Error: Could not find TLV after magic word\n");
                    break; // Exit the loop if TLV is not found
                }

                tlv_index += offset;

                // Validate TLV payload
                if (validate_tlv_payload(buffer, tlv_index, buffer_length) == 0) {
                    // Extract object data
                    if (extract_object_data(buffer, tlv_index, &object_data[i]) == 0) {
                        // Write data to CSV file
                        if (write_to_csv(csv_file, timestamp, i, object_data[i].range, object_data[i].velocity) != 0) {
                            fprintf(stderr, "Error writing object data to CSV. Continuing...\n");
                        }
                    } else {
                        fprintf(stderr, "Error extracting object data. Continuing...\n");
                    }
                } else {
                    fprintf(stderr, "Error validating TLV payload. Continuing...\n");
                }

                offset = tlv_index + sizeof(tlv_header_t) + object_data[i].range; // Move offset to the next TLV
            }

            // Remove processed data from the buffer
            memmove(buffer, buffer + offset, buffer_length - offset);
            buffer_length -= offset;
        }
    }

    // Cleanup resources
    cleanup();

    return 0;
}

