#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <termios.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC 0
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;    // Read at least 0 characters
    tty.c_cc[VTIME] = 5;   // 0.5 second timeout (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction failed");
        return 1;
    }

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("open failed");
        return 1;
    }

    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return 1;
    }

    char buffer[BUFFER_SIZE];
    int buffer_index = 0;
    fd_set readfds;
    struct timeval timeout;

    while (program_running) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = TIMEOUT_USEC;

        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("select failed");
            break;
        } else if (select_result == 0) {
            // Timeout occurred
            fprintf(stderr, "Timeout occurred, no data received.\n");
            continue;
        } else {
            // Data is available
            char read_buffer[1];
            ssize_t bytes_read = read(uart_fd, read_buffer, 1);
            if (bytes_read == -1) {
                perror("read failed");
                break;
            } else if (bytes_read == 0) {
                fprintf(stderr, "UART closed.\n");
                break;
            } else {
                buffer[buffer_index++] = read_buffer[0];

                if (buffer_index >= BUFFER_SIZE) {
                    fprintf(stderr, "Buffer overflow!\n");
                    buffer_index = 0; // Reset buffer
                    continue;
                }

                if (read_buffer[0] == '\n') {
                    buffer[buffer_index] = '\0'; // Null-terminate the string

                    // Parse the data
                    char *timestamp_str = strtok(buffer, ",");
                    char *range_str = strtok(NULL, "\n");

                    if (timestamp_str != NULL && range_str != NULL) {
                        time_t timestamp = strtol(timestamp_str, NULL, 10);
                        double range = strtod(range_str, NULL);

                        // Validate the data
                        if (timestamp > 0 && range >= 0.0) {
                            // Format the output
                            char timestamp_str_formatted[32];
                            struct tm *tm_info = localtime(&timestamp);
                            strftime(timestamp_str_formatted, sizeof(timestamp_str_formatted), "%Y-%m-%d %H:%M:%S", tm_info);

                            printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str_formatted, range);
                        } else {
                            fprintf(stderr, "Invalid data: timestamp=%ld, range=%.2f\n", timestamp, range);
                        }
                    } else {
                        fprintf(stderr, "Invalid data format: %s\n", buffer);
                    }

                    buffer_index = 0; // Reset buffer for next line
                }
            }
        }
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    return 0;
}

