#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
int send_emergency_stop();
void signal_handler(int signal);
int setup_uart();
void cleanup();

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    // Setup UART communication
    if (setup_uart() != 0) {
        fprintf(stderr, "Error setting up UART communication.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor data
        sensor_data_t sensor_values;
        sensor_values.left = read_sensor(LEFT_SENSOR);
        sensor_values.middle = read_sensor(MIDDLE_SENSOR);
        sensor_values.right = read_sensor(RIGHT_SENSOR);

        // Log sensor data
        log_sensor_data(sensor_values.left, sensor_values.middle, sensor_values.right);

        // Check for emergency stop condition
        if (sensor_values.left == 0 && sensor_values.middle == 0 && sensor_values.right == 0) {
            send_emergency_stop();
        }

        // Delay for 100ms (10Hz loop)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log sensor data with timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: Left=%d, Middle=%d, Right=%d\n", timestamp, left, middle, right);
}

// Function to send emergency stop message via UART
int send_emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    ssize_t bytes_written = write(uart_fd, message, strlen(message));

    if (bytes_written == -1) {
        perror("Error writing to UART");
        return 1; // Indicate failure
    }

    printf("Emergency stop message sent.\n");
    return 0; // Indicate success
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Function to setup UART communication
int setup_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return 1;
    }

    struct termios options;
    tcgetattr(uart_fd, &options);
    options.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcflush(uart_fd, TCIFLUSH);
    tcsetattr(uart_fd, TCSANOW, &options);

    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close UART port
    if (uart_fd != -1) {
        close(uart_fd);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

